fun formatQuantity(value: Double): String {
    return try {
        if (value.isNaN() || value.isInfinite()) return "0"
        val bd = java.math.BigDecimal(value.toString())
            .setScale(3, java.math.RoundingMode.HALF_UP)
            .stripTrailingZeros()
        bd.toPlainString()
    } catch (e: Exception) {
        try {
            val symbols = java.text.DecimalFormatSymbols(java.util.Locale.US)
            val df = java.text.DecimalFormat("#.###", symbols)
            df.format(value)
        } catch (ex: Exception) {
            value.toString()
        }
    }
}

fun parseUserDouble(input: String): Double? {
    var cleaned = input.trim()
    val arabicIndicDigits = charArrayOf('٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩')
    for (i in 0..9) {
        cleaned = cleaned.replace(arabicIndicDigits[i], (i + 48).toChar())
    }
    cleaned = cleaned.replace(',', '.').replace('،', '.')
    return cleaned.toDoubleOrNull()
}

fun isPartialUserDouble(input: String): Boolean {
    if (input.isEmpty()) return true
    if (input.endsWith(".") || input.endsWith(",") || input.endsWith("،")) {
        val sub = input.substring(0, input.length - 1)
        return sub.isEmpty() || parseUserDouble(sub) != null
    }
    return parseUserDouble(input) != null
}

fun formatDecimalsInText(input: String): String {
    if (input.isBlank()) return input
    val words = input.split(" ")
    return words.joinToString(" ") { word ->
        val regex = Regex("""^([^0-9]*?)(\d+\.\d+)([^0-9]*)$""")
        val match = regex.find(word)
        if (match != null) {
            val prefix = match.groupValues[1]
            val numStr = match.groupValues[2]
            val suffix = match.groupValues[3]
            if (word.count { it == '.' } == 1) {
                val numDouble = numStr.toDoubleOrNull()
                if (numDouble != null) {
                    val formatted = try {
                        val bd = java.math.BigDecimal(numDouble.toString())
                            .setScale(2, java.math.RoundingMode.HALF_UP)
                            .stripTrailingZeros()
                        bd.toPlainString()
                    } catch (e: Exception) {
                        numStr
                    }
                    "$prefix$formatted$suffix"
                } else {
                    word
                }
            } else {
                word
            }
        } else {
            word
        }
    }
}

