fun formatPercent(value: Double): String {
    return try {
        if (value.isNaN() || value.isInfinite()) return "0%"
        val bd = java.math.BigDecimal(value.toString())
            .setScale(3, java.math.RoundingMode.HALF_UP)
            .stripTrailingZeros()
        "${bd.toPlainString()}%"
    } catch (e: Exception) {
        "$value%"
    }
}

fun formatCost(value: Double): String {
    return try {
        if (value.isNaN() || value.isInfinite()) return "0"
        val bd = java.math.BigDecimal(value.toString())
            .setScale(2, java.math.RoundingMode.HALF_UP)
            .stripTrailingZeros()
        bd.toPlainString()
    } catch (e: Exception) {
        value.toString()
    }
}

fun formatWeightTwoDecimals(value: Double): String {
    return try {
        if (value.isNaN() || value.isInfinite()) return "0"
        val bd = java.math.BigDecimal(value.toString())
            .setScale(2, java.math.RoundingMode.HALF_UP)
            .stripTrailingZeros()
        bd.toPlainString()
    } catch (e: Exception) {
        try {
            val symbols = java.text.DecimalFormatSymbols(java.util.Locale.US)
            val df = java.text.DecimalFormat("#.##", symbols)
            df.format(value)
        } catch (ex: Exception) {
            value.toString()
        }
    }
}

fun formatDateOnly(dateStr: String): String {
    if (dateStr.contains(" ") && dateStr.length >= 10) {
        val parts = dateStr.split(" ")
        if (parts.isNotEmpty()) {
            return parts[0]
        }
    }
    return dateStr
}

class MainActivity : ComponentActivity() {
    private val intentFlow = kotlinx.coroutines.flow.MutableSharedFlow<Intent>(extraBufferCapacity = 8)
    private var lastBackgroundTime: Long = 0L

    private val requestNotificationPermissionLauncher = registerForActivityResult(
        androidx.activity.result.contract.ActivityResultContracts.RequestPermission()
    ) { _ -> }

    override fun onCreate(savedInstanceState: Bundle?) {
        com.example.ui.CrashReporter.install(this) // يعرض سبب أي انهيار كإشعار للتشخيص
        // Fix for Android duplicate-activity launcher bug:
        // Clicking launcher icon while app is raw-running in background should show existing state.
        if (!isTaskRoot
            && intent.hasCategory(Intent.CATEGORY_LAUNCHER)
            && intent.action != null
            && intent.action == Intent.ACTION_MAIN
        ) {
            super.onCreate(savedInstanceState)
            finish()
            return
        }
        
        // Request POST_NOTIFICATIONS permission on Android 13+
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
            if (androidx.core.content.ContextCompat.checkSelfPermission(
                    this,
                    android.Manifest.permission.POST_NOTIFICATIONS
                ) != android.content.pm.PackageManager.PERMISSION_GRANTED
            ) {
                requestNotificationPermissionLauncher.launch(android.Manifest.permission.POST_NOTIFICATIONS)
            }
        }
        
        // Initialize Device Security System
        com.example.data.DeviceSecurityManager.initialize(applicationContext)
        val scope = kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main)
        scope.launch {
            com.example.data.DeviceSecurityManager.verifyDeviceStatus(applicationContext)
            com.example.data.DeviceSecurityManager.startAdminPendingDevicesListener(applicationContext)
        }

        super.onCreate(savedInstanceState)
        intent?.let { intentFlow.tryEmit(it) }
        enableEdgeToEdge()
        setContent {
            val viewModel: GbrViewModel = viewModel()

             // Handle incoming notification click intent
             val currentIntent by intentFlow.collectAsState(initial = intent)
             androidx.compose.runtime.LaunchedEffect(currentIntent) {
                 val orderId = currentIntent?.getStringExtra("orderId")
                 val stepKey = currentIntent?.getStringExtra("stepKey")
                 if (!orderId.isNullOrEmpty()) {
                     try {
                         currentIntent?.removeExtra("orderId")
                         currentIntent?.removeExtra("stepKey")
                     } catch (e: Exception) {
                         e.printStackTrace()
                     }
                     viewModel.stopGrindingAlarm(applicationContext, orderId, stepKey)
                     viewModel.selectAndNavigateToProductionOrder(orderId, stepKey)
                 }

                 val goToAlerts = currentIntent?.getBooleanExtra("goToAlerts", false) ?: false
                 if (goToAlerts) {
                     try {
                         currentIntent?.removeExtra("goToAlerts")
                     } catch (e: Exception) {
                         e.printStackTrace()
                     }
                     viewModel.showSegment("operational_alerts")
                 }
             }

            val themeStr by viewModel.appTheme.collectAsState()
            val langStr by viewModel.appLanguage.collectAsState()
            
            val isDark = when (themeStr) {
                "dark" -> true
                "light" -> false
                else -> isSystemInDarkTheme()
            }
            
            val layoutDirection = if (langStr == "en") LayoutDirection.Ltr else LayoutDirection.Rtl
            
            MyApplicationTheme(darkTheme = isDark) {
                val context = androidx.compose.ui.platform.LocalContext.current
                val appStrings = remember(langStr) { com.example.ui.theme.JsonAppStrings(langStr, context) }
                CompositionLocalProvider(
                    LocalAppLanguage provides langStr,
                    LocalAppStrings provides appStrings,
                    LocalLayoutDirection provides layoutDirection
                ) {
                    GbrAppContainer(
                        modifier = Modifier.fillMaxSize(),
                        viewModel = viewModel
                    )
                }
            }
        }
    }

    override fun onNewIntent(intent: android.content.Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        intentFlow.tryEmit(intent)
    }

    override fun onStart() {
        super.onStart()
        if (lastBackgroundTime != 0L) {
            val elapsedMs = System.currentTimeMillis() - lastBackgroundTime
            // 2 hours in milliseconds: 2 * 60 * 60 * 1000 = 7,200,000 ms
            if (elapsedMs >= 7200000L) {
                try {
                    val viewModel = androidx.lifecycle.ViewModelProvider(this)[com.example.ui.GbrViewModel::class.java]
                    if (viewModel.isLoggedIn.value) {
                        viewModel.autoLogoutOnTimeout()
                        android.widget.Toast.makeText(
                            this,
                            "تم تسجيل الخروج تلقائياً لانتهاء صلاحية الجلسة بعد بقاء التطبيق في الخلفية",
                            android.widget.Toast.LENGTH_LONG
                        ).show()
                    }
                } catch (e: java.lang.Exception) {
                    e.printStackTrace()
                }
            }
            lastBackgroundTime = 0L
        }
    }

    override fun onStop() {
        super.onStop()
        lastBackgroundTime = System.currentTimeMillis()
    }
}

@Composable
fun GbrAppContainer(
    modifier: Modifier = Modifier,
    viewModel: GbrViewModel = viewModel()
) {
    // Export/Import states
    val expMaterials by viewModel.expMaterials.collectAsState()
    val expEquipment by viewModel.expEquipment.collectAsState()
    val expFormulations by viewModel.expFormulations.collectAsState()
    val expRevisions by viewModel.expRevisions.collectAsState()
    val expRecipes by viewModel.expRecipes.collectAsState()
    val expOrders by viewModel.expOrders.collectAsState()
    val expTests by viewModel.expTests.collectAsState()
    val expPackagings by viewModel.expPackagings.collectAsState()
    val expCosts by viewModel.expCosts.collectAsState()
    
    val isFullExport by viewModel.isFullExport.collectAsState()

    val impMaterials by viewModel.impMaterials.collectAsState()
    val impFormulations by viewModel.impFormulations.collectAsState()
    val impRevisions by viewModel.impRevisions.collectAsState()
    val impRecipes by viewModel.impRecipes.collectAsState()
    val impOrders by viewModel.impOrders.collectAsState()
    val impTests by viewModel.impTests.collectAsState()
    val impPackagings by viewModel.impPackagings.collectAsState()
    val impCosts by viewModel.impCosts.collectAsState()
    
    var showExportAlert by remember { mutableStateOf(false) }

    val context = androidx.compose.ui.platform.LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    val deviceStatus by com.example.data.DeviceSecurityManager.deviceStatus.collectAsState()

    // Collect and display transaction alerts (Saves, Edits, Deletes)
    LaunchedEffect(viewModel.globalToastEvents) {
        viewModel.globalToastEvents.collect { msg ->
            android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_LONG).show()
        }
    }

    // Collect and display real-time live cross-device sync notifications
    LaunchedEffect(Unit) {
        com.example.ui.GbrViewModel.cloudNotifications.collect { msg ->
            val formattedMsg = formatDecimalsInText(msg)
            android.widget.Toast.makeText(context, formattedMsg, android.widget.Toast.LENGTH_LONG).show()
        }
    }

    // Continuous real-time listener for this device's security status in the cloud
    DisposableEffect(Unit) {
        com.example.data.DeviceSecurityManager.startRealtimeStatusListener(context) { newStatus ->
            if (newStatus == com.example.data.DeviceSecurityManager.STATUS_SUSPENDED) {
                com.example.data.SyncManager.stopRealtimeListeners()
                viewModel.addSystemLog("security", "تم تعليق صلاحية الجهاز وقفل الشاشة مؤقتاً في الوقت الفعلي")
                android.widget.Toast.makeText(context, "⏸️ تم تعليق صلاحية هذا الجهاز مؤقتاً من قِبل الإدارة.", android.widget.Toast.LENGTH_LONG).show()
            } else if (newStatus == com.example.data.DeviceSecurityManager.STATUS_BLOCKED) {
                com.example.data.SyncManager.stopRealtimeListeners()
                com.example.data.DeviceSecurityManager.wipeDeviceData(context)
                viewModel.addSystemLog("security", "تم حظر وإلغاء الجهاز نهائياً من السحابة وتدمير البيانات محلياً")
                android.widget.Toast.makeText(context, "🚫 تم حظر الجهاز وتدمير البيانات المحلية لحماية أسرار الشركة.", android.widget.Toast.LENGTH_LONG).show()
            } else if (newStatus == com.example.data.DeviceSecurityManager.STATUS_APPROVED) {
                viewModel.addSystemLog("security", "تم اعتماد وتنشيط الجهاز من الإدارة السحابية - جاري المزامنة الشاملة")
                android.widget.Toast.makeText(context, "🎉 تم اعتماد وتنشيط جهازك بنجاح! جاري بدء المزامنة التلقائية...", android.widget.Toast.LENGTH_LONG).show()
                com.example.data.SyncManager.initializeFirebase(context)
                if (viewModel.syncMode.value == "realtime") {
                    com.example.data.SyncManager.startRealtimeListeners(context, viewModel.repository)
                }
                viewModel.triggerManualSync("all", force = true)
            }
        }
        onDispose {
            // Keep listener active
        }
    }

    // Auto-trigger full sync when device status transitions to APPROVED
    var prevObservedDeviceStatus by remember { mutableStateOf(deviceStatus) }
    LaunchedEffect(deviceStatus) {
        if (deviceStatus == com.example.data.DeviceSecurityManager.STATUS_APPROVED &&
            prevObservedDeviceStatus != com.example.data.DeviceSecurityManager.STATUS_APPROVED) {
            if (com.example.data.DeviceSecurityManager.isCloudConfigured(context) &&
                com.example.data.SyncManager.isNetworkAvailable(context)) {
                com.example.data.SyncManager.initializeFirebase(context)
                if (viewModel.syncMode.value == "realtime") {
                    com.example.data.SyncManager.startRealtimeListeners(context, viewModel.repository)
                }
                viewModel.triggerManualSync("all", force = true)
            }
        }
        prevObservedDeviceStatus = deviceStatus
    }

    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en

    data class PendingDeviceNotice(
        val deviceId: String,
        val deviceName: String,
        val alert: com.example.data.OperationalAlert
    )

    var activeNewDeviceNoticeForPopup by remember { mutableStateOf<PendingDeviceNotice?>(null) }
    val shownDevicePopups = remember { mutableStateOf(setOf<String>()) }

    fun sendDeviceSecuritySystemNotification(title: String, message: String) {
        try {
            val notificationManager = context.getSystemService(android.content.Context.NOTIFICATION_SERVICE) as? android.app.NotificationManager
            if (notificationManager != null) {
                val channelId = "gbr_device_security_channel"
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                    val channel = android.app.NotificationChannel(
                        channelId,
                        "تنبيهات أمان واعتماد الأجهزة",
                        android.app.NotificationManager.IMPORTANCE_HIGH
                    ).apply {
                        description = "إشعارات فورية عند محاولة أجهزة جديدة الاتصال بالسحابة"
                        enableVibration(true)
                    }
                    notificationManager.createNotificationChannel(channel)
                }
                val notifIntent = Intent(context, MainActivity::class.java).apply {
                    flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
                }
                val pendingIntent = android.app.PendingIntent.getActivity(
                    context,
                    System.currentTimeMillis().toInt(),
                    notifIntent,
                    android.app.PendingIntent.FLAG_UPDATE_CURRENT or (if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.M) android.app.PendingIntent.FLAG_IMMUTABLE else 0)
                )
                val builder = androidx.core.app.NotificationCompat.Builder(context, channelId)
                    .setSmallIcon(android.R.drawable.ic_dialog_alert)
                    .setContentTitle(title)
                    .setContentText(message)
                    .setStyle(androidx.core.app.NotificationCompat.BigTextStyle().bigText(message))
                    .setPriority(androidx.core.app.NotificationCompat.PRIORITY_HIGH)
                    .setAutoCancel(true)
                    .setContentIntent(pendingIntent)
                
                notificationManager.notify((System.currentTimeMillis() % 100000).toInt(), builder.build())
            }
        } catch (e: Exception) {
            android.util.Log.e("DeviceSecurity", "Failed to post system notification", e)
        }
    }

    val isPrimaryDevice by com.example.data.DeviceSecurityManager.isPrimary.collectAsState()
    val pendingDevicesList by com.example.data.DeviceSecurityManager.pendingDevices.collectAsState()

    // Real-time listener for the admin device to detect incoming registration requests
    LaunchedEffect(Unit) {
        com.example.data.DeviceSecurityManager.startAdminPendingDevicesListener(context) { newDevice ->
            val msg = "🔔 تنبيه أمني: يوجد جهاز جديد ينتظر الاعتماد: ${newDevice.deviceName}"
            com.example.ui.GbrViewModel.cloudNotifications.tryEmit(msg)
            sendDeviceSecuritySystemNotification(
                "🔔 طلب اعتماد جهاز جديد 🔌",
                "تم رصد محاولة اتصال من (${newDevice.deviceName}) بانتظار موافقة أو حظر المسؤول."
            )
            val alert = com.example.data.OperationalAlert(
                id = "device_alert_" + newDevice.deviceId,
                title = "جهاز جديد يطلب المزامنة 🔌",
                description = "تم رصد جهاز جديد يتصل بالنظام ويطلب الاعتماد: ${newDevice.deviceName}",
                mainSection = "عام",
                bindingScope = "ALL",
                alertLevel = "WARNING",
                status = "ACTIVE",
                createdAt = System.currentTimeMillis()
            )
            viewModel.insertOperationalAlert(alert)
        }
    }

    // Automatically trigger alert dialog when new pending device appears
    LaunchedEffect(pendingDevicesList) {
        val currentPendingIds = pendingDevicesList.map { it.deviceId }.toSet()
        shownDevicePopups.value = shownDevicePopups.value.intersect(currentPendingIds)
        if (pendingDevicesList.isNotEmpty()) {
            val unshown = pendingDevicesList.firstOrNull { !shownDevicePopups.value.contains(it.deviceId) }
            if (unshown != null) {
                val alert = com.example.data.OperationalAlert(
                    id = "device_alert_" + unshown.deviceId,
                    title = "جهاز جديد يطلب المزامنة 🔌",
                    description = "تم رصد جهاز جديد يتصل بالنظام ويطلب الاعتماد: ${unshown.deviceName}",
                    mainSection = "عام",
                    bindingScope = "ALL",
                    alertLevel = "WARNING",
                    status = "ACTIVE",
                    createdAt = System.currentTimeMillis()
                )
                activeNewDeviceNoticeForPopup = PendingDeviceNotice(unshown.deviceId, unshown.deviceName, alert)
                shownDevicePopups.value = shownDevicePopups.value + unshown.deviceId
                
                sendDeviceSecuritySystemNotification(
                    "🔔 طلب اعتماد جهاز جديد 🔌",
                    "تم رصد محاولة اتصال من (${unshown.deviceName}) بانتظار موافقة أو حظر المسؤول."
                )
            }
        } else {
            activeNewDeviceNoticeForPopup = null
        }
    }

    if (activeNewDeviceNoticeForPopup != null) {
        val notice = activeNewDeviceNoticeForPopup!!
        var isOperatingOnDevice by remember { mutableStateOf(false) }

        AlertDialog(
            onDismissRequest = { if (!isOperatingOnDevice) activeNewDeviceNoticeForPopup = null },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Warning,
                        contentDescription = "Alert",
                        tint = WarningOrange,
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = t("🔌 جهاز جديد يطلب إذن المزامنة", "🔌 New Device Awaiting Approval"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp,
                        color = GBRDarkIndigo
                    )
                }
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        text = t(
                            "تم رصد محاولة اتصال جديدة بالسحابة وتثبيت التطبيق من جهاز آخر:",
                            "A new device connection attempt has been detected on the cloud:"
                        ),
                        fontSize = 12.sp,
                        color = Color.DarkGray
                    )
                    
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            Row(horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                                Text(t("📱 اسم الجهاز:", "Device Name:"), fontSize = 11.sp, color = Color.Gray)
                                Text(notice.deviceName, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                            }
                            Row(horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                                Text(t("🔑 المعرّف:", "Device ID:"), fontSize = 10.sp, color = Color.Gray)
                                Text(if (notice.deviceId.length > 14) notice.deviceId.take(14) + "..." else notice.deviceId, fontSize = 10.sp, fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace, color = Color.DarkGray)
                            }
                        }
                    }
                    
                    Text(
                        text = t(
                            "يمكنك اعتماد الجهاز فوراً ليبدأ المزامنة الكاملة، أو حظره لمنعه من الوصول لبيانات المصنع نهائياً.",
                            "You can immediately approve this device to start full sync, or block it to deny access."
                        ),
                        fontSize = 11.sp,
                        color = Color.Gray,
                        lineHeight = 15.sp
                    )
                }
            },
            confirmButton = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    Button(
                        onClick = {
                            coroutineScope.launch {
                                isOperatingOnDevice = true
                                val success = com.example.data.DeviceSecurityManager.updateDeviceStatusOnCloud(
                                    context,
                                    notice.deviceId,
                                    com.example.data.DeviceSecurityManager.STATUS_APPROVED
                                )
                                isOperatingOnDevice = false
                                if (success) {
                                    Toast.makeText(context, t("🎉 تم اعتماد وتنشيط الجهاز بنجاح!", "🎉 Device approved successfully!"), Toast.LENGTH_LONG).show()
                                    activeNewDeviceNoticeForPopup = null
                                } else {
                                    Toast.makeText(context, t("❌ فشل تحديث حالة الجهاز. تحقق من الإنترنت.", "❌ Failed to update device status."), Toast.LENGTH_SHORT).show()
                                }
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A)),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.weight(1f).height(38.dp),
                        enabled = !isOperatingOnDevice
                    ) {
                        if (isOperatingOnDevice) {
                            CircularProgressIndicator(color = Color.White, modifier = Modifier.size(16.dp))
                        } else {
                            Text(t("اعتماد فوري ✅", "Approve ✅"), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                    
                    Button(
                        onClick = {
                            coroutineScope.launch {
                                isOperatingOnDevice = true
                                val success = com.example.data.DeviceSecurityManager.updateDeviceStatusOnCloud(
                                    context,
                                    notice.deviceId,
                                    com.example.data.DeviceSecurityManager.STATUS_BLOCKED
                                )
                                isOperatingOnDevice = false
                                if (success) {
                                    Toast.makeText(context, t("🚫 تم حظر ومنع هذا الجهاز نهائياً.", "🚫 Device blocked permanently."), Toast.LENGTH_LONG).show()
                                    activeNewDeviceNoticeForPopup = null
                                } else {
                                    Toast.makeText(context, t("❌ فشل تنفيذ الحظر. تحقق من الإنترنت.", "❌ Failed to block device."), Toast.LENGTH_SHORT).show()
                                }
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDC2626)),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.weight(1f).height(38.dp),
                        enabled = !isOperatingOnDevice
                    ) {
                        Text(t("حظر الجهاز 🚫", "Block 🚫"), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    }
                }
            },
            dismissButton = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    TextButton(
                        onClick = {
                            activeNewDeviceNoticeForPopup = null
                            viewModel.activeSegment.value = "settings"
                            viewModel.selectedSettingSection.value = "إدارة الأجهزة والأمان"
                        },
                        enabled = !isOperatingOnDevice
                    ) {
                        Text(t("لوحة الأجهزة 🛡️", "Security Panel 🛡️"), fontSize = 11.sp, color = GBRBlueMain)
                    }
                    
                    TextButton(
                        onClick = { activeNewDeviceNoticeForPopup = null },
                        enabled = !isOperatingOnDevice
                    ) {
                        Text(t("تجاهل", "Ignore"), fontSize = 11.sp, color = Color.Gray)
                    }
                }
            },
            shape = RoundedCornerShape(16.dp),
            containerColor = Color.White
        )
    }

    var currentPhase by remember { mutableStateOf("SPLASH") }

    LaunchedEffect(Unit) {
        if (currentPhase == "SPLASH") {
            delay(2000) // 2-second splash screen (شاشة التشغيل)
            currentPhase = "MAIN_FLOW"
            viewModel.checkAndTriggerBackupReminder()
        }
    }

    val isLoggedIn by viewModel.isLoggedIn.collectAsState()
    val isOperationLoading by viewModel.isOperationLoading.collectAsState()
    val operationStatusMessage by viewModel.operationStatusMessage.collectAsState()

    val showBackupReminderPopup by viewModel.showBackupReminderPopup.collectAsState()
    val lastBackupTimeState by viewModel.lastBackupTime.collectAsState()
    val backupReminderDaysState by viewModel.backupReminderDays.collectAsState()
    val backupDueDaysCountState by viewModel.backupDueDaysCount.collectAsState()

    if (showBackupReminderPopup && currentPhase == "MAIN_FLOW" && isLoggedIn && activeNewDeviceNoticeForPopup == null) {
        AlertDialog(
            onDismissRequest = { viewModel.dismissBackupReminderPopup(forToday = true) },
            title = {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(36.dp)
                            .background(WarningOrange.copy(alpha = 0.15f), RoundedCornerShape(8.dp)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Notifications,
                            contentDescription = "Backup Reminder",
                            tint = WarningOrange,
                            modifier = Modifier.size(22.dp)
                        )
                    }
                    Column {
                        Text(
                            text = t("⏰ تذكير أمان: موعد النسخ الاحتياطي", "⏰ Scheduled Backup Reminder"),
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.5.sp,
                            color = GBRDarkIndigo
                        )
                        Text(
                            text = t("حماية وضمان سلامة بيانات المصنع", "Factory Data Protection"),
                            fontSize = 10.5.sp,
                            color = Color.Gray
                        )
                    }
                }
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Text(
                        text = t(
                            "مرحباً بك! تذكيراً دورياً لضمان سلامة وأمن معلومات المصنع، والتركيبات وسجلات الإنتاج من أي فقدان طارئ، يرجى إنشاء نسخة احتياطية جديدة الآن لقاعدة البيانات.",
                            "Welcome! As a scheduled reminder to ensure the safety and security of factory data, formulations, and production records, please create a new database backup."
                        ),
                        fontSize = 12.sp,
                        color = Color.DarkGray,
                        lineHeight = 16.sp
                    )

                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                        border = BorderStroke(1.dp, Color(0xFFFDE68A)),
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(
                            modifier = Modifier.padding(10.dp),
                            verticalArrangement = Arrangement.spacedBy(5.dp)
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.SpaceBetween,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Text(t("📅 آخر نسخة احتياطية:", "Last Backup:"), fontSize = 11.sp, color = Color.Gray)
                                Text(lastBackupTimeState, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                            }
                            Row(
                                horizontalArrangement = Arrangement.SpaceBetween,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Text(t("⏳ المدة المنقضية:", "Time Elapsed:"), fontSize = 11.sp, color = Color.Gray)
                                Text(
                                    t("$backupDueDaysCountState يوم", "$backupDueDaysCountState days"),
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = WarningOrange
                                )
                            }
                            Row(
                                horizontalArrangement = Arrangement.SpaceBetween,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Text(t("🔔 الفاصل المجدول:", "Scheduled Interval:"), fontSize = 11.sp, color = Color.Gray)
                                Text(
                                    when (backupReminderDaysState) {
                                        7 -> t("كل أسبوع (7 أيام)", "Every week (7 days)")
                                        15 -> t("كل 15 يوماً", "Every 15 days")
                                        30 -> t("كل شهر (30 يوماً)", "Every month (30 days)")
                                        else -> t("كل $backupReminderDaysState يوم", "Every $backupReminderDaysState days")
                                    },
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRBlueMain
                                )
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.dismissBackupReminderPopup(forToday = true)
                        viewModel.activeSegment.value = "settings"
                        viewModel.selectedSettingSection.value = "قاعدة البيانات"
                        viewModel.databaseSettingsActiveTab.value = 3
                        Toast.makeText(context, t("تم التوجيه لصفحة النسخ الاحتياطي والاستعادة 💾", "Navigated to Backup & Restore 💾"), Toast.LENGTH_SHORT).show()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.fillMaxWidth().height(40.dp)
                ) {
                    Icon(imageVector = Icons.Default.CheckCircle, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(t("عمل نسخة احتياطية الآن 💾", "Backup Database Now 💾"), fontSize = 11.5.sp, fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    TextButton(
                        onClick = {
                            viewModel.dismissBackupReminderPopup(forToday = true)
                            viewModel.activeSegment.value = "settings"
                            viewModel.selectedSettingSection.value = "قاعدة البيانات"
                            viewModel.databaseSettingsActiveTab.value = 3
                        }
                    ) {
                        Text(t("إعدادات التذكير ⚙️", "Reminder Settings ⚙️"), fontSize = 11.sp, color = GBRBlueMain)
                    }

                    TextButton(
                        onClick = { viewModel.dismissBackupReminderPopup(forToday = true) }
                    ) {
                        Text(t("تذكيري لاحقاً ⏳", "Remind Later ⏳"), fontSize = 11.sp, color = Color.Gray)
                    }
                }
            },
            shape = RoundedCornerShape(16.dp),
            containerColor = Color.White
        )
    }

    Box(modifier = modifier) {
        Crossfade(
            targetState = if (currentPhase == "SPLASH") {
                "SPLASH"
            } else if (deviceStatus == com.example.data.DeviceSecurityManager.STATUS_PENDING ||
                       deviceStatus == com.example.data.DeviceSecurityManager.STATUS_SUSPENDED ||
                       deviceStatus == com.example.data.DeviceSecurityManager.STATUS_BLOCKED ||
                       deviceStatus == com.example.data.DeviceSecurityManager.STATUS_OFFLINE_EXPIRED) {
                "DEVICE_BLOCKED"
            } else if (!isLoggedIn) {
                "LOGIN"
            } else {
                "HOME"
            },
            animationSpec = tween(durationMillis = 150)
        ) { phase ->
            when (phase) {
                "SPLASH" -> SplashScreen(viewModel = viewModel)
                "DEVICE_BLOCKED" -> com.example.ui.DeviceSecurityBlockScreen(
                    onVerified = {
                        com.example.data.SyncManager.initializeFirebase(context)
                        if (viewModel.syncMode.value == "realtime") {
                            com.example.data.SyncManager.startRealtimeListeners(context, viewModel.repository)
                        }
                        viewModel.triggerManualSync("all", force = true)
                    }
                )
                "LOGIN" -> LoginScreen(viewModel = viewModel)
                "HOME" -> HomeScreen(viewModel = viewModel)
            }
        }

        // إنذار الأعطال العاجلة من المتحكم (نفس فكرة وصوت تنبيه الطحن)
        com.example.ui.ControllerAlarmHost(viewModel)

        // مربع عائم يجمع الأجزاء العاملة على خطوط الإنتاج (محرك / هيدروليك / سرعة / تعبئة ماء)
        com.example.ui.EquipmentOpsFloatingBox(viewModel)

        // Global Grinding Alarm Popup
        val isGrindingAlarmActive by viewModel.isGrindingAlarmActive.collectAsState()
        val activeAlarmDetails by viewModel.activeAlarmDetails.collectAsState()

        if (isGrindingAlarmActive && activeAlarmDetails != null) {
            val details = activeAlarmDetails!!
            val ctx = androidx.compose.ui.platform.LocalContext.current
            
            DisposableEffect(details.orderId, details.stepKey) {
                var mediaPlayer: android.media.MediaPlayer? = null
                var vibrator = ctx.getSystemService(android.content.Context.VIBRATOR_SERVICE) as? android.os.Vibrator
                
                try {
                    val defaultAlarmUri: android.net.Uri = android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_NOTIFICATION)
                        ?: android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_RINGTONE)
                    mediaPlayer = android.media.MediaPlayer().apply {
                        setDataSource(ctx, defaultAlarmUri)
                        setAudioAttributes(
                            android.media.AudioAttributes.Builder()
                                .setUsage(android.media.AudioAttributes.USAGE_ALARM)
                                .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION)
                                .build()
                        )
                        isLooping = true
                        prepare()
                        start()
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                }
                
                try {
                    vibrator?.let { v ->
                        if (v.hasVibrator()) {
                            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                                val pattern = longArrayOf(0, 500, 500)
                                v.vibrate(android.os.VibrationEffect.createWaveform(pattern, 1))
                            } else {
                                @Suppress("DEPRECATION")
                                v.vibrate(longArrayOf(0, 500, 500), 1)
                            }
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                }
                
                onDispose {
                    try {
                        mediaPlayer?.let {
                            if (it.isPlaying) {
                                it.stop()
                            }
                            it.release()
                        }
                    } catch (e: Exception) {
                        e.printStackTrace()
                    }
                    try {
                        vibrator?.cancel()
                    } catch (e: Exception) {
                        e.printStackTrace()
                    }
                }
            }

            AlertDialog(
                onDismissRequest = {
                    viewModel.stopGrindingAlarm(ctx, details.orderId, details.stepKey)
                },
                title = {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Warning,
                            contentDescription = "Warning",
                            tint = ErrorRed,
                            modifier = Modifier.size(28.dp)
                        )
                        Text(
                            text = t("⏱️ انتهى وقت الطحن والخلط!", "⏱️ Grinding Time Finished!"),
                            fontWeight = FontWeight.Black,
                            fontSize = 18.sp,
                            color = GBRDarkIndigo
                        )
                    }
                },
                text = {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text(
                            text = t(
                                "تم رصد انتهاء المدة المطلوبة لطحن وتجانس المادة بنجاح في صالة الإنتاج.",
                                "The required grinding & mixing duration has been successfully completed in the production hall."
                            ),
                            fontSize = 13.sp,
                            color = Color.DarkGray,
                            lineHeight = 18.sp
                        )
                        
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                            border = BorderStroke(1.dp, Color(0xFFFDE68A)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = "📦 " + t("المادة: ", "Material: ") + details.materialName,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFFB45309)
                                )
                                if (details.orderNumber.isNotEmpty()) {
                                    Text(
                                        text = "🏭 " + t("أمر الإنتاج: ", "Order: ") + details.orderNumber,
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFFB45309)
                                    )
                                }
                                Text(
                                    text = "⏱️ " + t("المدة المطلوبة: ", "Required Duration: ") + "${details.durationMinutes} دقيقة",
                                    fontSize = 12.sp,
                                    color = Color.Gray
                                )
                            }
                        }
                    }
                },
                confirmButton = {
                    Button(
                        onClick = {
                            viewModel.stopGrindingAlarm(ctx, details.orderId, details.stepKey)
                            viewModel.selectAndNavigateToProductionOrder(details.orderId, details.stepKey)
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Text(
                            text = t("الانتقال لطلب الإنتاج ➡️", "Go to Production Order ➡️"),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White
                        )
                    }
                },
                dismissButton = {
                    TextButton(
                        onClick = {
                            viewModel.stopGrindingAlarm(ctx, details.orderId, details.stepKey)
                        }
                    ) {
                        Text(
                            text = t("موافق - إيقاف التنبيه 📴", "OK - Stop Alarm 📴"),
                            fontSize = 12.sp,
                            color = Color.Gray
                        )
                    }
                },
                shape = RoundedCornerShape(20.dp),
                containerColor = Color.White
            )
        }

        if (isOperationLoading) {
            AlertDialog(
                onDismissRequest = {},
                confirmButton = {},
                title = {
                    Text(
                        text = operationStatusMessage ?: "جاري معالجة الطلب...",
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF1E1B4B)
                    )
                },
                text = {
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        CircularProgressIndicator(color = Color(0xFF0056B3))
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "يرجى الانتظار، جاري معالجة الإجراء في الخلفية بأمان للتأكد من سلامة ومزامنة البيانات...",
                            fontSize = 11.sp,
                            color = Color.Gray,
                            lineHeight = 15.sp,
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center
                        )
                    }
                }
            )
        }
    }
}

fun formatLiveDbMessage(rawMsg: String, lang: String): String {
    if (lang == "ar") return rawMsg
    if (rawMsg.isBlank()) return rawMsg
    return when {
        rawMsg.contains("قاعدة البيانات متصلة ومزامنة تلقائية") || rawMsg.contains("مزامنة تلقائية") -> "Database Connected & Auto-Syncing ✓"
        rawMsg.contains("قاعدة البيانات متصلة ومحدثة بالكامل") || rawMsg.contains("محدثة بالكامل") -> "Database Connected & Fully Updated ✓"
        rawMsg.contains("التطبيق يعمل بالوضع المحلي المفتوح") -> "App running in open local mode. Configure cloud in settings ☁️"
        rawMsg.contains("جاري التأكد من سلامة قاعدة البيانات") -> "Checking database health and connection... ⏳"
        rawMsg.contains("جاري التحقق من وضع قاعدة البيانات") -> "Checking database status and connection... ⏳"
        rawMsg.contains("جاري التحقق الفوري من سلامة الاتصال") -> "Checking database health and connection instantly..."
        rawMsg.contains("غير متصل بالخادم: تعذر العثور على اتصال شبكة") -> "Offline: No active network connection found 🌐"
        rawMsg.contains("فشل الاتصال بقاعدة البيانات: تعذر تهيئة البيئة السحابية") -> "Database connection failed: Could not initialize cloud ❌"
        rawMsg.contains("أنت تعمل الآن بالوضع المحلي الآمن") -> "Operating in secure local offline mode 📴"
        rawMsg.startsWith("فشل الصلاحيات:") -> {
            val details = rawMsg.substringAfter("فشل الصلاحيات:").trim()
            "Permission error: $details"
        }
        rawMsg.startsWith("غير متصل بالسحابة:") -> {
            val details = rawMsg.substringAfter("غير متصل بالسحابة:").trim()
            "Disconnected from cloud: $details"
        }
        else -> rawMsg
    }
}

// --- 1. Splash Screen (شاشة التشغيل) ---
@Composable
fun SplashScreen(viewModel: GbrViewModel? = null) {
    val lang = viewModel?.appLanguage?.collectAsState()?.value ?: "ar"
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(PlusTealSoft)
            .windowInsetsPadding(WindowInsets.safeDrawing),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
            modifier = Modifier.padding(24.dp)
        ) {
            // الشعار المعتمد (نفس صورة «حول التطبيق») بالحجم نفسه تقريباً — يطابق شاشة الفتح الأصلية للنظام
            GbrOfficialLogo(scale = 1.4f)
            
            Spacer(modifier = Modifier.height(28.dp))
            
            Text(
                text = t("المنظومة الشاملة", "The Comprehensive System"),
                fontSize = 22.sp,
                color = PlusTealDark,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(14.dp))

            // شارة «PLUS» تميّز هذا التطبيق عن التطبيق الأصلي
            Box(
                modifier = Modifier
                    .background(PlusTeal, RoundedCornerShape(50))
                    .padding(horizontal = 18.dp, vertical = 5.dp)
            ) {
                Text(
                    text = "GBR PRO +",
                    fontSize = 13.sp,
                    color = Color.White,
                    fontWeight = FontWeight.Black,
                    letterSpacing = 2.sp
                )
            }
        }
    }
}

// --- 2. Login Screen (شاشة تسجيل الدخول) ---
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun LoginScreen(viewModel: GbrViewModel) {
    val error by viewModel.loginError.collectAsState()
    var selectedRole by remember { mutableStateOf("مدير النظام") }
    var dropdownExpanded by remember { mutableStateOf(false) }
    var enteredPassword by remember { mutableStateOf("") }
    var loginPasswordError by remember { mutableStateOf<String?>(null) }
    var passwordVisibility by remember { mutableStateOf(false) }
    var showCloseAppDialogInLogin by remember { mutableStateOf(false) }
    val context = LocalContext.current

    BackHandler(enabled = true) {
        showCloseAppDialogInLogin = true
    }

    if (showCloseAppDialogInLogin) {
         AlertDialog(
             onDismissRequest = { showCloseAppDialogInLogin = false },
             title = {
                 Row(
                     verticalAlignment = Alignment.CenterVertically,
                     horizontalArrangement = Arrangement.spacedBy(8.dp)
                 ) {
                     Icon(
                         imageVector = Icons.Default.ExitToApp,
                         contentDescription = null,
                         tint = GBRPinkAccent
                     )
                     Text(
                         text = "إغلاق التطبيق",
                         fontWeight = FontWeight.Bold,
                         fontSize = 18.sp,
                         color = GBRDarkIndigo
                     )
                 }
             },
             text = {
                 Text(
                     text = "هل تريد إغلاق تطبيق GBR للإنتاج؟",
                     fontSize = 14.sp,
                     color = Color(0xFF475569)
                 )
             },
             confirmButton = {
                 Button(
                     onClick = {
                         showCloseAppDialogInLogin = false
                         (context as? android.app.Activity)?.finish()
                     },
                     colors = ButtonDefaults.buttonColors(containerColor = GBRPinkAccent),
                     shape = RoundedCornerShape(10.dp)
                 ) {
                     Text("نعم", fontWeight = FontWeight.Bold, color = Color.White)
                 }
             },
             dismissButton = {
                 TextButton(
                     onClick = { showCloseAppDialogInLogin = false }
                 ) {
                     Text("لا", fontWeight = FontWeight.Medium, color = Color.Gray)
                 }
             },
