             shape = RoundedCornerShape(20.dp)
         )
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Brush.verticalGradient(listOf(PlusTealSoft, Color.White)))
            .windowInsetsPadding(WindowInsets.safeDrawing),
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .verticalScroll(rememberScrollState())
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            // Original GBR corporate logo placed at the top (First item the user sees)
            GbrOfficialLogo(
                scale = 1.25f
            )

            Spacer(modifier = Modifier.height(12.dp))

            // App Name directly below the logo
            Text(
                text = "GBR PRO +",
                fontSize = 20.sp,
                fontWeight = FontWeight.Black,
                color = PlusTeal,
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(4.dp))

            // اسم النظام الجديد + شارة تميّز التطبيق المتحوّر
            Text(
                text = "المنظومة الشاملة",
                fontSize = 14.sp,
                fontWeight = FontWeight.Medium,
                color = PlusTealDark,
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Elegant Card wrapping the input elements
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 12.dp),
                shape = RoundedCornerShape(24.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Color.White
                ),
                elevation = CardDefaults.cardElevation(defaultElevation = 6.dp),
                border = BorderStroke(1.5.dp, Color(0xFFE2E8F0))
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 24.dp, vertical = 28.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    // Title inside the card
                    Text(
                        text = "اختر المستخدم لتسجيل الدخول",
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Black,
                        color = PlusTeal,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(bottom = 6.dp)
                    )

                    val rolesList = listOf(
                        "مدير النظام",
                        "صالة الإنتاج",
                        "المختبر",
                        "المخزن"
                    )

                    // Dropdown Container
                    Box(modifier = Modifier.fillMaxWidth()) {
                        OutlinedCard(
                            onClick = { dropdownExpanded = true },
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.5.dp, PlusTeal),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(64.dp)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(horizontal = 16.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Person,
                                        contentDescription = null,
                                        tint = PlusTeal
                                    )
                                    Column {
                                        Text(
                                            text = "اسم المستخدم (الدور)",
                                            fontSize = 11.sp,
                                            color = Color.Gray
                                        )
                                        Text(
                                            text = selectedRole,
                                            fontSize = 15.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = GBRDarkIndigo
                                        )
                                    }
                                }
                                Icon(
                                    imageVector = Icons.Default.ArrowDropDown,
                                    contentDescription = null,
                                    tint = PlusTeal
                                )
                            }
                        }

                        DropdownMenu(
                            expanded = dropdownExpanded,
                            onDismissRequest = { dropdownExpanded = false },
                            modifier = Modifier
                                .fillMaxWidth(0.8f)
                                .background(Color.White)
                        ) {
                            rolesList.forEach { role ->
                                DropdownMenuItem(
                                    text = {
                                        Text(
                                            text = role,
                                            fontWeight = if (selectedRole == role) FontWeight.Bold else FontWeight.Normal,
                                            color = if (selectedRole == role) PlusTeal else GBRDarkIndigo
                                        )
                                    },
                                    onClick = {
                                        selectedRole = role
                                        dropdownExpanded = false
                                        loginPasswordError = null
                                    }
                                )
                            }
                        }
                    }

                    // Password Field
                    OutlinedTextField(
                        value = enteredPassword,
                        onValueChange = { 
                            enteredPassword = it
                            loginPasswordError = null
                        },
                        label = { Text("كلمة المرور") },
                        singleLine = true,
                        visualTransformation = if (passwordVisibility) VisualTransformation.None else PasswordVisualTransformation(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword),
                        keyboardActions = KeyboardActions(onDone = {
                            if (enteredPassword == "1234") {
                                val user = when (selectedRole) {
                                    "مدير النظام" -> GbrViewModel.CustomUser(id = "admin", name = "مدير النظام", role = "مدير النظام", password = "1234", isSupervisor = true, username = "admin", fullName = "مدير النظام", isActive = true)
                                    "صالة الإنتاج" -> GbrViewModel.CustomUser(id = "production", name = "صالة الإنتاج", role = "عامل صالة الإنتاج", password = "1234", isSupervisor = false, username = "operator", fullName = "صالة الإنتاج", isActive = true)
                                    "المختبر" -> GbrViewModel.CustomUser(id = "lab", name = "المختبر", role = "المختبر", password = "1234", isSupervisor = false, username = "lab_tech", fullName = "فني المختبر", isActive = true)
                                    "المخزن" -> GbrViewModel.CustomUser(id = "warehouse", name = "المخزن", role = "المخزن", password = "1234", isSupervisor = false, username = "warehouse_keeper", fullName = "أمين المخزن", isActive = true)
                                    else -> GbrViewModel.CustomUser(id = "temp", name = selectedRole, role = selectedRole, password = "1234", isSupervisor = false, username = "user", fullName = selectedRole, isActive = true)
                                }
                                viewModel.currentUser.value = user
                                viewModel.isLoggedIn.value = true
                                enteredPassword = ""
                                loginPasswordError = null
                            } else {
                                loginPasswordError = "كلمة المرور غير صحيحة."
                            }
                        }),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color(0xFF0F172A),
                            unfocusedTextColor = Color(0xFF0F172A),
                            focusedLabelColor = PlusTeal,
                            unfocusedLabelColor = Color(0xFF64748B),
                            focusedBorderColor = PlusTeal,
                            unfocusedBorderColor = Color(0xFFCBD5E1)
                        ),
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(64.dp),
                        leadingIcon = { Icon(Icons.Default.Lock, contentDescription = "Lock", tint = PlusTeal) },
                        trailingIcon = {
                            IconButton(onClick = { passwordVisibility = !passwordVisibility }) {
                                Icon(
                                    imageVector = if (passwordVisibility) Icons.Default.Check else Icons.Default.Lock,
                                    contentDescription = "عرض كلمة المرور",
                                    tint = PlusTeal
                                )
                            }
                        }
                    )

                    if (loginPasswordError != null) {
                        Text(
                            text = loginPasswordError!!,
                            color = ErrorRed,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center,
                            modifier = Modifier.padding(top = 4.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    // Login button styled matching brand identity
                    Button(
                        onClick = {
                            if (enteredPassword == "1234") {
                                val user = when (selectedRole) {
                                    "مدير النظام" -> GbrViewModel.CustomUser(id = "admin", name = "مدير النظام", role = "مدير النظام", password = "1234", isSupervisor = true, username = "admin", fullName = "مدير النظام", isActive = true)
                                    "صالة الإنتاج" -> GbrViewModel.CustomUser(id = "production", name = "صالة الإنتاج", role = "عامل صالة الإنتاج", password = "1234", isSupervisor = false, username = "operator", fullName = "صالة الإنتاج", isActive = true)
                                    "المختبر" -> GbrViewModel.CustomUser(id = "lab", name = "المختبر", role = "المختبر", password = "1234", isSupervisor = false, username = "lab_tech", fullName = "فني المختبر", isActive = true)
                                    "المخزن" -> GbrViewModel.CustomUser(id = "warehouse", name = "المخزن", role = "المخزن", password = "1234", isSupervisor = false, username = "warehouse_keeper", fullName = "أمين المخزن", isActive = true)
                                    else -> GbrViewModel.CustomUser(id = "temp", name = selectedRole, role = selectedRole, password = "1234", isSupervisor = false, username = "user", fullName = selectedRole, isActive = true)
                                }
                                viewModel.currentUser.value = user
                                viewModel.isLoggedIn.value = true
                                enteredPassword = ""
                                loginPasswordError = null
                            } else {
                                loginPasswordError = "كلمة المرور غير صحيحة."
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(58.dp)
                            .clip(RoundedCornerShape(16.dp))
                            .background(
                                Brush.horizontalGradient(
                                    colors = listOf(PlusTeal, PlusTealDark)
                                )
                            ),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = Color.Transparent
                        ),
                        contentPadding = PaddingValues()
                    ) {
                        Box(
                            modifier = Modifier.fillMaxSize(),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = "تسجيل الدخول",
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Version info at the bottom of the login screen
            Text(
                text = "الإصدار ${com.example.BuildConfig.VERSION_NAME}",
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = PlusTeal,
                modifier = Modifier.padding(bottom = 8.dp)
            )
        }
    }
}

// --- 3. Home Screen (الشاشة الرئيسية) ---
@Composable
fun HomeScreen(viewModel: GbrViewModel) {
    val activeSegment by viewModel.activeSegment.collectAsState()
    val currentUser by viewModel.currentUser.collectAsState()
    val pendingDevicesList by com.example.data.DeviceSecurityManager.pendingDevices.collectAsState()
    val coroutineScope = rememberCoroutineScope()
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val successApproveMsg = if (lang == "ar") "🎉 تم اعتماد الجهاز وتفعيل المزامنة!" else "🎉 Device approved!"
    val failApproveMsg = if (lang == "ar") "❌ تعذر الاعتماد، تحقق من الإنترنت" else "❌ Approval failed, check connection"

    var showLogoutConfirmDialog by remember { mutableStateOf(false) }
    val context = LocalContext.current
    val role = currentUser?.role
    val isSupervisorOrAdmin = role == "مدير النظام" || role == "مشرف الإنتاج" || currentUser?.isSupervisor == true

    val isRoleWithDedicatedDashboard = role == "المخزن" || role == "المختبر" || role == "عامل صالة الإنتاج" || role == "صالة الإنتاج"

    // Master Back Button Handler for the portal page / user dashboard -> prompts for logout
    BackHandler(enabled = activeSegment == null || isRoleWithDedicatedDashboard) {
        showLogoutConfirmDialog = true
    }

    BackHandler(enabled = activeSegment == "operational_alerts") {
        viewModel.showSegment(viewModel.previousSegmentForAlerts)
    }

    if (showLogoutConfirmDialog) {
         val isDark = false
         val userDisplayName = currentUser?.fullName?.takeIf { it.isNotBlank() } ?: currentUser?.name ?: currentUser?.role ?: ""
         AlertDialog(
             onDismissRequest = { showLogoutConfirmDialog = false },
             title = {
                 Row(
                     verticalAlignment = Alignment.CenterVertically,
                     horizontalArrangement = Arrangement.spacedBy(8.dp)
                 ) {
                     Icon(
                         imageVector = Icons.Default.ExitToApp,
                         contentDescription = null,
                         tint = GBRPinkAccent
                     )
                     Text(
                         text = "تسجيل الخروج",
                         fontWeight = FontWeight.Bold,
                         fontSize = 18.sp,
                         color = if (isDark) Color.White else GBRDarkIndigo
                     )
                 }
             },
             text = {
                 Text(
                     text = if (userDisplayName.isNotEmpty())
                         "هل أنت متأكد من رغبتك في تسجيل الخروج من حساب ($userDisplayName) والعودة لشاشة الدخول؟"
                     else
                         "هل أنت متأكد من رغبتك في تسجيل الخروج والعودة لشاشة الدخول؟",
                     fontSize = 14.sp,
                     color = if (isDark) Color.LightGray else Color(0xFF475569)
                 )
             },
             confirmButton = {
                 Button(
                     onClick = {
                         showLogoutConfirmDialog = false
                         viewModel.logout()
                     },
                     colors = ButtonDefaults.buttonColors(containerColor = GBRPinkAccent),
                     shape = RoundedCornerShape(10.dp)
                 ) {
                     Text("تسجيل الخروج", fontWeight = FontWeight.Bold, color = Color.White)
                 }
             },
             dismissButton = {
                 TextButton(
                     onClick = { showLogoutConfirmDialog = false }
                 ) {
                     Text("إلغاء", fontWeight = FontWeight.Medium, color = Color.Gray)
                 }
             },
             containerColor = if (isDark) IndustrialDarkSurface else Color.White,
             shape = RoundedCornerShape(20.dp)
         )
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .statusBarsPadding()
            .navigationBarsPadding()
    ) {
        // App Header Toolbar (أعلى الشاشة الرئيسية)
        HomeHeader(
            viewModel = viewModel,
            onLogoutClick = { showLogoutConfirmDialog = true }
        )

        // Prominent pending device alert banner for admin only
        if (pendingDevicesList.isNotEmpty() && isSupervisorOrAdmin) {
            val pendingItem = pendingDevicesList.first()
            var isProcessingApproval by remember { mutableStateOf(false) }
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 12.dp, vertical = 6.dp),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(containerColor = Color(0xFFFEF3C7)),
                border = BorderStroke(1.5.dp, Color(0xFFF59E0B))
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp, vertical = 8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier.weight(1f)
                    ) {
                        Text("⚡", fontSize = 20.sp)
                        Spacer(modifier = Modifier.width(8.dp))
                        Column {
                            Text(
                                text = t("طلب اعتماد هاتف جديد (${pendingDevicesList.size}) 🔌", "New Device Approval Request (${pendingDevicesList.size}) 🔌"),
                                fontWeight = FontWeight.Bold,
                                fontSize = 12.sp,
                                color = Color(0xFF92400E)
                            )
                            Text(
                                text = "${pendingItem.deviceName} (${if (pendingItem.deviceId.length > 12) pendingItem.deviceId.take(12) + "..." else pendingItem.deviceId})",
                                fontSize = 10.5.sp,
                                color = Color(0xFFB45309)
                            )
                        }
                    }
                    
                    Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
                        Button(
                            onClick = {
                                coroutineScope.launch {
                                    isProcessingApproval = true
                                    val ok = com.example.data.DeviceSecurityManager.updateDeviceStatusOnCloud(
                                        context,
                                        pendingItem.deviceId,
                                        com.example.data.DeviceSecurityManager.STATUS_APPROVED
                                    )
                                    isProcessingApproval = false
                                    if (ok) {
                                        Toast.makeText(context, successApproveMsg, Toast.LENGTH_SHORT).show()
                                    } else {
                                        Toast.makeText(context, failApproveMsg, Toast.LENGTH_SHORT).show()
                                    }
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A)),
                            shape = RoundedCornerShape(8.dp),
                            contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp),
                            modifier = Modifier.height(32.dp),
                            enabled = !isProcessingApproval
                        ) {
                            if (isProcessingApproval) {
                                CircularProgressIndicator(color = Color.White, modifier = Modifier.size(14.dp))
                            } else {
                                Text(t("اعتماد 📥", "Approve 📥"), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                        
                        OutlinedButton(
                            onClick = {
                                viewModel.activeSegment.value = "settings"
                                viewModel.selectedSettingSection.value = "إدارة الأجهزة والأمان"
                            },
                            shape = RoundedCornerShape(8.dp),
                            contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp),
                            modifier = Modifier.height(32.dp)
                        ) {
                            Text(t("عرض الكل 🛡️", "View All 🛡️"), fontSize = 10.sp, color = Color(0xFF92400E))
                        }
                    }
                }
            }
        }

        // Navigation flow switcher based on selected segments
        Box(modifier = Modifier.weight(1f)) {
            val role = currentUser?.role
            if (activeSegment == "operational_alerts") {
                com.example.ui.OperationalAlertsPanel(viewModel = viewModel)
            } else if (role == "عامل صالة الإنتاج" || role == "صالة الإنتاج") {
                ProductionFloorOperatorDashboard(viewModel = viewModel)
            } else if (role == "المختبر") {
                LaboratoryDashboard(viewModel = viewModel)
            } else if (role == "المخزن") {
                // أمين المخزن: وحدة المخزون (فيها تبويب «الكتالوج» لإدارة المواد الخام كما كان)
                com.example.ui.InventoryPanel(viewModel = viewModel)
            } else if (role == "مدير النظام" || role == "مشرف الإنتاج" || currentUser?.isSupervisor == true) {
                when (activeSegment) {
                    null -> MainDeckSelector(viewModel = viewModel)
                    "materials" -> MaterialsPanel(viewModel = viewModel)
                    "inventory" -> com.example.ui.InventoryPanel(viewModel = viewModel)
                    "formulations" -> FormulationsPanel(viewModel = viewModel)
                    "production" -> com.example.ui.ProductionPanel(viewModel = viewModel)
                    "reports" -> ReportsPanel(viewModel = viewModel)
                    "settings" -> SettingsPanel(viewModel = viewModel)
                    "app_info" -> AppInfoPanel(viewModel = viewModel)
                    "recipe" -> RecipePanel(viewModel = viewModel)
                    "equipment_control" -> com.example.ui.EquipmentControlPanel(viewModel = viewModel)
                    "research_development" -> com.example.ui.ResearchAndDevelopmentPanel(viewModel = viewModel)
                    "sync_monitoring" -> com.example.ui.SyncMonitoringPanel(viewModel = viewModel)
                    "laboratory_management" -> com.example.ui.LaboratoryPanel(viewModel = viewModel)
                    "recycle_bin" -> com.example.ui.RecycleBinPanel(viewModel = viewModel)
                }
            } else {
                // When currentUser is null (during logout / unauthenticated transition), display a neutral background
                // so the admin dashboard (MainDeckSelector) NEVER flashes or appears momentarily
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(MaterialTheme.colorScheme.background)
                )
            }
        }

        com.example.ui.UpdateAvailableNotice(enabled = viewModel.currentUser.collectAsState().value != null)
        // Beautiful bottom status footer displaying the version number clearly
        FooterInfoBar(viewModel)
    }
}

// --- Header component with LOGO & Logout (أعلى الشاشة الرئيسية) ---
@Composable
fun HomeHeader(
    viewModel: GbrViewModel,
    onLogoutClick: () -> Unit = {}
) {
    val activeSegment by viewModel.activeSegment.collectAsState()
    val currentUser by viewModel.currentUser.collectAsState()
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val isDark = false
    val role = currentUser?.role
    val isSupervisorOrAdmin = role == "مدير النظام" || role == "مشرف الإنتاج" || currentUser?.isSupervisor == true

    Surface(
        tonalElevation = 2.dp,
        color = if (isDark) IndustrialDarkSurface else Color.White,
        modifier = Modifier
            .fillMaxWidth()
            .border(
                width = 1.dp,
                color = if (isDark) IndustrialBorderDark else IndustrialBorder,
                shape = RoundedCornerShape(0.dp)
            )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 3.dp), // Reduced vertical spacing for minimal height
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.clickable { if (isSupervisorOrAdmin) viewModel.showSegment(null) }
            ) {
                if (activeSegment != null && isSupervisorOrAdmin) {
                    IconButton(onClick = { viewModel.showSegment(null) }) {
                        Icon(
                            Icons.Default.ArrowForward, // RTL back arrow direction
                            contentDescription = t("الرجوع", "Back"),
                            tint = if (isDark) Color.White else GBRBlueMain
                        )
                    }
                }

                // Mini elegant brand logo image
                GbrOfficialLogo(
                    scale = 0.32f, // Minimized scale
                )
                
                Spacer(modifier = Modifier.width(8.dp))
                
                Text(
                    text = "إدارة الإنتاج والعمليات",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = if (isDark) Color.White else GBRBlueMain
                )
            }

            // Right side of Header: Operational Alerts Notification + System Settings Icon + Logout Button
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                if (currentUser != null) {
                    val isGrindingAlarmActive by viewModel.isGrindingAlarmActive.collectAsState()
                    if (isGrindingAlarmActive) {
                        val infiniteTransition = androidx.compose.animation.core.rememberInfiniteTransition(label = "alarm")
                        val alpha by infiniteTransition.animateFloat(
                            initialValue = 0.4f,
                            targetValue = 1.0f,
                            animationSpec = androidx.compose.animation.core.infiniteRepeatable(
                                animation = androidx.compose.animation.core.tween(500, easing = androidx.compose.animation.core.LinearEasing),
                                repeatMode = androidx.compose.animation.core.RepeatMode.Reverse
                            ),
                            label = "alarm_alpha"
                        )
                        
                        val context = androidx.compose.ui.platform.LocalContext.current
                        Button(
                            onClick = { viewModel.stopGrindingAlarm(context) },
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Red.copy(alpha = alpha)),
                            contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp),
                            modifier = Modifier
                                .height(32.dp)
                                .padding(end = 4.dp),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Warning,
                                    contentDescription = null,
                                    tint = Color.White,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = "إيقاف التنبيه 📴",
                                    color = Color.White,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }

                    val alerts by viewModel.allOperationalAlerts.collectAsState(initial = emptyList())
                    val activeOrders by viewModel.productionOrders.collectAsState(initial = emptyList())
                    val activeTimers by viewModel.activeGrindingTimers.collectAsState(initial = emptyList())
                    val line1Status by viewModel.line1Status.collectAsState()
                    val line2Status by viewModel.line2Status.collectAsState()
                    
                    val activeAlertsCount = remember(alerts, activeOrders, activeTimers, line1Status, line2Status) {
                        val activeFillsCount = (if (line1Status?.fill_active == true) 1 else 0) + (if (line2Status?.fill_active == true) 1 else 0)
                        alerts.count { it.status == "ACTIVE" } +
                        activeOrders.count { it.status == "قيد التنفيذ" } +
                        activeTimers.size +
                        activeFillsCount
                    }
                    
                    // Bell icon for Operational Alerts with Red Badge overlay
                    Box(
                        modifier = Modifier
                            .padding(end = 4.dp)
                            .size(38.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        IconButton(
                            onClick = { viewModel.showSegment("operational_alerts") },
                            modifier = Modifier.size(36.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Notifications,
                                contentDescription = "التنبيهات التشغيلية",
                                tint = GBRBlueMain,
                                modifier = Modifier.size(24.dp)
                            )
                        }
                        if (activeAlertsCount > 0) {
                            Box(
                                modifier = Modifier
                                    .align(Alignment.TopEnd)
                                    .offset(x = (-2).dp, y = (2).dp)
                                    .background(Color.Red, shape = CircleShape)
                                    .sizeIn(minWidth = 16.dp, minHeight = 16.dp)
                                    .padding(horizontal = 4.dp, vertical = 1.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = activeAlertsCount.toString(),
                                    color = Color.White,
                                    fontSize = 9.sp,
                                    fontWeight = FontWeight.Bold,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    }

                    if (isSupervisorOrAdmin) {
                        IconButton(
                            onClick = { 
                                viewModel.showSegment("equipment_control")
                            },
                            modifier = Modifier.size(34.dp).clip(RoundedCornerShape(8.dp))
                        ) {
                            Icon(
                                imageVector = Icons.Default.SettingsRemote,
                                contentDescription = "قسم التحكم بالمعدات",
                                tint = GBRBlueMain,
                                modifier = Modifier.size(22.dp)
                            )
                        }
                    }

                    // Direct logout button for all users
                    IconButton(
                        onClick = onLogoutClick,
                        modifier = Modifier.size(34.dp).clip(RoundedCornerShape(8.dp))
                    ) {
                        Icon(
                            imageVector = Icons.Default.ExitToApp,
                            contentDescription = t("تسجيل الخروج", "Logout"),
                            tint = Color(0xFFEF4444),
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            }
        }
    }
}
// --- User Context Area (شريط معلومات المشغل) ---
@Composable
fun UserContextArea(viewModel: GbrViewModel) {
    val username by viewModel.username.collectAsState()
    val isDark = false
    
    Surface(
        color = if (isDark) IndustrialDarkSurface.copy(alpha = 0.5f) else Color(0x66FFFFFF),
        modifier = Modifier
            .fillMaxWidth()
            .border(
                width = 1.dp,
                color = if (isDark) IndustrialBorderDark.copy(alpha = 0.4f) else Color(0xFFF1F5F9),
                shape = RoundedCornerShape(0.dp)
            )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(28.dp)
                        .clip(RoundedCornerShape(14.dp))
                        .background(if (isDark) Color(0xFF334155) else Color(0xFFF1F5F9)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Person,
                        contentDescription = null,
                        tint = if (isDark) Color.LightGray else Color(0xFF64748B),
                        modifier = Modifier.size(16.dp)
                    )
                }
                Text(
                    text = "المشغل: ${if (username.isBlank()) "admin" else username}",
                    fontSize = 13.sp,
                    fontWeight = FontWeight.SemiBold,
                    color = if (isDark) Color.White else Color(0xFF334155)
                )
            }
            
            Text(
                text = "محطة الإنتاج رقم 1",
                fontSize = 12.sp,
                color = if (isDark) Color.Gray else Color(0xFF94A3B8),
                fontWeight = FontWeight.Medium
            )
        }
    }
}

// --- Footer Connection Info Bar ---
@Composable
fun FooterInfoBar(viewModel: GbrViewModel) {
    val isDark = false
    val liveDbState by viewModel.liveDbState.collectAsState()
    val lang by viewModel.appLanguage.collectAsState()
    fun t(key: String, default: String): String {
        val jsonVal = com.example.ui.theme.JsonI18n.t(key)
        if (jsonVal.isNotEmpty()) return jsonVal
        return if (lang == "ar") key else default
    }
    
    val (dotColor, statusText) = when (liveDbState) {
        "connected_healthy" -> Pair(Color(0xFF10B981), t("قاعدة البيانات متصلة وسليمة ✅", "Database Connected & Healthy ✅"))
        "disconnected" -> Pair(Color(0xFFEF4444), t("عطل اتصال: قاعدة البيانات غير متصلة ⚠️", "Connection Failure: Database Offline ⚠️"))
        "checking" -> Pair(Color(0xFFF59E0B), t("جاري التحقق من قاعدة البيانات... ⏳", "Checking Database... ⏳"))
        "structure_error" -> Pair(Color(0xFFEF4444), t("خلل هيكلي في السحابة 🛠️", "Cloud Structural Error 🛠️"))
        "not_configured", "local_only" -> Pair(Color(0xFF64748B), t("الوضع المحلي: السحابة غير نشطة 📴", "Local Mode: Cloud Inactive 📴"))
        else -> Pair(Color(0xFF10B981), t("قاعدة البيانات متصلة وسليمة ✅", "Database Connected & Healthy ✅"))
    }

    Surface(
        color = if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC),
        modifier = Modifier.fillMaxWidth()
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(8.dp)
                        .clip(RoundedCornerShape(4.dp))
                        .background(dotColor)
                )
                Text(
                    text = statusText,
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF64748B)
                )
            }
            Text(
                text = t("version_label", "Version") + " " + com.example.BuildConfig.VERSION_NAME,
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                color = GBRBlueMain
            )
        }
    }
}

// --- Medium Facility Button (أزرار متوسطة الحجم لشبكة الملاحة الثنائية) ---
@Composable
fun MediumFacilityButton(
    title: String,
    subtitle: String,
    icon: ImageVector,
    iconBgColor: Color,
    iconColor: Color,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    emoji: String? = null
) {
    val isDark = false
    val cardBg = if (isDark) IndustrialDarkSurface else Color.White
    val cardBorder = BorderStroke(2.dp, if (isDark) IndustrialBorderDark else IndustrialBorder)
    val titleColor = if (isDark) Color.White else GBRDarkIndigo
    val subtitleColor = Color.Gray

    Card(
        onClick = onClick,
        modifier = modifier.height(115.dp),
        shape = RoundedCornerShape(20.dp),
        colors = CardDefaults.cardColors(containerColor = cardBg),
        border = cardBorder,
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(12.dp),
            verticalArrangement = Arrangement.Center,
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                // Icon emblem
                Box(
                    modifier = Modifier
                        .size(36.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(iconBgColor),
                    contentAlignment = Alignment.Center
                ) {
                    if (emoji != null) {
                        Text(text = emoji, fontSize = 20.sp)
                    } else {
                        Icon(
                            imageVector = icon,
                            contentDescription = null,
                            modifier = Modifier.size(20.dp),
                            tint = iconColor
                        )
                    }
                }
                
                Text(
                    text = title,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = titleColor,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
            
            Spacer(modifier = Modifier.height(6.dp))
            
            Text(
                text = subtitle,
                fontSize = 11.sp,
                color = subtitleColor,
                textAlign = TextAlign.Center,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                lineHeight = 14.sp,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

// --- Main Menu Buttons (الأزرار المسؤولة عن الملاحة) ---
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MainDeckSelector(viewModel: GbrViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val isDark = false
    
    val homeSyncMode by viewModel.syncMode.collectAsState()
    val liveDbState by viewModel.liveDbState.collectAsState()
    val liveDbMessage by viewModel.liveDbMessage.collectAsState()
    val rawMaterialsLast by viewModel.syncLastRawMaterials.collectAsState()
    val formulationsLast by viewModel.syncLastFormulations.collectAsState()
    val ordersLast by viewModel.syncLastProductionOrders.collectAsState()
    val homePendingSyncCount by viewModel.pendingSyncCount.collectAsState()
    val pendingSyncItems by viewModel.pendingSyncItems.collectAsState()

    var showPendingSyncItemsDialog by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    var isRefreshing by remember { mutableStateOf(false) }

    val lastUpdateTime = remember(rawMaterialsLast, formulationsLast, ordersLast, lang) {
        val notSyncedText = if (lang == "ar") "لم يتم المزامنة بعد" else "Not synced yet"
        val unknownText = if (lang == "ar") "غير معروف" else "Unknown"
        val list = listOf(rawMaterialsLast, formulationsLast, ordersLast).filter { it != "لم يتم المزامنة بعد" && !it.contains("Never") && it != "Not synced yet" }
        if (list.isEmpty()) {
            notSyncedText
        } else {
            list.firstOrNull() ?: unknownText
        }
    }

    PullToRefreshBox(
        isRefreshing = isRefreshing,
        onRefresh = {
            isRefreshing = true
            scope.launch {
                viewModel.liveDbState.value = "checking"
                viewModel.liveDbMessage.value = if (lang == "ar") "جاري التحقق الفوري من سلامة الاتصال..." else "Checking database connection instantly..."
                viewModel.startContinuousDatabaseHealthCheck()
                delay(1500)
                isRefreshing = false
            }
        },
        modifier = Modifier.fillMaxSize()
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(20.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(
                    containerColor = when (homeSyncMode) {
                        "local" -> Color(0xFFF1F5F9)
                        "manual" -> Color(0xFFFEF3C7)
                        else -> when (liveDbState) {
                            "checking" -> Color(0xFFEFF6FF)
                            "connected_healthy" -> Color(0xFFECFDF5)
                            "disconnected" -> Color(0xFFFEF2F2)
                            "structure_error" -> Color(0xFFFFF7ED)
                            "not_configured" -> Color(0xFFF8FAFC)
                            else -> Color(0xFFECFDF5)
                        }
                    }
                ),
                border = BorderStroke(
                    width = 1.dp,
                    color = when (homeSyncMode) {
                        "local" -> Color(0xFFCBD5E1)
                        "manual" -> Color(0xFFFDBA74)
                        else -> when (liveDbState) {
                            "checking" -> Color(0xFFBFDBFE)
                            "connected_healthy" -> Color(0xFFA7F3D0)
                            "disconnected" -> Color(0xFFFCA5A5)
                            "structure_error" -> Color(0xFFFED7AA)
                            "not_configured" -> Color(0xFFE2E8F0)
                            else -> Color(0xFFA7F3D0)
                        }
                    }
                )
            ) {
                Row(
                    modifier = Modifier.padding(14.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Color indicator dot
                    val dotColor = when (homeSyncMode) {
                        "local" -> Color.Gray
                        "manual" -> WarningOrange
                        else -> when (liveDbState) {
                            "checking" -> GBRBlueMain
                            "connected_healthy" -> SuccessGreen
                            "disconnected" -> Color(0xFFEF4444)
                            "structure_error" -> Color(0xFFF97316)
                            "not_configured" -> Color(0xFF94A3B8)
                            else -> SuccessGreen
                        }
                    }
                    
                    Box(
                        modifier = Modifier
                            .size(10.dp)
                            .background(dotColor, CircleShape)
                            .border(1.5.dp, Color.White, CircleShape)
                    )

                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = when(homeSyncMode) {
                                "realtime" -> when (liveDbState) {
                                    "checking" -> t("جاري التحقق من السحابة... ⏳", "Checking Cloud... ⏳")
                                    "connected_healthy" -> t("مزامنة مباشرة: متصلة وسليمة ✓", "Live Sync: Connected & Healthy ✓")
                                    "disconnected" -> t("عطل اتصال: قاعدة البيانات غير متصلة ⚠️", "Connection Fault: DB Disconnected ⚠️")
                                    "structure_error" -> t("خلل هيكلي: قاعدة البيانات وبحاجة لإصلاح 🛠️", "Structural Fault: DB Repair Required 🛠️")
                                    "not_configured" -> t("وضع محلي مفتوح: السحاب غير نشط 📴", "Local Mode Active: Cloud Offline 📴")
                                    else -> t("متصل بالسحابة (مزامنة مباشرة 🔄)", "Connected to Cloud (Live Sync 🔄)")
                                }
                                "manual" -> t("مزامنة يدوية (عند الطلب ☁️)", "Manual Sync (On Demand ☁️)")
                                else -> t("وضع تشغيل محلي (أوفلاين 📴)", "Local Run Mode (Offline 📴)")
                            },
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )

                        Spacer(modifier = Modifier.height(2.dp))

                        Text(
                            text = if (homeSyncMode == "realtime") formatLiveDbMessage(liveDbMessage, lang) else t("آخر تحديث: $lastUpdateTime", "Last update: $lastUpdateTime"),
                            fontSize = 10.sp,
                            color = Color.DarkGray,
                            lineHeight = 13.sp,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    if (homePendingSyncCount > 0) {
                        Box(
                            modifier = Modifier
                                .background(Color(0xFFFEE2E2), RoundedCornerShape(6.dp))
                                .clickable { showPendingSyncItemsDialog = true }
                                .padding(horizontal = 8.dp, vertical = 4.dp)
                        ) {
                            Text(
                                text = t("$homePendingSyncCount معلقة", "$homePendingSyncCount pending"),
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFFEF4444)
                            )
                        }
                    }

                    IconButton(
                        onClick = {
                            viewModel.liveDbState.value = "checking"
                            viewModel.liveDbMessage.value = if (lang == "ar") "جاري التحقق الفوري من سلامة الاتصال بقاعدة البيانات..." else "Checking database health and connection instantly..."
                            viewModel.startContinuousDatabaseHealthCheck()
                            android.widget.Toast.makeText(
                                context,
                                if (lang == "ar") "جاري فحص وتحديث حالة الاتصال بالقاعدة السحابية..." else "Testing and updating active cloud server status...",
                                android.widget.Toast.LENGTH_SHORT
                            ).show()
                        },
                        modifier = Modifier
                            .size(32.dp)
                            .background(Color.White, CircleShape)
                            .border(1.dp, Color.LightGray.copy(alpha = 0.5f), CircleShape)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Refresh,
                            contentDescription = "تحديث فوري لاتصال السحابة",
                            tint = GBRBlueMain,
                            modifier = Modifier.size(16.dp)
                        )
                    }
                }
            }

        if (showPendingSyncItemsDialog) {
            AlertDialog(
                onDismissRequest = { showPendingSyncItemsDialog = false },
                title = {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Warning,
                            contentDescription = null,
                            tint = Color(0xFFEF4444),
                            modifier = Modifier.size(24.dp)
                        )
                        Text(
                            text = t("السجلات المعلقة بانتظار المزامنة", "Pending Sync Queue"),
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )
                    }
                },
                text = {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text(
                            text = t(
                                "السجلات أدناه لم يتم مزامنتها مع السحابة بعد. يمكنك الضغط على أيقونة التحديث بجانب كل سجل لمزامنته يدوياً وفورياً.",
                                "The records below have not been synced to the cloud yet. You can click the sync icon next to each record to sync it manually and instantly."
                            ),
                            fontSize = 11.sp,
                            color = Color.Gray,
                            lineHeight = 15.sp
                        )
                        
                        Spacer(modifier = Modifier.height(4.dp))
                        
                        if (pendingSyncItems.isEmpty()) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 16.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = t("🎉 كل السجلات مزامنة بالكامل!", "🎉 All records are perfectly synced!"),
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = SuccessGreen
                                )
                            }
                        } else {
                            LazyColumn(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .heightIn(max = 280.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                items(pendingSyncItems) { item ->
                                    val arabicType = when (item.entityType) {
                                        "raw_material" -> "مادة خام"
                                        "formulation" -> "تركيبة إنتاجية"
                                        "production_order" -> "أمر تشغيل/إنتاج"
                                        "development_project" -> "مشروع بحث وتطوير R&D"
                                        "quality_test" -> "فحص جودة"
                                        "production_adjustment" -> "تعديل كميات إنتاج"
                                        "lab_session" -> "جلسة فحص مخبري"
                                        "lab_test" -> "تحليل مختبري"
                                        else -> item.entityType
                                    }
                                    
                                    val englishType = when (item.entityType) {
                                        "raw_material" -> "Raw Material"
                                        "formulation" -> "Formulation"
                                        "production_order" -> "Production Order"
                                        "development_project" -> "R&D Project"
                                        "quality_test" -> "Quality Test"
                                        "production_adjustment" -> "Production Adjustment"
                                        "lab_session" -> "Lab Session"
                                        "lab_test" -> "Lab Test"
                                        else -> item.entityType
                                    }
                                    
                                    val displayType = t(arabicType, englishType)
                                    
                                    Surface(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(10.dp),
                                        color = Color(0xFFF8FAFC),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(horizontal = 10.dp, vertical = 8.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(
                                                    text = displayType,
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = GBRDarkIndigo
                                                )
                                                Spacer(modifier = Modifier.height(2.dp))
                                                Text(
                                                    text = "ID: ${item.id.take(8)}...",
                                                    fontSize = 10.sp,
                                                    color = Color.Gray
                                                )
                                            }
                                            
                                            Box(
                                                modifier = Modifier.size(48.dp),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                var isSyncingItem by remember { mutableStateOf(false) }
                                                val coroutineScope = rememberCoroutineScope()
                                                
                                                IconButton(
                                                    onClick = {
                                                        coroutineScope.launch {
                                                            isSyncingItem = true
                                                            val syncResult = viewModel.triggerSingleSyncSuspending(item)
                                                            isSyncingItem = false
                                                            syncResult.fold(
                                                                onSuccess = {
                                                                    android.widget.Toast.makeText(
                                                                        context,
                                                                        if (lang == "ar") "✅ تمت مزامنة السجل بنجاح!" else "✅ Record synced successfully!",
                                                                        android.widget.Toast.LENGTH_SHORT
                                                                    ).show()
                                                                },
                                                                onFailure = { error ->
                                                                    android.widget.Toast.makeText(
                                                                        context,
                                                                        if (lang == "ar") "❌ فشلت المزامنة: ${error.localizedMessage}" else "❌ Sync failed: ${error.localizedMessage}",
                                                                        android.widget.Toast.LENGTH_LONG
                                                                    ).show()
                                                                }
                                                            )
                                                        }
                                                    },
                                                    modifier = Modifier.size(36.dp)
                                                ) {
                                                    if (isSyncingItem) {
                                                        CircularProgressIndicator(
                                                            modifier = Modifier.size(18.dp),
                                                            strokeWidth = 2.dp,
                                                            color = GBRBlueMain
                                                        )
                                                    } else {
                                                        Icon(
                                                            imageVector = Icons.Default.Refresh,
                                                            contentDescription = t("مزامنة السجل", "Sync Record"),
                                                            tint = GBRBlueMain,
                                                            modifier = Modifier.size(20.dp)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                
                                item {
                                    Spacer(modifier = Modifier.height(12.dp))
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(12.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                                        border = BorderStroke(1.dp, Color(0xFFFDE68A))
                                    ) {
                                        Column(modifier = Modifier.padding(12.dp)) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text(text = "💡", fontSize = 16.sp)
                                                Text(
                                                    text = t("دليل حل مشاكل السجلات المعلقة", "Pending Sync Troubleshooting Guide"),
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color(0xFFB45309)
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(8.dp))
                                            Text(
                                                text = t(
                                                    "لماذا تظهر السجلات معلقة رغم أن حالة الاتصال خضراء وسليمة؟\n" +
                                                    "شريط الحالة العلوي يؤكد قدرة التطبيق على الاتصال وقراءة السحابة (Read). لكن رفع السجلات (Write) قد يفشل أو ينتهي مهلته (8 ثوانٍ) للأسباب التالية:\n\n" +
                                                    "1️⃣ صلاحيات الكتابة مقيدة: قد تكون قواعد الحماية (Firestore Security Rules) تمنع الكتابة.\n" +
                                                    "👈 الحل: افتح Firebase Console واضبط القواعد لتسمح بالكتابة: allow read, write: if true;\n\n" +
                                                    "2️⃣ انقطاع أو بطء الإنترنت: تفشل الكتابة الفورية وتظهر رسالة انتهاء المهلة.\n" +
                                                    "👈 الحل: تحقق من جودة شبكة الإنترنت والاتصال ثم أعد المحاولة.\n\n" +
                                                    "3️⃣ إعدادات المشروع غير مطابقة: إذا كنت تستخدم المشروع التجريبي الافتراضي دون ضبط مشروعك الخاص.\n" +
                                                    "👈 الحل: اذهب إلى الإعدادات > ضبط السحابة وتأكد من كتابة Project ID و API Key و App ID الصحيحة لمشروعك.",
                                                    "Why do records remain pending while the connection is green & healthy?\n" +
                                                    "The top bar confirms the app can connect and read cloud data. However, writing new records may fail or timeout due to:\n\n" +
                                                     "1️⃣ Restrictive Firestore Rules: Your security rules might block write access.\n" +
                                                     "👈 Solution: Go to Firebase Console and ensure rules allow write access: allow read, write: if true;\n\n" +
                                                     "2️⃣ Weak or Intermittent Connection: Immediate writes fail and cause an 8-second timeout.\n" +
                                                     "👈 Solution: Verify internet signal strength and retry.\n\n" +
                                                     "3️⃣ Default Emulation project: If you are running the fallback demo project without configuring your credentials.\n" +
                                                     "👈 Solution: Go to App Settings > Cloud Config and enter your custom Firebase Project ID, API Key, and App ID."
                                                ),
                                                fontSize = 10.5.sp,
                                                color = Color(0xFF78350F),
                                                lineHeight = 15.sp
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                confirmButton = {
                    TextButton(onClick = { showPendingSyncItemsDialog = false }) {
                        Text(text = t("إغلاق", "Close"), color = GBRBlueMain, fontWeight = FontWeight.Bold)
                    }
                },
                containerColor = Color.White,
                shape = RoundedCornerShape(16.dp)
            )
        }

        // Dynamic Statistics Panel
        val rawMaterialsListStat by viewModel.rawMaterials.collectAsState()
        val formulationsListStat by viewModel.formulations.collectAsState()

        val totalRawMaterialsCount = rawMaterialsListStat.size
        val latestFormulationsOnlyStat = remember(formulationsListStat) {
            formulationsListStat
                .groupBy { it.code.trim().ifBlank { it.name.trim() }.uppercase() }
                .map { entry -> 
                    entry.value.maxByOrNull { f ->
                        val ver = f.version.trim()
                        val vNum = if (ver.startsWith("الإصدار ")) {
                            ver.substringAfter("الإصدار ").trim().toIntOrNull() ?: 1
                        } else {
                            ver.filter { it.isDigit() }.toIntOrNull() ?: 1
                        }
                        vNum
                    }!!
                }
        }
        val approvedFormulationsCount = latestFormulationsOnlyStat.count { it.status == "🟢 معتمدة للإنتاج" }

        var showActiveOrdersDialog by remember { mutableStateOf(false) }

        // Redeveloped PREMIUM STATISTICS SUMMARY BANNERS
        // Completely redesigned to NOT look like buttons, preventing user confusion. 
        // Built as flat unified read-only status widgets.
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(
                    color = Color(0xFFF8FAFC),
                    shape = RoundedCornerShape(20.dp)
                )
                .border(BorderStroke(1.dp, Color(0xFFE2E8F0)), RoundedCornerShape(20.dp))
                .padding(16.dp)
        ) {
            Column(
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                // Header of statistics readout (clearly showing it is an informative non-clickable banner)
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = t("📊 إحصائيات النظام العامة", "📊 General System Statistics"),
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF64748B)
                    )
                    Spacer(modifier = Modifier.weight(1f))
                    Box(
                        modifier = Modifier
                            .background(Color(0xFFE2E8F0), RoundedCornerShape(6.dp))
                            .padding(horizontal = 6.dp, vertical = 2.dp)
                    ) {
                        Text(
                            text = t("محدث تلقائياً 🔄", "Auto-Updated 🔄"),
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF475569)
                        )
                    }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceAround,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    // Stat column 1: Raw materials count
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(2.dp),
                        modifier = Modifier.weight(1f)
                    ) {
                        Text(
                            text = t("المواد الخام المسجلة", "Registered Raw Materials"),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF475569)
                        )
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(24.dp)
                                    .background(GBRBlueMain.copy(alpha = 0.1f), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("🧪", fontSize = 11.sp)
                            }
                            Text(
                                text = "$totalRawMaterialsCount",
                                fontSize = 28.sp,
                                fontWeight = FontWeight.Black,
                                color = GBRDarkIndigo
                            )
                        }
                    }

                    // Separation Line
                    Box(
                        modifier = Modifier
                            .width(1.dp)
                            .height(44.dp)
                            .background(Color(0xFFCBD5E1))
                    )

                    // Stat column 2: Approved formulations count
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(2.dp),
                        modifier = Modifier.weight(1f)
                    ) {
                        Text(
                            text = t("التركيبات المعتمدة للإنتاج", "Approved Formulations"),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF166534)
                        )
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(24.dp)
                                    .background(Color(0xFF22C55E).copy(alpha = 0.1f), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("🟢", fontSize = 11.sp)
                            }
                            Text(
                                text = "$approvedFormulationsCount",
                                fontSize = 28.sp,
                                fontWeight = FontWeight.Black,
                                color = Color(0xFF15803D)
                            )
                        }
                    }
                }
            }
        }

        // Quick-Access for Production Orders "In Progress"
        val ordersInMainReady by viewModel.productionOrders.collectAsState(initial = emptyList())
        val liveRunningOrders = remember(ordersInMainReady) {
            ordersInMainReady.filter { it.status == "قيد التنفيذ" }
        }

        // Interactive Banner for running orders which opens selection Dialog
        if (liveRunningOrders.isNotEmpty()) {
            Card(
                onClick = { showActiveOrdersDialog = true },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF7ED)),
                border = BorderStroke(1.5.dp, Color(0xFFFDBA74))
            ) {
                Row(
                    modifier = Modifier.padding(14.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .background(WarningOrange.copy(alpha = 0.15f), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.PlayArrow,
                            contentDescription = null,
                            tint = WarningOrange,
                            modifier = Modifier.size(22.dp)
                        )
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(8.dp)
                                    .background(Color.Red, CircleShape)
                            )
                            Text(
                                text = t("أوامر إنتاج جارية قيد التنفيذ", "Active Production Orders"),
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFFC2410C)
                            )
                        }
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = t(
                                "لدينا حالياً (${liveRunningOrders.size}) أوامر نشطة. اضغط للاستئناف ومتابعة العمل الفوري.",
                                "We have (${liveRunningOrders.size}) active orders. Click to resume and monitor ongoing work."
                            ),
                            fontSize = 11.sp,
                            color = Color(0xFF7C2D12),
                            fontWeight = FontWeight.Medium
                        )
                    }
                    Icon(
                        imageVector = Icons.Default.ArrowForward,
                        contentDescription = null,
                        tint = WarningOrange,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }
        }

        // Active Orders Selection Dialog
        if (showActiveOrdersDialog) {
            androidx.compose.ui.window.Dialog(
                onDismissRequest = { showActiveOrdersDialog = false }
            ) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Column(
                        modifier = Modifier
                            .padding(20.dp)
                            .fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        // Title
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(30.dp)
                                        .background(Color(0xFFFEF3C7), CircleShape),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.PlayArrow,
                                        contentDescription = null,
                                        tint = WarningOrange,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                                Text(
                                    text = t("استئناف ومتابعة الإنتاج الجاري", "Resume & Track Active Production"),
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRDarkIndigo
                                )
                            }
                            IconButton(onClick = { showActiveOrdersDialog = false }) {
                                Icon(
                                    imageVector = Icons.Default.Close,
                                    contentDescription = null,
                                    tint = ErrorRed,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }

                        Divider(color = Color(0xFFF1F5F9))

                        Text(
                            text = t(
                                "الرجاء اختيار الأمر المطلوب من صالة الإنتاج لمواصلة خلط ومطابقة الدفعة المجدولة:",
                                "Please select the desired production order from the shop floor to continue mixing and batch matching:"
                            ),
                            fontSize = 11.sp,
                            color = Color.Gray,
                            lineHeight = 16.sp
                        )

                        // Scrollable List of active orders
                        val scrollState = rememberScrollState()
                        Column(
                            modifier = Modifier
                                .weight(weight = 1f, fill = false)
                                .verticalScroll(scrollState),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            if (liveRunningOrders.isEmpty()) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(24.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = t("لا توجد أوامر جارية حالياً قيد التنفيذ.", "No active production orders currently executing."),
                                        fontSize = 12.sp,
                                        color = Color.Gray
                                    )
                                }
                            } else {
                                liveRunningOrders.forEach { ord ->
                                    Card(
                                        onClick = {
                                            showActiveOrdersDialog = false
                                            viewModel.activeSegment.value = "production"
                                            viewModel.selectedProductionOrder.value = ord
                                        },
                                        shape = RoundedCornerShape(12.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(modifier = Modifier.padding(12.dp)) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = ord.formulationName,
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = GBRDarkIndigo
                                                )
                                                Text(
                                                    text = ord.orderNumber,
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color.Gray
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(4.dp))
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = t(
                                                        "الوزن: ${formatQuantity(ord.requiredWeightKg)} كغم | معامل: ${formatQuantity(ord.scaleFactor)}",
                                                        "Weight: ${formatQuantity(ord.requiredWeightKg)} kg | Factor: ${formatQuantity(ord.scaleFactor)}"
                                                    ),
                                                    fontSize = 9.sp,
                                                    color = Color.DarkGray
                                                )
                                                Text(
                                                    text = "نسبة الإنجاز: ${formatPercent(ord.progressPercent.toDouble())}",
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = WarningOrange
                                                )
                                            }
                                            Spacer(modifier = Modifier.height(6.dp))
                                            LinearProgressIndicator(
                                                progress = ord.progressPercent / 100f,
                                                color = WarningOrange,
                                                trackColor = Color(0xFFFEF3C7),
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .height(6.dp)
                                                    .clip(RoundedCornerShape(3.dp))
                                            )
                                            Spacer(modifier = Modifier.height(8.dp))
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.Start
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .background(GBRBlueMain, RoundedCornerShape(6.dp))
                                                        .padding(horizontal = 10.dp, vertical = 4.dp),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Text(
                                                        text = t("استئناف ومواصلة العمل ⚡", "Resume & Continue Work ⚡"),
                                                        fontSize = 10.sp,
                                                        color = Color.White,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(4.dp))

                        Button(
                            onClick = { showActiveOrdersDialog = false },
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Gray),
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(s().back, color = Color.White, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }


        // Row 1: المواد الخام & التركيبات
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            MediumFacilityButton(
                title = s().deckMaterialsTitle,
                subtitle = s().deckMaterialsSubtitle,
                icon = Icons.Default.Menu,
                iconBgColor = if (isDark) Color(0xFF1E293B) else Color(0xFFEFF6FF),
                iconColor = if (isDark) GBRCyanAccent else GBRBlueMain,
                onClick = { viewModel.showSegment("materials") },
                modifier = Modifier.weight(1f)
            )

            MediumFacilityButton(
                title = s().deckFormulationsTitle,
                subtitle = s().deckFormulationsSubtitle,
                icon = Icons.Default.Info,
                iconBgColor = if (isDark) Color(0xFF332A15) else Color(0xFFFEF3C7),
                iconColor = WarningOrange,
                onClick = { viewModel.showSegment("formulations") },
                modifier = Modifier.weight(1f)
            )
        }

        // Row 2: الإنتاج (Starting Production) - Full width prominent card
        val readyAndInProgressCount = remember(ordersInMainReady) {
            ordersInMainReady.count { it.status == "جاهز للتنفيذ" || it.status == "قيد التنفيذ" }
        }

        LargeFacilityButton(
            title = s().deckProductionTitle,
            subtitle = s().deckProductionSubtitle,
            icon = Icons.Default.PlayArrow,
            isPrimary = true,
            iconBgColor = Color(0x33FFFFFF),
            iconColor = Color.White,
            badgeCount = readyAndInProgressCount,
            onClick = { viewModel.showSegment("production") }
        )

        // Row 3: التقارير & الأبحاث والتطوير (R&D)
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            MediumFacilityButton(
                title = s().deckReportsTitle,
                subtitle = s().deckReportsSubtitle,
                icon = Icons.Default.List,
                iconBgColor = Color(0xFFECFDF5),
                iconColor = SuccessGreen,
                onClick = { viewModel.showSegment("reports") },
                modifier = Modifier.weight(1f)
            )

            MediumFacilityButton(
                title = t("الأبحاث والتطوير (R&D)", "Research & Development (R&D)"),
                subtitle = t("إدارة المشاريع والعينات التجريبية", "Manage projects and experimental samples"),
                icon = Icons.Default.Info,
                emoji = "🧪",
                iconBgColor = Color(0xFFECE9FF),
                iconColor = GBRPurpleAccent,
                onClick = { viewModel.showSegment("research_development") },
                modifier = Modifier.weight(1f)
            )
        }

        // المخزون (دفتر حركات: مواد خام الآن، والمنتج التام في المراحل القادمة)
        LargeFacilityButton(
            title = t("المخزون", "Inventory"),
            subtitle = t("أرصدة المواد الخام وبطاقة الصنف والتقييم وإعادة الطلب", "Raw-material balances, item card, valuation and reorder"),
            icon = Icons.Default.Inventory2,
            isPrimary = false,
            iconBgColor = Color(0xFFE4F4F0),
            iconColor = PlusTeal,
            onClick = { viewModel.showSegment("inventory") }
        )

        // Row 4: إدارة المختبر (Laboratory Management)
        LargeFacilityButton(
            title = t("🧪 قسم المختبر وضبط الجودة", "🧪 Laboratory & Quality Control"),
            subtitle = t("إدارة جلسات الفحوصات المقارنة والأحادية والأرشفة المنظمة للأقسام", "Manage single/comparative test sessions with organized archives"),
            icon = Icons.Default.Science,
            isPrimary = true,
            iconBgColor = Color(0xFFEFF6FF),
            iconColor = Color(0xFF0056B3),
            onClick = { viewModel.showSegment("laboratory_management") }
        )

        // Row 5: التحكم بالمعدات - Full width prominent card
        LargeFacilityButton(
            title = t("التحكم بالمعدات", "Equipment Control"),
            subtitle = t("تشغيل الخلاطات، جدولة المؤقتات ومراقبة الآلات سحابياً", "Operate mixers, schedule timers, and monitor machines via cloud"),
            icon = Icons.Default.Build,
            isPrimary = false,
            iconBgColor = Color(0xFFF3E8FF),
            iconColor = GBRPurpleAccent,
            onClick = { viewModel.showSegment("equipment_control") }
        )

        // Row 6: الإعدادات (Settings) - Full width prominent card as the LAST section at the bottom of the home screen
        LargeFacilityButton(
            title = s().deckSettingsTitle,
            subtitle = s().deckSettingsSubtitle,
            icon = Icons.Default.Settings,
            isPrimary = false,
            iconBgColor = Color(0xFFFDF2F8),
            iconColor = GBRPinkAccent,
            onClick = { viewModel.showSegment("settings") }
        )
    }
    }
}

@Composable
fun LargeFacilityButton(
    title: String,
    subtitle: String,
    icon: ImageVector,
    isPrimary: Boolean,
    iconBgColor: Color,
    iconColor: Color,
    badgeCount: Int = 0,
    onClick: () -> Unit
) {
    val isDark = false
    val cardBg = if (isPrimary) {
        GBRBlueMain
    } else {
        if (isDark) IndustrialDarkSurface else Color.White
    }
    val cardBorder = if (isPrimary) {
        BorderStroke(2.dp, Color(0xFF003D7E))
    } else {
        BorderStroke(2.dp, if (isDark) IndustrialBorderDark else IndustrialBorder)
    }
    val titleColor = if (isPrimary) Color.White else (if (isDark) Color.White else GBRDarkIndigo)
    val subtitleColor = if (isPrimary) Color(0xFFDBEAFE) else Color.Gray

    Card(
        onClick = onClick,
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 115.dp),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = cardBg),
        border = cardBorder,
        elevation = CardDefaults.cardElevation(defaultElevation = if (isPrimary) 6.dp else 2.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Icon emblem framed cleanly
            Box(
                modifier = Modifier
                    .size(64.dp)
                    .clip(RoundedCornerShape(16.dp))
                    .background(iconBgColor),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = icon,
                    contentDescription = null,
                    tint = iconColor,
                    modifier = Modifier.size(34.dp)
                )
            }

            Spacer(modifier = Modifier.width(20.dp))

            Column(
                modifier = Modifier.weight(1f)
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = title,
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold,
                        color = titleColor
                    )
                    if (badgeCount > 0) {
                        Spacer(modifier = Modifier.width(8.dp))
                        Box(
                            modifier = Modifier
                                .background(Color(0xFFEF4444), CircleShape)
                                .padding(horizontal = 8.dp, vertical = 2.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = badgeCount.toString(),
                                color = Color.White,
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
                Text(
                    text = subtitle,
                    fontSize = 12.sp,
                    color = subtitleColor,
                    maxLines = 3,
                    lineHeight = 16.sp,
                    overflow = TextOverflow.Ellipsis
                )
            }

            Icon(
                imageVector = Icons.Default.KeyboardArrowLeft, // RTL arrow direction in Arabic
                contentDescription = null,
                tint = if (isPrimary) Color(0xFFDBEAFE) else Color.Gray,
                modifier = Modifier.size(24.dp)
            )
        }
    }
}

@Composable
fun GbrEmptyState(
    title: String,
    description: String,
    onAddNew: () -> Unit,
    onRestoreBackup: () -> Unit,
    onCloudSync: () -> Unit,
    addNewText: String = "إضافة جديد ➕",
    restoreBackupText: String = "استيراد نسخة احتياطية 📂",
    cloudSyncText: String = "تزامن مع السحابة ☁️"
) {
    Card(
        modifier = androidx.compose.ui.Modifier
            .fillMaxWidth()
            .padding(16.dp),
        shape = androidx.compose.foundation.shape.RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Column(
            modifier = androidx.compose.ui.Modifier
                .fillMaxWidth()
                .padding(24.dp),
            horizontalAlignment = androidx.compose.ui.Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Box(
                modifier = androidx.compose.ui.Modifier
                    .size(64.dp)
                    .background(Color(0xFFF1F5F9), shape = androidx.compose.foundation.shape.CircleShape),
                contentAlignment = androidx.compose.ui.Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Default.Info,
                    contentDescription = null,
                    tint = Color(0xFF64748B),
                    modifier = androidx.compose.ui.Modifier.size(32.dp)
                )
            }
            Spacer(modifier = androidx.compose.ui.Modifier.height(16.dp))
            Text(
                text = title,
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                color = Color(0xFF0F172A),
                textAlign = TextAlign.Center
            )
            Spacer(modifier = androidx.compose.ui.Modifier.height(6.dp))
            Text(
                text = description,
                fontSize = 12.sp,
                color = Color(0xFF64748B),
                textAlign = TextAlign.Center,
                lineHeight = 17.sp
            )
            Spacer(modifier = androidx.compose.ui.Modifier.height(20.dp))
            
            Column(
                modifier = androidx.compose.ui.Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp),
                horizontalAlignment = androidx.compose.ui.Alignment.CenterHorizontally
            ) {
                Button(
                    onClick = onAddNew,
                    modifier = androidx.compose.ui.Modifier.fillMaxWidth(0.9f),
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0284C7)),
                    shape = androidx.compose.foundation.shape.RoundedCornerShape(10.dp)
                ) {
                    Text(text = addNewText, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
                
                Row(
                    modifier = androidx.compose.ui.Modifier.fillMaxWidth(0.9f),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    OutlinedButton(
                        onClick = onRestoreBackup,
                        modifier = androidx.compose.ui.Modifier.weight(1f),
                        border = BorderStroke(1.dp, Color(0xFFCBD5E1)),
                        shape = androidx.compose.foundation.shape.RoundedCornerShape(10.dp)
                    ) {
                        Text(text = restoreBackupText, fontSize = 10.sp, fontWeight = FontWeight.SemiBold, color = Color(0xFF475569))
                    }
                    
                    OutlinedButton(
                        onClick = onCloudSync,
                        modifier = androidx.compose.ui.Modifier.weight(1f),
                        border = BorderStroke(1.dp, Color(0xFFCBD5E1)),
                        shape = androidx.compose.foundation.shape.RoundedCornerShape(10.dp)
                    ) {
                        Text(text = cloudSyncText, fontSize = 10.sp, fontWeight = FontWeight.SemiBold, color = Color(0xFF475569))
                    }
                }
            }
        }
    }
}

