@Composable
fun DetailItemRow(label: String, value: String) {
    Row(
        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = label,
            fontSize = 13.sp,
            fontWeight = FontWeight.Medium,
            color = Color.Gray
        )
        Text(
            text = value,
            fontSize = 14.sp,
            fontWeight = FontWeight.Bold,
            color = GBRDarkIndigo,
            textAlign = TextAlign.End
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class, ExperimentalFoundationApi::class)
@Composable
fun MaterialsPanel(viewModel: GbrViewModel) {
    val materialsList by viewModel.rawMaterials.collectAsState()
    val isAdding by viewModel.isAddingRawMaterial.collectAsState()
    val allFormulationItems by viewModel.allFormulationItems.collectAsState()
    val formulationsList by viewModel.formulations.collectAsState()
    val rawUploadState by viewModel.rawMaterialUploadState.collectAsState()
    val rawUploadProgress by viewModel.rawMaterialUploadProgress.collectAsState()
    val rawUploadMessage by viewModel.rawMaterialUploadMessage.collectAsState()
    val isDark = false
    val context = LocalContext.current
    val isEn = LocalAppLanguage.current == "en"

    // State for Adding Form
    var nameInput by remember { mutableStateOf("") }
    var productionNameInput by remember { mutableStateOf("") }
    var priceInput by remember { mutableStateOf("") }
    var priceUnitInput by remember { mutableStateOf("شيكل") }
    var notesInput by remember { mutableStateOf("") }
    var pdfUriInput by remember { mutableStateOf<String?>(null) }
    var isActiveInput by remember { mutableStateOf(true) }
    var currentNewMaterialId by remember { mutableStateOf(java.util.UUID.randomUUID().toString()) }

    // State for Editing
    var materialToEdit by remember { mutableStateOf<RawMaterial?>(null) }
    var editNameInput by remember { mutableStateOf("") }
    var editProductionNameInput by remember { mutableStateOf("") }
    var editPriceInput by remember { mutableStateOf("") }
    var editPriceUnitInput by remember { mutableStateOf("شيكل") }
    var editNotesInput by remember { mutableStateOf("") }
    var editPdfUriInput by remember { mutableStateOf<String?>(null) }
    var editIsActiveInput by remember { mutableStateOf(true) }

    // State for Price History Report
    var showPriceHistoryDialog by remember { mutableStateOf<RawMaterial?>(null) }

    // State for Deleting Confirmation
    var materialToDelete by remember { mutableStateOf<RawMaterial?>(null) }

    // State for Search Bar
    var searchQueryInput by remember { mutableStateOf("") }
    var isSearchActive by remember { mutableStateOf(false) }

    // State for Detail View
    var selectedMaterialDetail by remember { mutableStateOf<RawMaterial?>(null) }
    val currentDetail = selectedMaterialDetail?.let { target ->
        materialsList.find { it.id == target.id }
    }

    LaunchedEffect(currentDetail) {
        if (selectedMaterialDetail != null && currentDetail == null) {
            selectedMaterialDetail = null
        }
    }

    // Document Pickers for PDF
    val pdfPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        uri?.let {
            val copiedUri = com.example.data.GbrFileManager.copyUriToCache(context, it, "tds")
            if (copiedUri != null) {
                viewModel.uploadRawMaterialFileDirectly(currentNewMaterialId, copiedUri) { cloudUrl ->
                    if (cloudUrl != null) {
                        pdfUriInput = cloudUrl
                        Toast.makeText(context, "تم رفع وحفظ رابط الملف السحابي بنجاح! ✅", Toast.LENGTH_SHORT).show()
                    } else {
                        pdfUriInput = copiedUri.toString()
                    }
                }
            } else {
                Toast.makeText(context, "فشل حفظ نسخة محلية مؤقتة من الملف.", Toast.LENGTH_SHORT).show()
            }
        }
    }

    val editPdfPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        uri?.let {
            val materialId = materialToEdit?.id ?: java.util.UUID.randomUUID().toString()
            val copiedUri = com.example.data.GbrFileManager.copyUriToCache(context, it, "tds")
            if (copiedUri != null) {
                viewModel.uploadRawMaterialFileDirectly(materialId, copiedUri) { cloudUrl ->
                    if (cloudUrl != null) {
                        editPdfUriInput = cloudUrl
                        Toast.makeText(context, "تم رفع وحفظ رابط الملف السحابي بنجاح! ✅", Toast.LENGTH_SHORT).show()
                    } else {
                        editPdfUriInput = copiedUri.toString()
                    }
                }
            } else {
                Toast.makeText(context, "فشل حفظ نسخة محلية مؤقتة من الملف.", Toast.LENGTH_SHORT).show()
            }
        }
    }

    val isSubViewActive = selectedMaterialDetail != null || materialToEdit != null || isAdding
    val currentUser by viewModel.currentUser.collectAsState()
    val role = currentUser?.role
    val activeSegment by viewModel.activeSegment.collectAsState()

    // Navigation and Back Button Handler for Materials
    BackHandler(enabled = isSubViewActive || (role != "المخزن" && activeSegment == "materials")) {
        if (selectedMaterialDetail != null) {
            selectedMaterialDetail = null
        } else if (materialToEdit != null) {
            materialToEdit = null
        } else if (isAdding) {
            viewModel.isAddingRawMaterial.value = false
        } else if (role != "المخزن" && activeSegment == "materials") {
            viewModel.showSegment(null)
        }
    }

    if (currentDetail != null) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            // Header for Detail Screen
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 16.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                IconButton(
                    onClick = { selectedMaterialDetail = null },
                    modifier = Modifier.size(40.dp)
                ) {
                    Icon(
                        imageVector = Icons.Default.ArrowBack,
                        contentDescription = t("تراجع", "Back"),
                        tint = GBRBlueMain
                    )
                }
                Text(
                    text = t("تفاصيل المادة الخام", "Raw Material Details"),
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    color = if (isDark) Color.White else GBRDarkIndigo
                )
            }

            Column(
                modifier = Modifier
                    .weight(1f)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Main Info Card
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, IndustrialBorder)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(20.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            text = t("المعلومات الأساسية", "Basic Information"),
                            fontWeight = FontWeight.Bold,
                            color = GBRBlueMain,
                            fontSize = 15.sp
                        )

                        Divider(color = IndustrialBorder.copy(alpha = 0.5f))

                        DetailItemRow(label = t("الاسم الحقيقي (علمياً):", "Scientific / Real Name:"), value = currentDetail.name)
                        DetailItemRow(label = t("اسم المتداول (الإنتاج):", "Trade / Production Name:"), value = currentDetail.productionName.ifBlank { t("غير محدد", "Not specified") })

                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            verticalArrangement = Arrangement.spacedBy(2.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = t("حالة المادة:", "Material Status:"),
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = Color.Gray
                                )
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Icon(
                                        imageVector = if (currentDetail.isActive) Icons.Default.CheckCircle else Icons.Default.Cancel,
                                        contentDescription = null,
                                        tint = if (currentDetail.isActive) Color(0xFF16A34A) else Color(0xFFDC2626),
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Text(
                                        text = if (currentDetail.isActive) t("فعالة", "Active") else t("غير فعالة", "Inactive"),
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (currentDetail.isActive) Color(0xFF16A34A) else Color(0xFFDC2626)
                                    )
                                }
                            }
                            Text(
                                text = if (currentDetail.isActive) t("(متاحة للاستخدام في التركيبات)", "(Available for formulations)") else t("(غير متاحة للاستخدام في التركيبات)", "(Not available for formulations)"),
                                fontSize = 11.sp,
                                color = Color.Gray,
                                fontWeight = FontWeight.Normal,
                                textAlign = TextAlign.End,
                                modifier = Modifier.fillMaxWidth()
                            )
                        }
                    }
                }

                // Pricing Card
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, IndustrialBorder)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(20.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            text = t("السعر والوحدات", "Pricing & Units"),
                            fontWeight = FontWeight.Bold,
                            color = GBRPinkAccent,
                            fontSize = 15.sp
                        )

                        Divider(color = IndustrialBorder.copy(alpha = 0.5f))

                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            DetailItemRow(
                                label = t("السعر الحالي:", "Current Price:"),
                                value = "${currentDetail.price} ${if (currentDetail.priceUnit == "شيكل" || currentDetail.priceUnit.isBlank()) t("شيكل", "ILS") else currentDetail.priceUnit} / ${t("كغم", "kg")}"
                            )

                            Button(
                                onClick = { showPriceHistoryDialog = currentDetail },
                                shape = RoundedCornerShape(10.dp),
                                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain.copy(alpha = 0.12f)),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Icon(
                                    imageVector = Icons.Default.List,
                                    contentDescription = t("حركة الأسعار", "Price Movement"),
                                    tint = GBRBlueMain,
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = t("تقرير حركة الأسعار", "Price Movement Report"),
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRBlueMain
                                )
                            }
                        }
                    }
                }

                // Notes Card
                if (currentDetail.notes.isNotBlank()) {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(20.dp),
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        border = BorderStroke(1.dp, IndustrialBorder)
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(20.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Text(
                                text = t("ملاحظات وتفاصيل إضافية", "Notes & Additional Details"),
                                fontWeight = FontWeight.Bold,
                                color = GBRDarkIndigo,
                                fontSize = 15.sp
                            )

                            Divider(color = IndustrialBorder.copy(alpha = 0.5f))

                            Text(
                                text = currentDetail.notes,
                                fontSize = 14.sp,
                                color = Color(0xFF475569),
                                lineHeight = 20.sp
                            )
                        }
                    }
                }

                // TDS PDF File Card / Button
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, IndustrialBorder)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(20.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            text = t("الدليل الفني والمستندات (TDS)", "Technical Data Sheet & Documents (TDS)"),
                            fontWeight = FontWeight.Bold,
                            color = if (!currentDetail.tdsUri.isNullOrBlank()) SuccessGreen else Color.Gray,
                            fontSize = 15.sp
                        )

                        val localScope = rememberCoroutineScope()
                        var isDownloadingTds by remember { mutableStateOf(false) }
                        var tdsDownloadProgress by remember { mutableStateOf(0f) }
                        var isShowingDiagnostics by remember { mutableStateOf(false) }
                        var updatedDiagnosticInfo by remember { mutableStateOf<com.example.data.GbrFileManager.FileDiagnosticInfo?>(null) }
                        
                        LaunchedEffect(currentDetail.id, isShowingDiagnostics) {
                            updatedDiagnosticInfo = com.example.data.GbrFileManager.getFileDiagnostic(context, currentDetail.id)
                        }

                        Divider(color = IndustrialBorder.copy(alpha = 0.5f))

                        if (!currentDetail.tdsUri.isNullOrBlank()) {
                            if (isDownloadingTds) {
                                Column(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    LinearProgressIndicator(
                                        progress = { tdsDownloadProgress },
                                        modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(4.dp)),
                                        color = SuccessGreen,
                                        trackColor = Color.LightGray.copy(alpha = 0.3f)
                                    )
                                    Text(
                                        text = "${t("جاري تنزيل وتحديث مستند الـ TDS...", "Downloading & updating TDS document...")} ${(tdsDownloadProgress * 100).toInt()}%",
                                        fontSize = 11.sp,
                                        color = Color.Gray
                                    )
                                }
                            } else {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(SuccessGreen.copy(alpha = 0.08f))
                                        .clickable {
                                            localScope.launch {
                                                isDownloadingTds = true
                                                val resFile = com.example.data.GbrFileManager.getFileWithAutoUpdate(
                                                    context = context,
                                                    urlStr = currentDetail.tdsUri,
                                                    targetId = currentDetail.id,
                                                    onProgress = { progress -> tdsDownloadProgress = progress }
                                                )
                                                isDownloadingTds = false
                                                if (resFile != null) {
                                                    val success = com.example.data.GbrFileManager.openCachedFile(context, resFile)
                                                    if (!success) {
                                                        Toast.makeText(context, if (isEn) "Failed to open TDS PDF file. Please install a PDF reader." else "فشل فتح ملف PDF الفني. يرجى تثبيت تطبيق قارئ PDF.", Toast.LENGTH_SHORT).show()
                                                    }
                                                } else {
                                                    val diag = com.example.data.GbrFileManager.getFileDiagnostic(context, currentDetail.id)
                                                    val reason = diag.failureReason ?: if (isEn) "Network resource currently unavailable." else "مورد الشبكة غير متاح للملف حالياً."
                                                    Toast.makeText(context, "${if (isEn) "Sync & download failed:" else "فشل المزامنة والتنزيل:"} $reason", Toast.LENGTH_SHORT).show()
                                                }
                                                updatedDiagnosticInfo = com.example.data.GbrFileManager.getFileDiagnostic(context, currentDetail.id)
                                            }
                                        }
                                        .padding(horizontal = 16.dp, vertical = 12.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Info,
                                        contentDescription = null,
                                        tint = SuccessGreen,
                                        modifier = Modifier.size(18.dp)
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        text = t("📄 عرض وثيقة الدليل الفني (TDS)", "📄 View Technical Data Sheet (TDS)"),
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = SuccessGreen
                                    )
                                }
                            }

                            Spacer(modifier = Modifier.height(6.dp))
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { isShowingDiagnostics = !isShowingDiagnostics }
                                    .padding(vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Icon(
                                    imageVector = if (isShowingDiagnostics) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                    contentDescription = null,
                                    tint = GBRBlueMain,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = if (isShowingDiagnostics) t("إخفاء لوحة تشخيص الملف", "Hide File Diagnostics") else t("تشخيص حالة المستند في السحابة والاتصال 🔍", "Diagnose Cloud & Connection Status 🔍"),
                                    fontSize = 11.sp,
                                    color = GBRBlueMain,
                                    fontWeight = FontWeight.SemiBold
                                )
                            }

                            if (isShowingDiagnostics && updatedDiagnosticInfo != null) {
                                val diag = updatedDiagnosticInfo!!
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(Color(0xFFF8FAFC))
                                        .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(8.dp))
                                        .padding(12.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Text(
                                        text = t("لوحة أدوات تشخيص السحابة TDS:", "TDS Cloud Diagnostic Console:"),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF1E293B)
                                    )
                                    
                                    val sizeInKB = if (diag.size > 0) "${diag.size / 1024} KB" else t("غير معروف", "Unknown")

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("رابط السحابة :", "Cloud Link:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(
                                            text = currentDetail.tdsUri ?: t("لا يوجد", "None"),
                                            fontSize = 11.sp,
                                            color = GBRBlueMain,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis,
                                            modifier = Modifier.weight(1f).padding(start = 8.dp),
                                            textAlign = TextAlign.End
                                        )
                                    }

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("اسم الملف الفني الأصلي :", "Original File Name:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(text = diag.originalName ?: t("معين تلقائياً", "Auto-assigned"), fontSize = 11.sp, color = Color(0xFF334155))
                                    }

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("حجم المستند الفعلي :", "Actual Document Size:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(text = sizeInKB, fontSize = 11.sp, color = Color(0xFF334155))
                                    }

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("تاريخ المزامنة Сloud :", "Cloud Sync Date:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(text = diag.lastSync ?: t("لم تتم المزامنة", "Not synced"), fontSize = 11.sp, color = Color(0xFF334155))
                                    }

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("تاريخ آخر تنزيل محلي :", "Last Local Download:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(text = diag.lastDownload ?: t("لم ينزل", "Not downloaded"), fontSize = 11.sp, color = Color(0xFF334155))
                                    }

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("مسار التخزين (الكاش) :", "Storage Cache Status:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(
                                            text = if (diag.localCopyExists) t("✅ متوفر محلياً (جاهز للعمل دون إنترنت)", "✅ Available locally (Offline ready)") else t("☁️ متوفر سحابياً ومطلوب للتحميل", "☁️ Available in cloud (Download required)"),
                                            fontSize = 11.sp,
                                            color = if (diag.localCopyExists) SuccessGreen else Color(0xFF334155)
                                        )
                                    }

                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text(text = t("حالة الاتصال والربط السحابي :", "Connection & Cloud Status:"), fontSize = 11.sp, color = Color(0xFF64748B))
                                        Text(
                                            text = when(diag.status) {
                                                "synchronized" -> t("🟢 تم الرفع والحفظ سحابياً بنجاح ✅", "🟢 Uploaded & Synced successfully ✅")
                                                "local_pending_sync" -> t("🟡 تم الحفظ محلياً وبانتظار المزامنة ⏳", "🟡 Saved locally, pending sync ⏳")
                                                "failed" -> t("🔴 فشل الرفع والربط السحابي ❌", "🔴 Cloud upload/sync failed ❌")
                                                else -> t("🟡 جاهز للمزامنة والتحميل", "🟡 Ready for sync & download")
                                            },
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = when(diag.status) {
                                                "synchronized" -> SuccessGreen
                                                "local_pending_sync" -> Color(0xFFD97706)
                                                else -> Color.DarkGray
                                            }
                                        )
                                    }

                                    if (!diag.failureReason.isNullOrBlank()) {
                                        Text(
                                            text = "${t("⚠️ سبب الفشل:", "⚠️ Failure Reason:")} ${diag.failureReason}",
                                            color = Color.Red,
                                            fontSize = 11.sp,
                                            lineHeight = 15.sp
                                        )
                                    }
                                }
                            }
                        } else {
                            Text(
                                text = t("لا يوجد ملف دليل فني TDS مرفق لهذه المادة.", "No TDS technical document attached for this material."),
                                fontSize = 13.sp,
                                color = Color.Gray
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(8.dp))

                // Control Actions Button row
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Edit Button
                    Button(
                        onClick = {
                            materialToEdit = currentDetail
                            editNameInput = currentDetail.name
                            editProductionNameInput = currentDetail.productionName
                            editPriceInput = currentDetail.price.toString()
                            editPriceUnitInput = currentDetail.priceUnit
                            editNotesInput = currentDetail.notes
                            editPdfUriInput = currentDetail.tdsUri
                            editIsActiveInput = currentDetail.isActive
                        },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                    ) {
                        Icon(imageVector = Icons.Default.Edit, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(text = t("تعديل البيانات", "Edit Details"), fontWeight = FontWeight.Bold)
                    }

                    // Delete Button
                    Button(
                        onClick = {
                            materialToDelete = currentDetail
                        },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = ErrorRed)
                    ) {
                        Icon(imageVector = Icons.Default.Delete, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(text = t("حذف المادة", "Delete Material"), fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    } else {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            // Upper Title & Add Button Bar
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 12.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Text(
                        text = t("المواد الخام", "Raw Materials"),
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isDark) Color.White else GBRDarkIndigo
                    )
                    IconButton(onClick = { 
                        isSearchActive = !isSearchActive 
                        if (!isSearchActive) searchQueryInput = "" 
                    }) {
                        Icon(
                            imageVector = if (isSearchActive) Icons.Default.Close else Icons.Default.Search,
                            contentDescription = t("بحث", "Search"),
                            tint = GBRBlueMain
                        )
                    }
                }

                Button(
                    onClick = { viewModel.isAddingRawMaterial.value = !isAdding },
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isAdding) Color(0xFF64748B) else GBRBlueMain
                    )
                ) {
                    Icon(
                        if (isAdding) Icons.Default.Close else Icons.Default.Add,
                        contentDescription = null,
                        modifier = Modifier.size(18.dp)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = if (isAdding) t("إلغاء وتراجع", "Cancel") else t("إضافة مادة", "Add Material"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp
                    )
                }
            }

            // Search input field
            AnimatedVisibility(
                visible = isSearchActive,
                enter = expandVertically() + fadeIn(),
                exit = shrinkVertically() + fadeOut()
            ) {
                OutlinedTextField(
                    value = searchQueryInput,
                    onValueChange = { searchQueryInput = it },
                    placeholder = { Text(t("بحث عن المواد بالاسم أو الإنتاج...", "Search materials by name or trade name...")) },
                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = t("بحث", "Search"), tint = GBRBlueMain) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp),
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                        focusedContainerColor = Color.White,
                        unfocusedContainerColor = Color.White,
                        focusedBorderColor = GBRBlueMain,
                        unfocusedBorderColor = IndustrialBorder
                    ),
                    trailingIcon = {
                        if (searchQueryInput.isNotEmpty()) {
                            IconButton(onClick = { searchQueryInput = "" }) {
                                Icon(Icons.Default.Clear, contentDescription = t("مسح", "Clear"), tint = Color.Gray)
                            }
                        }
                    }
                )
            }

            // Quick Statistics section for Raw Materials List
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 12.dp),
                shape = RoundedCornerShape(14.dp),
                colors = CardDefaults.cardColors(containerColor = Color(0xFFEFF6FF)),
                border = BorderStroke(1.dp, Color(0xFFDBEAFE))
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 14.dp, vertical = 10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Icon(
                        imageVector = Icons.Default.List,
                        contentDescription = null,
                        tint = GBRBlueMain,
                        modifier = Modifier.size(20.dp)
                    )
                    Text(
                        text = t("إجمالي عدد المواد الخام المسجلة:", "Total Registered Raw Materials:"),
                        fontSize = 12.sp,
                        color = Color(0xFF1E3A8A),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.weight(1f)
                    )
                    Text(
                        text = "${materialsList.size} ${t("مادة خام", "raw materials")}",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                }
            }

            // Slide-down Add raw material Form
            AnimatedVisibility(
                visible = isAdding,
                enter = expandVertically() + fadeIn(),
                exit = shrinkVertically() + fadeOut()
            ) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 16.dp),
                    shape = RoundedCornerShape(20.dp),
                    border = BorderStroke(1.5.dp, if (isDark) IndustrialBorderDark else IndustrialBorder),
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDark) IndustrialDarkSurface else Color.White
                    ),
                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .verticalScroll(rememberScrollState())
                            .padding(20.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        Text(
                            text = t("تفاصيل المادة الجديدة", "New Material Details"),
                            fontWeight = FontWeight.Bold,
                            color = GBRBlueMain,
                            fontSize = 16.sp
                        )

                        // Material Name Input (الاسم العملي/الحقيقي المعتمد)
                        OutlinedTextField(
                            value = nameInput,
                            onValueChange = { nameInput = it },
                            label = { Text(t("اسم المادة الحقيقي (الاسم العلمي أو التجاري) *", "Material Scientific / Real Name *")) },
                            placeholder = { Text(t("مثال: Titanium Dioxide R-996", "e.g. Titanium Dioxide R-996")) },
                            modifier = Modifier.fillMaxWidth(),
                            singleLine = false,
                            minLines = 2,
                            maxLines = 2,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                focusedLabelColor = GBRBlueMain,
                                unfocusedLabelColor = Color(0xFF94A3B8),
                                focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                focusedBorderColor = GBRBlueMain,
                                unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                                cursorColor = GBRBlueMain
                            ),
                            shape = RoundedCornerShape(12.dp)
                        )

                        // Production Name Input (اسم المادة المستخدم في الإنتاج)
                        OutlinedTextField(
                            value = productionNameInput,
                            onValueChange = { productionNameInput = it },
                            label = { Text(t("اسم المادة المستخدم في الإنتاج (الاسم المتداول) *", "Trade / Production Name *")) },
                            placeholder = { Text(t("مثال: 699 أو تيتانيوم أو العاطلة", "e.g. 699 or Titanium")) },
                            modifier = Modifier.fillMaxWidth(),
                            singleLine = false,
                            minLines = 2,
                            maxLines = 2,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                focusedLabelColor = GBRBlueMain,
                                unfocusedLabelColor = Color(0xFF94A3B8),
                                focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                focusedBorderColor = GBRBlueMain,
                                unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                                cursorColor = GBRBlueMain
                            ),
                            shape = RoundedCornerShape(12.dp)
                        )

                        // Price Input
                        OutlinedTextField(
                            value = priceInput,
                            onValueChange = { priceInput = it },
                            label = { Text(t("السعر الحالي *", "Current Price *")) },
                            placeholder = { Text(t("مثال: 12.0 أو 5 (بالشيكل)", "e.g. 12.0 or 5 (in ILS)")) },
                            modifier = Modifier.fillMaxWidth(),
                            singleLine = true,
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                focusedLabelColor = GBRPinkAccent,
                                unfocusedLabelColor = Color(0xFF94A3B8),
                                focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                focusedBorderColor = GBRPinkAccent,
                                unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                                cursorColor = GBRPinkAccent
                            ),
                            shape = RoundedCornerShape(12.dp)
                        )

                        // Active status checkbox
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(12.dp))
                                .clickable { isActiveInput = !isActiveInput }
                                .padding(vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Checkbox(
                                checked = isActiveInput,
                                onCheckedChange = { isActiveInput = it },
                                colors = CheckboxDefaults.colors(checkedColor = GBRBlueMain)
                            )
                            Column {
                                Text(
                                    text = t("مادة فعالة", "Active Material"),
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isActiveInput) GBRDarkIndigo else Color.Gray
                                )
                                Text(
                                    text = t("السماح باستخدام هذه المادة في تركيبات إنتاج المصنع", "Allow using this material in factory formulations"),
                                    fontSize = 11.sp,
                                    color = Color.Gray
                                )
                            }
                        }

                        // Notes Input
                        OutlinedTextField(
                            value = notesInput,
                            onValueChange = { notesInput = it },
                            label = { Text(t("ملاحظات / وصف المادة (اختياري)", "Notes / Description (Optional)")) },
                            placeholder = { Text(t("مثال: مادة ملئ ومقاومة للمعان الفائق", "e.g. Filler and anti-sheen agent")) },
                            modifier = Modifier.fillMaxWidth(),
                            minLines = 2,
                            maxLines = 3,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                                focusedLabelColor = GBRBlueMain,
                                unfocusedLabelColor = Color(0xFF94A3B8),
                                focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                                focusedBorderColor = GBRBlueMain,
                                unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                                cursorColor = GBRBlueMain
                            ),
                            shape = RoundedCornerShape(12.dp)
                        )

                        // PDF Attachment Section (TDS)
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(
                                    width = 1.dp,
                                    color = if (pdfUriInput != null) SuccessGreen else Color.LightGray.copy(alpha = 0.5f),
                                    shape = RoundedCornerShape(12.dp)
                                )
                                .background(
                                    color = if (pdfUriInput != null) SuccessGreen.copy(alpha = 0.05f) else Color.Transparent,
                                    shape = RoundedCornerShape(12.dp)
                                )
                                .padding(12.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                text = t("الدليل الفني للنشاط والمنتج (TDS PDF)", "Technical Data Sheet (TDS PDF)"),
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp,
                                color = if (pdfUriInput != null) SuccessGreen else GBRDarkIndigo
                            )

                            if (rawUploadState == "uploading") {
                                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                    LinearProgressIndicator(
                                        progress = { (rawUploadProgress / 100.0).toFloat() },
                                        modifier = Modifier.fillMaxWidth().height(6.dp).clip(RoundedCornerShape(3.dp)),
                                        color = GBRBlueMain
                                    )
                                    Text(
                                        text = "$rawUploadMessage (${rawUploadProgress.toInt()}%)",
                                        fontSize = 11.sp,
                                        color = Color.Gray,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            } else if (pdfUriInput == null) {
                                Button(
                                    onClick = { pdfPickerLauncher.launch("application/pdf") },
                                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain.copy(alpha = 0.1f)),
                                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                                ) {
                                    Text(t("📄 اختيار ملف PDF وتثبيته", "📄 Select & Attach PDF File"), color = GBRBlueMain, fontSize = 13.sp)
                                }
                            } else {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Text("✅", fontSize = 16.sp)
                                        Text(
                                            text = t("تم ربط ملف PDF بنجاح", "PDF file attached successfully"),
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = SuccessGreen
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(ErrorRed.copy(alpha = 0.1f))
                                            .clickable { pdfUriInput = null }
                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                    ) {
                                        Text(t("حذف الملف", "Delete File"), color = ErrorRed, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }

                        // Save Button
                        Button(
                            onClick = {
                                if (nameInput.isNotBlank() && productionNameInput.isNotBlank()) {
                                    val priceVal = priceInput.toDoubleOrNull() ?: 0.0
                                    viewModel.addRawMaterial(
                                        name = nameInput,
                                        productionName = productionNameInput,
                                        price = priceVal,
                                        priceUnit = "شيكل",
                                        notes = notesInput,
                                        tdsUri = pdfUriInput,
                                        isActive = isActiveInput
                                    )
                                    nameInput = ""
                                    productionNameInput = ""
                                    priceInput = ""
                                    notesInput = ""
                                    pdfUriInput = null
                                    isActiveInput = true
                                }
                            },
                            enabled = nameInput.isNotBlank() && productionNameInput.isNotBlank(),
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp)
                                .clip(RoundedCornerShape(12.dp))
                                .background(
                                    Brush.horizontalGradient(
                                        colors = if (nameInput.isNotBlank() && productionNameInput.isNotBlank()) {
                                            listOf(GBRBlueMain, GBRPurpleAccent)
                                        } else {
                                            listOf(Color.Gray.copy(alpha = 0.5f), Color.Gray.copy(alpha = 0.5f))
                                        }
                                    )
                                ),
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Transparent)
                        ) {
                            Text(
                                text = t("حفظ المادة في الذاكرة المحلية (SQLite)", "Save Material to Local Database"),
                                color = Color.White,
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp
                            )
                        }
                    }
                }
            }

            // List Header or Empty State
            val filteredMaterials = remember(materialsList, searchQueryInput) {
                if (searchQueryInput.isBlank()) {
                    materialsList
                } else {
                    materialsList.filter { material ->
                        material.name.contains(searchQueryInput, ignoreCase = true) ||
                        material.productionName.contains(searchQueryInput, ignoreCase = true)
                    }
                }
            }

            if (filteredMaterials.isEmpty()) {
                if (searchQueryInput.isNotBlank()) {
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxWidth(),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center,
                            modifier = Modifier.padding(24.dp)
                        ) {
                            Icon(
                                Icons.Default.Info,
                                contentDescription = null,
                                modifier = Modifier.size(64.dp),
                                tint = GBRBlueMain.copy(alpha = 0.4f)
                            )
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = t("لا توجد نتائج مطابقة لبحثك.", "No matching results found."),
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.Gray
                            )
                            Text(
                                text = t("يرجى المحاولة بكود آخر أو اسم مختلف.", "Please try searching with another code or name."),
                                fontSize = 12.sp,
                                color = Color.Gray,
                                textAlign = TextAlign.Center,
                                modifier = Modifier.padding(top = 4.dp)
                            )
                        }
                    }
                } else {
                    GbrEmptyState(
                        title = t("لا توجد مواد خام مسجلة حالياً 🧪", "No Raw Materials Registered Yet 🧪"),
                        description = t("للبدء، يمكنك إضافة أول مادة خام يدوياً، أو استرداد ملف قاعدة بيانات احتياطي، أو تنزيل البيانات من خادم السحابة.", "To start, add a raw material manually, restore a database backup, or sync with cloud server."),
                        onAddNew = { viewModel.isAddingRawMaterial.value = true },
                        onRestoreBackup = { viewModel.activeSegment.value = "settings" },
                        onCloudSync = { viewModel.triggerManualSync("all" ) },
                        addNewText = t("إضافة مادة خام جديدة ➕", "Add New Raw Material ➕")
                    )
                }
            } else {
                // Raw Materials List View
                LazyColumn(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredMaterials) { material ->
                        var showContextMenuForMaterial by remember { mutableStateOf(false) }

                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(14.dp))
                                .combinedClickable(
                                    onClick = { selectedMaterialDetail = material },
                                    onLongClick = { showContextMenuForMaterial = true }
                                ),
                            shape = RoundedCornerShape(14.dp),
                            colors = CardDefaults.cardColors(
                                containerColor = Color.White
                            ),
                            border = BorderStroke(1.dp, IndustrialBorder.copy(alpha = 0.9f)),
                            elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                        ) {
                            Box {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 16.dp, vertical = 12.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = material.name,
                                            fontWeight = FontWeight.ExtraBold,
                                            fontSize = 15.sp,
                                            color = if (isDark) Color.White else GBRDarkIndigo,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )

                                        Spacer(modifier = Modifier.height(6.dp))

                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            if (material.productionName.isNotBlank()) {
                                                Surface(
                                                    color = GBRBlueMain.copy(alpha = 0.08f),
                                                    shape = RoundedCornerShape(6.dp)
                                                ) {
                                                    Text(
                                                        text = material.productionName,
                                                        maxLines = 1,
                                                        overflow = TextOverflow.Ellipsis,
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = GBRBlueMain,
                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp).widthIn(max = 130.dp)
                                                    )
                                                }
                                            }

                                            val itemScope = rememberCoroutineScope()
                                            var isDownloadingCompact by remember { mutableStateOf(false) }

                                            // PDF existence Indicator
                                            Surface(
                                                color = if (!material.tdsUri.isNullOrBlank()) {
                                                    if (isDownloadingCompact) Color(0xFFFEF3C7) else Color(0xFFEFF6FF)
                                                } else Color.LightGray.copy(alpha = 0.15f),
                                                shape = RoundedCornerShape(6.dp),
                                                border = if (!material.tdsUri.isNullOrBlank()) {
                                                    BorderStroke(1.dp, if (isDownloadingCompact) Color(0xFFFDE68A) else Color(0xFFBFDBFE))
                                                } else null,
                                                modifier = Modifier.then(
                                                    if (!material.tdsUri.isNullOrBlank() && !isDownloadingCompact) {
                                                        Modifier.clickable {
                                                            itemScope.launch {
                                                                isDownloadingCompact = true
                                                                android.widget.Toast.makeText(context, if (isEn) "Fetching TDS document from cloud..." else "جاري جلب وتحديث ملف الـ TDS من السحابة...", android.widget.Toast.LENGTH_SHORT).show()
                                                                val resFile = com.example.data.GbrFileManager.getFileWithAutoUpdate(
                                                                    context = context,
                                                                    urlStr = material.tdsUri,
                                                                    targetId = material.id,
                                                                    onProgress = {}
                                                                )
                                                                isDownloadingCompact = false
                                                                if (resFile != null) {
                                                                    val success = com.example.data.GbrFileManager.openCachedFile(context, resFile)
                                                                    if (!success) {
                                                                        android.widget.Toast.makeText(context, if (isEn) "Failed to open PDF reader." else "فشل فتح مستند الـ PDF. يرجى تثبيت قارئ PDF.", android.widget.Toast.LENGTH_SHORT).show()
                                                                    }
                                                                } else {
                                                                    val diag = com.example.data.GbrFileManager.getFileDiagnostic(context, material.id)
                                                                    val prefix = if (isEn) "Failed to download document:" else "تعذر تنزيل المستند:"
                                                                    val fallback = if (isEn) "Unknown error" else "مشكلة غير معروفة"
                                                                    android.widget.Toast.makeText(context, "$prefix ${diag.failureReason ?: fallback}", android.widget.Toast.LENGTH_LONG).show()
                                                                }
                                                            }
                                                        }
                                                    } else Modifier
                                                )
                                            ) {
                                                Row(
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.Info,
                                                        contentDescription = t("عرض الدليل الفني", "View Technical Sheet"),
                                                        tint = if (!material.tdsUri.isNullOrBlank()) GBRBlueMain else Color.Gray.copy(alpha = 0.4f),
                                                        modifier = Modifier.size(12.dp)
                                                    )
                                                    Text(
                                                        text = "TDS PDF",
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = if (!material.tdsUri.isNullOrBlank()) GBRBlueMain else Color.Gray.copy(alpha = 0.5f)
                                                    )
                                                }
                                            }

                                            // Active state Indicator
                                            Surface(
                                                color = if (material.isActive) SuccessGreen.copy(alpha = 0.08f) else Color.LightGray.copy(alpha = 0.15f),
                                                shape = RoundedCornerShape(6.dp)
                                            ) {
                                                Text(
                                                    text = if (material.isActive) t("فعالة", "Active") else t("موقوفة", "Inactive"),
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = if (material.isActive) SuccessGreen else Color.Gray.copy(alpha = 0.5f),
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                        }
                                    }

                                    // Modern Price Badge
                                    Surface(
                                        color = Color(0xFFECFDF5),
                                        shape = RoundedCornerShape(10.dp),
                                        border = BorderStroke(1.dp, Color(0xFFA7F3D0))
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally
                                        ) {
                                            Text(
                                                text = t("السعر الحالي", "Current Price"),
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF065F46)
                                            )
                                            Text(
                                                text = "${material.price} ${if (material.priceUnit == "شيكل" || material.priceUnit.isBlank()) t("شيكل", "ILS") else material.priceUnit}",
                                                fontSize = 15.sp,
                                                fontWeight = FontWeight.Black,
                                                color = Color(0xFF047857)
                                            )
                                        }
                                    }
                                }

                                DropdownMenu(
                                    expanded = showContextMenuForMaterial,
                                    onDismissRequest = { showContextMenuForMaterial = false }
                                ) {
                                    DropdownMenuItem(
                                        text = { Text(t("تعديل", "Edit"), fontWeight = FontWeight.Bold) },
                                        onClick = {
                                            showContextMenuForMaterial = false
                                            materialToEdit = material
                                            editNameInput = material.name
                                            editProductionNameInput = material.productionName
                                            editPriceInput = material.price.toString()
                                            editPriceUnitInput = material.priceUnit
                                            editNotesInput = material.notes
                                            editPdfUriInput = material.tdsUri
                                            editIsActiveInput = material.isActive
                                        },
                                        leadingIcon = { Icon(Icons.Default.Edit, contentDescription = null, tint = GBRBlueMain) }
                                    )
                                    DropdownMenuItem(
                                        text = { Text(t("حذف", "Delete"), fontWeight = FontWeight.Bold, color = ErrorRed) },
                                        onClick = {
                                            showContextMenuForMaterial = false
                                            materialToDelete = material
                                        },
                                        leadingIcon = { Icon(Icons.Default.Delete, contentDescription = null, tint = ErrorRed) }
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // A. EXQUISITE EDIT MODAL DIALOG
    val editTarget = materialToEdit
    if (editTarget != null) {
        AlertDialog(
            onDismissRequest = { materialToEdit = null },
            title = {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(32.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(GBRBlueMain.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(Icons.Default.Edit, contentDescription = null, modifier = Modifier.size(18.dp), tint = GBRBlueMain)
                    }
                    Text(
                        text = t("تعديل بيانات مادة خام", "Edit Raw Material Details"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = if (isDark) Color.White else GBRDarkIndigo
                    )
                }
            },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState())
                        .padding(top = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    // Edit Name
                    OutlinedTextField(
                        value = editNameInput,
                        onValueChange = { editNameInput = it },
                        label = { Text(t("اسم المادة الحقيقي (علمياً)", "Material Real/Scientific Name")) },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = false,
                        minLines = 2,
                        maxLines = 2,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            focusedLabelColor = GBRBlueMain,
                            unfocusedLabelColor = Color(0xFF94A3B8),
                            focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            focusedBorderColor = GBRBlueMain,
                            unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                            cursorColor = GBRBlueMain
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )

                    // Edit Production Name
                    OutlinedTextField(
                        value = editProductionNameInput,
                        onValueChange = { editProductionNameInput = it },
                        label = { Text(t("اسم المادة المستخدم في الإنتاج", "Trade / Production Name")) },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = false,
                        minLines = 2,
                        maxLines = 2,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            focusedLabelColor = GBRBlueMain,
                            unfocusedLabelColor = Color(0xFF94A3B8),
                            focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            focusedBorderColor = GBRBlueMain,
                            unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                            cursorColor = GBRBlueMain
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )

                    // Edit Price
                    OutlinedTextField(
                        value = editPriceInput,
                        onValueChange = { editPriceInput = it },
                        label = { Text(t("السعر الحالي", "Current Price")) },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            focusedLabelColor = GBRPinkAccent,
                            unfocusedLabelColor = Color(0xFF94A3B8),
                            focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            focusedBorderColor = GBRPinkAccent,
                            unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                            cursorColor = GBRPinkAccent
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )

                    // Edit Active status checkbox
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(12.dp))
                            .clickable { editIsActiveInput = !editIsActiveInput }
                            .padding(vertical = 4.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Checkbox(
                            checked = editIsActiveInput,
                            onCheckedChange = { editIsActiveInput = it },
                            colors = CheckboxDefaults.colors(checkedColor = GBRBlueMain)
                        )
                        Column {
                            Text(
                                    text = t("مادة فعالة", "Active Material"),
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (editIsActiveInput) GBRDarkIndigo else Color.Gray
                            )
                            Text(
                                    text = t("السماح باستخدام هذه المادة في تركيبات إنتاج المصنع", "Allow using this material in factory formulations"),
                                    fontSize = 11.sp,
                                    color = Color.Gray
                            )
                        }
                    }

                    // Edit Notes
                    OutlinedTextField(
                        value = editNotesInput,
                        onValueChange = { editNotesInput = it },
                        label = { Text(t("الملاحظات / الوصف (اختياري)", "Notes / Description (Optional)")) },
                        modifier = Modifier.fillMaxWidth(),
                        minLines = 2,
                        maxLines = 3,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                            focusedLabelColor = GBRPinkAccent,
                            unfocusedLabelColor = Color(0xFF94A3B8),
                            focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                            focusedBorderColor = GBRPinkAccent,
                            unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder,
                            cursorColor = GBRPinkAccent
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )

                    // Edit TDS Section
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(
                                width = 1.dp,
                                color = if (editPdfUriInput != null) SuccessGreen else Color.LightGray.copy(alpha = 0.5f),
                                shape = RoundedCornerShape(12.dp)
                            )
                            .background(
                                color = if (editPdfUriInput != null) SuccessGreen.copy(alpha = 0.05f) else Color.Transparent,
                                shape = RoundedCornerShape(12.dp)
                            )
                            .padding(12.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = t("الدليل الفني للنشاط والمنتج (TDS PDF)", "Technical Data Sheet (TDS PDF)"),
                            fontWeight = FontWeight.Bold,
                            fontSize = 13.sp,
                            color = if (editPdfUriInput != null) SuccessGreen else GBRDarkIndigo
                        )

                        if (rawUploadState == "uploading") {
                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                LinearProgressIndicator(
                                    progress = { (rawUploadProgress / 100.0).toFloat() },
                                    modifier = Modifier.fillMaxWidth().height(6.dp).clip(RoundedCornerShape(3.dp)),
                                    color = GBRBlueMain
                                )
                                Text(
                                    text = "$rawUploadMessage (${rawUploadProgress.toInt()}%)",
                                    fontSize = 11.sp,
                                    color = Color.Gray,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        } else if (editPdfUriInput == null) {
                            Button(
                                onClick = { editPdfPickerLauncher.launch("application/pdf") },
                                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain.copy(alpha = 0.1f)),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                            ) {
                                Text(t("📄 اختيار ملف PDF وتثبيته", "📄 Select & Attach PDF File"), color = GBRBlueMain, fontSize = 13.sp)
                            }
                        } else {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Text("✅", fontSize = 16.sp)
                                    Text(
                                        text = t("تم ربط ملف PDF بنجاح", "PDF file attached successfully"),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = SuccessGreen
                                    )
                                }
                                Box(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(ErrorRed.copy(alpha = 0.1f))
                                        .clickable { editPdfUriInput = null }
                                        .padding(horizontal = 8.dp, vertical = 4.dp)
                                ) {
                                    Text(t("حذف الملف", "Delete File"), color = ErrorRed, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (editNameInput.isNotBlank() && editProductionNameInput.isNotBlank()) {
                            val priceVal = editPriceInput.trim().replace(',', '.').toDoubleOrNull() ?: 0.0
                            viewModel.updateRawMaterial(
                                id = editTarget.id,
                                name = editNameInput,
                                productionName = editProductionNameInput,
                                price = priceVal,
                                priceUnit = "شيكل",
                                notes = editNotesInput,
                                tdsUri = editPdfUriInput,
                                isActive = editIsActiveInput
                            )
                            materialToEdit = null
                        }
                    },
                    enabled = editNameInput.isNotBlank() && editProductionNameInput.isNotBlank(),
                    shape = RoundedCornerShape(10.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text(t("حفظ التغييرات", "Save Changes"), fontWeight = FontWeight.Bold, color = Color.White)
                }
            },
            dismissButton = {
                TextButton(
                    onClick = { materialToEdit = null }
                ) {
                    Text(t("إلغاء التعديل", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Medium)
                }
            },
            containerColor = if (isDark) IndustrialDarkSurface else Color.White,
            shape = RoundedCornerShape(20.dp)
        )
    }

    // B. EXQUISITE DELETE CONFIRMATION DIALOG
    val deleteTarget = materialToDelete
    if (deleteTarget != null) {
        val usedInFormulationIds = allFormulationItems
            .filter { it.rawMaterialId == deleteTarget.id }
            .map { it.formulationId }
            .toSet()
        val usedInFormulations = formulationsList.filter { it.id in usedInFormulationIds }
        val isUsed = usedInFormulations.isNotEmpty()

        AlertDialog(
            onDismissRequest = { materialToDelete = null },
            title = {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(32.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (isUsed) Color(0xFFF59E0B).copy(alpha = 0.15f) else ErrorRed.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            if (isUsed) Icons.Default.Warning else Icons.Default.Delete,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            tint = if (isUsed) Color(0xFFD97706) else ErrorRed
                        )
                    }
                    Text(
                        text = if (isUsed) t("لا يمكن حذف المادة الخام", "Cannot Delete Raw Material") else t("تأكيد حذف المادة الخام", "Confirm Raw Material Deletion"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        color = if (isUsed) Color(0xFFD97706) else ErrorRed
                    )
                }
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    if (isUsed) {
                        Text(
                            text = t("هذه المادة الخام مستخدمة حالياً في التركيبات التالية وصناعة المنتجات ولا يمكن حذفها لتجنب تلف البيانات:", "This raw material is currently used in the following formulations and cannot be deleted to prevent data corruption:"),
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        usedInFormulations.forEach { formulation ->
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(6.dp)
                                        .clip(CircleShape)
                                        .background(Color(0xFFD97706))
                                )
                                Text(
                                    text = formulation.name,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = Color(0xFF1E293B)
                                )
                            }
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = t("نصيحة: يرجى فتح هذه التركيبات وإزالة المادة منها أو حذف التركيبة أولاً لكي تتمكن من حذف المادة الخام بنجاح.", "Tip: Please remove this material from those formulations or delete the formulations first before deleting this material."),
                            fontSize = 12.sp,
                            color = Color.Gray,
                            lineHeight = 18.sp
                        )
                    } else {
                        Text(
                            text = t("هل أنت متأكد من حذف هذه المادة الخام نهائياً؟", "Are you sure you want to permanently delete this raw material?"),
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )
                        Text(
                            text = "${t("اسم المادة:", "Material Name:")} ${deleteTarget.name}",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Medium,
                            color = Color(0xFF475569)
                        )
                        Text(
                            text = t("تنبيه: سيؤدي هذا الإجراء إلى حذف المادة من قاعدة البيانات المحلية (SQLite).", "Warning: This action will permanently remove the material from the database."),
                            fontSize = 11.sp,
                            color = ErrorRed,
                            lineHeight = 16.sp
                        )
                    }
                }
            },
            confirmButton = {
                if (isUsed) {
                    Button(
                        onClick = { materialToDelete = null },
                        shape = RoundedCornerShape(10.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                    ) {
                        Text(t("موافق وفهمت", "OK, Understood"), fontWeight = FontWeight.Bold, color = Color.White)
                    }
                } else {
                    Button(
                        onClick = {
                            viewModel.deleteRawMaterial(deleteTarget)
                            materialToDelete = null
                        },
                        shape = RoundedCornerShape(10.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = ErrorRed)
                    ) {
                        Text(t("نعم، احذف المادة", "Yes, Delete Material"), fontWeight = FontWeight.Bold, color = Color.White)
                    }
                }
            },
            dismissButton = {
                if (!isUsed) {
                    TextButton(
                        onClick = { materialToDelete = null }
                    ) {
                        Text(t("إلغاء وتراجع", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Medium)
                    }
                }
            },
            containerColor = Color.White,
            shape = RoundedCornerShape(20.dp)
        )
    }

    // C. DYNAMIC PRICE HISTORY REPORT DIALOG
    val historyTarget = showPriceHistoryDialog
    if (historyTarget != null) {
        val historyList by remember(historyTarget.id) { viewModel.getPriceHistoryForMaterial(historyTarget.id) }.collectAsState(initial = emptyList())

        AlertDialog(
            onDismissRequest = { showPriceHistoryDialog = null },
            title = {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(32.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(GBRPinkAccent.copy(alpha = 0.15f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.List,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            tint = GBRPinkAccent
                        )
                    }
                    Text(
                        text = t("تقرير حركة الأسعار", "Price Movement Report"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = GBRDarkIndigo
                    )
                }
            },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Text(
                        text = "${t("المادة:", "Material:")} ${historyTarget.name}",
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp,
                        color = GBRDarkIndigo
                    )
                    Text(
                        text = t("يتتبع هذا التقرير جميع التعديلات التاريخية والتدريجية التي طرأت على سعر المادة الخام بوحدة الشيكل.", "This report tracks all historical price modifications for this raw material."),
                        fontSize = 12.sp,
                        color = Color.Gray,
                        lineHeight = 16.sp
                    )

                    Spacer(modifier = Modifier.height(4.dp))

                    if (historyList.isEmpty()) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFF1F5F9), RoundedCornerShape(10.dp))
                                .padding(16.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = t("لا توجد تعديلات مسجلة حتى الآن لسعر هذه المادة.", "No recorded price changes yet for this material."),
                                fontSize = 12.sp,
                                color = Color.Gray,
                                textAlign = TextAlign.Center
                            )
                        }
                    } else {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .heightIn(max = 220.dp)
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            historyList.forEachIndexed { index, entry ->
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                    shape = RoundedCornerShape(10.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(10.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = entry.dateChange,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = GBRBlueMain
                                            )
                                            Surface(
                                                color = GBRBlueMain.copy(alpha = 0.1f),
                                                shape = RoundedCornerShape(4.dp)
                                            ) {
                                                Text(
                                                    text = "${t("تعديل", "Edit")} #${historyList.size - index}",
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = GBRBlueMain,
                                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                                )
                                            }
                                        }
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "${t("من:", "From:")} ${entry.oldPrice} ${t("شيكل", "ILS")}",
                                                fontSize = 12.sp,
                                                color = Color.Gray
                                            )
                                            Text(
                                                text = "${t("إلى:", "To:")} ${entry.newPrice} ${t("شيكل", "ILS")}",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.ExtraBold,
                                                color = SuccessGreen
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = { showPriceHistoryDialog = null },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Text(t("تم الاستلام", "Done"), fontWeight = FontWeight.Bold)
                }
            },
            containerColor = Color.White,
            shape = RoundedCornerShape(20.dp)
        )
    }
}

// ==========================================
// SEGMENT 2 PANEL: FORMULATIONS (التركيبات)
// ==========================================
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun FormulationsPanel(viewModel: GbrViewModel) {
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val coroutineScope = rememberCoroutineScope()
    val formulationsList by viewModel.formulations.collectAsState()
    val selectedFormulation by viewModel.selectedFormulation.collectAsState()
    val isReadOnly by viewModel.isSelectedFormulationReadOnly.collectAsState()
    val formulationItems by viewModel.selectedFormulationDetailItems.collectAsState()
    val rawMaterialsList by viewModel.rawMaterials.collectAsState()
    val originalItems by viewModel.originalFormulationItems.collectAsState()
    val productionLogsList by viewModel.productionLogs.collectAsState()
    val allFormulationItems by viewModel.allFormulationItems.collectAsState()

    var pendingStatusChangeFormula by remember { mutableStateOf<Formulation?>(null) }
    var pendingTargetStatus by remember { mutableStateOf("") }
    var showPrintDialog by remember { mutableStateOf(false) }
    var formulationForNewVersion by remember { mutableStateOf<com.example.data.Formulation?>(null) }

    val recipePhasesList by viewModel.selectedFormulationRecipePhases.collectAsState()
    val recipeStatusObj by viewModel.selectedFormulationRecipeStatus.collectAsState()

    val latestFormulationsOnly = remember(formulationsList) {
        formulationsList
            .groupBy { it.code.trim().ifBlank { it.name.trim() }.uppercase() }
            .map { entry -> 
                entry.value.maxByOrNull { f ->
                    val ver = f.version.trim()
                    val vNum = if (ver.startsWith("الإصدار ")) {
                        ver.substringAfter("الإصدار ").trim().toIntOrNull() ?: 1
                    } else {
                        ver.filter { it.isDigit() }.toIntOrNull() ?: 1
                    }
                    vNum
                }!!
            }
    }

    val formulationVersions = remember(selectedFormulation, formulationsList) {
        val currentCode = selectedFormulation?.code.orEmpty().trim().uppercase()
        if (currentCode.isBlank()) {
            emptyList()
        } else {
            formulationsList.filter { it.code.trim().uppercase() == currentCode }
                .sortedByDescending { f ->
                    val ver = f.version.trim()
                    val vNum = if (ver.startsWith("الإصدار ")) {
                        ver.substringAfter("الإصدار ").trim().toIntOrNull() ?: 1
                    } else {
                        ver.filter { it.isDigit() }.toIntOrNull() ?: 1
                    }
                    vNum
                }
        }
    }
    val hasUnsavedChanges by viewModel.hasUnsavedChangesState.collectAsState(initial = false)
    var showBackConfirmDialog by remember { mutableStateOf(false) }
    var shouldExitAfterSave by remember { mutableStateOf(false) }
    var showRecipeUnsavedChangesDialog by remember { mutableStateOf(false) }
    var navigateToRecipeAfterSave by remember { mutableStateOf(false) }
    val isDark = false

    // State for managing ingredients of selected formulation
    var showAddMaterialDialog by remember { mutableStateOf(false) }
    var selectedRmForAdd by remember { mutableStateOf<RawMaterial?>(null) }
    var quantityForAdd by remember { mutableStateOf("") }
    var addNeedsGrinding by remember { mutableStateOf(false) }
    var addGrindingDuration by remember { mutableStateOf("30") }
    var reasonForAdd by remember { mutableStateOf("") }

    var showEditMaterialDialog by remember { mutableStateOf<FormulationItemWithDetails?>(null) }
    var quantityForEdit by remember { mutableStateOf("") }
    var editNeedsGrinding by remember { mutableStateOf(false) }
    var editGrindingDuration by remember { mutableStateOf("30") }
    var reasonForEdit by remember { mutableStateOf("") }

    var showReplaceMaterialDialog by remember { mutableStateOf<FormulationItemWithDetails?>(null) }
    var selectedRmForReplace by remember { mutableStateOf<RawMaterial?>(null) }
    var quantityForReplace by remember { mutableStateOf("") }
    var replaceNeedsGrinding by remember { mutableStateOf(false) }
    var replaceGrindingDuration by remember { mutableStateOf("30") }

    var itemToDelete by remember { mutableStateOf<FormulationItemWithDetails?>(null) }
    var reasonForDelete by remember { mutableStateOf("") }

    var showWeightMismatchDialog by remember { mutableStateOf(false) }
    var pendingSaveAction by remember { mutableStateOf<(() -> Unit)?>(null) }
    var showCompensateMaterialSelector by remember { mutableStateOf(false) }

    var showRevisionHistory by remember { mutableStateOf(false) }
    var showCostCalculator by remember { mutableStateOf(false) }
    var showPercentagesAsUnit by remember { mutableStateOf(false) }

    val context = LocalContext.current

    // State for local Search
    var searchQuery by remember { mutableStateOf("") }
    var isFormulationSearchActive by remember { mutableStateOf(false) }

    // State for status filtering
    var statusFilter by remember { mutableStateOf("🟢 معتمدة للإنتاج") }

    // State for local Form (Add)
    val isAdding by viewModel.isAddingFormulation.collectAsState()
    var addName by remember { mutableStateOf("") }
    var addDesc by remember { mutableStateOf("") }
    var addLine by remember { mutableStateOf(-1) }
    var addImageUri by remember { mutableStateOf<String?>(null) }
    val formUploadState by viewModel.formulationImageUploadState.collectAsState()
    val formUploadProgress by viewModel.formulationImageUploadProgress.collectAsState()
    val formUploadMessage by viewModel.formulationImageUploadMessage.collectAsState()
    var currentNewFormulationId by remember { mutableStateOf(java.util.UUID.randomUUID().toString()) }

    // Formulation Creation Wizard state variables
    var wizardStep by remember { mutableStateOf(1) }
    var selectedPackagesState by remember { mutableStateOf<Map<String, String>>(emptyMap()) } // CustomPackaging.id (String) -> Net Weight (String)
    var selectedTestsState by remember { mutableStateOf<Map<String, Pair<String, String>>>(emptyMap()) } // QualityTest.id (String) -> Pair(minText, maxText)

    LaunchedEffect(isAdding) {
        if (!isAdding) {
            wizardStep = 1
            addName = ""
            addDesc = ""
            addLine = -1
            addImageUri = null
            selectedPackagesState = emptyMap()
            selectedTestsState = emptyMap()
        } else {
            currentNewFormulationId = java.util.UUID.randomUUID().toString()
        }
    }

    // State for Edit Dialog
    var editId by remember { mutableStateOf<String?>(null) }
    var editPackagingId by remember { mutableStateOf<String?>(null) }
    var editQualityTestId by remember { mutableStateOf<String?>(null) }
    var editFormulationTestsMap by remember { mutableStateOf<Map<String, com.example.data.FormulationQualityTest>>(emptyMap()) }
    var limitTextInputs by remember { mutableStateOf<Map<String, Pair<String, String>>>(emptyMap()) }
    var editName by remember { mutableStateOf("") }
    var editCode by remember { mutableStateOf("") }
    val editCodeConflict = run {
        val n = editCode.trim().uppercase()
        val old = formulationsList.find { it.id == editId }?.code?.trim()?.uppercase().orEmpty()
        n.isNotBlank() && n != old && formulationsList.any { it.id != editId && it.code.trim().uppercase() == n }
    }
    var editDesc by remember { mutableStateOf("") }
    var editImageUri by remember { mutableStateOf<String?>(null) }
    var editCreatedAt by remember { mutableStateOf("") }
    var editLine by remember { mutableStateOf(-1) }
    var editSupports18L by remember { mutableStateOf(false) }
    var editNetWeight18L by remember { mutableStateOf("") }
    var editSupports5L by remember { mutableStateOf(false) }
    var editNetWeight5L by remember { mutableStateOf("") }
    var editPackagingWeights by remember { mutableStateOf<Map<String, String>>(emptyMap()) }

    // State for Delete Dialog
    var formulationToDelete by remember { mutableStateOf<Formulation?>(null) }
    var formulationWithAssociationsToShow by remember { mutableStateOf<Formulation?>(null) }
    var checkedAssociations by remember { mutableStateOf<List<com.example.ui.FormulationAssociation>>(emptyList()) }
    var isCheckingAssociations by remember { mutableStateOf(false) }

    // State for Approved Formulation Status Protection Dialog
    var blockedStatusChangeFormula by remember { mutableStateOf<Formulation?>(null) }
    var blockedStatusChangeAssociations by remember { mutableStateOf<List<com.example.ui.FormulationAssociation>>(emptyList()) }
    var blockedStatusTargetStatus by remember { mutableStateOf("") }
    var pendingUnusedRevertFormula by remember { mutableStateOf<Formulation?>(null) }
    var pendingUnusedRevertTargetStatus by remember { mutableStateOf("") }

    // State for Duplication Dialog
    var formulationToDuplicate by remember { mutableStateOf<Formulation?>(null) }
    var duplicateName by remember { mutableStateOf("") }

    // Image Picker Launchers
    val addImagePickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        uri?.let {
            val copiedUri = com.example.data.GbrFileManager.copyUriToPersistentStorage(context, it, "formulation_img")
            if (copiedUri != null) {
                viewModel.uploadFormulationImageDirectly(currentNewFormulationId, copiedUri) { cloudUrl ->
                    if (cloudUrl != null) {
                        addImageUri = cloudUrl
                        Toast.makeText(context, "تم رفع وحفظ صورة التركيبة بنجاح! ✅", Toast.LENGTH_SHORT).show()
                    } else {
                        addImageUri = copiedUri.toString()
                    }
                }
            }
        }
    }

    val editImagePickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        uri?.let {
            val formulationId = editId ?: java.util.UUID.randomUUID().toString()
            val copiedUri = com.example.data.GbrFileManager.copyUriToPersistentStorage(context, it, "formulation_img")
            if (copiedUri != null) {
                viewModel.uploadFormulationImageDirectly(formulationId, copiedUri) { cloudUrl ->
                    if (cloudUrl != null) {
                        editImageUri = cloudUrl
                        Toast.makeText(context, "تم رفع وبصمة الصورة بنجاح! ✅", Toast.LENGTH_SHORT).show()
                    } else {
                        editImageUri = copiedUri.toString()
                    }
                }
            }
        }
    }

    var formulationCameraTempUri by remember { mutableStateOf<Uri?>(null) }
    
    val addFormulationCameraLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.TakePicture()
    ) { success: Boolean ->
        if (success && formulationCameraTempUri != null) {
            viewModel.uploadFormulationImageDirectly(currentNewFormulationId, formulationCameraTempUri!!) { cloudUrl ->
                if (cloudUrl != null) {
                    addImageUri = cloudUrl
                    Toast.makeText(context, "تم التقاط ورفع صورة التركيبة بنجاح! ✅", Toast.LENGTH_SHORT).show()
                } else {
                    addImageUri = formulationCameraTempUri.toString()
                }
            }
        } else {
            Toast.makeText(context, "فشل أو تم إلغاء التقاط الصورة بالكاميرا", Toast.LENGTH_SHORT).show()
        }
    }

    val editFormulationCameraLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.TakePicture()
    ) { success: Boolean ->
        if (success && formulationCameraTempUri != null) {
            val formulationId = editId ?: java.util.UUID.randomUUID().toString()
            viewModel.uploadFormulationImageDirectly(formulationId, formulationCameraTempUri!!) { cloudUrl ->
                if (cloudUrl != null) {
                    editImageUri = cloudUrl
                    Toast.makeText(context, "تم التقاط وتعديل صورة التركيبة بنجاح! ✅", Toast.LENGTH_SHORT).show()
                } else {
                    editImageUri = formulationCameraTempUri.toString()
                }
            }
        } else {
            Toast.makeText(context, "فشل أو تم إلغاء التقاط الصورة بالكاميرا", Toast.LENGTH_SHORT).show()
        }
    }

    // Navigation and Back Button Handler for Formulations
    BackHandler(enabled = true) {
        if (selectedFormulation != null) {
            if (hasUnsavedChanges) {
                showBackConfirmDialog = true
            } else {
                viewModel.closeFormulationDetails()
            }
        } else if (isAdding) {
            viewModel.isAddingFormulation.value = false
        } else if (editId != null) {
            editId = null
        } else {
            viewModel.showSegment(null)
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        if (selectedFormulation == null) {
            // Title & Add Button Bar
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 12.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Text(
                        text = stringResource(id = R.string.formulations_title),
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isDark) Color.White else GBRDarkIndigo
                    )
                    IconButton(onClick = { 
                        isFormulationSearchActive = !isFormulationSearchActive 
                        if (!isFormulationSearchActive) searchQuery = "" 
                    }) {
                        Icon(
                            imageVector = if (isFormulationSearchActive) Icons.Default.Close else Icons.Default.Search,
                            contentDescription = t("بحث", "Search"),
                            tint = GBRBlueMain
                        )
                    }
                }

                Button(
                    onClick = { viewModel.isAddingFormulation.value = !isAdding },
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isAdding) Color(0xFF64748B) else GBRBlueMain
                    )
                ) {
                    Icon(
                        if (isAdding) Icons.Default.Close else Icons.Default.Add,
                        contentDescription = null,
                        modifier = Modifier.size(18.dp)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = if (isAdding) t("إلغاء وإغلاق", "Cancel & Close") else t("إضافة تركيبة", "Add Formulation"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp
                    )
                }
            }

            // Slide-down Add formulation Form
            AnimatedVisibility(
                visible = isAdding,
                modifier = Modifier.weight(1f, fill = false),
                enter = expandVertically() + fadeIn(),
                exit = shrinkVertically() + fadeOut()
            ) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 16.dp),
                    shape = RoundedCornerShape(20.dp),
                    border = BorderStroke(1.5.dp, if (isDark) IndustrialBorderDark else IndustrialBorder),
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDark) IndustrialDarkSurface else Color.White
                    ),
                    elevation = CardDefaults.cardElevation(defaultElevation = 3.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .verticalScroll(rememberScrollState())
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        // Elegant Progress Stepper Bar Header
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(if (isDark) Color(0xFF1E293B) else Color(0xFFF8FAFC), RoundedCornerShape(12.dp))
                                .padding(12.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Icon(Icons.Default.Add, contentDescription = null, tint = GBRBlueMain)
                                    Text(
                                        text = t("معالج إنشاء منتج جديد 🛠️", "New Product Wizard 🛠️"),
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                }
                                Text(
                                    text = t("الخطوة $wizardStep من 3", "Step $wizardStep of 3"),
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRBlueMain
                                )
                            }
                            
                            // Stepper indicator visual tracker row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(top = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                StepIndicatorItem(step = 1, currentStep = wizardStep, icon = Icons.Default.List, label = t("المعلومات", "Info"), modifier = Modifier.weight(1f))
                                Box(modifier = Modifier.width(12.dp).height(2.dp).background(if (wizardStep >= 2) GBRBlueMain else Color.LightGray))
                                StepIndicatorItem(step = 2, currentStep = wizardStep, icon = Icons.Default.Settings, label = t("العبوات", "Packages"), modifier = Modifier.weight(1f))
                                Box(modifier = Modifier.width(12.dp).height(2.dp).background(if (wizardStep >= 3) GBRBlueMain else Color.LightGray))
                                StepIndicatorItem(step = 3, currentStep = wizardStep, icon = Icons.Default.CheckCircle, label = t("المراجعة", "Review"), modifier = Modifier.weight(1f))
                            }
                        }

                        // Wizard Step Content switching
                        when (wizardStep) {
                            1 -> {
                                // Step 1: Product general info
                                Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
                                    Text(
                                        text = t("الخطوة الأولى: معلومات المنتج الأساسية 📝", "Step 1: Basic Product Info 📝"),
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    
                                    OutlinedTextField(
                                        value = addName,
                                        onValueChange = { addName = it },
                                        label = { Text(t("اسم المنتج الجديد (إجباري) *", "New Product Name (Required) *")) },
                                        placeholder = { Text(t("مثال: باما بوند 504", "Example: Bama Bond 504")) },
                                        singleLine = true,
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(12.dp),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = GBRBlueMain,
                                            unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder
                                        )
                                    )

                                    OutlinedTextField(
                                        value = addDesc,
                                        onValueChange = { addDesc = it },
                                        label = { Text(t("وصف المنتج (مثلاً الاستخدامات والتطبيقات والدهان)", "Product Description (e.g. uses, applications)")) },
                                        placeholder = { Text(t("أدخل تفاصيل ومواصفات وتطبيقات المنتج...", "Enter product details and specs...")) },
                                        modifier = Modifier.fillMaxWidth(),
                                        minLines = 2,
                                        maxLines = 3,
                                        shape = RoundedCornerShape(12.dp),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = GBRBlueMain,
                                            unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder
                                        )
                                    )

                                    com.example.ui.FormulationLineSelector(selected = addLine, onSelect = { addLine = it })

                                    // Image Picker attachment widget
                                    Column(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Text(
                                            text = t("صورة المنتج والملصق (اختياري)", "Product Image & Label (Optional)"),
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color.Gray
                                        )
                                        
                                        if (formUploadState == "uploading") {
                                            Column(
                                                modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                                                verticalArrangement = Arrangement.spacedBy(6.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally
                                            ) {
                                                LinearProgressIndicator(
                                                    progress = { (formUploadProgress / 100).toFloat() },
                                                    modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(4.dp)),
                                                    color = GBRBlueMain
                                                )
                                                Text(
                                                    text = "$formUploadMessage (${formUploadProgress.toInt()}%)",
                                                    fontSize = 12.sp,
                                                    color = Color.DarkGray,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        } else if (addImageUri != null) {
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .border(1.dp, Color.LightGray, RoundedCornerShape(12.dp))
                                                    .padding(8.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                                            ) {
                                                AsyncImage(
                                                    model = addImageUri,
                                                    contentDescription = t("صورة المنتج", "Product Image"),
                                                    contentScale = ContentScale.Crop,
                                                    modifier = Modifier
                                                        .size(56.dp)
                                                        .clip(RoundedCornerShape(8.dp))
                                                        .background(Color.LightGray.copy(alpha = 0.3f))
                                                )
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text(t("تم تحديد ملصق للتركيبة", "Product label selected"), fontSize = 13.sp, fontWeight = FontWeight.Bold)
                                                    Text(
                                                        text = t("مسار الصورة متصل", "Image path linked"),
                                                        fontSize = 11.sp,
                                                        color = Color.Gray
                                                    )
                                                }
                                                IconButton(onClick = { addImageUri = null }) {
                                                    Icon(Icons.Default.Delete, contentDescription = t("حذف الصورة", "Delete Image"), tint = ErrorRed)
                                                }
                                            }
                                        } else {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                OutlinedButton(
                                                    onClick = { addImagePickerLauncher.launch("image/*") },
                                                    modifier = Modifier.weight(1f),
                                                    shape = RoundedCornerShape(12.dp),
                                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = GBRBlueMain),
                                                    border = BorderStroke(1.dp, GBRBlueMain)
                                                ) {
                                                    Icon(Icons.Default.Collections, contentDescription = null, modifier = Modifier.size(16.dp))
                                                    Spacer(modifier = Modifier.width(6.dp))
                                                    Text(t("معرض الصور 🖼️", "Gallery 🖼️"), fontWeight = FontWeight.Bold, fontSize = 11.sp)
                                                }
                                                
                                                OutlinedButton(
                                                    onClick = {
                                                        try {
                                                            val cacheDir = com.example.data.GbrFileManager.getCacheDir(context)
                                                            val tempFile = java.io.File(cacheDir, "gbr_camera_form_${System.currentTimeMillis()}.jpg")
                                                            val authority = "${context.packageName}.provider"
                                                            val tempUri = androidx.core.content.FileProvider.getUriForFile(context, authority, tempFile)
                                                            formulationCameraTempUri = tempUri
                                                            addFormulationCameraLauncher.launch(tempUri)
                                                        } catch (e: Exception) {
                                                            android.util.Log.e("GBR_Formulation", "Error launching camera: ${e.message}", e)
                                                            Toast.makeText(context, t("فشل تهيئة الكاميرا لحفظ الصورة بدقة عالية", "Failed to initialize camera"), Toast.LENGTH_SHORT).show()
                                                        }
                                                    },
                                                    modifier = Modifier.weight(1f),
                                                    shape = RoundedCornerShape(12.dp),
                                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = GBRBlueMain),
                                                    border = BorderStroke(1.dp, GBRBlueMain)
                                                ) {
                                                    Icon(Icons.Default.PhotoCamera, contentDescription = null, modifier = Modifier.size(16.dp))
                                                    Spacer(modifier = Modifier.width(6.dp))
                                                    Text(t("التقاط كاميرا 📸", "Camera 📸"), fontWeight = FontWeight.Bold, fontSize = 11.sp)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            2 -> {
                                // Step 2: Selecting supporting custom packaging templates
                                val customPackagings by viewModel.customPackagings.collectAsState()
                                
                                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                    Text(
                                        text = t("الخطوة الثانية: العبوات المدعومة وأوزان التعبئة 📦", "Step 2: Supported Packages & Net Weights 📦"),
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    Text(
                                        text = t("اختر العبوات المعتمدة لهذا الصنف لتسهيل الميزان الرقمي وتصنيف التشغيل المخزني اللاحق:", "Select approved packaging for this item for batch calculations:"),
                                        fontSize = 12.sp,
                                        color = Color.Gray
                                    )
                                    
                                    if (customPackagings.isEmpty()) {
                                        Text(
                                            text = t("⚠️ لم يتم تعريف أي عبوات في الإعدادات العامة للنظام حالياً. سيتم حفظ الوزن التجريبي افتراضياً.", "⚠️ No packaging defined in settings currently."),
                                            color = ErrorRed,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 12.sp
                                        )
                                    } else {
                                        customPackagings.forEach { pkg ->
                                            val isChecked = selectedPackagesState.containsKey(pkg.id)
                                            val currentWeight = selectedPackagesState[pkg.id] ?: ""
                                            
                                            Card(
                                                modifier = Modifier.fillMaxWidth(),
                                                shape = RoundedCornerShape(12.dp),
                                                colors = CardDefaults.cardColors(
                                                    containerColor = if (isChecked) Color(0xFFEFF6FF) else if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC)
                                                ),
                                                border = BorderStroke(1.dp, if (isChecked) GBRBlueMain.copy(alpha = 0.5f) else Color.LightGray.copy(alpha = 0.3f))
                                            ) {
                                                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                                    Row(
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                                        modifier = Modifier.fillMaxWidth()
                                                    ) {
                                                        Checkbox(
                                                            checked = isChecked,
                                                            onCheckedChange = { checked ->
                                                                val updated = selectedPackagesState.toMutableMap()
                                                                if (checked) {
                                                                    updated[pkg.id] = pkg.netWeight.toString()
                                                                } else {
                                                                    updated.remove(pkg.id)
                                                                }
                                                                selectedPackagesState = updated
                                                            },
                                                            colors = CheckboxDefaults.colors(checkedColor = GBRBlueMain)
                                                        )
                                                        Text(
                                                            text = "${pkg.name} (${pkg.price} ${t("شيكل", "ILS")})",
                                                            fontSize = 13.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = GBRDarkIndigo,
                                                            modifier = Modifier.weight(1f)
                                                        )
                                                    }
                                                    
                                                    AnimatedVisibility(visible = isChecked) {
                                                        OutlinedTextField(
                                                            value = currentWeight,
                                                            onValueChange = { newVal ->
                                                                val updated = selectedPackagesState.toMutableMap()
                                                                updated[pkg.id] = newVal
                                                                selectedPackagesState = updated
                                                            },
                                                            label = { Text(t("الوزن الصافي المعبأ لتلك العبوة (كجم)", "Net filled weight for package (kg)")) },
                                                            placeholder = { Text(pkg.netWeight.toString()) },
                                                            singleLine = true,
                                                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                                                            modifier = Modifier.fillMaxWidth().padding(start = 12.dp),
                                                            shape = RoundedCornerShape(8.dp),
                                                            colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = GBRBlueMain)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            3 -> {
                                // Step 3: Final Summary details & review before draft launch
                                val customPackagings by viewModel.customPackagings.collectAsState()
                                
                                Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
                                    Text(
                                        text = t("الخطوة الثالثة والأخيرة: التأكيد والمراجعة 🏁", "Step 3: Confirmation & Review 🏁"),
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1E293B) else Color(0xFFFAF9F6)),
                                        shape = RoundedCornerShape(12.dp),
                                        border = BorderStroke(1.dp, Color.LightGray.copy(alpha = 0.4f))
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                            Text(text = t("اسم المنتج والوصف 📝", "Product Name & Description 📝"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                            Text(text = addName, fontSize = 16.sp, fontWeight = FontWeight.ExtraBold, color = GBRDarkIndigo)
                                            if (addDesc.isNotBlank()) {
                                                Text(text = addDesc, fontSize = 13.sp, color = Color.Gray)
                                            }
                                            
                                            Divider(color = Color.LightGray.copy(alpha = 0.3f))
                                            
                                            Text(text = t("العبوات المدعومة والتعبئة 📦", "Supported Packaging & Filling 📦"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                            val selectedPacks = customPackagings.filter { selectedPackagesState.containsKey(it.id) }
                                            if (selectedPacks.isEmpty()) {
                                                Text(text = t("⚠️ لم يتم تحديد عَبوات مفعلة!", "⚠️ No active packages selected!"), color = ErrorRed, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                            } else {
                                                selectedPacks.forEach { pkg ->
                                                    val w = selectedPackagesState[pkg.id] ?: ""
                                                    Text(text = "• ${pkg.name}: ${t("الوزن الصافي", "Net weight")} $w ${t("كجم", "kg")}", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                                                }
                                            }
                                        }
                                    }
                                    
                                    // Explanation card showing the default draft status
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1E293B) else Color(0xFFF1F5F9)),
                                        shape = RoundedCornerShape(10.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(12.dp),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(text = "⚪", fontSize = 16.sp)
                                            Column {
                                                Text(
                                                    text = t("الحالة الافتراضية للإنشاء: مسودة", "Default Creation Status: Draft"),
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = if (isDark) Color.LightGray else Color(0xFF334155)
                                                )
                                                Text(
                                                    text = t("سيتم إنشاء هذا المنتج كمسودة لعدم احتوائه على مواد خام بعد. يمكنك ملء تفاصيل ومكونات التركيبة بمجرد نجاح الإعداد.", "This product will be created as a draft. You can add ingredients after creation."),
                                                    fontSize = 11.sp,
                                                    color = if (isDark) Color.Gray else Color(0xFF64748B)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Stepper Wizard Footer Buttons Navigation
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 8.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            if (wizardStep > 1) {
                                OutlinedButton(
                                    onClick = { wizardStep -= 1 },
                                    shape = RoundedCornerShape(12.dp),
                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.Gray),
                                    border = BorderStroke(1.dp, Color.LightGray)
                                ) {
                                    Icon(Icons.Default.KeyboardArrowLeft, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(t("السابق", "Previous"), fontWeight = FontWeight.Bold)
                                }
                            } else {
                                Spacer(modifier = Modifier.width(1.dp))
                            }
                            
                            val context = androidx.compose.ui.platform.LocalContext.current
                            if (wizardStep < 3) {
                                val isNextEnabled = when (wizardStep) {
                                    1 -> addName.isNotBlank()
                                    2 -> selectedPackagesState.isNotEmpty()
                                    else -> true
                                }
                                Button(
                                    onClick = { wizardStep += 1 },
                                    enabled = isNextEnabled,
                                    shape = RoundedCornerShape(12.dp),
                                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                                ) {
                                    Text(t("التالي", "Next"), fontWeight = FontWeight.Bold)
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Icon(Icons.Default.ArrowForward, contentDescription = null, modifier = Modifier.size(16.dp))
                                }
                            } else {
                                Button(
                                    onClick = {
                                        val finalPackages = selectedPackagesState
                                        
                                        viewModel.createWizardFormulation(
                                            name = addName,
                                            description = addDesc,
                                            imageUri = addImageUri,
                                            selectedPackagesNetWeights = finalPackages,
                                            selectedTestsRanges = emptyMap(),
                                            productionLine = addLine,
                                            onSuccess = { createdFormulation ->
                                                android.widget.Toast.makeText(
                                                    context,
                                                    if (lang == "ar") "تم إنشاء التركيبة بنجاح.\nهذه التركيبة حالياً في حالة: مسودة" else "Formulation created successfully.\nCurrent status: Draft",
                                                    android.widget.Toast.LENGTH_LONG
                                                ).show()
                                                
                                                viewModel.isAddingFormulation.value = false
                                                viewModel.openFormulationDetails(createdFormulation)
                                            }
                                        )
                                    },
                                    enabled = addName.isNotBlank() && selectedPackagesState.isNotEmpty(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                                ) {
                                    Icon(Icons.Default.CheckCircle, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(t("إنشاء التركيبة بنجاح", "Create Formulation"), fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }
                }
            }

            if (!isAdding) {
                // Quick Statistics Row for Formulation types
                val approvedCount = latestFormulationsOnly.count { it.status == "🟢 معتمدة للإنتاج" }
                val devCount = latestFormulationsOnly.count { it.status == "🟡 قيد التطوير" }
                val draftCount = latestFormulationsOnly.count { it.status == "⚪ مسودة" }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                // Approved card
                Card(
                    modifier = Modifier
                        .weight(1f)
                        .clickable { statusFilter = if (lang == "ar") "🟢 معتمدة للإنتاج" else "🟢 Approved" },
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFECFDF5)),
                    border = BorderStroke(1.dp, Color(0xFFD1FAE5))
                ) {
                    Column(
                        modifier = Modifier.padding(10.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(t("معتمدة للإنتاج", "Approved"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF047857), maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("$approvedCount", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color(0xFF065F46))
                    }
                }

                // In Development card
                Card(
                    modifier = Modifier
                        .weight(1f)
                        .clickable { statusFilter = if (lang == "ar") "🟡 قيد التطوير" else "🟡 In Development" },
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                    border = BorderStroke(1.dp, Color(0xFFFEF3C7))
                ) {
                    Column(
                        modifier = Modifier.padding(10.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(t("قيد التطوير", "In Development"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFFB45309), maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("$devCount", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color(0xFF92400E))
                    }
                }

                // Draft card
                Card(
                    modifier = Modifier
                        .weight(1f)
                        .clickable { statusFilter = if (lang == "ar") "⚪ مسودة" else "⚪ Draft" },
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Column(
                        modifier = Modifier.padding(10.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(t("مسودة", "Draft"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF475569), maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Spacer(modifier = Modifier.height(4.dp))
                        Text("$draftCount", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E293B))
                    }
                }
            }

            // Search Bar for formulations
            AnimatedVisibility(
                visible = isFormulationSearchActive,
                enter = expandVertically() + fadeIn(),
                exit = shrinkVertically() + fadeOut()
            ) {
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    placeholder = { Text(t("بحث باسم التركيبة...", "Search formulation name...")) },
                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = t("بحث", "Search"), tint = GBRBlueMain) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp),
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                        unfocusedTextColor = if (isDark) Color.White else Color(0xFF0F172A),
                        focusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                        unfocusedContainerColor = if (isDark) Color(0xFF0F172A) else Color.White,
                        focusedBorderColor = GBRBlueMain,
                        unfocusedBorderColor = if (isDark) IndustrialBorderDark else IndustrialBorder
                    ),
                    trailingIcon = {
                        if (searchQuery.isNotEmpty()) {
                            IconButton(onClick = { searchQuery = "" }) {
                                Icon(Icons.Default.Clear, contentDescription = t("مسح", "Clear"), tint = Color.Gray)
                            }
                        }
                    }
                )
            }

            // Status filter chips (Classification Row)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 12.dp)
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                val filters = if (lang == "ar") listOf("الكل", "🟢 معتمدة للإنتاج", "🟡 قيد التطوير", "⚪ مسودة", "📦 الأرشيف") else listOf("All", "🟢 Approved", "🟡 In Development", "⚪ Draft", "📦 Archive")
                filters.forEach { filter ->
                    val isSelected = statusFilter == filter
                    val containerColor = if (isSelected) GBRBlueMain else Color(0xFFF1F5F9)
                    val contentColor = if (isSelected) Color.White else Color(0xFF475569)
                    val borderColor = if (isSelected) GBRBlueMain else Color(0xFFE2E8F0)
                    
                    Surface(
                        modifier = Modifier
                            .clip(RoundedCornerShape(10.dp))
                            .clickable { statusFilter = filter },
                        shape = RoundedCornerShape(10.dp),
                        color = containerColor,
                        border = BorderStroke(1.dp, borderColor)
                    ) {
                        Text(
                            text = filter,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = contentColor,
                            modifier = Modifier.padding(horizontal = 14.dp, vertical = 7.dp)
                        )
                    }
                }
            }

            // Formulations List filtering
            val filteredFormulations = latestFormulationsOnly.filter {
                val matchesSearch = it.name.contains(searchQuery, ignoreCase = true)
                val matchesStatus = when (statusFilter) {
                    "📦 الأرشيف", "📦 Archive" -> it.status.contains("مؤرشف") || it.status.contains("Archive")
                    "الكل", "All" -> !it.status.contains("مؤرشف") && !it.status.contains("Archive")
                    "🟢 معتمدة للإنتاج", "🟢 Approved" -> it.status.contains("معتمدة") || it.status.contains("Approved")
                    "🟡 قيد التطوير", "🟡 In Development" -> it.status.contains("تطوير") || it.status.contains("Development")
                    "⚪ مسودة", "⚪ Draft" -> it.status.contains("مسودة") || it.status.contains("Draft")
                    else -> it.status == statusFilter
                }
                matchesSearch && matchesStatus
            }

            if (filteredFormulations.isEmpty()) {
                val hasActiveFilter = searchQuery.isNotBlank() || (statusFilter != "الكل" && statusFilter != "All")
                if (hasActiveFilter) {
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxWidth(),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center,
                            modifier = Modifier.padding(24.dp)
                        ) {
                            Icon(
                                Icons.Default.Info,
                                contentDescription = null,
                                modifier = Modifier.size(64.dp),
                                tint = GBRBlueMain.copy(alpha = 0.4f)
                            )
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = t("لا توجد تركيبات تطابق البحث.", "No formulations match search."),
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.Gray
                            )
                        }
                    }
                } else {
                    GbrEmptyState(
                        title = t("لا توجد تركيبات طلاء مسجلة حالياً 🎨", "No paint formulations registered currently 🎨"),
                        description = t("للبدء، يمكنك إضافة أول تركيبة كيميائية معتمدة، أو استيراد ملف نسخة احتياطية محلية، أو مزامنة التطبيق مع السحابة الكونية.", "To start, add your first approved chemical formulation, restore a backup, or sync with cloud."),
                        onAddNew = { viewModel.isAddingFormulation.value = true },
                        onRestoreBackup = { viewModel.activeSegment.value = "settings" },
                        onCloudSync = { viewModel.triggerManualSync("all") },
                        addNewText = t("إضافة تركيبة تلوين جديدة ➕", "Add New Color Formulation ➕")
                    )
                }
            } else {
                LazyColumn(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredFormulations) { formula ->
                        val statusColor = when {
                            formula.status.contains("معتمدة") -> Color(0xFF10B981)
                            formula.status.contains("تطوير") -> Color(0xFFF59E0B)
                            formula.status.contains("مؤرشف") -> Color(0xFFD97706)
                            else -> Color(0xFF94A3B8)
                        }
                        val cleanStatusText = formula.status
                            .replace("🟢", "")
                            .replace("🟡", "")
                            .replace("⚪", "")
                            .replace("📦", "")
                            .trim()

                        val initials = remember(formula.name) {
                            val clean = formula.name.trim().filter { it.isLetterOrDigit() }
                            if (clean.length >= 2) {
                                clean.take(2)
                            } else if (clean.isNotEmpty()) {
                                clean.take(1)
                            } else {
                                "TR"
                            }
                        }

                        var showMenu by remember { mutableStateOf(false) }

                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { viewModel.openFormulationDetails(formula) },
                            shape = RoundedCornerShape(16.dp),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(IntrinsicSize.Min),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                // Right status vertical bar (شريط الحالة)
                                Box(
                                    modifier = Modifier
                                        .width(6.dp)
                                        .fillMaxHeight()
                                        .background(statusColor)
                                )

                                Row(
                                    modifier = Modifier
                                        .weight(1f)
                                        .padding(14.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(16.dp)
                                ) {
                                    // 1. Right product image / initials fallback
                                    Box(
                                        modifier = Modifier
                                            .size(76.dp)
                                            .clip(RoundedCornerShape(12.dp))
                                            .background(Color(0xFFF8FAFC))
                                            .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(12.dp)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        if (!formula.imageUri.isNullOrBlank()) {
                                            AsyncImage(
                                                model = formula.imageUri,
                                                contentDescription = "صورة المنتج",
                                                contentScale = ContentScale.Crop,
                                                modifier = Modifier.fillMaxSize()
                                            )
                                        } else {
                                            Box(
                                                modifier = Modifier
                                                    .fillMaxSize()
                                                    .background(statusColor.copy(alpha = 0.1f)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = initials,
                                                    color = if (statusColor == Color(0xFF94A3B8)) Color(0xFF475569) else statusColor,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 18.sp
                                                )
                                            }
                                        }
                                    }

                                    // 2. Middle product info (largest Name, soft Badge below, version/date)
                                    Column(
                                        modifier = Modifier.weight(1f),
                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Text(
                                            text = formula.name,
                                            fontSize = 16.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = GBRDarkIndigo,
                                            maxLines = 2,
                                            overflow = TextOverflow.Ellipsis
                                        )

                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(6.dp))
                                                .background(statusColor.copy(alpha = 0.12f))
                                                .padding(horizontal = 8.dp, vertical = 2.dp)
                                        ) {
                                            Text(
                                                text = cleanStatusText,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = if (statusColor == Color(0xFF94A3B8)) Color(0xFF475569) else statusColor
                                            )
                                        }

                                        Column(
                                            verticalArrangement = Arrangement.spacedBy(4.dp),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Info,
                                                    contentDescription = null,
                                                    tint = Color.Gray,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                                Text(
                                                    text = "${t("الإصدار:", "Version:")} ${formula.version.replace("الإصدار ", "v")}",
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis,
                                                    fontSize = 11.sp,
                                                    color = Color.Gray
                                                )
                                            }

                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.DateRange,
                                                    contentDescription = null,
                                                    tint = Color.Gray,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                                Text(
                                                    text = formula.createdAt.split("T").firstOrNull()?.split(" ")?.firstOrNull() ?: formula.createdAt,
