                                    // 3. Left product open details Button & settings
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        // Settings Menu dropdown
                                        Box {
                                            IconButton(
                                                onClick = { showMenu = true },
                                                modifier = Modifier.size(36.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Settings,
                                                    contentDescription = t("خيارات التركيبة", "Formulation options"),
                                                    tint = GBRBlueMain.copy(alpha = 0.8f)
                                                )
                                            }
                                            DropdownMenu(
                                                expanded = showMenu,
                                                onDismissRequest = { showMenu = false },
                                                modifier = Modifier
                                                    .width(250.dp)
                                                    .background(Color.White)
                                                    .border(BorderStroke(1.dp, Color(0xFFE2E8F0)), RoundedCornerShape(14.dp)),
                                                shape = RoundedCornerShape(14.dp)
                                            ) {
                                                // G21: عناوين مجموعات صغيرة + أيقونات خطية موحدة
                                                Text(t("التركيبة", "Formulation"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF94A3B8), modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = 6.dp, bottom = 2.dp))
                                                // 📝 Action Group 1: Edit & Manage
                                                DropdownMenuItem(
                                                    text = {
                                                        Text(
                                                            text = t("تعديل بيانات التركيبة", "Edit Formulation"),
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 13.sp,
                                                            color = GBRDarkIndigo
                                                        )
                                                    },
                                                    onClick = {
                                                        showMenu = false
                                                        viewModel.openFormulationDetails(formula)
                                                        editId = formula.id
                                                        editName = formula.name
                                                        editCode = formula.code
                                                        editDesc = formula.description
                                                        editImageUri = formula.imageUri
                                                        editCreatedAt = formula.createdAt
                                                        editLine = formula.productionLine
                                                    },
                                                    leadingIcon = { Icon(Icons.Default.Edit, contentDescription = null, tint = GBRBlueMain, modifier = Modifier.size(18.dp)) }
                                                )
                                                DropdownMenuItem(
                                                    text = {
                                                        Text(
                                                            text = t("إنشاء إصدار جديد", "Create New Version"),
                                                            fontWeight = FontWeight.Medium,
                                                            fontSize = 13.sp,
                                                            color = Color(0xFF334155)
                                                        )
                                                    },
                                                    onClick = {
                                                        showMenu = false
                                                        formulationForNewVersion = formula
                                                    },
                                                    leadingIcon = { Icon(Icons.Default.Add, contentDescription = null, tint = GBRBlueMain, modifier = Modifier.size(18.dp)) }
                                                )
                                                DropdownMenuItem(
                                                    text = {
                                                      Column {
                                                        Text(
                                                            text = t("نسخ التركيبة", "Duplicate Formulation"),
                                                            fontWeight = FontWeight.Medium,
                                                            fontSize = 13.sp,
                                                            color = Color(0xFF334155)
                                                        )
                                                        Text(t("تركيبة جديدة بنفس المواد", "A new formulation with the same materials"), fontSize = 10.sp, color = Color(0xFF94A3B8))
                                                      }
                                                    },
                                                    onClick = {
                                                        showMenu = false
                                                        formulationToDuplicate = formula
                                                        duplicateName = "${formula.name} - ${t("مكرر", "Copy")}"
                                                    },
                                                    leadingIcon = { Icon(Icons.Default.ContentCopy, contentDescription = null, tint = GBRBlueMain, modifier = Modifier.size(18.dp)) }
                                                )

                                                Divider(color = Color(0xFFF1F5F9), thickness = 1.dp, modifier = Modifier.padding(vertical = 4.dp))
                                                Text("${t("الحالة", "Status")} · ${formula.status.replace(Regex("^[^\\p{L}]+"), "")}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF94A3B8), modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = 6.dp, bottom = 2.dp))

                                                // 🟢 Action Group 2: Status Transitions
                                                if (!formula.status.contains("معتمدة") && !formula.status.contains("Approved")) {
                                                    DropdownMenuItem(
                                                        text = {
                                                            Text(
                                                                text = t("اعتماد للإنتاج", "Approve for Production"),
                                                                fontWeight = FontWeight.SemiBold,
                                                                fontSize = 13.sp,
                                                                color = Color(0xFF10B981)
                                                            )
                                                        },
                                                        onClick = {
                                                            showMenu = false
                                                            val formulaItems = allFormulationItems.filter { it.formulationId == formula.id }
                                                            val simCount = formulaItems.count { item ->
                                                                val originalPrice = rawMaterialsList.find { it.id == item.rawMaterialId }?.price
                                                                item.simulatedPrice != null && originalPrice != null && item.simulatedPrice != originalPrice
                                                            }
                                                            val targetStatusStr = if (lang == "ar") "🟢 معتمدة للإنتاج" else "🟢 Approved"
                                                            if ((formula.status.contains("مسودة") || formula.status.contains("Draft")) && simCount > 0) {
                                                                pendingStatusChangeFormula = formula
                                                                pendingTargetStatus = targetStatusStr
                                                            } else {
                                                                viewModel.updateFormulationStatus(formula.id, targetStatusStr)
                                                            }
                                                        },
                                                        leadingIcon = { Icon(Icons.Default.CheckCircle, contentDescription = null, tint = Color(0xFF10B981), modifier = Modifier.size(18.dp)) }
                                                    )
                                                }
                                                if (!formula.status.contains("تطوير") && !formula.status.contains("Development")) {
                                                    DropdownMenuItem(
                                                        text = {
                                                            Text(
                                                                text = t("نقل إلى «قيد التطوير»", "Move to In Development"),
