                                            Text(
                                                text = "${assoc.count}",
                                                color = Color.White,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                            )
                                        }
                                    }
                                    Text(
                                        text = assoc.description,
                                        fontSize = 12.sp,
                                        color = Color(0xFFB45309),
                                        modifier = Modifier.fillMaxWidth(),
                                        textAlign = TextAlign.Right
                                    )
                                    Divider(color = Color(0xFFF59E0B).copy(alpha = 0.2f), thickness = 1.dp)
                                }
                            }
                            
                            Text(
                                text = "هل ترغب في إيقاف استخدامها ونقلها إلى قسم 'الأرشيف' بدلاً من الحذف؟ ستبقى التركيبة محفوظة بكامل بياناتها التاريخية ولكنها لن تظهر في القوائم النشطة لإنشاء أوامر الإنتاج.",
                                fontSize = 13.sp,
                                color = Color.Gray,
                                modifier = Modifier.fillMaxWidth(),
                                textAlign = TextAlign.Right
                            )
                        }
                    },
                    confirmButton = {
