                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFD97706)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text("نقل إلى الأرشيف 📦", fontWeight = FontWeight.Bold)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { formulationWithAssociationsToShow = null }) {
                            Text("إلغاء", color = Color.Gray, fontWeight = FontWeight.Bold)
                        }
                    }
                )
            }

            // Protected Approved Formulation Status Dialog (associations exist)
