                                        Text(
                                            text = formula.version,
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = GBRBlueMain
                                        )
                                    }
                                }
                                Text(
                                    text = "الحالة: ${formula.status}",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = when (formula.status) {
                                         "🟢 معتمدة للإنتاج" -> Color(0xFF10B981)
                                         "🟡 قيد التطوير" -> Color(0xFFF59E0B)
                                         else -> Color(0xFF6B7280)
                                    }
                                )
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Text(
                                        text = "تاريخ آخر تعديل: ${formatDateOnly(latestRevisionDate)}",
                                        fontSize = 9.sp,
                                        color = Color.Gray,
                                    )
                                 }
                                 Spacer(modifier = Modifier.height(4.dp))
                                 Row(
                                     modifier = Modifier
                                         .clip(RoundedCornerShape(8.dp))
                                         .background(GBRBlueMain.copy(alpha = 0.05f))
                                         .clickable { showProductionHistoryDialog = true }
                                         .padding(horizontal = 10.dp, vertical = 6.dp),
                                     verticalAlignment = Alignment.CenterVertically,
                                     horizontalArrangement = Arrangement.spacedBy(6.dp)
                                 ) {
                                     Text(
                                         text = "📦 سجل الإنتاج (${formulationCompletedOrders.size})",
                                         fontSize = 11.sp,
                                         fontWeight = FontWeight.Bold,
                                         color = GBRBlueMain
                                     )
                                     Icon(
                                         imageVector = Icons.Default.KeyboardArrowLeft,
                                         contentDescription = "عرض السجل",
                                         tint = GBRBlueMain,
                                         modifier = Modifier.size(14.dp)
                                     )
                                 }
                                 if (lastOrderAdjustmentsForIndicator.isNotEmpty()) {
                                     Spacer(modifier = Modifier.height(6.dp))
                                     Row(
                                         modifier = Modifier
                                             .clip(RoundedCornerShape(8.dp))
                                             .background(Color(0xFFFEF3C7))
                                             .border(1.dp, Color(0xFFF59E0B), RoundedCornerShape(8.dp))
                                             .clickable { showLastOrderAdjustmentsDialog = true }
                                             .padding(horizontal = 10.dp, vertical = 6.dp),
                                         verticalAlignment = Alignment.CenterVertically,
                                         horizontalArrangement = Arrangement.spacedBy(6.dp)
                                     ) {
                                         Icon(
                                             imageVector = Icons.Default.Warning,
                                             contentDescription = null,
                                             tint = Color(0xFFD97706),
                                             modifier = Modifier.size(14.dp)
                                         )
                                         Text(
                                             text = "⚠ آخر أمر إنتاج احتوى على تعديلات",
                                             fontSize = 11.sp,
                                             fontWeight = FontWeight.Bold,
                                             color = Color(0xFFB45309)
                                         )
                                         Icon(
                                             imageVector = Icons.Default.KeyboardArrowLeft,
                                             contentDescription = "عرض التعديلات",
                                             tint = Color(0xFFD97706),
                                             modifier = Modifier.size(14.dp)
                                         )
                                     }
                                 }
                                 if (false) {
                                     Text(
                                         text = "",
                                        fontSize = 11.sp,
                                        color = Color.Gray,
                                        fontWeight = FontWeight.Medium
                                    )
                                    if (formula.createdAt.isNotBlank()) {
                                        Text(
                                            text = "تاريخ الإنشاء: ${formatDateOnly(formula.createdAt)}",
                                            fontSize = 11.sp,
                                            color = Color.Gray,
                                            fontWeight = FontWeight.Medium
                                        )
                                    }
                                }

                                // Display Packaging information
                                if (false) {
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = "العبوات المدعومة:",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = GBRDarkIndigo
                                        )
                                        if (formula.supports18L) {
                                            Box(
                                                modifier = Modifier
                                                    .clip(RoundedCornerShape(6.dp))
                                                    .background(GBRBlueMain.copy(alpha = 0.08f))
                                                    .border(1.dp, GBRBlueMain.copy(alpha = 0.2f), RoundedCornerShape(6.dp))
                                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                                            ) {
                                                Text(
                                                    text = "📦 18 لتر (${formula.netWeight18L.ifBlank { "لم يحدد وزن" }})",
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = GBRBlueMain
                                                )
                                            }
                                        }
                                        if (formula.supports5L) {
                                            Box(
                                                modifier = Modifier
                                                    .clip(RoundedCornerShape(6.dp))
                                                    .background(GBRBlueMain.copy(alpha = 0.08f))
                                                    .border(1.dp, GBRBlueMain.copy(alpha = 0.2f), RoundedCornerShape(6.dp))
                                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                                            ) {
                                                Text(
                                                    text = "📦 5 لتر (${formula.netWeight5L.ifBlank { "لم يحدد وزن" }})",
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = GBRBlueMain
                                                )
                                            }
                                        }
                                    }
                                }

                                Spacer(modifier = Modifier.height(6.dp))
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(Color(0xFFF1F5F9))
                                        .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(8.dp))
                                        .clickable(enabled = true) {
                                            editNotesText = formula.notes
                                            showNotesDialog = true
                                        }
                                        .padding(horizontal = 10.dp, vertical = 6.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Row(
                                        modifier = Modifier.weight(1f),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Text(
                                            text = "📝 الملاحظات:",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = GBRDarkIndigo
                                        )
                                        Text(
                                            text = if (formula.notes.isNotBlank()) {
                                                if (formula.notes.startsWith("[IMPORTANT_ALERT]")) {
                                                    formula.notes.removePrefix("[IMPORTANT_ALERT]").trim()
                                                } else {
                                                    formula.notes
                                                }
                                            } else {
                                                if (isReadOnly) "لا توجد ملاحظات مسجلة" else "لا توجد ملاحظات... انقر للإضافة أو التعديل"
                                            },
                                            fontSize = 11.sp,
                                            color = if (formula.notes.isNotBlank()) Color(0xFF475569) else Color(0xFF94A3B8),
                                            fontWeight = FontWeight.Medium,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                    }
                                    Text(
                                        text = if (isReadOnly) "عرض 🔍" else "تعديل ✎",
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRBlueMain,
                                        modifier = Modifier.padding(start = 4.dp)
                                    )
                                }
                            }
                        }

                        // Beautiful, sleek integrated bottom actions for the Formulation Card
                        HorizontalDivider(color = Color(0xFFF1F5F9), thickness = 1.dp)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFF8FAFC))
                                .padding(horizontal = 16.dp, vertical = 10.dp),
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Button(
                                onClick = { showVersionsDialog = true },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = GBRBlueMain.copy(alpha = 0.08f),
                                    contentColor = GBRBlueMain
                                ),
                                shape = RoundedCornerShape(10.dp),
                                modifier = Modifier.weight(1f),
                                contentPadding = PaddingValues(vertical = 8.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.List,
                                    contentDescription = null,
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("سجل الإصدارات 📋", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            }

                            if (formula.status == "🟢 معتمدة للإنتاج") {
                                Button(
                                    onClick = { showRevisionsDialog = true },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = GBRBlueMain.copy(alpha = 0.08f),
                                        contentColor = GBRBlueMain
                                    ),
                                    shape = RoundedCornerShape(10.dp),
                                    modifier = Modifier.weight(1f),
                                    contentPadding = PaddingValues(vertical = 8.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Info,
                                        contentDescription = null,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text("سجل التعديلات 📜", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Title for Ingredients table & Toggler
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "مكونات التركيبة",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo,
                        modifier = Modifier.padding(vertical = 4.dp)
                    )

                    // Mode Toggler for Percentages
                    Row(
                        modifier = Modifier
                            .background(Color(0xFFF1F5F9), RoundedCornerShape(20.dp))
                            .padding(3.dp),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        // KG Mode
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(16.dp))
                                .background(if (!showPercentagesAsUnit) GBRBlueMain else Color.Transparent)
                                .clickable { showPercentagesAsUnit = false }
                                .padding(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = "وزن (كجم)",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (!showPercentagesAsUnit) Color.White else Color(0xFF64748B)
                            )
                        }
                        // % Mode
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(16.dp))
                                .background(if (showPercentagesAsUnit) GBRBlueMain else Color.Transparent)
                                .clickable { showPercentagesAsUnit = true }
                                .padding(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = "نسبة مئوية (%)",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (showPercentagesAsUnit) Color.White else Color(0xFF64748B)
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(10.dp))

                // TABLE CARD
                val sharedFormulationItems = remember(formulationItems, showPercentagesAsUnit) {
                    val totalWeightForPct = formulationItems.sumOf { it.quantityMultiplier }
                    formulationItems.map { item ->
                        val itemPercentage = if (totalWeightForPct > 0) (item.quantityMultiplier / totalWeightForPct) * 100.0 else 0.0
                        val displayVal = if (showPercentagesAsUnit) {
                            formatPercent(itemPercentage)
                        } else {
                            formatQuantity(item.quantityMultiplier)
                        }
                        SharedMaterialItem(
                            id = item.id,
                            rawMaterialId = item.rawMaterialId,
                            rawMaterialName = item.rawMaterialName,
                            displayValue = displayVal,
                            needsGrinding = item.needsGrinding,
                            grindingDurationMinutes = item.grindingDurationMinutes
                        )
                    }
                }

                SharedMaterialsTable(
                    items = sharedFormulationItems,
                    isReadOnly = isReadOnly,
                    isEditable = !showPercentagesAsUnit && !isReadOnly,
                    onItemClick = { sItem ->
                        val item = formulationItems.firstOrNull { it.id == sItem.id }
                        if (item != null && !showPercentagesAsUnit && !isReadOnly) {
                            showEditMaterialDialog = item
                            quantityForEdit = item.quantityMultiplier.toString()
                            editNeedsGrinding = item.needsGrinding
                            editGrindingDuration = item.grindingDurationMinutes.toString()
                            reasonForEdit = ""
                        }
                    },
                    onMoveUp = { sItem, idx ->
                        viewModel.moveDraftItem(sItem.id, moveUp = true)
                    },
                    onMoveDown = { sItem, idx ->
                        viewModel.moveDraftItem(sItem.id, moveUp = false)
                    },
                    onDelete = { sItem ->
                        val item = formulationItems.firstOrNull { it.id == sItem.id }
                        if (item != null) {
                            itemToDelete = item
                            reasonForDelete = ""
                        }
                    }
                )

                val originalTotalWeight = remember(originalItems) { originalItems.sumOf { it.quantityMultiplier } }
                val currentTotalWeight = remember(formulationItems) { formulationItems.sumOf { it.quantityMultiplier } }
                if (originalTotalWeight > 0.0) {
                    val weightDiff = currentTotalWeight - originalTotalWeight
                    val isMatching = kotlin.math.abs(weightDiff) < 0.001
                    val diffSign = if (weightDiff > 0) "+" else ""
                    val formattedDiff = String.format(java.util.Locale.US, "%.3f", weightDiff)
                    val formattedOriginalWeight = remember(originalTotalWeight) { formatWeightTwoDecimals(originalTotalWeight) }
                    val formattedCurrentWeight = remember(currentTotalWeight) { formatWeightTwoDecimals(currentTotalWeight) }
                    
                    Spacer(modifier = Modifier.height(8.dp))
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(
                                if (isMatching) Color(0xFFF0FDF4) else Color(0xFFFEF2F2),
                                RoundedCornerShape(12.dp)
                            )
                            .border(
                                1.dp,
                                if (isMatching) Color(0xFFBBF7D0) else Color(0xFFFCA5A5),
                                RoundedCornerShape(12.dp)
                            )
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Text(
                            text = if (isMatching) {
                                "🟢 الوزن الكلي مطابق للوزن الأصلي ($formattedOriginalWeight كجم)."
                            } else {
                                "🔴 يوجد فرق في الوزن: ($diffSign$formattedDiff كجم) [الأصلي: $formattedOriginalWeight كجم، الحالي: $formattedCurrentWeight كجم]"
                            },
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (isMatching) Color(0xFF166534) else Color(0xFF991B1B)
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                if (showPercentagesAsUnit) {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF0FDF4)),
                        border = BorderStroke(1.dp, Color(0xFFBBF7D0))
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "🔒 وضع عرض النسب المئوية (للاطلاع فقط ومجموعه ١٠٠%). لا يمكن تعديل الكميات أو إضافة مواد جديدة في هذا الوضع.",
                                fontSize = 12.sp,
                                color = Color(0xFF166534),
                                fontWeight = FontWeight.Medium,
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                } else if (!isReadOnly) {
                    // Re-added "إضافة مادة" button INSIDE each formulation as requested
                    Button(
                        onClick = {
                            showAddMaterialDialog = true
                            selectedRmForAdd = null
                            quantityForAdd = ""
                            reasonForAdd = ""
                        },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                        contentPadding = PaddingValues(vertical = 12.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Add,
                            contentDescription = null,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("إضافة مادة", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                val numberOfMaterials = formulationItems.size
                val totalWeight = formulationItems.sumOf { it.quantityMultiplier }

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(14.dp),
                        horizontalArrangement = Arrangement.SpaceAround,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Text(
                                text = "عدد المواد",
                                fontSize = 12.sp,
                                color = Color.Gray,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "$numberOfMaterials",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Black,
                                color = GBRDarkIndigo
                            )
                        }

                        // Divider helper
                        Box(
                            modifier = Modifier
                                .width(1.dp)
                                .height(30.dp)
                                .background(Color(0xFFE2E8F0))
                        )

                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Text(
                                text = if (showPercentagesAsUnit) "إجمالي النسب" else "إجمالي الوزن",
                                fontSize = 12.sp,
                                color = Color.Gray,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center
                            ) {
                                Text(
                                    text = if (showPercentagesAsUnit) "100%" else "${formatWeightTwoDecimals(totalWeight)} كجم",
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.Black,
                                    color = GBRBlueMain
                                )
                                if (!showPercentagesAsUnit) {
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Box(
                                        modifier = Modifier
                                            .size(24.dp)
                                            .clickable { showTheoreticalVolumeDialog = true }
                                            .testTag("formulation_info_volume_button"),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = "🧪",
                                            fontSize = 14.sp
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // We add the "💰 حساب التكاليف" button here if the user is administrator/supervisor!
                val currentUser by viewModel.username.collectAsState()

                // Check supervisor permission
                val isSupervisor = remember(currentUser, viewModel.customUsers.collectAsState().value) {
                    val input = currentUser.trim().lowercase()
                    if (input == "admin" || input.isEmpty()) {
                        true
                    } else {
                        val matched = viewModel.customUsers.value.find { user ->
                            val uName = user.name.trim().lowercase()
                            uName == input || 
                            (uName.contains("(") && uName.substringAfter("(").substringBefore(")").trim() == input) ||
                            (uName.contains("（") && uName.substringAfter("（").substringBefore("）").trim() == input)
                        }
                        matched?.isSupervisor == true
                    }
                }

                if (isSupervisor) {
                    Spacer(modifier = Modifier.height(16.dp))
                    Button(
                        onClick = { showCostCalculator = true },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0284C7)),
                        contentPadding = PaddingValues(vertical = 14.dp)
                    ) {
                        Text("💰 حساب التكاليف", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color.White)
                    }
                }

                // Production Recipe Link status and Button
                val formulaStatus = formula.status
                if (formulaStatus == "🟢 معتمدة للإنتاج") {
                    val recipeStatusText = remember(recipePhasesList, recipeStatusObj) {
                        if (recipePhasesList.isEmpty()) {
                            "❌ لا توجد وصفة تشغيل"
                        } else {
                            val statusStr = recipeStatusObj?.status ?: "READY"
                            if (statusStr == "READY") "📖 وصفة تشغيل جاهزة" else "⚠️ وصفة التشغيل تحتاج مراجعة"
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = when {
                                recipeStatusText.contains("جاهزة") -> Color(0xFFF0FDF4)
                                recipeStatusText.contains("مراجعة") -> Color(0xFFFFFBEB)
                                else -> Color(0xFFF8FAFC)
                            }
                        ),
                        border = BorderStroke(
                            1.dp,
                            when {
                                recipeStatusText.contains("جاهزة") -> Color(0xFFBBF7D0)
                                recipeStatusText.contains("مراجعة") -> Color(0xFFFDE68A)
                                else -> Color(0xFFE2E8F0)
                            }
                        )
                    ) {
                        Row(
                            modifier = Modifier.padding(14.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(10.dp)
                                    .background(
                                        color = when {
                                            recipeStatusText.contains("جاهزة") -> Color(0xFF10B981)
                                            recipeStatusText.contains("مراجعة") -> Color(0xFFF59E0B)
                                            else -> Color(0xFF94A3B8)
                                        },
                                        shape = CircleShape
                                    )
                            )
                            Text(
                                text = "جاهزية الإنتاج: $recipeStatusText",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = when {
                                    recipeStatusText.contains("جاهزة") -> Color(0xFF166534)
                                    recipeStatusText.contains("مراجعة") -> Color(0xFF92400E)
                                    else -> Color(0xFF475569)
                                }
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Button(
                        onClick = {
                            if (hasUnsavedChanges) {
                                showRecipeUnsavedChangesDialog = true
                            } else {
                                if (recipePhasesList.isEmpty()) {
                                    viewModel.initializeRecipeForFormulation(formula.id)
                                }
                                viewModel.activeSegment.value = "recipe"
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = GBRDarkIndigo),
                        contentPadding = PaddingValues(vertical = 14.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Menu,
                            contentDescription = null,
                            tint = Color.White,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("📖 وصفة التشغيل", fontWeight = FontWeight.Black, fontSize = 15.sp, color = Color.White)
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Button(
                        onClick = {
                            if (!isReadOnly) {
                                viewModel.preselectedFormulationForOrder.value = formula
                                viewModel.isAddingProductionOrder.value = true
                                viewModel.showSegment("production")
                            }
                        },
                        enabled = !isReadOnly,
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("create_production_order_from_formula_btn"),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = GBRBlueMain,
                            disabledContainerColor = Color(0xFFE2E8F0),
                            disabledContentColor = Color(0xFF94A3B8)
                        ),
