                                onClick = {
                                    val saveAction = {
                                        showBackConfirmDialog = false
                                        if (formula.status == "🟢 معتمدة للإنتاج" && viewModel.hasRealContentChanges()) {
                                            saveReasonInput = ""
                                            shouldExitAfterSave = true
                                            showSaveReasonDialog = true
                                        } else {
                                            viewModel.saveDraftChanges("")
                                            viewModel.closeFormulationDetails()
                                        }
                                    }
                                    val origTotal = originalItems.sumOf { it.quantityMultiplier }
                                    val currTotal = formulationItems.sumOf { it.quantityMultiplier }
                                    if (originalItems.isNotEmpty() && kotlin.math.abs(origTotal - currTotal) >= 0.001) {
                                        pendingSaveAction = saveAction
                                        showWeightMismatchDialog = true
                                    } else {
                                        saveAction()
                                    }
