            if (showWeightMismatchDialog) {
                val origTotal = originalItems.sumOf { it.quantityMultiplier }
                val currTotal = formulationItems.sumOf { it.quantityMultiplier }
                val diffVal = kotlin.math.abs(origTotal - currTotal)
                val isLess = currTotal < origTotal
                val lessOrMoreText = if (isLess) "أقل" else "أكثر"
                
                AlertDialog(
                    onDismissRequest = { 
                        showWeightMismatchDialog = false 
                        pendingSaveAction = null
                    },
                    shape = RoundedCornerShape(20.dp),
                    containerColor = Color.White,
                    title = {
                        Text(
                            text = "تنبيه: اختلاف في الوزن الكلي ⚠️",
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo,
                            modifier = Modifier.fillMaxWidth(),
                            textAlign = TextAlign.Right
                        )
