                    text = {
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Text(
                                text = "تم تعديل كمية إحدى المواد، وأصبح الوزن الكلي $lessOrMoreText بمقدار ${String.format(java.util.Locale.US, "%.3f", diffVal)} كجم.\nكيف تريد معالجة الفرق؟",
                                fontSize = 14.sp,
                                color = Color.DarkGray,
                                modifier = Modifier.fillMaxWidth(),
                                textAlign = TextAlign.Right,
                                lineHeight = 20.sp
                            )
                        }
                    },
                    confirmButton = {
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(8.dp),
