                            // Option 1: Compensate with another material (التعويض بمادة أخرى)
                            Button(
                                onClick = {
                                    showCompensateMaterialSelector = true
                                    showWeightMismatchDialog = false
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("التعويض بمادة أخرى", fontWeight = FontWeight.Bold)
                            }

                            // Option 2: Compensate with water (التعويض بالماء)
