                                onClick = {
                                    val waterItem = formulationItems.find { 
                                        it.rawMaterialName.contains("ماء") || 
                                        it.rawMaterialName.lowercase().contains("water") 
                                    }
                                    if (waterItem != null) {
                                        val difference = origTotal - currTotal
                                        val adjustedQty = waterItem.quantityMultiplier + difference
                                        if (adjustedQty < 0) {
                                            Toast.makeText(context, "الكمية الناتجة للماء ستكون سالبة (${String.format(java.util.Locale.US, "%.3f", adjustedQty)} كجم)، لا يمكن التعويض بالماء.", Toast.LENGTH_LONG).show()
                                        } else {
                                            viewModel.updateDraftItem(
