                                        val hasAdjustments = orderAdjustments.isNotEmpty()
                                        Card(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable {
                                                    showProductionHistoryDialog = false
                                                    viewModel.orderOpeningSourceSegment.value = "formulations"
                                                    viewModel.activeSegment.value = "production"
                                                    viewModel.selectedProductionOrder.value = order
                                                },
                                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                            shape = RoundedCornerShape(12.dp)
