                AlertDialog(
                    onDismissRequest = { editPackagingId = null },
                    shape = RoundedCornerShape(24.dp),
                    containerColor = Color.White,
                    title = {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = if (isReadOnly) "الاطلاع على العبوات المدعومة 📦" else "العبوات المدعومة واوزان التعبئة 📦",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = GBRDarkIndigo
                            )
                            IconButton(onClick = { editPackagingId = null }) {
                                Icon(Icons.Default.Close, contentDescription = "إغلاق")
                            }
                        }
                    },
                    text = {
                        val customPackagings by viewModel.customPackagings.collectAsState()
                        LazyColumn(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(14.dp)
                        ) {
                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(12.dp),
                                        verticalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Text(
                                            text = if (isReadOnly) "انواع العبوات المعتمدة وأوزانها المحددة لهذه التركيبة" else "انواع العبوات المعتمدة وأوزانها لهذه التركيبة",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 12.sp,
                                            color = GBRDarkIndigo
                                        )
                                        HorizontalDivider(color = Color(0xFFE2E8F0))
                                        
                                        customPackagings.forEachIndexed { index, pkg ->
                                            val isChecked = editPackagingWeights.containsKey(pkg.id)
                                            val rawVal = editPackagingWeights[pkg.id] ?: ""
                                            val parts = rawVal.split(":")
                                            val weightVal = parts.getOrNull(0) ?: ""
                                            val costVal = parts.getOrNull(1) ?: "0.0"
                                            
                                            Column(modifier = Modifier.fillMaxWidth()) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                ) {
                                                    Checkbox(
                                                        checked = isChecked,
                                                        onCheckedChange = { checked ->
                                                            if (!isReadOnly) {
                                                                val newMap = editPackagingWeights.toMutableMap()
                                                                if (checked) {
                                                                    val defaultWeight = if (pkg.name.contains("18")) "25.0" else if (pkg.name.contains("5")) "7.2" else "1.0"
                                                                    newMap[pkg.id] = "$defaultWeight:0.0"
                                                                } else {
                                                                    newMap.remove(pkg.id)
                                                                }
                                                                editPackagingWeights = newMap
                                                            }
                                                        },
                                                        enabled = !isReadOnly,
                                                        colors = CheckboxDefaults.colors(checkedColor = GBRBlueMain)
                                                    )
                                                    Text(
                                                        text = "${pkg.name} (${pkg.price} شيكل)",
                                                        fontSize = 13.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = Color(0xFF334155),
                                                        modifier = Modifier.weight(1f)
                                                    )
                                                }
                                                
                                                if (isChecked) {
                                                    OutlinedTextField(
                                                        value = weightVal,
                                                        onValueChange = { newVal ->
                                                            if (!isReadOnly) {
                                                                val newMap = editPackagingWeights.toMutableMap()
                                                                newMap[pkg.id] = "$newVal:$costVal"
                                                                editPackagingWeights = newMap
                                                            }
                                                        },
                                                        enabled = !isReadOnly,
                                                        readOnly = isReadOnly,
                                                        label = { Text("الوزن الصافي (كجم)") },
                                                        modifier = Modifier.fillMaxWidth().padding(start = 12.dp, bottom = 4.dp),
                                                        singleLine = true,
                                                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                                                        shape = RoundedCornerShape(10.dp),
                                                        colors = OutlinedTextFieldDefaults.colors(
                                                            focusedBorderColor = GBRBlueMain,
                                                            unfocusedBorderColor = Color.LightGray,
                                                            focusedContainerColor = Color.White,
                                                            unfocusedContainerColor = Color.White
                                                        )
                                                    )
                                                }
                                                
                                                if (index < customPackagings.size - 1) {
                                                    HorizontalDivider(color = Color(0xFFE2E8F0), modifier = Modifier.padding(vertical = 4.dp))
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    confirmButton = {
                        if (!isReadOnly) {
                            Button(
                                onClick = {
                                    if (editPackagingId != null) {
                                        viewModel.updateFormulationPackaging(
                                            id = editPackagingId!!,
                                            supports18L = editSupports18L,
                                            netWeight18L = editNetWeight18L,
                                            supports5L = editSupports5L,
                                            netWeight5L = editNetWeight5L,
                                            packagingWeightsJson = org.json.JSONObject(editPackagingWeights as Map<*,*>).toString()
                                        )
                                        editPackagingId = null
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("حفظ التعبئة", fontWeight = FontWeight.Bold)
                            }
                        } else {
                            Button(
                                onClick = { editPackagingId = null },
                                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("إغلاق", fontWeight = FontWeight.Bold)
                            }
                        }
                    },
                    dismissButton = {
                        if (!isReadOnly) {
                            TextButton(onClick = { editPackagingId = null }) {
                                Text("إلغاء", color = Color.Gray, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                )
            }

        if (showCostCalculator && selectedFormulation != null) {
            val allPackagings by viewModel.customPackagings.collectAsState()
            androidx.compose.ui.window.Dialog(
                onDismissRequest = { showCostCalculator = false },
                properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
            ) {
                CostCalculatorScreen(
                    formulation = selectedFormulation!!,
                    items = formulationItems,
                    allPackagings = allPackagings,
                    viewModel = viewModel,
                    onDismiss = { showCostCalculator = false }
                )
            }
        }
    }

    if (pendingStatusChangeFormula != null) {
        SimulatedPriceStatusChangeDialog(
            formula = pendingStatusChangeFormula!!,
            targetStatus = pendingTargetStatus,
            allFormulationItems = allFormulationItems,
            rawMaterialsList = rawMaterialsList,
            viewModel = viewModel,
            onDismiss = { pendingStatusChangeFormula = null }
        )
    }

    if (formulationForNewVersion != null) {
        val formula = formulationForNewVersion!!
        AlertDialog(
            onDismissRequest = { formulationForNewVersion = null },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = "إنشاء إصدار جديد للتركيبة 🧪",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Text(
                    text = "هل أنت متأكد من رغبتك في إنشاء إصدار جديد من تركيبة \"${formula.name}\"؟\n\n- سيتم توليد الإصدار التالي تلقائياً في حالة قيد التطوير.\n- سيتم إغلاق الإصدار الحالي ولن يطرأ عليه أي تعديلات مستقبلية لحفظ تاريخ التصنيع وجودته كنسخة (للقراء فقط 🔒).",
                    fontSize = 13.sp,
                    color = Color(0xFF334155),
                    textAlign = TextAlign.Right
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.createNewVersion(formula)
                        formulationForNewVersion = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("تأكيد وإنشاء الإصدار 🎯", fontWeight = FontWeight.Bold, color = Color.White)
                }
            },
            dismissButton = {
                TextButton(
                    onClick = { formulationForNewVersion = null }
                ) {
                    Text("إلغاء الأمر", color = Color.Gray, fontWeight = FontWeight.SemiBold)
                }
            }
        )
    }
}
}

@Composable
fun SimulatedPriceStatusChangeDialog(
    formula: com.example.data.Formulation,
    targetStatus: String,
    allFormulationItems: List<com.example.data.FormulationItem>,
    rawMaterialsList: List<com.example.data.RawMaterial>,
    viewModel: com.example.ui.GbrViewModel,
    onDismiss: () -> Unit
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val formulaItems = allFormulationItems.filter { it.formulationId == formula.id }
    val simCount = formulaItems.count { item ->
        val originalPrice = rawMaterialsList.find { it.id == item.rawMaterialId }?.price
        item.simulatedPrice != null && originalPrice != null && item.simulatedPrice != originalPrice
    }
    
    var selectedOption by remember(formula.id) { mutableStateOf(0) }
    
    AlertDialog(
        onDismissRequest = onDismiss,
        shape = RoundedCornerShape(20.dp),
        containerColor = Color.White,
        title = {
            Text(
                text = "⚠️ تم اكتشاف أسعار محاكاة داخل هذه التركيبة",
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                color = Color(0xFFC2410C),
                modifier = Modifier.fillMaxWidth(),
                textAlign = TextAlign.Right
            )
        },
        text = {
            Column(
                verticalArrangement = Arrangement.spacedBy(14.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    text = "هذه التركيبة تحتوي على أسعار محاكاة غير معتمدة لعدد ($simCount) من المواد.\n\nعند نقل التركيبة إلى الحالة الجديدة ($targetStatus)، كيف ترغب في التعامل مع أسعار المحاكاة؟",
                    fontSize = 12.sp,
                    color = Color(0xFF1E293B),
                    lineHeight = 18.sp,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
                
                Column(
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    val isApprovedTarget = targetStatus == "🟢 معتمدة للإنتاج"

                    // Option 0: Revert to official
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (selectedOption == 0) Color(0xFFF1F5F9) else Color.Transparent)
                            .clickable { selectedOption = 0 }
                            .padding(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        RadioButton(
                            selected = selectedOption == 0,
                            onClick = { selectedOption = 0 }
                        )
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (isApprovedTarget) "سوف يتم تحويل الأسعار إلى الأسعار الأصلية المسجلة" else "اعتماد الأسعار الأصلية من قاعدة المواد الخام",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1E293B),
                                textAlign = TextAlign.Right,
                                modifier = Modifier.fillMaxWidth()
                            )
                            Text(
                                text = if (isApprovedTarget) "سيتم إلغاء أسعار المحاكاة واستيراد الأسعار المسجلة رسمياً لكل مادة خام بشكل آلي." else "سيتم التخلص من أسعار المحاكاة واستيراد الأسعار الرسمية من قاعدة المواد.",
                                fontSize = 10.sp,
                                color = Color.Gray,
                                textAlign = TextAlign.Right,
                                modifier = Modifier.fillMaxWidth()
                            )
                        }
                    }
                    
                    if (!isApprovedTarget) {
                        // Option 1: Keep override
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(if (selectedOption == 1) Color(0xFFF1F5F9) else Color.Transparent)
                                .clickable { selectedOption = 1 }
                                .padding(8.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            RadioButton(
                                selected = selectedOption == 1,
                                onClick = { selectedOption = 1 }
                            )
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = "الاحتفاظ بأسعار المحاكاة داخل هذه النسخة",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF1E293B),
                                    textAlign = TextAlign.Right,
                                    modifier = Modifier.fillMaxWidth()
                                )
                                Text(
                                    text = "سيتم تجميد أسعار المحاكاة الحالية واعتمادها كأسعار رسمية ثابتة لهذه النسخة فقط.",
                                    fontSize = 10.sp,
                                    color = Color.Gray,
                                    textAlign = TextAlign.Right,
                                    modifier = Modifier.fillMaxWidth()
                                )
                            }
                        }
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    if (selectedOption == 0) {
                        // Revert to official prices
                        viewModel.clearAllFormulationItemSimulatedPrices(formula.id)
                        viewModel.updateFormulationStatus(formula.id, targetStatus)
                        android.widget.Toast.makeText(context, "تم التراجع عن أسعار المحاكاة واستعادة الأسعار الأصلية! 🔄", android.widget.Toast.LENGTH_LONG).show()
                    } else {
                        // Keep simulated prices
                        viewModel.updateFormulationStatus(formula.id, targetStatus)
                        android.widget.Toast.makeText(context, "تم بنجاح الاحتفاظ بأسعار المحاكاة كشروط معتمدة للنسخة! 💾", android.widget.Toast.LENGTH_LONG).show()
                    }
                    onDismiss()
                },
                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
            ) {
                Text("متابعة", color = Color.White, fontWeight = FontWeight.Bold)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("إلغاء")
            }
        }
    )
}

@Composable
fun CostCalculatorScreen(
    formulation: Formulation,
    items: List<FormulationItemWithDetails>,
    allPackagings: List<com.example.ui.GbrViewModel.CustomPackaging>,
    viewModel: GbrViewModel,
    onDismiss: () -> Unit
) {
    val context = LocalContext.current
    val isDraft = formulation.status == "⚪ مسودة"
    
    // Manage simulated prices in local state instead of db on-the-fly
    val localSimulatedPrices = remember(items) {
        val map = androidx.compose.runtime.mutableStateMapOf<String, Double?>()
        items.forEach { map[it.id] = it.simulatedPrice }
        map
    }

    var selectedItemForSimulation by remember { mutableStateOf<FormulationItemWithDetails?>(null) }
    var simulationPriceInput by remember { mutableStateOf("") }

    val refSpecsState = remember(formulation.id) { viewModel.getFormulationReferenceSpecs(formulation.id) }.collectAsState(initial = null)

    // Parse dynamic packaging weights and extra/operating costs from formulation settings
    val supportedPackagings = remember(formulation, allPackagings) {
        try {
            if (formulation.packagingWeightsJson.isBlank()) {
                emptyList()
            } else {
                val json = org.json.JSONObject(formulation.packagingWeightsJson)
                val list = mutableListOf<Triple<com.example.ui.GbrViewModel.CustomPackaging, Double, Double>>() // (Packaging, NetWeight, OperatingCost)
                allPackagings.forEach { pkg ->
                    if (json.has(pkg.id)) {
                        val rawVal = json.optString(pkg.id, "")
                        val parts = rawVal.split(":")
                        val netW = parts.getOrNull(0)?.toDoubleOrNull() ?: 1.0
                        val extraC = parts.getOrNull(1)?.toDoubleOrNull() ?: 0.0
                        list.add(Triple(pkg, netW, extraC))
                    }
                }
                list
            }
        } catch (e: Exception) {
            emptyList()
        }
    }

    // Calculations based on local simulated prices
    val itemsWithCosts = remember(items, localSimulatedPrices.toMap()) {
        items.map { item ->
            val activePrice = localSimulatedPrices[item.id] ?: item.rawMaterialPrice
            val cost = item.quantityMultiplier * activePrice
            Triple(item, activePrice, cost)
        }
    }

    val totalRawCost = itemsWithCosts.sumOf { it.third }
    val totalWeight = items.sumOf { it.quantityMultiplier }
    val costPerKg = if (totalWeight > 0) totalRawCost / totalWeight else 0.0

    // Fetch initial total operating cost from json
    val initialTotalOperatingCost = remember(formulation) {
        try {
            if (formulation.packagingWeightsJson.isNotBlank()) {
                val json = org.json.JSONObject(formulation.packagingWeightsJson)
                if (json.has("total_operating_cost")) {
                    val savedTotal = json.optDouble("total_operating_cost", 0.0)
                    if (savedTotal > 0.0) {
                        formatCost(savedTotal)
                    } else ""
                } else {
                    ""
                }
            } else {
                ""
            }
        } catch (e: java.lang.Exception) {
            ""
        }
    }

    var operatingCostInput by remember(initialTotalOperatingCost) { mutableStateOf(initialTotalOperatingCost) }
    val enteredOperatingCost = operatingCostInput.toDoubleOrNull() ?: 0.0
    val operatingCostPerKg = if (totalWeight > 0) enteredOperatingCost / totalWeight else 0.0

    // Detect if we have unsaved changes
    val hasUnsavedChanges = remember(localSimulatedPrices.toMap(), operatingCostInput, items, initialTotalOperatingCost) {
        val pricesChanged = items.any { item ->
            localSimulatedPrices[item.id] != item.simulatedPrice
        }
        val operatingCostChanged = operatingCostInput != initialTotalOperatingCost
        pricesChanged || operatingCostChanged
    }

    var showExitConfirmDialog by remember { mutableStateOf(false) }

    val supportedPackagingsWithOperating = remember(supportedPackagings, operatingCostPerKg) {
        supportedPackagings.map { (pkg, netW, _) ->
            val computedExtraCost = netW * operatingCostPerKg
            Triple(pkg, netW, computedExtraCost)
        }
    }

    var selectedIndex by remember { mutableStateOf(0) }
    
    // Clamp selectedIndex if supportedPackagingsWithOperating changed
    val activeIndex = if (supportedPackagingsWithOperating.isNotEmpty()) {
        selectedIndex.coerceIn(0, supportedPackagingsWithOperating.size - 1)
    } else {
        0
    }

    val currentSelection = supportedPackagingsWithOperating.getOrNull(activeIndex)
    val selectedPackage = currentSelection?.first
    
    val netWeight = currentSelection?.second ?: 0.0
    val packagingCost = selectedPackage?.price ?: 0.0

    val paintCostInside = costPerKg * netWeight
    val packagesCount = if (netWeight > 0.0) totalWeight / netWeight else 0.0
    val operatingCostPerPackage = currentSelection?.third ?: 0.0

    val finalCost = paintCostInside + packagingCost + operatingCostPerPackage

    val originalTotalRawCost = remember(items) {
        items.sumOf { it.quantityMultiplier * it.rawMaterialPrice }
    }
    val originalCostPerKg = if (totalWeight > 0) originalTotalRawCost / totalWeight else 0.0
    val originalPaintCostInside = originalCostPerKg * netWeight
    val originalFinalCost = originalPaintCostInside + packagingCost + operatingCostPerPackage

    val hasActiveSimulation = remember(items, localSimulatedPrices.toMap()) {
        items.any { item ->
            val simPrice = localSimulatedPrices[item.id]
            simPrice != null && simPrice != item.rawMaterialPrice
        }
    }
    val costDiff = finalCost - originalFinalCost

    // Interactive explanatory modal/dialog states
    var showHelpNetCostPerKg by remember { mutableStateOf(false) }
    var showHelpPaintCostInside by remember { mutableStateOf(false) }
    var showHelpOperatingCostPerKg by remember { mutableStateOf(false) }
    var isPackagingsExpanded by remember { mutableStateOf(false) }

    if (showHelpNetCostPerKg) {
        AlertDialog(
            onDismissRequest = { showHelpNetCostPerKg = false },
            title = {
                Text(
                    text = "تفاصيل العمليّة الحسابيّة ℹ️",
                    fontWeight = FontWeight.Bold,
                    fontSize = 16.sp,
                    color = GBRDarkIndigo
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        text = "طريقة حساب تكلفة الكيلو الصافي للتركيبة:",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF1E293B)
                    )
                    Text(
                        text = "التكلفة = (إجمالي كلفة المواد الخام المباشرة) ÷ (إجمالي الوزن الكلي للتركيبة بالكيلو).\n\nهذه القيمة تعبر عن تكلفة المواد الكيميائية لكل كيلو جرام واحد من هذا الدهان بشكل دقيق جداً قبل تعبئته.",
                        fontSize = 12.sp,
                        color = Color(0xFF475569),
                        lineHeight = 18.sp
                    )
                }
            },
            confirmButton = {
                TextButton(onClick = { showHelpNetCostPerKg = false }) {
                    Text("حسناً وفهمت", fontWeight = FontWeight.Bold, color = GBRBlueMain)
                }
            },
            shape = RoundedCornerShape(16.dp),
            containerColor = Color.White
        )
    }

    if (selectedItemForSimulation != null) {
        val currentItem = selectedItemForSimulation!!
        AlertDialog(
            onDismissRequest = { selectedItemForSimulation = null },
            title = {
                Text(
                    text = "📊 محاكاة سعر: ${currentItem.rawMaterialName}",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Column(
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = "تحديد سعر افتراضي خاص بهذه المادة في هذه التركيبة فقط لإجراء دراسة محاكاة التكاليف والتأثير على السعر النهائي.",
                        fontSize = 12.sp,
                        color = Color.Gray,
                        lineHeight = 18.sp,
                        modifier = Modifier.fillMaxWidth(),
                        textAlign = TextAlign.Right
                    )
                    
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFFF8FAFC), RoundedCornerShape(8.dp))
                            .padding(8.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "${currentItem.rawMaterialPrice} ${t("شيكل", "ILS")} / ${t("كجم", "kg")}",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF1E293B)
                        )
                        Text(
                            text = t("السعر الرسمي المعتمد:", "Official Approved Price:"),
                            fontSize = 12.sp,
                            color = Color(0xFF475569)
                        )
                    }
                    
                    OutlinedTextField(
                        value = simulationPriceInput,
                        onValueChange = { simulationPriceInput = it },
                        label = { Text(t("سعر المحاكاة الجديد", "New Simulation Price"), fontSize = 12.sp, fontWeight = FontWeight.Bold) },
                        placeholder = { Text(t("مثال: 28.5", "e.g. 28.5"), fontSize = 12.sp) },
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                        modifier = Modifier.fillMaxWidth(),
                        trailingIcon = {
                            Text(t("شيكل", "ILS"), style = TextStyle(fontWeight = FontWeight.Bold, color = GBRBlueMain), modifier = Modifier.padding(end = 12.dp))
                        },
                        shape = RoundedCornerShape(10.dp)
                    )
                    
                    Text(
