    if (showExitConfirmDialog) {
        AlertDialog(
            onDismissRequest = { showExitConfirmDialog = false },
            title = {
                Text(
                    text = "⚠️ حفظ التعديلات",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Text(
                    text = "لقد أجريت تعديلات على أسعار المحاكاة أو تكاليف التشغيل. هل تود حفظ هذه التعديلات قبل الخروج؟",
                    fontSize = 13.sp,
                    color = Color(0xFF334155),
                    lineHeight = 20.sp,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        val currentOperatingCost = operatingCostInput.toDoubleOrNull() ?: 0.0
                        val currentWeightsJson = try {
                            val currentJson = if (formulation.packagingWeightsJson.isBlank()) {
                                org.json.JSONObject()
                            } else {
                                org.json.JSONObject(formulation.packagingWeightsJson)
                            }
                            currentJson.put("total_operating_cost", currentOperatingCost)
                            allPackagings.forEach { pkg ->
                                if (currentJson.has(pkg.id)) {
                                    val rawVal = currentJson.optString(pkg.id, "")
                                    val parts = rawVal.split(":")
                                    val netW = parts.getOrNull(0)?.toDoubleOrNull() ?: pkg.netWeight
                                    val pkgOperatingCost = netW * operatingCostPerKg
                                    currentJson.put(pkg.id, "$netW:$pkgOperatingCost")
                                }
                            }
                            currentJson.toString()
                        } catch (e: Exception) {
                            formulation.packagingWeightsJson
                        }
                        
                        viewModel.saveFormulationSimulationAndOperatingCostBatch(
                            formulationId = formulation.id,
                            simulatedPrices = localSimulatedPrices.toMap(),
                            packagingWeightsJson = currentWeightsJson
                        )
                        showExitConfirmDialog = false
                        Toast.makeText(context, "تم حفظ جميع التعديلات بنجاح 💾", Toast.LENGTH_SHORT).show()
                        onDismiss()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981))
                ) {
                    Text("حفظ التعديلات وخروج", color = Color.White, fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    TextButton(
                        onClick = {
                            showExitConfirmDialog = false
                            onDismiss()
                        }
                    ) {
                        Text("خروج دون حفظ", color = Color(0xFFDC2626), fontWeight = FontWeight.Bold)
                    }
                    TextButton(
                        onClick = { showExitConfirmDialog = false }
                    ) {
                        Text("إلغاء", color = Color.Gray)
                    }
                }
            },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White
        )
    }

    Surface(
        modifier = Modifier.fillMaxSize(),
        color = Color(0xFFF8FAFC)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            // Top App Bar
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 16.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.weight(1f)
                ) {
                    IconButton(onClick = {
                        if (hasUnsavedChanges) {
                            showExitConfirmDialog = true
                        } else {
                            onDismiss()
                        }
                    }) {
                        Icon(imageVector = Icons.Default.ArrowForward, contentDescription = "رجوع", tint = GBRBlueMain)
                    }
                    Column(
                        modifier = Modifier.weight(1f)
                    ) {
                        Text(
                            text = "تحليل التكاليف",
                            fontSize = 17.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        Text(
                            text = formulation.name,
                            fontSize = 12.sp,
                            color = Color.Gray,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
                
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    if (hasUnsavedChanges) {
                        Button(
                            onClick = {
                                val currentOperatingCost = operatingCostInput.toDoubleOrNull() ?: 0.0
                                val currentWeightsJson = try {
                                    val currentJson = if (formulation.packagingWeightsJson.isBlank()) {
                                        org.json.JSONObject()
                                    } else {
                                        org.json.JSONObject(formulation.packagingWeightsJson)
                                    }
                                    currentJson.put("total_operating_cost", currentOperatingCost)
                                    allPackagings.forEach { pkg ->
                                        if (currentJson.has(pkg.id)) {
                                            val rawVal = currentJson.optString(pkg.id, "")
                                            val parts = rawVal.split(":")
                                            val netW = parts.getOrNull(0)?.toDoubleOrNull() ?: pkg.netWeight
                                            val pkgOperatingCost = netW * operatingCostPerKg
                                            currentJson.put(pkg.id, "$netW:$pkgOperatingCost")
                                        }
                                    }
                                    currentJson.toString()
                                } catch (e: Exception) {
                                    formulation.packagingWeightsJson
                                }
                                
                                viewModel.saveFormulationSimulationAndOperatingCostBatch(
                                    formulationId = formulation.id,
                                    simulatedPrices = localSimulatedPrices.toMap(),
                                    packagingWeightsJson = currentWeightsJson
                                )
                                Toast.makeText(context, "تم حفظ جميع التعديلات بنجاح 💾", Toast.LENGTH_SHORT).show()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF10B981)),
                            contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                            modifier = Modifier.height(36.dp),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Icon(imageVector = Icons.Default.Check, contentDescription = null, modifier = Modifier.size(16.dp), tint = Color.White)
                            Spacer(modifier = Modifier.width(4.dp))
                            Text("حفظ التعديلات 💾", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.White)
                        }
                    }

                    // Print Cost Analysis Button
                    Button(
                        onClick = {
                            val transientItems = items.map { item ->
                                item.copy(simulatedPrice = localSimulatedPrices[item.id])
                            }
                            val transientFormulation = formulation.copy(
                                packagingWeightsJson = try {
                                    val currentJson = if (formulation.packagingWeightsJson.isBlank()) {
                                        org.json.JSONObject()
                                    } else {
                                        org.json.JSONObject(formulation.packagingWeightsJson)
                                    }
                                    currentJson.put("total_operating_cost", operatingCostInput.toDoubleOrNull() ?: 0.0)
                                    allPackagings.forEach { pkg ->
                                        if (currentJson.has(pkg.id)) {
                                            val rawVal = currentJson.optString(pkg.id, "")
                                            val parts = rawVal.split(":")
                                            val netW = parts.getOrNull(0)?.toDoubleOrNull() ?: pkg.netWeight
                                            val pkgOperatingCost = netW * ( (operatingCostInput.toDoubleOrNull() ?: 0.0) / (items.sumOf { it.quantityMultiplier }.takeIf { it > 0 } ?: 1.0) )
                                            currentJson.put(pkg.id, "$netW:$pkgOperatingCost")
                                        }
                                    }
                                    currentJson.toString()
                                } catch (e: Exception) {
                                    formulation.packagingWeightsJson
                                }
                            )

                            GbrPdfGenerator.printFormulationPdf(
                                context = context,
                                formulation = transientFormulation,
                                items = transientItems,
                                qualityTests = emptyList(),
                                allQCDefinitions = emptyList(),
                                recipePhases = emptyList(),
                                customPackagings = allPackagings,
                                useRealNames = true,
                                usePercentage = false,
                                checkedSections = mapOf(
                                    "product_info" to true,
                                    "ingredients" to true,
                                    "packagings" to true,
                                    "tests" to false,
                                    "recipe" to false,
                                    "notes" to false
                                ),
                                docType = 2
                            )
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                        contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                        modifier = Modifier.height(36.dp),
                        shape = RoundedCornerShape(8.dp)
                    ) {
                        Icon(imageVector = Icons.Default.Print, contentDescription = "طباعة تقرير التكاليف", modifier = Modifier.size(20.dp), tint = Color.White)
                    }

                    Box(
