                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Text(
                            text = "📋 جدول تكلفة المواد الخام الحالية",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = GBRDarkIndigo,
                            modifier = Modifier.padding(bottom = 12.dp)
                        )

                        if (isDraft) {
                            Card(
                                modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                                shape = RoundedCornerShape(12.dp),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF7ED)),
                                border = BorderStroke(1.dp, Color(0xFFFFEDD5))
                            ) {
                                Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                    Text(
                                        text = "🧪 بيئة دراسة ومحاكاة التكاليف (مسودة)",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFFC2410C)
                                    )
                                    Text(
                                        text = "يمكنك النقر على أي مادة خام لتعديل سعر المحاكاة الخاص بها لغرض الدراسة دون التأثير على الأسعار الرسمية المعتمدة.",
                                        fontSize = 10.sp,
                                        color = Color(0xFF913412),
                                        modifier = Modifier.fillMaxWidth(),
                                        textAlign = TextAlign.Right
                                    )
                                    
                                    HorizontalDivider(color = Color(0xFFFFEDD5).copy(alpha = 0.5f))
                                    
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = "عدد المواد المعدلة: $simulatedItemsCount",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFFEA580C)
                                        )
                                        
                                        if (simulatedItemsCount > 0) {
                                            TextButton(
                                                onClick = {
                                                    items.forEach { localSimulatedPrices[it.id] = null }
                                                    Toast.makeText(context, "تمت إعادة جميع الأسعار للرسمية محلياً 🔄 (اضغط حفظ للاعتماد)", Toast.LENGTH_SHORT).show()
                                                },
                                                colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFDC2626)),
                                                modifier = Modifier.height(28.dp),
                                                contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 4.dp, vertical = 0.dp)
                                            ) {
                                                Icon(imageVector = Icons.Default.Refresh, contentDescription = null, modifier = Modifier.size(14.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("إعادة جميع الأسعار المعتمدة", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Table Header
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                                .padding(8.dp),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(t("اسم المادة", "Material Name"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF475569), modifier = Modifier.weight(2f), textAlign = TextAlign.Right)
                            Text(t("الكمية (كجم)", "Qty (kg)"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF475569), modifier = Modifier.weight(1f), textAlign = TextAlign.Center)
                            Text(t("سعر الكيلو (ILS)", "Price/kg (ILS)"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF475569), modifier = Modifier.weight(1.2f), textAlign = TextAlign.Center)
                            Text(t("التكلفة (ILS)", "Cost (ILS)"), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF475569), modifier = Modifier.weight(1.2f), textAlign = TextAlign.Left)
                        }

                        Spacer(modifier = Modifier.height(6.dp))

                        if (itemsWithCosts.isEmpty()) {
                            Text(
                               text = t("لا توجد مواد مضافة في هذه التركيبة حالياً.", "No raw materials added to this formulation yet."),
                               fontSize = 12.sp,
                               color = Color.LightGray,
                               modifier = Modifier.fillMaxWidth().padding(16.dp),
                               textAlign = TextAlign.Center
                            )
                        } else {
                            itemsWithCosts.forEachIndexed { idx, (item, price, cost) ->
                                val localPrice = localSimulatedPrices[item.id]
                                val hasSimulatedPrice = localPrice != null && localPrice != item.rawMaterialPrice
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .then(
                                            if (isDraft) {
                                                Modifier.clickable {
                                                    selectedItemForSimulation = item
                                                    simulationPriceInput = localPrice?.toString() ?: ""
                                                }
                                            } else {
                                                Modifier
                                            }
                                        )
                                        .padding(vertical = 10.dp, horizontal = 4.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(2f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                                        Text(item.rawMaterialName, fontSize = 12.sp, fontWeight = FontWeight.Medium, color = Color(0xFF1E293B), textAlign = TextAlign.Right, modifier = Modifier.fillMaxWidth())
                                        if (hasSimulatedPrice) {
                                            Text(
                                                text = t("⚠️ سعر محاكاة نشط", "⚠️ Active simulation price"),
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFFD97706),
                                                textAlign = TextAlign.Right,
                                                modifier = Modifier.fillMaxWidth()
                                            )
                                        }
                                    }
                                    Text(formatQuantity(item.quantityMultiplier), fontSize = 12.sp, color = Color(0xFF475569), modifier = Modifier.weight(1f), textAlign = TextAlign.Center)
                                    
                                    Column(
                                        modifier = Modifier.weight(1.2f),
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.spacedBy(2.dp)
                                    ) {
                                        Text(
                                            text = "${formatCost(price)} ${t("شيكل", "ILS")}",
                                            fontSize = 12.sp,
                                            fontWeight = if (hasSimulatedPrice) FontWeight.Bold else FontWeight.Normal,
                                            color = if (hasSimulatedPrice) Color(0xFFD97706) else Color(0xFF475569)
                                        )
                                        if (hasSimulatedPrice) {
                                            Text(
                                                text = "(الأصلي: ${formatCost(item.rawMaterialPrice)})",
                                                fontSize = 9.sp,
                                                color = Color.Gray,
                                                style = TextStyle(textDecoration = androidx.compose.ui.text.style.TextDecoration.LineThrough)
                                            )
                                        } else if (isDraft) {
                                            Text(
                                                text = "تعديل ✍️",
                                                fontSize = 9.sp,
                                                color = GBRBlueMain,
                                                fontWeight = FontWeight.Light
                                            )
                                        }
                                    }
                                    
                                    Text(
                                        text = formatCost(cost),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (hasSimulatedPrice) Color(0xFFD97706) else Color(0xFF0F172A),
                                        modifier = Modifier.weight(1.2f),
                                        textAlign = TextAlign.Left
                                    )
                                }
                                if (idx < itemsWithCosts.size - 1) {
                                    HorizontalDivider(color = Color(0xFFF1F5F9))
                                }
                            }
                        }
                    }
                }

