                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = Color(0xFF0369A1)
                        )

                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text(t("إجمالي تكلفة المواد الخام:", "Total Raw Material Cost:"), fontSize = 12.sp, color = Color(0xFF334155))
                            Text(
                                  text = "${formatCost(totalRawCost)} ${t("شيكل", "ILS")}",
                                  fontSize = 13.sp,
                                  fontWeight = FontWeight.Bold,
                                  color = Color(0xFF0F172A)
                            )
                        }

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(t("تكلفة التشغيل لكل كغم:", "Operating Cost per kg:"), fontSize = 12.sp, color = Color(0xFF334155))
                                IconButton(
                                    onClick = { showHelpOperatingCostPerKg = true },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Info,
                                        contentDescription = t("تفاصيل حساب تكلفة التشغيل", "Operating cost calculation details"),
                                        tint = Color(0xFF0284C7),
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                            Text(
                                text = "${formatQuantity(operatingCostPerKg)} ${t("شيكل", "ILS")}/${t("كجم", "kg")}",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF0F172A),
                                maxLines = 1,
                                softWrap = false
                            )
                        }

                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text(t("الوزن الكلي للتركيبة:", "Total Formulation Weight:"), fontSize = 12.sp, color = Color(0xFF334155))
                            Text(
                                text = "${formatQuantity(totalWeight)} ${t("كجم", "kg")}",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF0F172A)
                            )
                        }

                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text(t("عدد العبوات المنتج (الوزن الكلي ÷ وزن العبوة):", "Produced Packages Count:"), fontSize = 12.sp, color = Color(0xFF334155))
                            Text(
                                text = "${formatQuantity(packagesCount)} ${t("عبوة", "packages")}",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF0F172A)
                            )
                        }

                        HorizontalDivider(color = Color(0xFFBAE6FD).copy(alpha = 0.5f))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(t("تكلفة الكيلو الصافي", "Net Cost per kg"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFF0369A1))
                                IconButton(
                                    onClick = { showHelpNetCostPerKg = true },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Info,
                                        contentDescription = t("تفاصيل الحساب", "Calculation details"),
                                        tint = Color(0xFF0284C7),
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                            Text(
                                text = "${formatCost(costPerKg)} ${t("شيكل", "ILS")}/${t("كجم", "kg")}",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Black,
                                color = Color(0xFF0284C7),
                                maxLines = 1,
                                softWrap = false
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // 3- مدخلات وعناصر تعبئة العبوة وتكاليف التشغيل (تعديل مباشر)
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "⚙️ تكاليف التشغيل والتعبئة للوجبة",
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp,
                                color = GBRDarkIndigo,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.weight(1f)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = "توزيع وزني تلقائي 🔄",
                                fontSize = 11.sp,
                                color = GBRBlueMain,
                                fontWeight = FontWeight.Bold,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }

                        if (selectedPackage == null) {
                            Text(
                                text = "الرجاء تمكين العبوات وتهيئة أوزانها وتكاليفها لهذه التركيبة باستخدام أيقونة الترس ⚙️.",
                                fontSize = 13.sp,
                                color = ErrorRed,
                                modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                                textAlign = TextAlign.Center
                            )
                        } else {
                            // Total operating costs input
                            OutlinedTextField(
                                value = operatingCostInput,
                                onValueChange = { operatingCostInput = it },
                                enabled = true,
                                label = { Text("إجمالي تكلفة تشغيلية", fontWeight = FontWeight.Bold, fontSize = 12.sp) },
                                placeholder = { Text("مثال: 150", fontSize = 12.sp, color = Color.Gray) },
                                modifier = Modifier.fillMaxWidth().padding(bottom = 4.dp),
                                singleLine = true,
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                                shape = RoundedCornerShape(12.dp),
                                trailingIcon = {
                                    Text("شيكل", style = TextStyle(fontWeight = FontWeight.Bold, color = GBRBlueMain), modifier = Modifier.padding(end = 12.dp))
                                },
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = GBRBlueMain,
                                    unfocusedBorderColor = Color.LightGray,
                                    focusedContainerColor = Color(0xFFF8FAFC),
                                    unfocusedContainerColor = Color(0xFFF8FAFC)
                                )
                            )

                            HorizontalDivider(color = Color(0xFFE2E8F0), modifier = Modifier.padding(vertical = 6.dp))

                            // Beautiful table of all supported packagings showing their dynamically distributed operating costs
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { isPackagingsExpanded = !isPackagingsExpanded }
                                    .padding(vertical = 4.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Text(
                                        text = "📦 توزيع تكلفة التشغيل النهائيّة على العبوات المدعومة تلقائياً",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                }
                                Icon(
                                    imageVector = if (isPackagingsExpanded) Icons.Default.KeyboardArrowDown else Icons.Default.KeyboardArrowLeft,
                                    contentDescription = if (isPackagingsExpanded) "إغلاق" else "توسيع",
                                    tint = GBRDarkIndigo,
                                    modifier = Modifier.size(20.dp)
                                )
                            }

                            AnimatedVisibility(visible = isPackagingsExpanded) {
                                Column(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    supportedPackagingsWithOperating.forEach { (pkg, netW, extraC) ->
                                        val pkgChemicalCost = costPerKg * netW
                                        val pkgContainerPrice = pkg.price
                                        val pkgFinalCost = pkgChemicalCost + pkgContainerPrice + extraC

                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                            shape = RoundedCornerShape(8.dp)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Row(
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                    ) {
                                                        Box(
                                                            modifier = Modifier
                                                                .size(8.dp)
                                                                .background(GBRBlueMain, androidx.compose.foundation.shape.CircleShape)
                                                        )
                                                        val densityVal = refSpecsState.value?.densityFinalResult
                                                        val volSuffix = if (densityVal != null && densityVal > 0) {
                                                            " | ${formatQuantity(netW / densityVal)} لتر"
                                                        } else ""
                                                        Text(
                                                            text = "${pkg.name} (${netW} كجم$volSuffix)",
                                                            fontSize = 12.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = Color(0xFF1E293B)
                                                        )
                                                    }
                                                    Text(
                                                        text = "${formatCost(pkgFinalCost)} شيكل / عبوة",
                                                        fontSize = 13.sp,
                                                        fontWeight = FontWeight.Black,
                                                        color = Color(0xFF0F172A)
                                                    )
                                                }

                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                ) {
                                                    // Chemical Cost share
                                                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                                        Text("سائل التركيبة", fontSize = 9.sp, color = Color.Gray)
                                                        Text("${formatCost(pkgChemicalCost)} شيكل", fontSize = 11.sp, fontWeight = FontWeight.Medium, color = Color(0xFF475569))
                                                    }
                                                    // Empty Container Cost share
                                                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                                        Text("العبوة فارغة", fontSize = 9.sp, color = Color.Gray)
                                                        Text("${formatCost(pkgContainerPrice)} شيكل", fontSize = 11.sp, fontWeight = FontWeight.Medium, color = Color(0xFF475569))
                                                    }
                                                    // Dynamic allocated Operating Cost share
                                                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                                        Text("نصيب التشغيل ⚙️", fontSize = 9.sp, color = Color(0xFFC2410C))
                                                        Text("${formatCost(extraC)} شيكل", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFFD97706))
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                // 4- النتيجة النهائية لحساب كلفة العبوة
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFECFDF5)),
                    border = BorderStroke(1.5.dp, Color(0xFF10B981)),
                    elevation = CardDefaults.cardElevation(defaultElevation = 3.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(18.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text(
                            text = "🏁 النتيجة النهائية لحساب تكلفة العبوة",
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp,
                            color = Color(0xFF047857)
                        )

                        if (supportedPackagings.isEmpty()) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color.White.copy(alpha = 0.5f), RoundedCornerShape(12.dp))
                                    .border(1.dp, Color(0xFFFCA5A5), RoundedCornerShape(12.dp))
                                    .padding(16.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = "⚠️ لم يتم تحديد عَبوات مفعلة لهذه التركيبة. الرجاء الضغط على رمز الترس للتركيبة لتمكين وتحديد العبوات المناسبة.",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFFC53030),
                                    textAlign = TextAlign.Center
                                )
                            }
                        } else {
                            // Render navigation selector if supportedPackagings.size > 1
                            if (supportedPackagings.size > 1) {
                                Text(
                                    text = "🔄 العبوات والخيارات المتاحة للتركيبة (انقر للتبديل السريع بينها):",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF065F46)
                                )
                                
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    supportedPackagings.forEachIndexed { idx, (pkg, netW, _) ->
                                        val isSelected = idx == activeIndex
                                        val bgColor = if (isSelected) Color(0xFF10B981) else Color.White
                                        val textColor = if (isSelected) Color.White else Color(0xFF374151)
                                        val borderColor = if (isSelected) Color(0xFF10B981) else Color(0xFFD1D5DB)
                                        
                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(bgColor)
                                                .border(1.dp, borderColor, RoundedCornerShape(8.dp))
                                                .clickable { selectedIndex = idx }
                                                .padding(vertical = 8.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(
                                                text = "${pkg.name} (${netW} كجم${refSpecsState.value?.densityFinalResult?.let { if (it > 0) " | ${formatQuantity(netW / it)} لتر" else "" } ?: ""})",
                                                color = textColor,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                maxLines = 1,
                                                textAlign = TextAlign.Center
                                            )
                                        }
                                    }
                                }
                                
                                HorizontalDivider(color = Color(0xFF10B981).copy(alpha = 0.2f), modifier = Modifier.padding(vertical = 4.dp))
                            }

                             Row(
                                 modifier = Modifier.fillMaxWidth(),
                                 horizontalArrangement = Arrangement.SpaceBetween,
                                 verticalAlignment = Alignment.CenterVertically
                             ) {
                                 Row(
                                     verticalAlignment = Alignment.CenterVertically,
                                     horizontalArrangement = Arrangement.spacedBy(4.dp)
                                 ) {
                                     Text("تكلفة الدهان داخل العبوة", fontSize = 12.sp, color = Color(0xFF065F46))
                                     IconButton(
                                         onClick = { showHelpPaintCostInside = true },
                                         modifier = Modifier.size(24.dp)
                                     ) {
                                         Icon(
                                             imageVector = Icons.Default.Info,
                                             contentDescription = "تفاصيل الحساب",
                                             tint = Color(0xFF047857),
                                             modifier = Modifier.size(16.dp)
                                         )
                                     }
                                 }
                                 Text(
                                     text = "${formatCost(paintCostInside)} شيكل",
                                     fontSize = 13.sp,
                                     fontWeight = FontWeight.Bold,
                                     color = Color(0xFF065F46)
                                 )
                             }

                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("تكلفة العبوة الفارغة الحالية:", fontSize = 12.sp, color = Color(0xFF374151))
                                Text(
                                    text = "${formatCost(packagingCost)} شيكل",
                                    fontSize = 13.sp,
                                    color = Color(0xFF1F2937)
                                )
                            }

                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("نصيب العبوة من تكاليف التشغيل:", fontSize = 12.sp, color = Color(0xFF374151))
                                Text(
                                    text = "${formatCost(operatingCostPerPackage)} شيكل",
                                    fontSize = 13.sp,
                                    color = Color(0xFF1F2937)
                                )
                            }

                            HorizontalDivider(color = Color(0xFF10B981).copy(alpha = 0.3f), thickness = 1.2.dp)

                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color.White.copy(alpha = 0.7f), RoundedCornerShape(12.dp))
                                    .border(1.dp, Color(0xFFA7F3D0), RoundedCornerShape(12.dp))
                                    .padding(14.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Text(
                                    text = "التكلفة النهائية للعبوة (${selectedPackage?.name ?: ""})",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF1F2937)
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "${formatCost(finalCost)} شيكل",
                                    fontSize = 30.sp,
                                    fontWeight = FontWeight.Black,
                                    color = Color(0xFF059669)
                                )
                                Text(
                                    text = "وزن تعبئة صافي ${formatQuantity(netWeight)} كجم | عدد العبوات المنتج: ${formatQuantity(packagesCount)} عبوة" + (refSpecsState.value?.densityFinalResult?.let { if (it > 0) " | الحجم داخل العبوة: ${String.format(java.util.Locale.US, "%.2f", netWeight / it)} لتر" else " | الحجم داخل العبوة: (لا توجد كثافة معتمدة)" } ?: " | الحجم داخل العبوة: (لا توجد كثافة معتمدة)"),
                                    fontSize = 11.sp,
                                    color = Color(0xFF039855)
                                )

                                if (hasActiveSimulation) {
                                    Spacer(modifier = Modifier.height(10.dp))
                                    HorizontalDivider(color = Color(0xFF10B981).copy(alpha = 0.2f), thickness = 0.8.dp)
                                    Spacer(modifier = Modifier.height(10.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceEvenly,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        // Original Cost
                                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                            Text(
                                                text = "التكلفة الأصلية",
                                                fontSize = 10.sp,
                                                color = Color.Gray,
                                                fontWeight = FontWeight.Normal
                                            )
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(
                                                text = "${formatCost(originalFinalCost)} شيكل",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF475569)
                                            )
                                        }

                                        // Vertical Separator
                                        Box(
                                            modifier = Modifier
                                                .height(24.dp)
                                                .width(1.dp)
                                                .background(Color(0xFF10B981).copy(alpha = 0.2f))
                                        )

                                        // Difference (Savings or Increase)
                                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                            val isSavings = costDiff < -0.005
                                            val isIncrease = costDiff > 0.005
                                            val diffColor = when {
                                                isSavings -> Color(0xFF16A34A) // Green
                                                isIncrease -> Color(0xFFDC2626) // Red
                                                else -> Color.Gray
                                            }
                                            val diffLabel = when {
                                                isSavings -> "توفير"
                                                isIncrease -> "زيادة"
                                                else -> "الفرق"
                                            }
                                            val diffText = when {
                                                isSavings -> "-${formatCost(Math.abs(costDiff))} شيكل"
                                                isIncrease -> "+${formatCost(costDiff)} شيكل"
                                                else -> "0 شيكل"
                                            }

                                            Text(
                                                text = "قيمة الفرق ($diffLabel)",
                                                fontSize = 10.sp,
                                                color = Color.Gray,
                                                fontWeight = FontWeight.Normal
                                            )
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(
                                                text = diffText,
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = diffColor
                                            )
                                        }

                                        // Vertical Separator
                                        Box(
                                            modifier = Modifier
                                                .height(24.dp)
                                                .width(1.dp)
                                                .background(Color(0xFF10B981).copy(alpha = 0.2f))
                                        )

                                        // New Cost
                                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                            Text(
                                                text = "بعد المحاكاة",
                                                fontSize = 10.sp,
                                                color = Color.Gray,
                                                fontWeight = FontWeight.Normal
                                            )
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(
                                                text = "${formatCost(finalCost)} شيكل",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF0F172A)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                Spacer(modifier = Modifier.height(32.dp))
            }
        }
    }
}
// ==========================================
// SEGMENT 3 PANEL: PRODUCTION RUN (بدء التشغيل)
// ==========================================
@Composable
fun LegacyProductionPanel(viewModel: GbrViewModel) {
    val selectedOrder by viewModel.selectedProductionOrder.collectAsState()
    val selectedOrderItems by viewModel.selectedProductionOrderItems.collectAsState()
    val selectedOrderEvents by viewModel.selectedProductionOrderEvents.collectAsState()
    val ordersList by viewModel.productionOrders.collectAsState()
    val formulationsList by viewModel.formulations.collectAsState()

    val allTestRecords by viewModel.allProductionOrderTestRecords.collectAsState()
    val labSessions by viewModel.labSessions.collectAsState(initial = emptyList())
    val allLabTests by viewModel.allLabTests.collectAsState(initial = emptyList())

    var isAddingNewOrder by remember { mutableStateOf(false) }
    var searchQuery by remember { mutableStateOf("") }
    var statusFilter by remember { mutableStateOf("الكل") }

    // Navigation Back Button Handler
    BackHandler(enabled = true) {
        if (selectedOrder != null) {
            viewModel.selectedProductionOrder.value = null
        } else if (isAddingNewOrder) {
            isAddingNewOrder = false
        } else {
            viewModel.showSegment(null)
        }
    }

    if (selectedOrder != null) {
        // --- Tab 3: Detailed view of a production order ---
        val order = selectedOrder!!
        var activeTab by remember { mutableIntStateOf(0) }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            // Header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = "تفاصيل أمر الإنتاج ${order.orderNumber}",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                    Text(
                        text = "رقم الدفعة: ${order.batchNumber}",
                        fontSize = 12.sp,
                        color = Color.Gray
                    )
                }

                IconButton(
                    onClick = { viewModel.selectedProductionOrder.value = null }
                ) {
                    Icon(
                        imageVector = Icons.Default.Close,
                        contentDescription = "إغلاق",
                        tint = ErrorRed
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Tabs Header
            ScrollableTabRow(
                selectedTabIndex = activeTab,
                edgePadding = 0.dp,
                containerColor = Color.Transparent,
                contentColor = GBRBlueMain
            ) {
                val tabs = listOf("المعلومات", "المكونات المطلوبة", "المراحل", "سجل التنفيذ", "الفحوصات 🔬")
                tabs.forEachIndexed { index, title ->
                    Tab(
                        selected = activeTab == index,
                        onClick = { activeTab = index },
                        text = { Text(title, fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f)
                    .swipeableTabs(
                        selectedTab = activeTab,
                        totalTabs = 5,
                        onTabSelected = { activeTab = it }
                    )
            ) {
                when (activeTab) {
                    0 -> {
                    // TAB 1: General Info & Status Controls
                    val selectedOrderPhases by viewModel.selectedProductionOrderPhases.collectAsState()
                    val selectedOrderRecipeStatus by viewModel.selectedOrderRecipeStatus.collectAsState()

                    val hasNoRecipe = selectedOrderPhases.isEmpty()
                    val recipeNeedsReview = false
                    val formula = formulationsList.find { it.id == order.formulationId }
                    val versionNotApproved = formula?.status != "🟢 معتمدة للإنتاج"

                    val validationErrors = remember(hasNoRecipe, recipeNeedsReview, versionNotApproved) {
                        mutableListOf<String>().apply {
                            if (hasNoRecipe) add("خطأ: لا توجد وصفة تشغيل معرفة لهذه التركيبة.")
                            if (recipeNeedsReview) add("خطأ: وصفة التشغيل تحتاج إلى مراجعة واعتماد.")
                            if (versionNotApproved) add("خطأ: إصدار التركيبة هذا غير معتمد للإنتاج في النظام بعد.")
                        }
                    }

                    Column(
                        modifier = Modifier
                            .fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, IndustrialBorder),
                            colors = CardDefaults.cardColors(containerColor = Color.White)
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("اسم الدفعة / المنتج:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    Text(order.formulationName, fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 14.sp)
                                }
                                Divider(color = IndustrialBorder)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("نسخة إصدار التركيبة:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(6.dp))
                                            .background(GBRCyanAccent.copy(alpha = 0.12f))
                                            .padding(horizontal = 8.dp, vertical = 2.dp)
                                    ) {
                                        Text(order.formulationVersion, fontWeight = FontWeight.Bold, color = GBRCyanAccent, fontSize = 12.sp)
                                    }
                                }
                                Divider(color = IndustrialBorder)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("معامل التشغيل المعتمد:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    Text("× ${order.scaleFactor}", fontWeight = FontWeight.Bold, color = Color(0xFF15803D), fontSize = 13.sp)
                                }
                                Divider(color = IndustrialBorder)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("الوزن الأصلي للتركيبة الكاملة:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    val origW = if (order.originalWeightKg > 0.0) order.originalWeightKg else (selectedOrderItems.sumOf { it.quantityMultiplier })
                                    Text("${formatQuantity(origW)} كجم", fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 13.sp)
                                }
                                Divider(color = IndustrialBorder)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("الوزن النهائي المتوقع للدفعة:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    Text("${formatQuantity(order.requiredWeightKg)} كجم", fontWeight = FontWeight.Black, color = GBRPinkAccent, fontSize = 15.sp)
                                }
                                Divider(color = IndustrialBorder)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("تاريخ الإنشاء وتوقيته:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US)
                                    Text(sdf.format(java.util.Date(order.createdAt)), color = GBRDarkIndigo, fontSize = 12.sp)
                                }
                                Divider(color = IndustrialBorder)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("حالة أمر الإنتاج الحالية:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 12.sp)
                                    val (color, bg) = when (order.status) {
                                        "مسودة" -> Color.Gray to Color(0xFFF1F5F9)
                                        "جاهز للتنفيذ" -> GBRBlueMain to Color(0xFFEFF6FF)
                                        "قيد التنفيذ" -> WarningOrange to Color(0xFFFEF3C7)
                                        "متوقفة" -> ErrorRed to Color(0xFFFFF1F2)
                                        "مكتمل" -> SuccessGreen to Color(0xFFD1FAE5)
                                        else -> ErrorRed to Color(0xFFFEE2E2)
                                    }
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(12.dp))
                                            .background(bg)
                                            .padding(horizontal = 10.dp, vertical = 4.dp)
                                    ) {
                                        Text(order.status, fontWeight = FontWeight.Bold, color = color, fontSize = 11.sp)
                                    }
                                }
                                if (order.notes.isNotBlank()) {
                                    val notesParts = order.notes.split("\nملاحظات الإكمال:")
                                    val originalNotes = notesParts.getOrNull(0)?.trim() ?: ""
                                    val finalNotes = if (notesParts.size > 1) notesParts[1].trim() else ""

                                    if (originalNotes.isNotBlank()) {
                                        Divider(color = IndustrialBorder)
                                        Column(modifier = Modifier.fillMaxWidth()) {
                                            Text("الملاحظات والتعليمات التشغيلية الأصلية:", fontWeight = FontWeight.Bold, color = Color.Gray, fontSize = 11.sp)
                                            Spacer(modifier = Modifier.height(4.dp))
                                            Text(originalNotes, color = Color.DarkGray, fontSize = 12.sp)
                                        }
                                    }

                                    if (finalNotes.isNotBlank()) {
                                        Divider(color = IndustrialBorder)
                                        Column(modifier = Modifier.fillMaxWidth()) {
                                            Text("الملاحظات الختامية وإنحرافات التشغيل:", fontWeight = FontWeight.Bold, color = SuccessGreen, fontSize = 11.sp)
                                            Spacer(modifier = Modifier.height(4.dp))
                                            Text(finalNotes, color = Color.DarkGray, fontSize = 12.sp)
                                        }
                                    }
                                }
                            }
                        }

                        // Execution Progress % Control Card
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, IndustrialBorder),
                            colors = CardDefaults.cardColors(containerColor = Color.White)
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                Text(
                                    text = "تحديث نسبة إنجاز العمل الفعلي للدفعة:",
                                    fontWeight = FontWeight.Bold,
                                    color = GBRDarkIndigo,
                                    fontSize = 13.sp
                                )

                                // Linear indicator of current progress
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text("نسبة الإنجاز الحالية:", fontSize = 11.sp, color = Color.Gray)
                                    Text("${order.progressPercent}%", fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 14.sp)
                                }

                                LinearProgressIndicator(
                                    progress = order.progressPercent / 100f,
                                    modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(4.dp)),
                                    color = GBRBlueMain,
                                    trackColor = Color(0xFFF1F5F9)
                                )

                                Spacer(modifier = Modifier.height(4.dp))

                                // Button selector for progress (0%, 25%, 50%, 75%, 100%)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    val percentages = listOf(0, 25, 50, 75, 100)
                                    percentages.forEach { pct ->
                                        val isCurrent = order.progressPercent == pct
                                        val btnColor = if (isCurrent) GBRBlueMain else Color(0xFFF1F5F9)
                                        val textColor = if (isCurrent) Color.White else GBRDarkIndigo

                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(btnColor)
                                                .clickable {
                                                    viewModel.updateProductionOrderProgress(order.id, pct)
                                                }
                                                .padding(vertical = 8.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text("$pct%", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textColor)
                                        }
                                    }
                                }
                            }
                        }

                        // Status Workflows Controls
                        Text(
                            text = "التحكم في حالة وسير تشغيل خط الإنتاج:",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.Gray,
                            modifier = Modifier.padding(top = 8.dp)
                        )

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, IndustrialBorder),
                            colors = CardDefaults.cardColors(containerColor = Color.White)
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                when (order.status) {
                                    "مسودة" -> {
                                        if (validationErrors.isNotEmpty()) {
                                            // Show errors
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(Color(0xFFFEF2F2))
                                                    .border(1.dp, Color(0xFFFCA5A5), RoundedCornerShape(8.dp))
                                                    .padding(12.dp),
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Text("تنبيه: لا يمكن ترقية أمر الإنتاج للأعطال التالية:", fontWeight = FontWeight.Bold, color = Color(0xFF991B1B), fontSize = 12.sp)
                                                validationErrors.forEach { err ->
                                                    Text("• $err", color = Color(0xFF991B1B), fontSize = 11.sp)
                                                }
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "جاهز للتنفيذ",
                                                    eventName = "تحديث الحالة إلى جاهز للتنفيذ",
                                                    description = "تم اعتماد وجدولة أمر الإنتاج وإعلانه جاهزاً لبدء التنفيذ الفعلي."
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("promote_to_ready_btn"),
                                            enabled = validationErrors.isEmpty(),
                                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Icon(imageVector = Icons.Default.Send, contentDescription = null, tint = Color.White)
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text("اعتماد وتحويل إلى جاهز للتنفيذ", fontWeight = FontWeight.Bold, color = Color.White)
                                        }

                                        OutlinedButton(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "ملغي",
                                                    eventName = "إلغاء التنفيذ",
                                                    description = "تم إلغاء أمر الإنتاج وهو في حالة مسودة"
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("cancel_draft_btn"),
                                            border = BorderStroke(1.dp, ErrorRed),
                                            colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Text("إلغاء أمر الإنتاج", fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "جاهز للتنفيذ" -> {
                                        if (validationErrors.isNotEmpty()) {
                                            // Show errors
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(Color(0xFFFEF2F2))
                                                    .border(1.dp, Color(0xFFFCA5A5), RoundedCornerShape(8.dp))
                                                    .padding(12.dp),
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Text("تنبيه: تم رصد مشكلة بعد الاعتماد:", fontWeight = FontWeight.Bold, color = Color(0xFF991B1B), fontSize = 12.sp)
                                                validationErrors.forEach { err ->
                                                    Text("• $err", color = Color(0xFF991B1B), fontSize = 11.sp)
                                                }
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "قيد التنفيذ",
                                                    eventName = "بدء التنفيذ",
                                                    description = "بدأ تشغيل الوجبة وإطلاق خلاط خط الإنتاج الفعلي"
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("start_execution_btn"),
                                            enabled = validationErrors.isEmpty(),
                                            colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Icon(imageVector = Icons.Default.PlayArrow, contentDescription = null, tint = Color.White)
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text("إطلاق وبدء الإنتاج الفعلي للوجبة", fontWeight = FontWeight.Bold, color = Color.White)
                                        }

                                        OutlinedButton(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "ملغي",
                                                    eventName = "إلغاء التنفيذ",
                                                    description = "تم إلغاء أمر الإنتاج المعتمر مسبقاً"
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("cancel_ready_btn"),
                                            border = BorderStroke(1.dp, ErrorRed),
                                            colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Text("إلغاء أمر الإنتاج", fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "قيد التنفيذ" -> {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Button(
                                                onClick = {
                                                    viewModel.updateProductionOrderStatus(
                                                        orderId = order.id,
                                                        newStatus = "مكتمل",
                                                        eventName = "إكمال التنفيذ",
                                                        description = "تم الانتهاء بنجاح كامل وحفظ كميات الدفعة كلياً"
                                                    )
                                                },
                                                modifier = Modifier.weight(1.2f).testTag("complete_btn"),
                                                colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen),
                                                shape = RoundedCornerShape(10.dp)
                                            ) {
                                                Icon(imageVector = Icons.Default.Check, contentDescription = null)
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("إكمال ناجح", fontWeight = FontWeight.Bold, color = Color.White)
                                            }

                                            Button(
                                                onClick = {
                                                    viewModel.updateProductionOrderStatus(
                                                        orderId = order.id,
                                                        newStatus = "متوقفة",
                                                        eventName = "إيقاف مؤقت للتشغيل",
                                                        description = "تم إيقاف تشغيل الخالط مؤقتاً لأسباب تشغيلية"
                                                    )
                                                },
                                                modifier = Modifier.weight(1f).testTag("pause_btn"),
                                                colors = ButtonDefaults.buttonColors(containerColor = WarningOrange),
                                                shape = RoundedCornerShape(10.dp)
                                            ) {
                                                Text("إيقاف مؤقت", fontWeight = FontWeight.Bold, color = Color.White)
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(4.dp))

                                        OutlinedButton(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "ملغي",
                                                    eventName = "إلغاء التنفيذ",
                                                    description = "تم إلغاء أمر الإنتاج أثناء الإنتاج"
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("cancel_exec_btn"),
                                            border = BorderStroke(1.dp, ErrorRed),
                                            colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Text("إلغاء الدفعة واحتساب تالف شحنة", fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "متوقفة" -> {
                                        Button(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "قيد التنفيذ",
                                                    eventName = "استئناف التنفيذ",
                                                    description = "تم استئناف تشغيل المحركات والصب مجدداً"
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("resume_btn"),
                                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Icon(imageVector = Icons.Default.PlayArrow, contentDescription = null, tint = Color.White)
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text("استئناف الإنتاج والمتابعة", fontWeight = FontWeight.Bold, color = Color.White)
                                        }

                                        OutlinedButton(
                                            onClick = {
                                                viewModel.updateProductionOrderStatus(
                                                    orderId = order.id,
                                                    newStatus = "ملغي",
                                                    eventName = "إلغاء التنفيذ",
                                                    description = "تم إلغاء أمر الإنتاج بعد التوقف"
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().testTag("cancel_paused_btn"),
                                            border = BorderStroke(1.dp, ErrorRed),
                                            colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Text("إلغاء أمر الإنتاج نهائياً", fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "مكتمل" -> {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .background(Color(0xFFD1FAE5))
                                                .clip(RoundedCornerShape(8.dp))
                                                .padding(12.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(imageVector = Icons.Default.CheckCircle, contentDescription = null, tint = SuccessGreen)
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Text("تم إنتاج وإغلاق أمر الإنتاج بنجاح كامل!", color = Color(0xFF065F46), fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                            }
                                        }
                                    }

                                    "ملغي" -> {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .background(Color(0xFFFEE2E2))
                                                .clip(RoundedCornerShape(8.dp))
                                                .padding(12.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(imageVector = Icons.Default.Warning, contentDescription = null, tint = ErrorRed)
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Text("أمر الإنتاج ملغي وغير مفعل.", color = Color(0xFF991B1B), fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                            }
                                        }
                                    }
                                }

                                // General Delete button for draft/cancelled orders
                                if (order.status == "مسودة" || order.status == "ملغي") {
                                    Divider(color = IndustrialBorder)
                                    TextButton(
                                        onClick = {
                                            viewModel.deleteProductionOrder(order.id)
                                        },
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Text("حذف السجل بالكامل من النظام نهائياً", color = ErrorRed, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }
                }

                1 -> {
                    // TAB 2: Calculated components multiplier
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                    ) {
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 12.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFEFF6FF)),
                            border = BorderStroke(1.dp, Color(0xFFDBEAFE))
                        ) {
                            Row(
                                modifier = Modifier.padding(14.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text("حساب المواد للكمية المطلوبة تلقائياً:", fontSize = 11.sp, color = Color(0xFF1E40AF), fontWeight = FontWeight.Bold)
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text("جميع المكونات مضاعفة على أساس وزن قدره: ${formatQuantity(order.requiredWeightKg)} كجم", fontSize = 13.sp, color = Color(0xFF1E3A8A), fontWeight = FontWeight.Bold)
                                }
                                Icon(imageVector = Icons.Default.Info, contentDescription = null, tint = GBRBlueMain)
                            }
                        }

                        if (selectedOrderItems.isEmpty()) {
                            Box(
                                modifier = Modifier.weight(1f).fillMaxWidth(),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("لا توجد مكونات مسجلة لهذه التركيبة.", color = Color.Gray)
                            }
                        } else {
                            LazyColumn(
                                modifier = Modifier.weight(1f).fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                items(selectedOrderItems) { item ->
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(12.dp),
                                        border = BorderStroke(1.dp, IndustrialBorder),
                                        colors = CardDefaults.cardColors(containerColor = Color.White)
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(14.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text(item.rawMaterialName, fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 14.sp)
                                                Text("النسبة الأساسية: ${formatQuantity(item.quantityMultiplier)} كجم لكل طن", fontSize = 11.sp, color = Color.Gray)
                                                if (item.needsGrinding) {
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(4.dp))
                                                            .background(GBRPurpleAccent.copy(alpha = 0.1f))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    ) {
                                                        Text("يحتاج طحن: ${item.grindingDurationMinutes} دقيقة", fontSize = 10.sp, color = GBRPurpleAccent, fontWeight = FontWeight.Bold)
                                                    }
                                                }
                                            }

                                            Text(
                                                text = "${formatQuantity(item.calculatedQuantity)} كجم",
                                                fontWeight = FontWeight.Black,
                                                color = GBRBlueMain,
                                                fontSize = 15.sp
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                2 -> {
                    // TAB 3: Frozen Snapshot Production Recipe Phases
                    val selectedOrderPhases by viewModel.selectedProductionOrderPhases.collectAsState()
                    val selectedOrderRecipeItems by viewModel.selectedProductionOrderRecipeItems.collectAsState()

                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                    ) {
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 12.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF0FDFA)),
                            border = BorderStroke(1.dp, Color(0xFFCCFBF1))
                        ) {
                            Row(
                                modifier = Modifier.padding(14.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text("مراحل وصفة تشغيل الوجبة:", fontSize = 11.sp, color = Color(0xFF0F766E), fontWeight = FontWeight.Bold)
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text("وصفة تشغيل معتمدة مستقلة ومحمية من التعديلات المستقبلية.", fontSize = 12.sp, color = Color(0xFF115E59))
                                
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(4.dp))
                                                .background(Color(0xFFCCFBF1))
                                                .padding(horizontal = 6.dp, vertical = 2.dp)
                                        ) {
                                            Text("إجمالي المراحل: ${selectedOrderPhases.size}", fontSize = 10.sp, color = Color(0xFF0F766E), fontWeight = FontWeight.Black)
                                        }
                                    }
                                }
                                Icon(imageVector = Icons.Default.Build, contentDescription = null, tint = Color(0xFF0F766E))
                            }
                        }

                        if (selectedOrderPhases.isEmpty()) {
                            Box(
                                modifier = Modifier.weight(1f).fillMaxWidth(),
                                contentAlignment = Alignment.Center
                            ) {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Icon(imageVector = Icons.Default.Info, contentDescription = null, tint = Color.LightGray, modifier = Modifier.size(32.dp))
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Text("لا توجد مراحل مسجلة أو مستوردة لأمر الإنتاج هذا.", color = Color.Gray, fontSize = 12.sp)
                                }
                            }
                        } else {
                            LazyColumn(
                                modifier = Modifier.weight(1f).fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                items(selectedOrderPhases.sortedBy { it.sequence }) { phase ->
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(14.dp),
                                        border = BorderStroke(1.dp, IndustrialBorder),
                                        colors = CardDefaults.cardColors(containerColor = Color.White)
                                    ) {
                                        Column(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(14.dp)
                                        ) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                ) {
                                                    Box(
                                                        modifier = Modifier
                                                            .size(28.dp)
                                                            .clip(CircleShape)
                                                            .background(GBRBlueMain)
                                                            .wrapContentSize(Alignment.Center)
                                                    ) {
                                                        Text(
                                                            text = phase.sequence.toString(),
                                                            color = Color.White,
                                                            fontWeight = FontWeight.Black,
                                                            fontSize = 12.sp
                                                        )
                                                    }
                                                    Text(
                                                        text = phase.name,
                                                        fontWeight = FontWeight.Bold,
                                                        color = GBRDarkIndigo,
                                                        fontSize = 14.sp
                                                    )
                                                }

                                                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(6.dp))
                                                            .background(Color(0xFFF1F5F9))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    ) {
                                                        val rpmText = if (phase.mixerRpm > 0) "سرعة الخلط: ${phase.mixerRpm} RPM" else "سرعة الخلط: غير محدد"
                                                        Text(rpmText, fontSize = 10.sp, color = Color.Gray, fontWeight = FontWeight.Bold)
                                                    }
                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(6.dp))
                                                            .background(Color(0xFFFFFAF0))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    ) {
                                                        val durationText = if (phase.durationMinutes > 0) "الزمن: ${phase.durationMinutes} دقيقة" else "الزمن: غير محدد"
                                                        Text(durationText, fontSize = 10.sp, color = WarningOrange, fontWeight = FontWeight.Bold)
                                                    }
                                                }
                                            }

                                            if (phase.instructions.isNotBlank()) {
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text(
                                                    text = "التعليمات: ${phase.instructions}",
                                                    fontSize = 11.sp,
                                                    color = Color.DarkGray
                                                )
                                            }

                                            Spacer(modifier = Modifier.height(10.dp))
                                            Divider(color = Color(0xFFF1F5F9))
                                            Spacer(modifier = Modifier.height(8.dp))

                                            val phaseItems = selectedOrderRecipeItems.filter { it.productionOrderPhaseId == phase.id }
                                            if (phaseItems.isEmpty()) {
                                                Text("لا توجد مواد تابعة لهذه المرحلة.", fontSize = 11.sp, color = Color.Gray)
                                            } else {
                                                Text("مواد المرحلة المقررة للوجبة:", fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 11.sp, modifier = Modifier.padding(bottom = 4.dp))
                                                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                    phaseItems.sortedBy { it.sequence }.forEach { recipeItem ->
                                                        Row(
                                                            modifier = Modifier
                                                                .fillMaxWidth()
                                                                .clip(RoundedCornerShape(6.dp))
                                                                .background(Color(0xFFF8FAFC))
                                                                .padding(horizontal = 8.dp, vertical = 4.dp),
                                                            horizontalArrangement = Arrangement.SpaceBetween,
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                            Text(recipeItem.rawMaterialName, fontSize = 11.sp, color = GBRDarkIndigo)
                                                            Text(
                                                                text = "${formatQuantity(recipeItem.calculatedQuantity)} كجم",
                                                                fontSize = 12.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = GBRPinkAccent
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                3 -> {
                    // TAB 4: Event Auditing Timeline
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                    ) {
                        Text(
                            text = "تتبع زمني لأوامر حركة الدفعة ومراحل التشغيل:",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.Gray,
                            modifier = Modifier.padding(bottom = 8.dp)
                        )

                        if (selectedOrderEvents.isEmpty()) {
                            Box(
                                modifier = Modifier.weight(1f).fillMaxWidth(),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("لا توجد أحداث مسجلة.", color = Color.Gray)
                            }
                        } else {
                            LazyColumn(
                                modifier = Modifier.weight(1f).fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                items(selectedOrderEvents) { event ->
                                    val formattedDate = try {
                                        val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US)
                                        sdf.format(java.util.Date(event.timestamp))
                                    } catch (e: Exception) {
                                        event.timestamp.toString()
                                    }

                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(12.dp),
                                        border = BorderStroke(1.dp, IndustrialBorder),
                                        colors = CardDefaults.cardColors(containerColor = Color.White)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(12.dp),
                                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            val indicatorColor = when (event.eventName) {
                                                "إنشاء أمر الإنتاج" -> GBRBlueMain
                                                "بدء التنفيذ" -> SuccessGreen
                                                "إكمال التنفيذ" -> SuccessGreen
                                                "إلغاء التنفيذ" -> ErrorRed
                                                else -> WarningOrange
                                            }

                                            Box(
                                                modifier = Modifier
                                                    .size(10.dp)
                                                    .background(indicatorColor, CircleShape)
                                            )

                                            Column(modifier = Modifier.weight(1f)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                ) {
                                                    Text(event.eventName, fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 13.sp)
                                                    Text(formattedDate, fontSize = 10.sp, color = Color.Gray)
                                                }
                                                if (event.description.isNotBlank()) {
                                                    Spacer(modifier = Modifier.height(2.dp))
                                                    Text(event.description, fontSize = 12.sp, color = Color.DarkGray)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                4 -> {
                    // TAB 5: Live Batch Quality Control (Frictionless Tests)
                    val frozenQCListRaw by remember(order.id) { viewModel.getProductionOrderQualityTests(order.id) }.collectAsState(initial = emptyList())
                    val frozenQCList = remember(frozenQCListRaw) { frozenQCListRaw.distinctBy { it.testId } }
                    val testRecordsList by remember(order.id) { viewModel.getProductionOrderTestRecords(order.id) }.collectAsState(initial = emptyList())

                    // Auto-setup if empty
                    LaunchedEffect(order.id, frozenQCListRaw) {
                        if (frozenQCListRaw.isEmpty()) {
                            viewModel.initializeDefaultQualityTestsForOrder(order)
                        }
                    }

                    val todayStr = remember {
                        java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date())
                    }

                    var directTestDate by remember { mutableStateOf(todayStr) }
                    val directTestInputs = remember { mutableStateMapOf<String, String>() }

                    var showAddMonitoringForm by remember { mutableStateOf(false) }
                    var monitoringDate by remember { mutableStateOf(todayStr) }
                    val monitoringSelectedTests = remember { mutableStateMapOf<String, Boolean>() }
                    val monitoringInputs = remember { mutableStateMapOf<String, String>() }

                    // Determine if there is already a Direct Test recorded on this Production Order
                    val directRecord = testRecordsList.find { it.isDirectTest }

                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        // Title/Instruction Card
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Text(
                                    text = "تسجيل ومتابعة فحوصات الجودة للدفعات المنتجة 🛡️",
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRDarkIndigo
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "مدرج أدناه المواصفات والفحوصات الفنية المعتمدة لوقت إنشاء أمر الإنتاج. الفحوصات لا تعيق التعبئة أو إكمال الدفعة، بل تتم بغرض مراقبة ورصد ثبات الجودة.",
                                    fontSize = 11.sp,
                                    color = Color.Gray,
                                    lineHeight = 16.sp
                                )
                            }
                        }

                        if (frozenQCList.isEmpty()) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.dp, Color(0xFFFED7D7)),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF5F5))
                            ) {
                                Column(
                                    modifier = Modifier.padding(16.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    Text(
                                        text = "🔬 جارٍ تهيئة أو استيراد فحوصات الجودة الفنية لهذه الدفعة...",
                                        color = Color(0xFFC53030),
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center
                                    )
                                    Text(
                                        text = "إذا لم تبدأ تلقائياً، يمكنك النقر على الزر أدناه لإنشاء وتفعيل الفحوصات الكيميائية المعيارية للدفعة مباشرة والبدء بتدوير النتائج:",
                                        color = Color.DarkGray,
                                        fontSize = 11.sp,
                                        textAlign = TextAlign.Center
                                    )
                                    Button(
                                        onClick = { viewModel.initializeDefaultQualityTestsForOrder(order) },
                                        colors = ButtonDefaults.buttonColors(containerColor = GBRPinkAccent),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        Text("تهيئة الفحوصات الافتراضية للدفعة 🧪", color = Color.White, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        } else {
                            // Section 1: Direct Test after Production (الفحص المباشر بعد الإنتاج)
                            Text(
                                text = "1. الفحص المباشر بعد الإنتاج (مرة واحدة للجودة المباشرة):",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = GBRBlueMain
                            )

                            if (directRecord == null) {
                                // Render Form to enter direct tests
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(16.dp),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                    colors = CardDefaults.cardColors(containerColor = Color.White)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        verticalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Text(
                                            text = "تسجيل الفحص المباشر (الأول بعد الانتهاء):",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 13.sp,
                                            color = GBRDarkIndigo
                                        )

                                        // Date Input field
                                        OutlinedTextField(
                                            value = directTestDate,
                                            onValueChange = { directTestDate = it },
                                            label = { Text("تاريخ الفحص المباشر (YYYY-MM-DD)") },
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(8.dp),
                                            singleLine = true,
                                            leadingIcon = {
                                                Icon(Icons.Default.DateRange, contentDescription = null, tint = GBRBlueMain)
                                            }
                                        )

                                        // Render input fields for ALL frozen tests
                                        frozenQCList.forEach { fTest ->
                                            val minVal = fTest.minValue?.toString() ?: "بلا حد أدنى"
                                            val maxVal = fTest.maxValue?.toString() ?: "بلا حد أقصى"
                                            val currentVal = directTestInputs[fTest.testId] ?: ""

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(12.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(modifier = Modifier.weight(1.5f)) {
                                                    Text(
                                                        text = fTest.testName,
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 13.sp,
                                                        color = GBRDarkIndigo
                                                    )
                                                    Text(
                                                        text = "المواصفة: $minVal - $maxVal",
                                                        fontSize = 11.sp,
                                                        color = Color.Gray
                                                    )
                                                }

                                                OutlinedTextField(
                                                    value = currentVal,
                                                    onValueChange = { directTestInputs[fTest.testId] = it },
                                                    label = { Text("النتيجة") },
                                                    modifier = Modifier.weight(1f),
                                                    shape = RoundedCornerShape(8.dp),
                                                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                                    singleLine = true
                                                )
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                // Validate/parse inputs
                                                val resultMap = mutableMapOf<String, Double?>()
                                                frozenQCList.forEach { fTest ->
                                                    val inputVal = directTestInputs[fTest.testId]
                                                    resultMap[fTest.testId] = inputVal?.toDoubleOrNull()
                                                }
                                                viewModel.addProductionOrderTestRecord(
                                                    orderId = order.id,
                                                    isDirectTest = true,
                                                    testDate = directTestDate,
                                                    results = resultMap
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                            shape = RoundedCornerShape(8.dp)
                                        ) {
                                            Text("حفظ الفحص المباشر المعتمد", fontWeight = FontWeight.Bold, color = Color.White)
                                        }
                                    }
                                }
                            } else {
                                // Direct Test already exists – Render beautifully in a card
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(16.dp),
                                    border = BorderStroke(1.2.dp, SuccessGreen.copy(alpha = 0.5f)),
                                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF0FDF4))
                                ) {
                                    Column(modifier = Modifier.padding(16.dp)) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "✅ الفحص المباشر بعد الإنتاج",
                                                fontWeight = FontWeight.Black,
                                                color = SuccessGreen,
                                                fontSize = 14.sp
                                            )
                                            Text(
                                                text = "تاريخ التسجيل: ${directRecord.testDate}",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color.DarkGray
                                            )
                                        }
                                        Spacer(modifier = Modifier.height(10.dp))

                                        // Display direct test results inside a pretty table
                                        val resultsMap = remember(directRecord.resultsJson) {
                                            try {
                                                val js = org.json.JSONObject(directRecord.resultsJson)
                                                val map = mutableMapOf<String, Double>()
                                                js.keys().forEach { k ->
                                                    map[k] = js.optDouble(k, 0.0)
                                                }
                                                map
                                            } catch (e: Exception) {
                                                emptyMap<String, Double>()
                                            }
                                        }

                                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                            frozenQCList.forEach { fTest ->
                                                val loggedVal = resultsMap[fTest.testId.toString()]
                                                val minVal = fTest.minValue?.toString() ?: "بلا حد أدنى"
                                                val maxVal = fTest.maxValue?.toString() ?: "بلا حد أقصى"
                                                val displayLogged = loggedVal?.toString() ?: "غير مقاس"

                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .background(Color.White, RoundedCornerShape(6.dp))
                                                        .padding(8.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(fTest.testName, fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 12.sp)
                                                        Text("المواصفة: $minVal - $maxVal", fontSize = 10.sp, color = Color.Gray)
                                                    }
                                                    Text(
                                                        text = displayLogged,
                                                        fontWeight = FontWeight.Black,
                                                        fontSize = 14.sp,
                                                        color = GBRBlueMain
                                                    )
                                                }
                                            }
                                        }
                                        
                                        Spacer(modifier = Modifier.height(10.dp))
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.End
                                        ) {
                                            TextButton(onClick = {
                                                viewModel.deleteProductionOrderTestRecord(directRecord)
                                            }) {
                                                Text("إعادة قياس الفحص المباشر 🔄", color = ErrorRed, fontSize = 11.sp)
                                            }
                                        }
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(8.dp))

                            // Section 2: Monitoring Tests (فحوصات المراقبة)
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "2. فحوصات المراقبة اللاحقة (عدد غير محدود):",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRBlueMain
                                )

                                if (!showAddMonitoringForm) {
                                    Button(
                                        onClick = {
                                            showAddMonitoringForm = true
                                            monitoringDate = todayStr
                                            // Auto-select all by default
                                            frozenQCList.forEach {
                                                monitoringSelectedTests[it.testId] = true
                                                monitoringInputs[it.testId] = ""
                                            }
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = GBRPinkAccent),
                                        shape = RoundedCornerShape(8.dp),
                                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                            Icon(Icons.Default.Add, contentDescription = null, tint = Color.White, modifier = Modifier.size(16.dp))
                                            Text("إضافة فحص مراقبة", fontSize = 11.sp, color = Color.White, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }

                            if (showAddMonitoringForm) {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(16.dp),
                                    border = BorderStroke(1.2.dp, GBRPinkAccent.copy(alpha = 0.5f)),
                                    colors = CardDefaults.cardColors(containerColor = Color.White)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        verticalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "فحص مراقبة دوري جديد",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 13.sp,
                                                color = GBRDarkIndigo
                                            )
                                            IconButton(onClick = { showAddMonitoringForm = false }) {
                                                Icon(Icons.Default.Close, contentDescription = "إلغاء", tint = Color.Gray, modifier = Modifier.size(20.dp))
                                            }
                                        }

                                        OutlinedTextField(
                                            value = monitoringDate,
                                            onValueChange = { monitoringDate = it },
                                            label = { Text("تاريخ فحص المراقبة (YYYY-MM-DD)") },
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(8.dp),
                                            singleLine = true,
                                            leadingIcon = {
                                                Icon(Icons.Default.DateRange, contentDescription = null, tint = GBRPinkAccent)
                                            }
                                        )

                                        Text("اختر الفحوصات المطلوب تسجيلها حالياً:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.Gray)

                                        // Display tests with check boxes
                                        frozenQCList.forEach { fTest ->
                                            val isChecked = monitoringSelectedTests[fTest.testId] ?: false
                                            val minVal = fTest.minValue?.toString() ?: "بلا حد أدنى"
                                            val maxVal = fTest.maxValue?.toString() ?: "بلا حد أقصى"
                                            val textVal = monitoringInputs[fTest.testId] ?: ""

                                            Column(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(Color(0xFFF8FAFC), RoundedCornerShape(8.dp))
                                                    .padding(6.dp)
                                            ) {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                                    modifier = Modifier.fillMaxWidth()
                                                ) {
                                                    Checkbox(
                                                        checked = isChecked,
                                                        onCheckedChange = { monitoringSelectedTests[fTest.testId] = it },
                                                        colors = CheckboxDefaults.colors(checkedColor = GBRPinkAccent)
                                                    )
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(fTest.testName, fontWeight = FontWeight.Bold, fontSize = 12.sp, color = GBRDarkIndigo)
                                                        Text("المواصفة: $minVal - $maxVal", fontSize = 10.sp, color = Color.Gray)
                                                    }
                                                }

                                                if (isChecked) {
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    OutlinedTextField(
                                                        value = textVal,
                                                        onValueChange = { monitoringInputs[fTest.testId] = it },
                                                        label = { Text("نتيجة فحص ${fTest.testName}") },
                                                        modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 2.dp),
                                                        shape = RoundedCornerShape(6.dp),
                                                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                                        singleLine = true
                                                    )
                                                }
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                val resultMap = mutableMapOf<String, Double?>()
                                                frozenQCList.forEach { fTest ->
                                                    val isChecked = monitoringSelectedTests[fTest.testId] ?: false
                                                    if (isChecked) {
                                                        val inputVal = monitoringInputs[fTest.testId]
                                                        resultMap[fTest.testId] = inputVal?.toDoubleOrNull()
                                                    }
                                                }
                                                viewModel.addProductionOrderTestRecord(
                                                    orderId = order.id,
                                                    isDirectTest = false,
                                                    testDate = monitoringDate,
                                                    results = resultMap
                                                )
                                                showAddMonitoringForm = false
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = ButtonDefaults.buttonColors(containerColor = GBRPinkAccent),
                                            shape = RoundedCornerShape(8.dp)
                                        ) {
                                            Text("حفظ فحص المراقبة", fontWeight = FontWeight.Bold, color = Color.White)
                                        }
                                    }
                                }
                            }

                            // Section 3: Historical Records display (تنظيم وعرض السجل زمنيّاً)
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(
                                text = "3. السجل التاريخي لفحوصات الجودة لهذه الدفعة (من الأحدث للأقدم):",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = GBRDarkIndigo
                            )

                            val sortedRecords = remember(testRecordsList) {
                                testRecordsList.sortedWith(compareByDescending<com.example.data.ProductionOrderTestRecord> { it.testDate }.thenByDescending { it.timestamp })
                            }

                            if (sortedRecords.isEmpty()) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(24.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text("لا توجد فحوصات جودة مسجلة حتى الآن لهذه الدفعة.", color = Color.Gray, fontSize = 12.sp)
                                }
                            } else {
                                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                    sortedRecords.forEach { record ->
                                        val rResults = remember(record.resultsJson) {
                                            try {
                                                val js = org.json.JSONObject(record.resultsJson)
                                                val map = mutableMapOf<String, Double>()
                                                js.keys().forEach { k ->
                                                    map[k] = js.optDouble(k, 0.0)
                                                }
                                                map
                                            } catch (e: Exception) {
                                                emptyMap<String, Double>()
                                            }
                                        }

                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(12.dp),
                                            border = BorderStroke(1.dp, IndustrialBorder),
                                            colors = CardDefaults.cardColors(containerColor = Color.White)
                                        ) {
                                            Column(modifier = Modifier.padding(12.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                        val (badgeText, badgeColor) = if (record.isDirectTest) {
                                                            "فحص مباشر" to SuccessGreen
                                                        } else {
                                                            "فحص مراقبة" to GBRPinkAccent
                                                        }
                                                        Box(
                                                            modifier = Modifier
                                                                .clip(RoundedCornerShape(6.dp))
                                                                .background(badgeColor.copy(alpha = 0.12f))
                                                                .padding(horizontal = 8.dp, vertical = 2.dp)
                                                        ) {
                                                            Text(badgeText, fontSize = 10.sp, fontWeight = FontWeight.Bold, color = badgeColor)
                                                        }
                                                        Text(record.testDate, fontWeight = FontWeight.Black, color = GBRDarkIndigo, fontSize = 12.sp)
                                                    }

                                                    IconButton(
                                                        onClick = { viewModel.deleteProductionOrderTestRecord(record) },
                                                        modifier = Modifier.size(24.dp)
                                                    ) {
                                                        Icon(Icons.Default.Delete, contentDescription = "حذف", tint = ErrorRed, modifier = Modifier.size(16.dp))
                                                    }
                                                }

                                                Spacer(modifier = Modifier.height(8.dp))

                                                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                    frozenQCList.forEach { fTest ->
                                                        if (rResults.containsKey(fTest.testId.toString())) {
                                                            val res = rResults[fTest.testId.toString()]
                                                            val minLimit = fTest.minValue?.toString() ?: "بلا حد أدنى"
                                                            val maxLimit = fTest.maxValue?.toString() ?: "بلا حد أقصى"

                                                            Row(
                                                                modifier = Modifier
                                                                    .fillMaxWidth()
                                                                    .background(Color(0xFFF8FAFC), RoundedCornerShape(6.dp))
                                                                    .padding(horizontal = 8.dp, vertical = 5.dp),
                                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                                verticalAlignment = Alignment.CenterVertically
                                                            ) {
                                                                Column(modifier = Modifier.weight(1f)) {
                                                                    Text(fTest.testName, fontWeight = FontWeight.Bold, fontSize = 11.sp, color = GBRDarkIndigo)
                                                                    Text("المواصفة القياسية: $minLimit - $maxLimit", fontSize = 9.sp, color = Color.Gray)
                                                                }
                                                                Text(
                                                                    text = res?.toString() ?: "",
                                                                    fontWeight = FontWeight.Black,
                                                                    fontSize = 13.sp,
                                                                    color = GBRBlueMain
                                                                )
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            }
        }
    } else if (isAddingNewOrder) {
        // --- Tab 2: Adding a custom new production order ---
        val approvedFormulations = formulationsList.filter { it.status == "🟢 معتمدة للإنتاج" }
        val allFormulationItems by viewModel.allFormulationItems.collectAsState()

        var chosenFormulation by remember { mutableStateOf<com.example.data.Formulation?>(null) }
        var inputWeightStr by remember { mutableStateOf("") }
        var inputNotesStr by remember { mutableStateOf("") }

        var lastCompletedOrderHasAdjustments by remember { mutableStateOf(false) }
        var lastCompletedOrderAdjustments by remember { mutableStateOf<List<com.example.data.ProductionAdjustment>>(emptyList()) }
        var isCheckingLastCompletedOrderAdjustments by remember { mutableStateOf(false) }
        var showNewOrderAdjustmentsWarningDialog by remember { mutableStateOf(false) }

        var chosenFormulaPhases by remember { mutableStateOf<List<com.example.data.RecipePhase>>(emptyList()) }
        var chosenFormulaStatus by remember { mutableStateOf<com.example.data.RecipeStatus?>(null) }
        var isCheckingChosenFormulaRecipe by remember { mutableStateOf(false) }

        LaunchedEffect(chosenFormulation) {
            val formula = chosenFormulation
            if (formula != null) {
                isCheckingChosenFormulaRecipe = true
                isCheckingLastCompletedOrderAdjustments = true
                try {
                    chosenFormulaPhases = viewModel.getRecipePhasesForFormulationSync(formula.id)
                    chosenFormulaStatus = viewModel.getRecipeStatusSync(formula.id)
                    val lastCompleted = viewModel.getLastCompletedProductionOrderForFormulation(formula.id)
                    if (lastCompleted != null) {
                        val adjustments = viewModel.getProductionAdjustmentsSync(lastCompleted.id)
                        lastCompletedOrderAdjustments = adjustments
                        lastCompletedOrderHasAdjustments = adjustments.isNotEmpty()
                    } else {
                        lastCompletedOrderAdjustments = emptyList()
                        lastCompletedOrderHasAdjustments = false
                    }
                } catch (e: Exception) {
                    chosenFormulaPhases = emptyList()
                    chosenFormulaStatus = null
                    lastCompletedOrderAdjustments = emptyList()
                    lastCompletedOrderHasAdjustments = false
                } finally {
                    isCheckingChosenFormulaRecipe = false
                    isCheckingLastCompletedOrderAdjustments = false
                }
            } else {
                chosenFormulaPhases = emptyList()
                chosenFormulaStatus = null
                lastCompletedOrderAdjustments = emptyList()
                lastCompletedOrderHasAdjustments = false
            }
        }

        val isRecipeInactive = remember(chosenFormulation, chosenFormulaPhases, chosenFormulaStatus) {
            chosenFormulation != null && (chosenFormulaPhases.isEmpty() || chosenFormulaStatus?.status != "READY")
        }

        // Reactive query for version revisions of the chosen formulation
        val revisionsFlow = remember(chosenFormulation) {
            chosenFormulation?.let { viewModel.getRevisionsForFormulation(it.id) }
                ?: kotlinx.coroutines.flow.flowOf(emptyList())
        }
        val revisionsList by revisionsFlow.collectAsState(initial = emptyList())
        var isVersionsExpanded by remember { mutableStateOf(false) }
        var chosenVersionName by remember { mutableStateOf("الإصدار الحالي (النشط)") }

        var scaleFactor by remember { mutableStateOf(1.0) }
        var customScaleFactorStr by remember { mutableStateOf("") }
        val activeScale = if (customScaleFactorStr.isNotBlank()) {
            customScaleFactorStr.toDoubleOrNull() ?: scaleFactor
        } else {
            scaleFactor
        }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            // Header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "إنشاء أمر إنتاج جديد للتشغيل",
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                IconButton(onClick = { isAddingNewOrder = false }) {
                    Icon(imageVector = Icons.Default.Close, contentDescription = "رجوع", tint = ErrorRed)
                }
            }

            // Step 1: Choose Formulation
            Text("1. اختر التركيبة (المعتمدة فقط للإنتاج):", fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 13.sp)

            if (approvedFormulations.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp)
                        .border(1.dp, ErrorRed.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                        .background(ErrorRed.copy(alpha = 0.05f))
                        .padding(12.dp)
                ) {
                    Text(
                        text = "لا توجد تركيبات معتمدة للإنتاج بعد في النظام! يرجى اعتماد تركيبة من صفحة التركيبات أولاً.",
                        color = ErrorRed,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            } else {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    border = BorderStroke(1.dp, IndustrialBorder),
                    colors = CardDefaults.cardColors(containerColor = Color.White)
                ) {
                    Column(modifier = Modifier.padding(8.dp)) {
                        approvedFormulations.forEach { formula ->
                            val isSelected = chosenFormulation?.id == formula.id
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (isSelected) GBRBlueMain.copy(alpha = 0.1f) else Color.Transparent)
                                    .clickable {
                                        chosenFormulation = formula
                                        chosenVersionName = "الإصدار الحالي (النشط)" // reset version index
                                    }
                                    .padding(12.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column {
                                    Text(formula.name, fontWeight = FontWeight.Bold, color = if (isSelected) GBRBlueMain else GBRDarkIndigo, fontSize = 14.sp)

                                }

                                if (isSelected) {
                                    Icon(imageVector = Icons.Default.CheckCircle, contentDescription = null, tint = GBRBlueMain)
                                }
                            }
                        }
                    }
                }
            }

            if (chosenFormulation != null) {
                if (isCheckingChosenFormulaRecipe) {
                    Text(
                        "⏳ جاري التحقق من وصفة تشغيل التركيبة المحددة...",
                        fontSize = 11.sp,
                        color = Color.Gray,
                        modifier = Modifier.padding(vertical = 4.dp)
                    )
                } else if (isRecipeInactive) {
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 4.dp),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFFEF2F2)),
                        border = BorderStroke(1.dp, Color(0xFFFCA5A5))
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Warning,
                                contentDescription = null,
                                tint = ErrorRed,
                                modifier = Modifier.size(24.dp)
                            )
                            Column {
                                Text(
                                    text = "تحذير: وصفة التشغيل غير معتمدة أو غير مفعلة!",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF991B1B)
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "طالما أن وصفة التشغيل للتركيبة غير معتمدة أو غير مفعلة، فلا يمكن إنشاء أمر الإنتاج.",
                                    fontSize = 11.sp,
                                    color = Color(0xFF7F1D1D)
                                )
                            }
                        }
                    }
                }
            }

            // Step 2: Choose Formulation Version
            if (chosenFormulation != null) {
                Text("2. اختر إصدار التركيبة المطلوبة للوجبة التكرارية:", fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 13.sp)

                Box(modifier = Modifier.fillMaxWidth()) {
                    OutlinedButton(
                        onClick = { isVersionsExpanded = true },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp),
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = GBRDarkIndigo)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(chosenVersionName, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                            Icon(imageVector = Icons.Default.ArrowDropDown, contentDescription = null)
                        }
                    }

                    DropdownMenu(
                        expanded = isVersionsExpanded,
                        onDismissRequest = { isVersionsExpanded = false },
                        modifier = Modifier.fillMaxWidth(0.9f)
                    ) {
                        DropdownMenuItem(
                            text = { Text("الإصدار الحالي (النشط)", fontWeight = FontWeight.Bold) },
                            onClick = {
                                chosenVersionName = "الإصدار الحالي (النشط)"
                                isVersionsExpanded = false
                            }
                        )

                        revisionsList.forEach { revision ->
                            DropdownMenuItem(
                                text = { Text("النسخة المحفوظة: ${revision.version}  (${revision.dateChange})") },
                                onClick = {
                                    chosenVersionName = revision.version
                                    isVersionsExpanded = false
                                }
                            )
                        }
                    }
                }
            }

            // Step 3: Operating Factor Multiplier
            Text("3. حدد معامل التشغيل المطلوب للدفعة (Multiplier):", fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 13.sp)
            
            // Multiplier quick picks Row
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                val quickPicks = listOf(
                    "¼" to 0.25,
                    "½" to 0.5,
                    "دفعة (1.0)" to 1.0,
                    "دفعتين (2.0)" to 2.0,
                    "3 دفعات" to 3.0
                )
                quickPicks.forEach { (label, value) ->
                    val isSelected = customScaleFactorStr.isBlank() && scaleFactor == value
                    ElevatedAssistChip(
                        onClick = {
                            scaleFactor = value
                            customScaleFactorStr = ""
                        },
                        label = { Text(label, fontWeight = FontWeight.Bold, fontSize = 11.sp) },
                        colors = AssistChipDefaults.elevatedAssistChipColors(
                            containerColor = if (isSelected) GBRBlueMain else Color.White,
                            labelColor = if (isSelected) Color.White else GBRDarkIndigo
                        ),
                        modifier = Modifier
                            .weight(1f)
                            .testTag("multiplier_chip_${value}")
                    )
                }
            }

            // Custom numerical multiplier text field
            OutlinedTextField(
                value = customScaleFactorStr,
                onValueChange = { 
                    customScaleFactorStr = it
                },
                label = { Text("معامل غير افتراضي (مخصص يدوياً)") },
                placeholder = { Text("مثلاً: 1.5 أو 0.75") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                singleLine = true,
                modifier = Modifier
                    .fillMaxWidth()
                    .testTag("custom_multiplier_input"),
                shape = RoundedCornerShape(10.dp),
                leadingIcon = { Icon(imageVector = Icons.Default.Settings, contentDescription = null) }
            )

            // Live weight simulation report
            if (chosenFormulation != null) {
                val formulationItems = allFormulationItems.filter { it.formulationId == chosenFormulation!!.id }
                val originalWeight = formulationItems.sumOf { it.quantityMultiplier }
                val expectedWeight = originalWeight * activeScale

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF0FDF4)),
                    border = BorderStroke(1.dp, Color(0xFFBBF7D0))
                ) {
                    Column(
                        modifier = Modifier.padding(14.dp),
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            text = "ملخص حسابات وكميات دفعة الإنتاج:",
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF166534),
                            fontSize = 12.sp
                        )
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text("الوزن الأصلي للوجبة الكاملة:", fontSize = 11.sp, color = Color.Gray)
                            Text("${formatQuantity(originalWeight)} كجم", fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 12.sp)
                        }
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text("معامل التشغيل المعتمد:", fontSize = 11.sp, color = Color.Gray)
                            Text("× $activeScale", fontWeight = FontWeight.Bold, color = Color(0xFF15803D), fontSize = 12.sp)
                        }
                        Divider(color = Color(0xFFDCFCE7), thickness = 1.dp)
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text("الوزن النهائي المتوقع للدفعة المجدولة:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFF14532D))
                            Text("${formatQuantity(expectedWeight)} كجم", fontWeight = FontWeight.Black, color = Color(0xFF166534), fontSize = 16.sp)
                        }
                    }
                }
            }

            // Step 4: Notes and Description
            Text("4. أي ملاحظات اختيارية أو تعليمات توجيه للمصنع:", fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 13.sp)
            OutlinedTextField(
                value = inputNotesStr,
                onValueChange = { inputNotesStr = it },
                label = { Text("ملاحظات أمر الإنتاج والتعبئة") },
                placeholder = { Text("مثال: تعبئة في عبوات البلاستيك المقوى أزرق 18L") },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(10.dp),
                maxLines = 4
            )

            Spacer(modifier = Modifier.height(10.dp))

            // CTA Submit Row
            val formulaItems = chosenFormulation?.let { f -> allFormulationItems.filter { it.formulationId == f.id } } ?: emptyList()
            val originalWeight = formulaItems.sumOf { it.quantityMultiplier }
            val isFormValid = chosenFormulation != null && activeScale > 0.0 && originalWeight > 0.0 && !isRecipeInactive && !isCheckingChosenFormulaRecipe

            Button(
                onClick = {
                    if (isFormValid && chosenFormulation != null) {
                        if (lastCompletedOrderHasAdjustments) {
                            showNewOrderAdjustmentsWarningDialog = true
                        } else {
                            viewModel.addProductionOrder(
                                formulationId = chosenFormulation!!.id,
                                formulationName = chosenFormulation!!.name,
                                versionName = chosenVersionName,
                                scaleFactor = activeScale,
                                originalWeightKg = originalWeight,
                                notes = inputNotesStr
                            )
                            isAddingNewOrder = false
                        }
                    }
                },
                enabled = isFormValid,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(52.dp),
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
            ) {
                Icon(imageVector = Icons.Default.Done, contentDescription = null)
                Spacer(modifier = Modifier.width(8.dp))
                Text("حفظ وإصدار أمر الإنتاج الفوري", fontWeight = FontWeight.Bold, color = Color.White, fontSize = 14.sp)
            }

            if (showNewOrderAdjustmentsWarningDialog && chosenFormulation != null) {
                AlertDialog(
                    onDismissRequest = { showNewOrderAdjustmentsWarningDialog = false },
                    title = {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Warning,
                                contentDescription = null,
                                tint = Color(0xFFD97706)
                            )
                            Text(
                                text = "تنبيه: تعديل في الدفعة السابقة!",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1F2937)
                            )
                        }
                    },
                    text = {
                        Column(
                            verticalArrangement = Arrangement.spacedBy(10.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(
                                text = "تنبيه! لقد تم تعديل آخر أمر إنتاج مكتمل ومؤرشف لهذه التركيبة. يرجى مراجعة التعديلات أدناه للتأكد مما إذا كان الأمر الجديد يتطلب تعديلات مماثلة في نسب وكميات المواد:",
                                fontSize = 13.sp,
                                color = Color(0xFF4B5563),
                                lineHeight = 18.sp
                            )
                            
                            Divider(color = Color(0xFFE5E7EB))
                            
                            Text(
                                text = "تعديلات المواد السابقة:",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1F2937)
                            )
                            
                            lastCompletedOrderAdjustments.forEach { adj ->
                                val diffQty = adj.newQuantity - adj.originalQuantity
                                val diffText = if (diffQty > 0) "+${String.format(java.util.Locale.US, "%.3f", diffQty)}" else String.format(java.util.Locale.US, "%.3f", diffQty)
                                val diffColor = if (diffQty > 0) Color(0xFF15803D) else Color(0xFFB91C1C)
                                
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(8.dp),
                                    colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                                    border = BorderStroke(1.dp, Color(0xFFFDE68A))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(10.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Text(
                                            text = "المادة: ${adj.rawMaterialName}",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF78350F)
                                        )
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Text(text = "الكمية الأصلية: ${String.format(java.util.Locale.US, "%.2f", adj.originalQuantity)} كجم", fontSize = 11.sp, color = Color(0xFF4B5563))
                                            Text(text = "الكمية المعدلة: ${String.format(java.util.Locale.US, "%.2f", adj.newQuantity)} كجم", fontSize = 11.sp, color = Color(0xFF4B5563))
                                        }
                                        Text(
                                            text = "الفرق: $diffText كجم",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = diffColor
                                        )
                                        if (!adj.reason.isNullOrBlank()) {
                                            Text(
                                                text = "السبب: ${adj.reason}",
                                                fontSize = 11.sp,
                                                fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                                                color = Color(0xFF4B5563)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                showNewOrderAdjustmentsWarningDialog = false
                                viewModel.addProductionOrder(
                                    formulationId = chosenFormulation!!.id,
                                    formulationName = chosenFormulation!!.name,
                                    versionName = chosenVersionName,
                                    scaleFactor = activeScale,
                                    originalWeightKg = originalWeight,
                                    notes = "تم تأكيد واجتياز تحذير الدفعة السابقة المعدلة. $inputNotesStr"
                                )
                                isAddingNewOrder = false
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFD97706)),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Text("تأكيد وإصدار الدفعة", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                    },
                    dismissButton = {
                        OutlinedButton(
                            onClick = { showNewOrderAdjustmentsWarningDialog = false },
                            shape = RoundedCornerShape(8.dp),
                            border = BorderStroke(1.dp, Color(0xFFD1D5DB))
                        ) {
                            Text("إلغاء والعودة للتعديل", color = Color(0xFF4B5563), fontSize = 12.sp)
                        }
                    }
                )
            }
        }
    } else {
        // --- Tab 1: Dashboard and Production Logs List ---
        val filteredOrders = ordersList.filter { order ->
            val matchesSearch = order.orderNumber.contains(searchQuery, ignoreCase = true) ||
                                order.batchNumber.contains(searchQuery, ignoreCase = true) ||
                                order.formulationName.contains(searchQuery, ignoreCase = true)
            val matchesStatus = if (statusFilter == "الكل") true else order.status == statusFilter
            matchesSearch && matchesStatus
        }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            // Dashboard header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "تشغيل وإدارة دفعات الإنتاج",
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                // Add button
                Button(
                    onClick = { isAddingNewOrder = true },
                    shape = RoundedCornerShape(10.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Icon(imageVector = Icons.Default.Add, contentDescription = null)
                    Spacer(modifier = Modifier.width(4.dp))
                    Text("أمر إنتاج جديد", fontWeight = FontWeight.Bold)
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Search text field
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                placeholder = { Text("ابحث برقم الأمر، الدفعة، اسم المنتج...") },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(10.dp),
                singleLine = true,
                leadingIcon = { Icon(imageVector = Icons.Default.Search, contentDescription = null) },
                trailingIcon = {
                    if (searchQuery.isNotEmpty()) {
                        IconButton(onClick = { searchQuery = "" }) {
                            Icon(imageVector = Icons.Default.Clear, contentDescription = null)
                        }
                    }
                }
            )

            Spacer(modifier = Modifier.height(12.dp))

            // Filter chips selection list
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                val statuses = listOf("الكل", "مسودة", "قيد التنفيذ", "مكتمل", "ملغي")
                statuses.forEach { stringStr ->
                    val isSelected = statusFilter == stringStr
                    val chipBg = if (isSelected) GBRBlueMain else Color(0xFFEFF6FF)
                    val chipText = if (isSelected) Color.White else GBRDarkIndigo

                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(32.dp))
                            .background(chipBg)
                            .clickable { statusFilter = stringStr }
                            .padding(horizontal = 14.dp, vertical = 6.dp)
                    ) {
                        Text(
                            text = stringStr,
                            color = chipText,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Orders list view
            if (filteredOrders.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(
                            imageVector = Icons.Default.List,
                            contentDescription = null,
                            tint = Color.LightGray,
                            modifier = Modifier.size(54.dp)
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = if (searchQuery.isBlank() && statusFilter == "الكل") "لم يتم إنشاء أي أوامر إنتاج بعد." else "لا توجد نتائج مطابقة لبحثك الحالي.",
                            color = Color.Gray,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = "اضغط على زر 'أمر إنتاج جديد' في الأعلى لإطلاق دفعة جديدة.",
                            color = Color.Gray,
                            fontSize = 11.sp
                        )
                    }
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredOrders) { order ->
                        val formattedDate = try {
                            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
                            sdf.format(java.util.Date(order.createdAt))
                        } catch (e: Exception) {
                            ""
                        }
                        val testsCount = remember(allTestRecords, labSessions, allLabTests, order.id) {
                            val classicCount = allTestRecords.count { 
                                it.productionOrderId == order.id && try {
                                    org.json.JSONObject(it.resultsJson).length() > 0
                                } catch (e: Exception) {
                                    false
                                }
                            }
                            val associatedSessions = labSessions.filter { it.sampleProperties.startsWith("ORDER_ID:${order.id}") }
                            val sessionTestsCount = if (associatedSessions.isNotEmpty()) {
                                val sessionIds = associatedSessions.map { it.id }.toSet()
                                allLabTests.count { it.sessionId in sessionIds }
                            } else {
                                0
                            }
                            classicCount + sessionTestsCount
                        }

                        Card(
                            onClick = { viewModel.selectedProductionOrder.value = order },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, IndustrialBorder),
                            colors = CardDefaults.cardColors(containerColor = Color.White)
                        ) {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(14.dp)
                            ) {
                                // Top row order keys & status badge
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column {
                                        Text(order.orderNumber, fontWeight = FontWeight.Bold, color = GBRBlueMain, fontSize = 15.sp)
                                        Text("رقم الدفعة: ${order.batchNumber}", fontSize = 11.sp, color = Color.Gray)
                                    }

                                    // Status Badge
                                    val (color, bg) = when (order.status) {
                                        "مسودة" -> Color.Gray to Color(0xFFF1F5F9)
                                        "قيد التنفيذ" -> WarningOrange to Color(0xFFFEF3C7)
                                        "مكتمل" -> SuccessGreen to Color(0xFFD1FAE5)
                                        else -> ErrorRed to Color(0xFFFEE2E2)
                                    }
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(bg)
                                            .padding(horizontal = 8.dp, vertical = 3.dp)
                                    ) {
                                        Text(order.status, fontWeight = FontWeight.Bold, color = color, fontSize = 10.sp)
                                    }
                                }

                                Spacer(modifier = Modifier.height(10.dp))
                                Divider(color = IndustrialBorder)
                                Spacer(modifier = Modifier.height(10.dp))

                                // Mid row details
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column {
                                        Text(order.formulationName, fontWeight = FontWeight.Bold, color = GBRDarkIndigo, fontSize = 14.sp)
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                                        ) {
                                            Text("إصدار التركيبة المستخدم:", fontSize = 11.sp, color = Color.Gray)
                                            Text(order.formulationVersion, fontSize = 11.sp, color = GBRCyanAccent, fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    Column(horizontalAlignment = Alignment.End) {
                                        Text("${formatQuantity(order.requiredWeightKg)} كجم", fontWeight = FontWeight.Black, color = GBRPinkAccent, fontSize = 16.sp)
                                        Text(formattedDate, fontSize = 10.sp, color = Color.Gray)
                                    }
                                }

                                Spacer(modifier = Modifier.height(10.dp))
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    if (order.status == "مكتمل" && testsCount > 0) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                            modifier = Modifier
                                                .background(Color(0xFFEFF6FF), RoundedCornerShape(4.dp))
                                                .padding(horizontal = 6.dp, vertical = 2.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Info,
                                                contentDescription = null,
                                                tint = GBRBlueMain,
                                                modifier = Modifier.size(10.dp)
                                            )
                                            Text(
                                                text = "الفحوصات: $testsCount",
                                                color = GBRBlueMain,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// ==========================================
// SEGMENT 5 PANEL: APPLICATION INFO (معلومات التطبيق)
// ==========================================
@Composable
fun AppInfoPanel(viewModel: GbrViewModel) {
    BackHandler(enabled = true) {
        viewModel.showSegment(null)
    }

    val context = LocalContext.current
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en

    val syncPrefs = remember { context.getSharedPreferences("gbr_sync_prefs", android.content.Context.MODE_PRIVATE) }
    val fbProjectId = syncPrefs.getString("fb_project_id", "") ?: ""
    val fbApiKey = syncPrefs.getString("fb_api_key", "") ?: ""
    val fbAppId = syncPrefs.getString("fb_app_id", "") ?: ""

    val rawMaterials by viewModel.rawMaterials.collectAsState()
    val formulations by viewModel.formulations.collectAsState()
    val productionOrders by viewModel.productionOrders.collectAsState()
    val syncMode by viewModel.syncMode.collectAsState()

    val rawMaterialsLast by viewModel.syncLastRawMaterials.collectAsState()
    val formulationsLast by viewModel.syncLastFormulations.collectAsState() 
    val ordersLast by viewModel.syncLastProductionOrders.collectAsState()

    val lastUpdateTime = remember(rawMaterialsLast, formulationsLast, ordersLast) {
        val list = listOf(rawMaterialsLast, formulationsLast, ordersLast).filter { it != "لم يتم المزامنة بعد" && !it.contains("Never") }
        if (list.isEmpty()) {
            "لم يتم المزامنة بعد"
        } else {
            list.firstOrNull() ?: "غير معروف"
        }
    }

    val dbSizeMb = remember {
        try {
            val dbFile = context.getDatabasePath("gbr_database")
            if (dbFile.exists()) {
                dbFile.length().toDouble() / (1024.0 * 1024.0)
            } else {
                0.0
            }
        } catch (e: Exception) {
            0.0
        }
    }

    val lastBackupTime = syncPrefs.getString("last_backup_time", "لا يوجد نسخة احتياطية بعد") ?: "لا يوجد نسخة احتياطية بعد"
    val lastBackupSize = syncPrefs.getString("last_backup_size", "--") ?: "--"
    val lastBackupType = syncPrefs.getString("last_backup_type", "--") ?: "--"

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .verticalScroll(rememberScrollState())
            .padding(20.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Top
    ) {
        // Back Header
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Start
        ) {
            IconButton(
                onClick = { viewModel.showSegment(null) },
                modifier = Modifier
                    .clip(RoundedCornerShape(12.dp))
                    .background(Color.LightGray.copy(alpha = 0.2f))
            ) {
                Icon(
                    imageVector = Icons.Default.ArrowForward,
                    contentDescription = "الرجوع",
                    tint = GBRBlueMain
                )
            }
            Spacer(modifier = Modifier.width(12.dp))
            Text(
                text = t("معلومات النظام والترخيص والموارد الكلية", "System Info & Resources"),
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                color = GBRDarkIndigo
            )
        }

        // Main info card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                // Large styled brand logo
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    GbrLogo(scale = 0.8f, showPaintsText = false)
                    Column {
                        Text(
                            text = "نظام دهانات GBR الذكي",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.ExtraBold,
                            color = GBRDarkIndigo
                        )
                        Text(
                            text = "v${com.example.BuildConfig.VERSION_NAME} Enterprise Premium 💎",
                            fontSize = 11.sp,
                            color = SuccessGreen,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(Color.LightGray.copy(alpha = 0.3f))
                )

                // Info Rows
                InfoRowItem(label = "نوع المزامنة الحالي", value = when(syncMode) {
                    "realtime" -> "مزامنة مباشرة (Live Realtime 🔄)"
                    "manual" -> "مزامنة يدوية (Manual Sync ☁️)"
                    else -> "وضع تشغيل محلي (Local Offline 📴)"
                })
                InfoRowItem(label = "تاريخ آخر مزامنة ناجحة", value = lastUpdateTime)
                InfoRowItem(label = "حجم قاعدة البيانات المحلية", value = String.format(java.util.Locale.US, "%.3f MB", dbSizeMb))
                InfoRowItem(label = "عدد المواد الخام المسجلة", value = "${rawMaterials.size} مادة")
                InfoRowItem(label = "عدد التركيبات المسجلة", value = "${formulations.size} تركيبة")
                InfoRowItem(label = "عدد أوامر الإنتاج والوجبات", value = "${productionOrders.size} أمر تشغيل")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Firebase Cloud Parameters Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "☁️ بارامترات الاتصال السحابي (Firebase Info)",
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(Color.LightGray.copy(alpha = 0.3f))
                )

                val maskedApiKey = if (fbApiKey.isNotBlank()) {
                    if (fbApiKey.length > 8) fbApiKey.take(4) + "********" + fbApiKey.takeLast(4)
                    else "********"
                } else "غير معرف ⚠️"

                InfoRowItem(label = "معرّف المشروع (Project ID)", value = fbProjectId.ifBlank { "غير معرف ⚠️" })
                InfoRowItem(label = "مفتاح واجهة التطبيق (API Key)", value = maskedApiKey)
                InfoRowItem(label = "مستودع السحابة (Cloud Storage)", value = if (fbProjectId.isNotBlank()) "gs://${fbProjectId}.appspot.com" else "غير مرتبط 🚫")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Last Backup Info Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "💾 أرشيف النسخ الاحتياطية المحلي",
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(Color.LightGray.copy(alpha = 0.3f))
                )

                InfoRowItem(label = "تاريخ آخر تصدير", value = lastBackupTime)
                InfoRowItem(label = "حجم ملف النسخة الأخيرة", value = lastBackupSize)
                InfoRowItem(label = "صيغة الملف المصدر", value = lastBackupType)
            }
        }

        Spacer(modifier = Modifier.height(24.dp))

        // Copyright footer
        Text(
            text = "جميع الحقوق محفوظة © ٢٠٢٦ لمجموعة مصانع GBR للدهانات وتكنولوجيا المواد",
            fontSize = 11.sp,
            fontWeight = FontWeight.Medium,
            color = Color.Gray,
            textAlign = TextAlign.Center
        )
    }
}

@Composable
fun InfoRowItem(label: String, value: String, isVersionValue: Boolean = false) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = label,
            fontSize = 14.sp,
            fontWeight = FontWeight.SemiBold,
            color = Color.Gray
        )
        if (isVersionValue) {
            Box(
                modifier = Modifier
                    .clip(RoundedCornerShape(8.dp))
                    .background(GBRBlueMain.copy(alpha = 0.1f))
                    .padding(horizontal = 12.dp, vertical = 4.dp)
            ) {
                Text(
                    text = value,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRBlueMain
                )
            }
        } else {
            Text(
                text = value,
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = GBRDarkIndigo
            )
        }
    }
}

// ==========================================
// SEGMENT 6 PANEL: REPORTS PANEL (سجل التقارير)
// ==========================================
data class MergedProductionRun(
    val id: String,
    val formulationId: String,
    val formulationName: String,
    val operatorName: String,
    val batchWeightKg: Double,
    val timestamp: Long,
    val source: String, // "order" or "direct"
    val referenceNumber: String // "PO-..." etc.
)

data class LeaderboardProductItem(
    val formulationName: String,
    val formulationCode: String,
    val formulationId: String,
    val completedOrderCount: Int,
    val totalOrderCount: Int,
    val totalWeightKg: Double,
    val orders: List<com.example.data.ProductionOrder>
)

data class OrderQCReportItem(
    val order: com.example.data.ProductionOrder,
    val sessions: List<com.example.data.LabSession>,
    val labTests: List<com.example.data.LabTest>,
    val directRecords: List<com.example.data.ProductionOrderTestRecord>,
    val latestInspectionTime: Long
)

@Composable
fun ReportsPanel(viewModel: GbrViewModel) {
    val historyLogs by viewModel.productionLogs.collectAsState()
    val formulationsList by viewModel.formulations.collectAsState()
    val productionOrdersList by viewModel.productionOrders.collectAsState()
    val allAdjustments by viewModel.productionAdjustments.collectAsState()
    val allRevisions by viewModel.allFormulationRevisions.collectAsState()
    val allFormulationQualityTests by viewModel.allFormulationQualityTests.collectAsState()
    val qualityTestsList by viewModel.qualityTests.collectAsState()
    val allProductionOrderTestRecords by viewModel.allProductionOrderTestRecords.collectAsState()
    val labSessions by viewModel.labSessions.collectAsState()
    val allLabTests by viewModel.allLabTests.collectAsState()
    val allProductionOrderQualityTests by viewModel.allProductionOrderQualityTests.collectAsState()

    val themeStr by viewModel.appTheme.collectAsState()
    val isDark = themeStr == "dark"

    val bgColors = if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC)
    val cardBg = if (isDark) Color(0xFF1E293B) else Color(0xFFFFFFFF)
    val borderColor = if (isDark) Color(0xFF334155) else Color(0xFFE2E8F0)
    val textPrimary = if (isDark) Color.White else GBRDarkIndigo
    val textSecondary = if (isDark) Color(0xFF94A3B8) else Color(0xFF475569)

    var activeReportTab by viewModel.keepState("rep_tab") { mutableStateOf<String?>(null) }
    var selectedQcSession by remember { mutableStateOf<com.example.data.LabSession?>(null) }
    var multipleSessionsForOrderDialog by remember { mutableStateOf<Pair<com.example.data.ProductionOrder, List<com.example.data.LabSession>>?>(null) }

    // Robust, strictly matching helper to avoid empty/null mismatches for unproduced/mismatched products
    val isRunMatchingFormula = remember(formulationsList) {
        { run: MergedProductionRun, formula: Formulation ->
            val runId = run.formulationId.trim()
            val formulaId = formula.id.trim()
            
            if (runId.isNotEmpty() && formulaId.isNotEmpty() && runId == formulaId) {
                true
            } else {
                val targetCode = formula.code.trim().uppercase()
                val targetName = formula.name.trim().lowercase()
                
                val runFormula = if (runId.isNotEmpty()) formulationsList.find { it.id == runId } else null
                val runCode = runFormula?.code?.trim()?.uppercase() ?: ""
                val runName = runFormula?.name?.trim()?.lowercase() ?: run.formulationName.trim().lowercase()
                
                if (targetCode.isNotEmpty() && runCode.isNotEmpty() && targetCode == runCode) {
                    true
                } else {
                    targetName.isNotEmpty() && runName.isNotEmpty() && targetName == runName
                }
            }
        }
    }

    // Navigation and Back Clicks
    BackHandler(enabled = true) {
        if (selectedQcSession != null) {
            selectedQcSession = null
        } else if (activeReportTab != null) {
            activeReportTab = null
        } else {
            viewModel.showSegment(null)
        }
    }

    // Unique formulations/products grouping by code to avoid duplicate counts from revisions/versions
    val latestFormulations = remember(formulationsList) {
        formulationsList
            .filter { it.name.trim().isNotBlank() && it.code.trim().isNotBlank() }
            .groupBy { it.code.trim().uppercase() }
            .map { entry -> 
                entry.value.maxByOrNull { f ->
                    val ver = f.version.trim()
                    val vNum = if (ver.startsWith("الإصدار ")) {
                        ver.substringAfter("الإصدار ").trim().toIntOrNull() ?: 1
                    } else {
                        ver.filter { it.isDigit() }.toIntOrNull() ?: 1
                    }
                    vNum
                }!!
            }
    }

    // Bidirectional/Unified Production Runs mapped directly from completed/archived production orders
    // to match exactly what is shown in the app
    val allRuns = remember(productionOrdersList) {
        val completedOrders = productionOrdersList.filter { it.status == "مكتمل" }
        completedOrders.map { order ->
            MergedProductionRun(
                id = order.id,
                formulationId = order.formulationId,
                formulationName = order.formulationName,
                operatorName = order.operatorName.ifBlank { "المشرف" },
                batchWeightKg = order.requiredWeightKg,
                timestamp = if (order.endTime > 0L) order.endTime else order.createdAt,
                source = "order",
                referenceNumber = order.orderNumber
            )
        }.sortedByDescending { it.timestamp }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(bgColors)
            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Top
    ) {
        // --- Core Header ---
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Start
        ) {
            IconButton(
                onClick = {
                    if (selectedQcSession != null) {
                        selectedQcSession = null
                    } else if (activeReportTab != null) {
                        activeReportTab = null
                    } else {
                        viewModel.showSegment(null)
                    }
                },
                modifier = Modifier
                    .clip(RoundedCornerShape(12.dp))
                    .background(if (isDark) Color(0xFF1E293B) else Color(0xFFF1F5F9))
            ) {
                Icon(
                    imageVector = Icons.Default.ArrowForward,
                    contentDescription = "الرجوع",
                    tint = GBRBlueMain
                )
            }
            Spacer(modifier = Modifier.width(12.dp))
            Column {
                Text(
                    text = if (selectedQcSession != null) {
                        "تفاصيل جلسة الفحص: ${selectedQcSession?.sampleOrProduct?.ifBlank { selectedQcSession?.testName } ?: "فحص جودة"}"
                    } else if (activeReportTab == null) "لوحة التقارير الذكية 📊" else {
                        when (activeReportTab) {
                            "movement" -> "حركة صنف 📦"
                            "cost" -> "انحراف تكلفة الوجبات 📊"
                            "adjustments" -> "المواد المعدلة والتحسينات ⚠"
                            "leaderboard" -> "المنتجات الأكثر إنتاجاً 📈"
                            "revisions" -> "أرشيف تعديل التركيبات 📋"
                            "qc" -> "أوامر الإنتاج المفحوصة مخبرياً 🧪"
                            "notes" -> "ملاحظات وتوجيهات التشغيل 📝"
                            "aging" -> "المنتجات الراكدة والمستهدفة 📦"
                            else -> "التقارير وسجلات الإنتاج 📊"
                        }
                    },
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = textPrimary
                )
                Text(
                    text = if (selectedQcSession != null) {
                        "عرض تفاصيل جلسة الفحص المخبري ونتائج الاختبارات"
                    } else if (activeReportTab == null) {
                        "نظرة شمولية قائمة على البيانات الحية لمصنع دهانات GBR"
                    } else {
                        "لوحة التقارير التفصيلية المربوطة والمطابقة"
                    },
                    fontSize = 11.sp,
                    color = textSecondary
                )
            }
        }

        if (activeReportTab == null) {
            // =========================================================================
            // MAIN DASHBOARD VIEW
            // =========================================================================
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Computing statistics using the unique latest formulations
                val approvedFormulasCount = latestFormulations.count { it.status == "🟢 معتمدة للإنتاج" || it.status.contains("معتمد") }
                val draftFormulasCount = latestFormulations.count { it.status == "⚪ مسودة" || it.status == "🟡 قيد التطوير" || it.status.contains("مسودة") || it.status.contains("تطوير") }
                val totalProducedWeight = allRuns.sumOf { it.batchWeightKg }
                
                // Track produced vs unproduced counts using robust, exact matching based on database values
                val uniqueProducedCount = latestFormulations.count { formula ->
                    allRuns.any { run -> isRunMatchingFormula(run, formula) }
                }
                val approvedFormulasForUnproduced = latestFormulations.filter { it.status == "🟢 معتمدة للإنتاج" || it.status.contains("معتمد") }
                val unproducedFormulasCount = approvedFormulasForUnproduced.count { formula ->
                    allRuns.none { run -> isRunMatchingFormula(run, formula) }
                }
                val adjustedOrdersCount = allAdjustments.map { it.productionOrderId }.distinct().size

                // --- TOP STATISTICS GRID ---
                Text(
                    text = "مؤشرات الأداء الأساسية (KPIs) 📈",
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = textPrimary,
                    modifier = Modifier.padding(top = 4.dp, bottom = 2.dp)
                )

                // Metric Cards Grid Layout (2 columns responsive)
                val chunkedMetrics = listOf(
                    Triple("إجمالي التركيبات الفريدة", "${latestFormulations.size}", GBRBlueMain),
                    Triple("التركيبات المعتمدة", "$approvedFormulasCount", SuccessGreen),
                    Triple("قيد التطوير / مسودة", "$draftFormulasCount", WarningOrange),
                    Triple("أوامر الإنتاج المؤرشفة", "${allRuns.size} أمر", GBRCyanAccent),
                    Triple("إجمالي الوزن الفعلي", "${formatQuantity(totalProducedWeight)} كغم", SuccessGreen),
                    Triple("أصناف تم إنتاجها", "$uniqueProducedCount صنف", GBRPurpleAccent),
                    Triple("أصناف غير منتجة", "$unproducedFormulasCount صنف", textSecondary),
                    Triple("أوامر معدلة أثناء التنفيذ", "$adjustedOrdersCount أمر", GBRPinkAccent)
                ).chunked(2)

                chunkedMetrics.forEach { rowPairs ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        rowPairs.forEach { metric ->
                            Card(
                                modifier = Modifier.weight(1f),
                                shape = RoundedCornerShape(14.dp),
                                colors = CardDefaults.cardColors(containerColor = cardBg),
                                border = BorderStroke(1.dp, borderColor)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(6.dp, 35.dp)
                                            .clip(RoundedCornerShape(3.dp))
                                            .background(metric.third)
                                    )
                                    Spacer(modifier = Modifier.width(10.dp))
                                    Column {
                                        Text(
                                            text = metric.first,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = textSecondary
                                        )
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = metric.second,
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = textPrimary
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // --- REPORT SECTION SELECTOR ---
                Text(
                    text = "فهارس التقارير الشاملة 📂",
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = textPrimary,
                    modifier = Modifier.padding(top = 8.dp)
                )

                // List of 8 reports with click handler
                val reportCards = listOf(
                    Triple("movement", "حركة صنف 📦", "سجل وتتبع حركة واستهلاك الأصناف (مواد خام أو تركيبات)."),
                    Triple("cost", "انحراف التكلفة والمطابقة 📊", "الفروقات والتفاوت بين المواد المخططة والكميات الفعلية المضافة."),
                    Triple("adjustments", "المواد المعدلة أثناء الإنتاج ⚠", "سجل بأوزان المواد الخام المعدلة يدوياً بواسطة مدراء صالة الإنتاج."),
                    Triple("leaderboard", "المنتجات الأكثر إنتاجاً 📈", "ترتيب مبيعات وتشغيل الأصناف حسب عدد الوجبات أو إجمالي الأوزان."),
                    Triple("revisions", "سجل تعديلات التركيبات 📋", "أرشيف كامل للتحديثات التي طرأت على نسب الخلطات والتركيبات."),
                    Triple("qc", "أوامر الإنتاج المفحوصة مخبرياً 🧪", "عرض أوامر الإنتاج التي تشتمل على نتائج واختبارات فحص الجودة الفعلي."),
                    Triple("notes", "التركيبات التي تحتوي ملاحظات تشغيل فنية 📝", "تعليمات وتوجيهات أضيفت إلى التركيبات لتنبيه عمال الصالة أثناء الإنتاج."),
                    Triple("aging", "المنتجات الراكدة (توقف إنتاجها) 📦", "متابعة التركيبات التي تم تغذيتها للمستودعات ولكن لم تنتج منذ وقت طويل.")
                )

                reportCards.forEach { card ->
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { activeReportTab = card.first },
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = cardBg),
                        border = BorderStroke(1.dp, borderColor)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = card.second,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = textPrimary
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = card.third,
                                    fontSize = 11.sp,
                                    color = textSecondary,
                                    lineHeight = 15.sp
                                )
                            }
                            IconButton(onClick = { activeReportTab = card.first }) {
                                Icon(
                                    imageVector = Icons.Default.ArrowBack, // Point to the left in RTL representing enter/exit
                                    contentDescription = "فتح التفاصيل",
                                    tint = GBRBlueMain
                                )
                            }
                        }
                    }
                }
            }
        } else {
            // =========================================================================
            // ACTIVE SUB-VIEW CHANNELS
            // =========================================================================
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f)
            ) {
                when (activeReportTab) {
                    "movement" -> {
                        // 1. ITEM MOVEMENT REPORT (حركة صنف)
                        val context = LocalContext.current
                        val rawMaterialsList by viewModel.rawMaterials.collectAsState()
                        val allProductionOrderItems by viewModel.allProductionOrderItems.collectAsState()
                        val allFormulationItems by viewModel.allFormulationItems.collectAsState()
                        val customPackagingsList by viewModel.customPackagings.collectAsState()
                        val dateFormatter = remember { java.text.SimpleDateFormat("dd/MM/yyyy", java.util.Locale.US) }
                        val dateTimeFormatter = remember { java.text.SimpleDateFormat("dd/MM/yyyy HH:mm", java.util.Locale.US) }

                        // 1) Category selection state: "raw_material" (مادة خام) or "formulation" (تركيبة)
                        var selectedCategory by viewModel.keepState("rep_cat") { mutableStateOf("raw_material") }

                        // 2) Selected Item states
                        var selectedRawMaterial by viewModel.keepState("rep_raw") { mutableStateOf<RawMaterial?>(null) }
                        var selectedMovementFormula by viewModel.keepState("rep_formula") { mutableStateOf<Formulation?>(null) }
                        var showItemSelectDialog by remember { mutableStateOf(false) }
                        var itemSearchInDialog by remember { mutableStateOf("") }

                        // 3) Date Range Filter states
                        var fromDateMillis by viewModel.keepState("rep_from") { mutableStateOf<Long?>(null) }
                        var toDateMillis by viewModel.keepState("rep_to") { mutableStateOf<Long?>(null) }

                        // 4) Packaging Type Filter state (for formulations)
                        var selectedPackagingType by viewModel.keepState("rep_pack") { mutableStateOf("الكل") }
                        var showPackagingDropdown by remember { mutableStateOf(false) }

                        // 5) Apply State: Don't display data until user selects options and clicks Apply!
                        var hasApplied by viewModel.keepState("rep_applied") { mutableStateOf(false) }
                        var isPreparingReport by remember { mutableStateOf(false) }
                        val reportCoroutineScope = rememberCoroutineScope()

                        // Filter active raw materials
                        val activeRawMaterials = remember(rawMaterialsList) {
                            rawMaterialsList.filter { it.isActive }.sortedBy { it.name }
                        }

                        // Filter approved formulations ONLY
                        val approvedFormulations = remember(latestFormulations) {
                            latestFormulations.filter { formula ->
                                formula.name.trim().isNotBlank() &&
                                formula.code.trim().isNotBlank() &&
                                (formula.status.contains("معتمد") || formula.status.contains("معتمدة") ||
                                (!formula.status.contains("تطوير") && !formula.status.contains("مسودة")))
                            }.sortedBy { it.name }
                        }

                        // Extract list of packaging names specifically used for the selected formulation (or all approved formulations)
                        val availablePackagingTypes = remember(customPackagingsList, productionOrdersList, selectedMovementFormula, approvedFormulations) {
                            val set = LinkedHashSet<String>()
                            set.add("الكل")

                            val formulaOrders = if (selectedMovementFormula != null) {
                                productionOrdersList.filter { order ->
                                    order.formulationId == selectedMovementFormula!!.id ||
                                    order.formulationName.trim().equals(selectedMovementFormula!!.name.trim(), ignoreCase = true)
                                }
                            } else {
                                productionOrdersList.filter { order ->
                                    val runFormula = approvedFormulations.firstOrNull { it.id == order.formulationId || it.name.equals(order.formulationName, ignoreCase = true) }
                                    runFormula != null || approvedFormulations.any { it.name.equals(order.formulationName, ignoreCase = true) }
                                }
                            }

                            // Collect package names with filled count > 0 for this formulation
                            formulaOrders.forEach { order ->
                                if (!order.actualPackagingJson.isNullOrBlank()) {
                                    try {
                                        val arr = org.json.JSONArray(order.actualPackagingJson)
                                        for (i in 0 until arr.length()) {
                                            val obj = arr.getJSONObject(i)
                                            val pName = obj.optString("name").ifBlank { obj.optString("size") }.ifBlank { obj.optString("packageName") }.trim()
                                            val count = obj.optInt("actualCount", obj.optInt("count", 0))
                                            if (pName.isNotBlank() && count > 0) {
                                                set.add(pName)
                                            }
                                        }
                                    } catch (e: Exception) {
                                        e.printStackTrace()
                                    }
                                }
                            }

                            // Fallback: if no packages with count > 0 found yet, collect any package names in actualPackagingJson for these orders
                            if (set.size == 1 && formulaOrders.isNotEmpty()) {
                                formulaOrders.forEach { order ->
                                    if (!order.actualPackagingJson.isNullOrBlank()) {
                                        try {
                                            val arr = org.json.JSONArray(order.actualPackagingJson)
                                            for (i in 0 until arr.length()) {
                                                val obj = arr.getJSONObject(i)
                                                val pName = obj.optString("name").ifBlank { obj.optString("size") }.ifBlank { obj.optString("packageName") }.trim()
                                                if (pName.isNotBlank()) set.add(pName)
                                            }
                                        } catch (e: Exception) { }
                                    }
                                }
                            }

                            if (selectedMovementFormula == null && set.size == 1) {
                                customPackagingsList.forEach { pkg ->
                                    if (pkg.name.isNotBlank()) set.add(pkg.name.trim())
                                }
                            }

                            set.toList()
                        }

                        // Reset selected packaging type if it is no longer available in the updated dropdown options
                        LaunchedEffect(selectedMovementFormula, availablePackagingTypes) {
                            if (selectedPackagingType != "الكل" && !availablePackagingTypes.contains(selectedPackagingType)) {
                                selectedPackagingType = "الكل"
                            }
                        }

                        // Map production orders by ID for fast lookup
                        val ordersById = remember(productionOrdersList) {
                            productionOrdersList.associateBy { it.id }
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .verticalScroll(rememberScrollState())
                        ) {
                            // -------------------------------------------------------------
                            // CONTROL PANEL: Category, Item, Date Range & Packaging Filters
                            // -------------------------------------------------------------
                            Card(
                                modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                                colors = CardDefaults.cardColors(containerColor = cardBg),
                                border = BorderStroke(1.dp, borderColor),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {

                                    // Row 1: Category Selection ("اختيار الفئة:")
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text("اختيار الفئة:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                            FilterChip(
                                                selected = selectedCategory == "raw_material",
                                                onClick = {
                                                    if (selectedCategory != "raw_material") {
                                                        selectedCategory = "raw_material"
                                                        selectedRawMaterial = null
                                                        selectedMovementFormula = null
                                                        hasApplied = false
                                                    }
                                                },
                                                label = { Text("🧪 مادة خام", fontSize = 11.sp, fontWeight = FontWeight.Bold) },
                                                colors = FilterChipDefaults.filterChipColors(
                                                    selectedContainerColor = GBRBlueMain,
                                                    selectedLabelColor = Color.White
                                                )
                                            )
                                            FilterChip(
                                                selected = selectedCategory == "formulation",
                                                onClick = {
                                                    if (selectedCategory != "formulation") {
                                                        selectedCategory = "formulation"
                                                        selectedRawMaterial = null
                                                        selectedMovementFormula = null
                                                        hasApplied = false
                                                    }
                                                },
                                                label = { Text("📦 تركيبة", fontSize = 11.sp, fontWeight = FontWeight.Bold) },
                                                colors = FilterChipDefaults.filterChipColors(
                                                    selectedContainerColor = GBRBlueMain,
                                                    selectedLabelColor = Color.White
                                                )
                                            )
                                        }
                                    }

                                    HorizontalDivider(color = borderColor.copy(alpha = 0.5f))

                                    // Row 2: Item Selection ("الصنف:")
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text("الصنف:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                        OutlinedButton(
                                            onClick = {
                                                itemSearchInDialog = ""
                                                showItemSelectDialog = true
                                            },
                                            shape = RoundedCornerShape(8.dp),
                                            border = BorderStroke(1.dp, GBRBlueMain),
                                            contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp)
                                        ) {
                                            val itemLabel = if (selectedCategory == "raw_material") {
                                                if (selectedRawMaterial == null) "الكل (جميع المواد الخام الفعالة) 🧪 🔽" else "${selectedRawMaterial!!.name} 🔽"
                                            } else {
                                                if (selectedMovementFormula == null) "الكل (جميع التركيبات المعتمدة) 📦 🔽" else "${selectedMovementFormula!!.name} (${selectedMovementFormula!!.code}) 🔽"
                                            }
                                            Text(itemLabel, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                        }
                                    }

                                    // Row 3: Date Range Filter ("الفترة:")
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        OutlinedButton(
                                            onClick = {
                                                val calendar = java.util.Calendar.getInstance()
                                                if (fromDateMillis != null) calendar.timeInMillis = fromDateMillis!!
                                                android.app.DatePickerDialog(
                                                    context,
                                                    { _, year, month, dayOfMonth ->
                                                        val cal = java.util.Calendar.getInstance()
                                                        cal.set(java.util.Calendar.YEAR, year)
                                                        cal.set(java.util.Calendar.MONTH, month)
                                                        cal.set(java.util.Calendar.DAY_OF_MONTH, dayOfMonth)
                                                        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)
                                                        cal.set(java.util.Calendar.MINUTE, 0)
                                                        cal.set(java.util.Calendar.SECOND, 0)
                                                        cal.set(java.util.Calendar.MILLISECOND, 0)
                                                        fromDateMillis = cal.timeInMillis
                                                    },
                                                    calendar.get(java.util.Calendar.YEAR),
                                                    calendar.get(java.util.Calendar.MONTH),
                                                    calendar.get(java.util.Calendar.DAY_OF_MONTH)
                                                ).apply {
                                                    if (toDateMillis != null) datePicker.maxDate = toDateMillis!!
                                                }.show()
                                            },
                                            modifier = Modifier.weight(1f),
                                            shape = RoundedCornerShape(8.dp),
                                            contentPadding = PaddingValues(horizontal = 4.dp, vertical = 2.dp),
                                            border = BorderStroke(1.dp, if (fromDateMillis != null) GBRBlueMain else borderColor),
                                            colors = ButtonDefaults.outlinedButtonColors(
                                                contentColor = if (fromDateMillis != null) GBRBlueMain else textSecondary
                                            )
                                        ) {
                                            val text = if (fromDateMillis != null) "من: " + dateFormatter.format(java.util.Date(fromDateMillis!!)) else "من تاريخ 📅"
                                            Text(text, fontSize = 11.sp, fontWeight = FontWeight.Medium)
                                        }

                                        OutlinedButton(
                                            onClick = {
                                                val calendar = java.util.Calendar.getInstance()
                                                if (toDateMillis != null) calendar.timeInMillis = toDateMillis!!
                                                android.app.DatePickerDialog(
                                                    context,
                                                    { _, year, month, dayOfMonth ->
                                                        val cal = java.util.Calendar.getInstance()
                                                        cal.set(java.util.Calendar.YEAR, year)
                                                        cal.set(java.util.Calendar.MONTH, month)
                                                        cal.set(java.util.Calendar.DAY_OF_MONTH, dayOfMonth)
                                                        cal.set(java.util.Calendar.HOUR_OF_DAY, 23)
                                                        cal.set(java.util.Calendar.MINUTE, 59)
                                                        cal.set(java.util.Calendar.SECOND, 59)
                                                        cal.set(java.util.Calendar.MILLISECOND, 999)
                                                        toDateMillis = cal.timeInMillis
                                                    },
                                                    calendar.get(java.util.Calendar.YEAR),
                                                    calendar.get(java.util.Calendar.MONTH),
                                                    calendar.get(java.util.Calendar.DAY_OF_MONTH)
                                                ).apply {
                                                    if (fromDateMillis != null) datePicker.minDate = fromDateMillis!!
                                                }.show()
                                            },
                                            modifier = Modifier.weight(1f),
                                            shape = RoundedCornerShape(8.dp),
                                            contentPadding = PaddingValues(horizontal = 4.dp, vertical = 2.dp),
                                            border = BorderStroke(1.dp, if (toDateMillis != null) GBRBlueMain else borderColor),
                                            colors = ButtonDefaults.outlinedButtonColors(
                                                contentColor = if (toDateMillis != null) GBRBlueMain else textSecondary
                                            )
                                        ) {
                                            val text = if (toDateMillis != null) "إلى: " + dateFormatter.format(java.util.Date(toDateMillis!!)) else "إلى تاريخ 📅"
                                            Text(text, fontSize = 11.sp, fontWeight = FontWeight.Medium)
                                        }

                                        if (fromDateMillis != null || toDateMillis != null) {
                                            IconButton(
                                                onClick = {
                                                    fromDateMillis = null
                                                    toDateMillis = null
                                                },
                                                modifier = Modifier.size(32.dp)
                                            ) {
                                                Icon(Icons.Default.Clear, contentDescription = "مسح التاريخ", tint = GBRPinkAccent)
                                            }
                                        }
                                    }

                                    // Row 4: Packaging Type Filter (Shown if category is formulation)
                                    if (selectedCategory == "formulation") {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text("نوع العبوة للتصفية:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                            Box {
                                                OutlinedButton(
                                                    onClick = { showPackagingDropdown = true },
                                                    shape = RoundedCornerShape(8.dp),
                                                    border = BorderStroke(1.dp, if (selectedPackagingType != "الكل") SuccessGreen else borderColor),
                                                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp)
                                                ) {
                                                    Text("نوع العبوة: $selectedPackagingType 🔽", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (selectedPackagingType != "الكل") SuccessGreen else textPrimary)
                                                }
                                                DropdownMenu(
                                                    expanded = showPackagingDropdown,
                                                    onDismissRequest = { showPackagingDropdown = false }
                                                ) {
                                                    availablePackagingTypes.forEach { pkgName ->
                                                        DropdownMenuItem(
                                                            text = { Text(pkgName, fontSize = 12.sp, fontWeight = if (pkgName == selectedPackagingType) FontWeight.Bold else FontWeight.Normal) },
                                                            onClick = {
                                                                selectedPackagingType = pkgName
                                                                showPackagingDropdown = false
                                                            }
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    // Row 5: Apply Button ("تطبيق")
                                    Button(
                                        onClick = {
                                            isPreparingReport = true
                                            reportCoroutineScope.launch {
                                                kotlinx.coroutines.delay(800L)
                                                hasApplied = true
                                                isPreparingReport = false
                                            }
                                        },
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(8.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                                    ) {
                                        Icon(Icons.Default.Check, contentDescription = null, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text("تطبيق التقرير 📊", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }

                            // Processing Loading Popup
                            if (isPreparingReport) {
                                androidx.compose.ui.window.Dialog(
                                    onDismissRequest = {},
                                    properties = androidx.compose.ui.window.DialogProperties(
                                        dismissOnBackPress = false,
                                        dismissOnClickOutside = false
                                    )
                                ) {
                                    Card(
                                        shape = RoundedCornerShape(20.dp),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, GBRBlueMain.copy(alpha = 0.3f)),
                                        elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
                                    ) {
                                        Column(
                                            modifier = Modifier.padding(28.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.spacedBy(16.dp)
                                        ) {
                                            Box(
                                                modifier = Modifier.size(64.dp),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                CircularProgressIndicator(
                                                    modifier = Modifier.size(56.dp),
                                                    color = GBRBlueMain,
                                                    strokeWidth = 4.dp
                                                )
                                                Icon(
                                                    imageVector = Icons.Default.Analytics,
                                                    contentDescription = null,
                                                    tint = GBRBlueMain,
                                                    modifier = Modifier.size(26.dp)
                                                )
                                            }

                                            Text(
                                                text = "جاري المعالجة...",
                                                fontSize = 16.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = textPrimary
                                            )

                                            Text(
                                                text = "يرجى الانتظار بينما يتم تحضير وتحليل بيانات حركة الصنف بالكامل...",
                                                fontSize = 12.sp,
                                                color = textSecondary,
                                                textAlign = TextAlign.Center
                                            )
                                        }
                                    }
                                }
                            }

                            // -------------------------------------------------------------
                            // REPORT BODY DISPLAY
                            // -------------------------------------------------------------
                            if (!hasApplied) {
                                // INITIAL UNAPPLIED STATE CARD
                                Card(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 20.dp),
                                    colors = CardDefaults.cardColors(containerColor = cardBg),
                                    border = BorderStroke(1.dp, borderColor),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(24.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(56.dp)
                                                .clip(CircleShape)
                                                .background(GBRBlueMain.copy(alpha = 0.1f)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Icon(Icons.Default.Assessment, contentDescription = null, tint = GBRBlueMain, modifier = Modifier.size(32.dp))
                                        }
                                        Text("تخصيص تقرير حركة الصنف", fontSize = 15.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                        Text(
                                            text = if (selectedCategory == "raw_material") {
                                                "الرجاء اختيار المادة الخام والفترة الزمنية من الخيارات أعلاه، ثم الضغط على زر 'تطبيق التقرير' لعرض جدول استخدام المادة في أوامر الإنتاج والنتائج الإجمالية."
                                            } else {
                                                "الرجاء اختيار التركيبة المعتمدة ونوع العبوة والفترة الزمنية من الخيارات أعلاه، ثم الضغط على زر 'تطبيق التقرير' لعرض سجل حركة الإنتاج والنتائج الإجمالية."
                                            },
                                            fontSize = 12.sp,
                                            color = textSecondary,
                                            textAlign = TextAlign.Center
                                        )
                                    }
                                }
                            } else if (selectedCategory == "raw_material") {
                                // =========================================================
                                // CATEGORY: RAW MATERIAL USAGE REPORT
                                // =========================================================
                                val rawMaterialUsages = remember(productionOrdersList, allProductionOrderItems, allFormulationItems, selectedRawMaterial, fromDateMillis, toDateMillis) {
                                    val usageList = mutableListOf<RawMaterialUsageItem>()
                                    val completedOrders = productionOrdersList.filter { it.status == "مكتمل" }

                                    completedOrders.forEach { order ->
                                        val orderTime = if (order.endTime > 0L) order.endTime else order.createdAt
                                        val dateFromMatch = fromDateMillis == null || orderTime >= fromDateMillis!!
                                        val dateToMatch = toDateMillis == null || orderTime <= toDateMillis!!

                                        if (dateFromMatch && dateToMatch) {
                                            val orderItems = allProductionOrderItems.filter { it.productionOrderId == order.id }

                                            if (orderItems.isNotEmpty()) {
                                                orderItems.forEach { pItem ->
                                                    val matchesMat = if (selectedRawMaterial == null) true
                                                    else pItem.rawMaterialId == selectedRawMaterial!!.id || pItem.rawMaterialName.equals(selectedRawMaterial!!.name, ignoreCase = true)

                                                    if (matchesMat) {
                                                        val qtyKg = if (pItem.calculatedQuantity > 0) pItem.calculatedQuantity
                                                        else (order.requiredWeightKg * pItem.quantityMultiplier) / 1000.0

                                                        usageList.add(
                                                            RawMaterialUsageItem(
                                                                orderId = order.id,
                                                                orderNumber = order.orderNumber,
                                                                batchNumber = order.batchNumber,
                                                                formulationName = order.formulationName,
                                                                rawMaterialName = pItem.rawMaterialName,
                                                                quantityKg = qtyKg,
                                                                timestamp = orderTime,
                                                                operatorName = order.operatorName.ifBlank { "المشرف" }
                                                            )
                                                        )
                                                    }
                                                }
                                            } else {
                                                val fItems = allFormulationItems.filter { it.formulationId == order.formulationId }
                                                fItems.forEach { fItem ->
                                                    val matchesMat = if (selectedRawMaterial == null) true
                                                    else fItem.rawMaterialId == selectedRawMaterial!!.id

                                                    if (matchesMat) {
                                                        val matName = activeRawMaterials.firstOrNull { it.id == fItem.rawMaterialId }?.name ?: selectedRawMaterial?.name ?: "مادة خام"
                                                        val qtyKg = (order.requiredWeightKg * fItem.quantityMultiplier) / 1000.0

                                                        usageList.add(
                                                            RawMaterialUsageItem(
                                                                orderId = order.id,
                                                                orderNumber = order.orderNumber,
                                                                batchNumber = order.batchNumber,
                                                                formulationName = order.formulationName,
                                                                rawMaterialName = matName,
                                                                quantityKg = qtyKg,
                                                                timestamp = orderTime,
                                                                operatorName = order.operatorName.ifBlank { "المشرف" }
                                                            )
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    usageList.sortedBy { it.timestamp }
                                }

                                val totalMaterialKg = rawMaterialUsages.sumOf { it.quantityKg }
                                val distinctOrdersCount = rawMaterialUsages.map { it.orderId }.distinct().size
                                val distinctFormulasCount = rawMaterialUsages.map { it.formulationName }.distinct().size

                                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                    Text("سجل استخدام المادة الخام في أوامر الإنتاج 🧪", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)

                                    if (rawMaterialUsages.isEmpty()) {
                                        Card(
                                            modifier = Modifier.fillMaxWidth().padding(vertical = 16.dp),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor)
                                        ) {
                                            Box(modifier = Modifier.padding(24.dp).fillMaxWidth(), contentAlignment = Alignment.Center) {
                                                Text("لا توجد حركة استخدام للمادة الخام المطابقة للخيارات المحددة.", fontSize = 12.sp, color = textSecondary)
                                            }
                                        }
                                    } else {
                                        // TABLE OF RAW MATERIAL USAGE
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor),
                                            shape = RoundedCornerShape(10.dp)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp)) {
                                                // Table Header
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .background(GBRBlueMain.copy(alpha = 0.08f), shape = RoundedCornerShape(6.dp))
                                                        .padding(horizontal = 8.dp, vertical = 8.dp),
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                ) {
                                                    Text("أمر الإنتاج / المنتج", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, modifier = Modifier.weight(1.3f))
                                                    Text("نوع الحركة", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, modifier = Modifier.weight(1.0f))
                                                    Text("الكمية (كجم)", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, modifier = Modifier.weight(0.9f), textAlign = TextAlign.Center)
                                                    Text("التاريخ", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, modifier = Modifier.weight(1.1f), textAlign = TextAlign.End)
                                                }

                                                HorizontalDivider(modifier = Modifier.padding(vertical = 6.dp), color = borderColor)

                                                // Table Content Rows
                                                rawMaterialUsages.forEachIndexed { idx, usage ->
                                                    val matchingOrder = ordersById[usage.orderId] ?: productionOrdersList.find { it.id == usage.orderId || it.orderNumber == usage.orderNumber }
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clickable(enabled = matchingOrder != null) {
                                                                if (matchingOrder != null) {
                                                                    viewModel.orderOpeningSourceSegment.value = "reports"
                                                                    viewModel.activeSegment.value = "production"
                                                                    viewModel.selectedProductionOrder.value = matchingOrder
                                                                }
                                                            }
                                                            .padding(horizontal = 8.dp, vertical = 6.dp),
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                    ) {
                                                        Column(modifier = Modifier.weight(1.3f)) {
                                                            Text(usage.orderNumber, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                            Text(usage.formulationName, fontSize = 10.sp, color = textSecondary)
                                                        }
                                                        Text(usage.movementType, fontSize = 11.sp, fontWeight = FontWeight.Medium, color = textPrimary, modifier = Modifier.weight(1.0f), maxLines = 1, overflow = TextOverflow.Ellipsis)
                                                        Text("${formatQuantity(usage.quantityKg)} كجم", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = SuccessGreen, modifier = Modifier.weight(0.9f), textAlign = TextAlign.Center)
                                                        Text(
                                                            text = dateFormatter.format(java.util.Date(usage.timestamp)),
                                                            fontSize = 11.sp,
                                                            fontWeight = FontWeight.Medium,
                                                            color = textPrimary,
                                                            modifier = Modifier.weight(1.1f),
                                                            textAlign = TextAlign.End
                                                        )
                                                    }
                                                    if (idx < rawMaterialUsages.size - 1) {
                                                        HorizontalDivider(color = borderColor.copy(alpha = 0.3f))
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    // SUMMARY RESULTS CARD (النتائج الإجمالية)
                                    Card(
                                        modifier = Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 16.dp),
                                        colors = CardDefaults.cardColors(containerColor = GBRBlueMain.copy(alpha = 0.05f)),
                                        border = BorderStroke(1.dp, GBRBlueMain.copy(alpha = 0.3f)),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp)) {
                                            Text("📊 النتائج الإجمالية لما هو متاح بالتقرير:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, modifier = Modifier.padding(bottom = 10.dp))
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                                                    Text("إجمالي الكمية المستخدمة", fontSize = 10.sp, color = textSecondary)
                                                    Text("${formatQuantity(totalMaterialKg)} كجم", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = SuccessGreen)
                                                }
                                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                                                    Text("عدد أوامر الإنتاج", fontSize = 10.sp, color = textSecondary)
                                                    Text("$distinctOrdersCount أمر", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                                }
                                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                                                    Text("عدد التركيبات", fontSize = 10.sp, color = textSecondary)
                                                    Text("$distinctFormulasCount تركيبة", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                                                }
                                            }
                                        }
                                    }
                                }
                            } else {
                                // =========================================================
                                // CATEGORY: FORMULATION PRODUCTION MOVEMENT REPORT
                                // =========================================================
                                val baseFilteredRuns = remember(allRuns, approvedFormulations, selectedMovementFormula, fromDateMillis, toDateMillis) {
                                    allRuns.filter { run ->
                                        val runFormula = approvedFormulations.firstOrNull { it.id == run.formulationId || it.name.equals(run.formulationName, ignoreCase = true) }
                                        val isApproved = selectedMovementFormula != null || runFormula != null || approvedFormulations.any { it.name.equals(run.formulationName, ignoreCase = true) }

                                        val productMatch = if (selectedMovementFormula == null) isApproved else isRunMatchingFormula(run, selectedMovementFormula!!)
                                        val dateFromMatch = fromDateMillis == null || run.timestamp >= fromDateMillis!!
                                        val dateToMatch = toDateMillis == null || run.timestamp <= toDateMillis!!
                                        productMatch && dateFromMatch && dateToMatch
                                    }
                                }

                                val baseFilteredOrders = remember(baseFilteredRuns, ordersById) {
                                    baseFilteredRuns.mapNotNull { run -> ordersById[run.id] }
                                }

                                // Overall packaging breakdown for the selected formula and date range
                                val packagingBreakdown = remember(baseFilteredOrders) {
                                    val countsByPkg = mutableMapOf<String, Int>()
                                    baseFilteredOrders.forEach { order ->
                                        if (!order.actualPackagingJson.isNullOrBlank()) {
                                            try {
                                                val arr = org.json.JSONArray(order.actualPackagingJson)
                                                for (i in 0 until arr.length()) {
                                                    val obj = arr.getJSONObject(i)
                                                    val pName = obj.optString("name").ifBlank { obj.optString("size") }.ifBlank { obj.optString("packageName") }.ifBlank { "عبوة عامة" }.trim()
                                                    val count = obj.optInt("actualCount", obj.optInt("count", 0))
                                                    if (count > 0) {
                                                        countsByPkg[pName] = (countsByPkg[pName] ?: 0) + count
                                                    }
                                                }
                                            } catch (e: Exception) {
                                                e.printStackTrace()
                                            }
                                        }
                                    }
                                    countsByPkg
                                }

                                // Filter runs by the selected packaging type
                                val filteredRuns = remember(baseFilteredRuns, selectedPackagingType, ordersById, productionOrdersList) {
                                    if (selectedPackagingType == "الكل") {
                                        baseFilteredRuns
                                    } else {
                                        baseFilteredRuns.filter { run ->
                                            val matchingOrder = ordersById[run.id] ?: productionOrdersList.find { it.orderNumber.equals(run.referenceNumber, ignoreCase = true) || it.id == run.id }
                                            if (matchingOrder != null && !matchingOrder.actualPackagingJson.isNullOrBlank()) {
                                                var matchesPkg = false
                                                try {
                                                    val arr = org.json.JSONArray(matchingOrder.actualPackagingJson)
                                                    for (i in 0 until arr.length()) {
                                                        val obj = arr.getJSONObject(i)
                                                        val pName = obj.optString("name").ifBlank { obj.optString("size") }.ifBlank { obj.optString("packageName") }.trim()
                                                        val count = obj.optInt("actualCount", obj.optInt("count", 0))
                                                        if (count > 0 && (pName.equals(selectedPackagingType, ignoreCase = true) || pName.contains(selectedPackagingType, ignoreCase = true))) {
                                                            matchesPkg = true
                                                            break
                                                        }
                                                    }
                                                } catch (e: Exception) {
                                                    e.printStackTrace()
                                                }
                                                matchesPkg
                                            } else {
                                                false
                                            }
                                        }
                                    }
                                }

                                val filteredOrders = remember(filteredRuns, ordersById) {
                                    filteredRuns.mapNotNull { run -> ordersById[run.id] }
                                }

                                val stats = remember(filteredOrders, selectedPackagingType) {
                                    var totalWeight = 0.0
                                    var totalPackageCount = 0

                                    filteredOrders.forEach { order ->
                                        totalWeight += order.requiredWeightKg
                                        if (!order.actualPackagingJson.isNullOrBlank()) {
                                            try {
                                                val arr = org.json.JSONArray(order.actualPackagingJson)
                                                for (i in 0 until arr.length()) {
                                                    val obj = arr.getJSONObject(i)
                                                    val pName = obj.optString("name").ifBlank { obj.optString("size") }.ifBlank { obj.optString("packageName") }.ifBlank { "عبوة عامة" }.trim()
                                                    val count = obj.optInt("actualCount", obj.optInt("count", 0))
                                                    if (count > 0) {
                                                        if (selectedPackagingType == "الكل" || pName.equals(selectedPackagingType, ignoreCase = true) || pName.contains(selectedPackagingType, ignoreCase = true)) {
                                                            totalPackageCount += count
                                                        }
                                                    }
                                                }
                                            } catch (e: Exception) {
                                                e.printStackTrace()
                                            }
                                        }
                                    }

                                    Pair(totalWeight, totalPackageCount)
                                }

                                val (totalWeightKg, totalFilledCount) = stats

                                Column {
                                    // STATS CARDS
                                    Row(
                                        modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                                Text("أوامر الإنتاج", fontSize = 10.sp, color = textSecondary)
                                                Text("${filteredRuns.size} أمر", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                            }
                                        }

                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                                Text("إجمالي الأوزان", fontSize = 10.sp, color = textSecondary)
                                                Text("${formatQuantity(totalWeightKg / 1000.0)} طن", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = SuccessGreen)
                                            }
                                        }

                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, if (selectedPackagingType != "الكل") SuccessGreen else borderColor)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                                Text(if (selectedPackagingType == "الكل") "إجمالي العبوات" else "عبوات ($selectedPackagingType)", fontSize = 10.sp, color = textSecondary, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                                Text("$totalFilledCount عبوة", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = if (selectedPackagingType != "الكل") SuccessGreen else GBRDarkIndigo)
                                            }
                                        }
                                    }

                                    // Packaging Breakdown Badges
                                    if (packagingBreakdown.isNotEmpty()) {
                                        Card(
                                            modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor)
                                        ) {
                                            Column(modifier = Modifier.padding(10.dp)) {
                                                Text("تفصيل العبوات المعبأة بالفترة والمنتج المختار:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary, modifier = Modifier.padding(bottom = 6.dp))
                                                Row(
                                                    modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                                ) {
                                                    packagingBreakdown.forEach { (pName, pCount) ->
                                                        Surface(
                                                            modifier = Modifier.clickable {
                                                                selectedPackagingType = if (selectedPackagingType == pName) "الكل" else pName
                                                            },
                                                            shape = RoundedCornerShape(16.dp),
                                                            color = if (selectedPackagingType == pName) SuccessGreen.copy(alpha = 0.15f) else GBRBlueMain.copy(alpha = 0.08f),
                                                            border = BorderStroke(1.dp, if (selectedPackagingType == pName) SuccessGreen else GBRBlueMain.copy(alpha = 0.3f))
                                                        ) {
                                                            Row(
                                                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
                                                                verticalAlignment = Alignment.CenterVertically,
                                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                                            ) {
                                                                Text("$pName:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                                Text("$pCount عبوة", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    // DETAILED MOVEMENTS LIST
                                    Row(
                                        modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text("سجل حركة أوامر الإنتاج ⏱", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                        Text("العدد: ${filteredRuns.size}", fontSize = 11.sp, color = textSecondary)
                                    }

                                    Column(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        if (filteredRuns.isEmpty()) {
                                            Box(
                                                modifier = Modifier.fillMaxWidth().padding(40.dp),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text("لا توجد حركة إنتاج مطابقة للخيارات المحددة.", fontSize = 12.sp, color = textSecondary)
                                            }
                                        } else {
                                            filteredRuns.forEachIndexed { index, run ->
                                                val dateStr = dateFormatter.format(java.util.Date(run.timestamp))
                                                val matchingOrder = ordersById[run.id] ?: productionOrdersList.find { it.orderNumber.equals(run.referenceNumber, ignoreCase = true) || it.id == run.id }

                                                val runPackList = remember(matchingOrder) {
                                                    val packInfoList = mutableListOf<String>()
                                                    if (matchingOrder != null && !matchingOrder.actualPackagingJson.isNullOrBlank()) {
                                                        try {
                                                            val arr = org.json.JSONArray(matchingOrder.actualPackagingJson)
                                                            for (i in 0 until arr.length()) {
                                                                val obj = arr.getJSONObject(i)
                                                                val pName = obj.optString("name").ifBlank { obj.optString("size") }.ifBlank { obj.optString("packageName") }.trim()
                                                                val count = obj.optInt("actualCount", obj.optInt("count", 0))
                                                                if (count > 0) {
                                                                    packInfoList.add("$pName: $count عبوة")
                                                                }
                                                            }
                                                        } catch (e: Exception) {
                                                            e.printStackTrace()
                                                        }
                                                    }
                                                    packInfoList
                                                }

                                                Card(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .clickable(enabled = matchingOrder != null) {
                                                            if (matchingOrder != null) {
                                                                viewModel.orderOpeningSourceSegment.value = "reports"
                                                                viewModel.activeSegment.value = "production"
                                                                viewModel.selectedProductionOrder.value = matchingOrder
                                                            }
                                                        },
                                                    colors = CardDefaults.cardColors(containerColor = cardBg),
                                                    border = BorderStroke(1.dp, borderColor)
                                                ) {
                                                    Column(modifier = Modifier.padding(12.dp)) {
                                                        Row(
                                                            modifier = Modifier.fillMaxWidth(),
                                                            horizontalArrangement = Arrangement.SpaceBetween,
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                            Column(modifier = Modifier.weight(1f)) {
                                                                Text(run.formulationName, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                                Text(
                                                                    text = "أمر إنتاج: ${if (run.referenceNumber.isNotBlank()) run.referenceNumber else matchingOrder?.orderNumber ?: "#${filteredRuns.size - index}"}",
                                                                    fontSize = 11.sp,
                                                                    fontWeight = FontWeight.SemiBold,
                                                                    color = textSecondary
                                                                )
                                                                Text(
                                                                    text = "التاريخ: $dateStr",
                                                                    fontSize = 10.sp,
                                                                    color = textSecondary
                                                                )
                                                            }
                                                            Row(
                                                                verticalAlignment = Alignment.CenterVertically,
                                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                            ) {
                                                                Text("${formatQuantity(run.batchWeightKg)} كغم", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                                                if (matchingOrder != null) {
                                                                    Icon(
                                                                        imageVector = Icons.Default.ChevronLeft,
                                                                        contentDescription = "عرض أمر الإنتاج",
                                                                        tint = GBRBlueMain,
                                                                        modifier = Modifier.size(20.dp)
                                                                    )
                                                                }
                                                            }
                                                        }

                                                        if (runPackList.isNotEmpty()) {
                                                            HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp), color = borderColor.copy(alpha = 0.5f))
                                                            Row(
                                                                modifier = Modifier.fillMaxWidth(),
                                                                verticalAlignment = Alignment.CenterVertically,
                                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                            ) {
                                                                Text("📦 التعبئة:", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = textSecondary)
                                                                Text(runPackList.joinToString(" | "), fontSize = 11.sp, fontWeight = FontWeight.Medium, color = SuccessGreen)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    // SUMMARY RESULTS CARD (النتائج الإجمالية)
                                    Card(
                                        modifier = Modifier.fillMaxWidth().padding(top = 12.dp, bottom = 16.dp),
                                        colors = CardDefaults.cardColors(containerColor = GBRBlueMain.copy(alpha = 0.05f)),
                                        border = BorderStroke(1.dp, GBRBlueMain.copy(alpha = 0.3f)),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp)) {
                                            Text("📊 النتائج الإجمالية لما هو متاح بالتقرير:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain, modifier = Modifier.padding(bottom = 10.dp))
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                                                    Text("إجمالي الأوزان المصنعة", fontSize = 10.sp, color = textSecondary)
                                                    Text("${formatQuantity(totalWeightKg / 1000.0)} طن", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = SuccessGreen)
                                                }
                                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                                                    Text("إجمالي العبوات المعبأة", fontSize = 10.sp, color = textSecondary)
                                                    Text("$totalFilledCount عبوة", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                                }
                                                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                                                    Text("إجمالي عدد الأوامر", fontSize = 10.sp, color = textSecondary)
                                                    Text("${filteredRuns.size} أمر", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // -------------------------------------------------------------
                        // UNIFIED ITEM SELECTION DIALOG (Raw Material / Formulation)
                        // -------------------------------------------------------------
                        if (showItemSelectDialog) {
                            AlertDialog(
                                onDismissRequest = { showItemSelectDialog = false },
                                title = {
                                    val dialogTitle = if (selectedCategory == "raw_material") "اختر المادة الخام لمتابعة الحركة" else "اختر التركيبة لمتابعة الحركة"
                                    Text(dialogTitle, fontSize = 15.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                },
                                text = {
                                    Column(modifier = Modifier.fillMaxWidth().heightIn(max = 400.dp)) {
                                        OutlinedTextField(
                                            value = itemSearchInDialog,
                                            onValueChange = { itemSearchInDialog = it },
                                            label = { Text("بحث باسم أو كود الصنف...") },
                                            leadingIcon = { Icon(Icons.Default.Search, contentDescription = null) },
                                            modifier = Modifier.fillMaxWidth().padding(bottom = 10.dp),
                                            colors = OutlinedTextFieldDefaults.colors(
                                                focusedBorderColor = GBRBlueMain,
                                                unfocusedBorderColor = borderColor
                                            )
                                        )

                                        Column(
                                            modifier = Modifier.fillMaxWidth().weight(1f).verticalScroll(rememberScrollState()),
                                            verticalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            if (selectedCategory == "raw_material") {
                                                // --- OPTION 1: ALL RAW MATERIALS ---
                                                Card(
                                                    modifier = Modifier.fillMaxWidth().clickable {
                                                        selectedRawMaterial = null
                                                        showItemSelectDialog = false
                                                        hasApplied = false
                                                    },
                                                    colors = CardDefaults.cardColors(
                                                        containerColor = if (selectedRawMaterial == null) GBRBlueMain.copy(alpha = 0.12f) else cardBg
                                                    ),
                                                    border = BorderStroke(1.dp, if (selectedRawMaterial == null) GBRBlueMain else borderColor)
                                                ) {
                                                    Row(
                                                        modifier = Modifier.padding(12.dp),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Column {
                                                            Text("الكل (جميع المواد الخام الفعالة)", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                            Text("عرض إجمالي حركة كافة المواد الخام بالمصنع", fontSize = 10.sp, color = textSecondary)
                                                        }
                                                        if (selectedRawMaterial == null) {
                                                            Icon(Icons.Default.Check, contentDescription = null, tint = GBRBlueMain)
                                                        }
                                                    }
                                                }

                                                // --- ACTIVE RAW MATERIALS LIST ---
                                                val filteredRawmats = activeRawMaterials.filter {
                                                    it.name.contains(itemSearchInDialog, ignoreCase = true) ||
                                                    it.productionName.contains(itemSearchInDialog, ignoreCase = true)
                                                }

                                                filteredRawmats.forEach { rawMat ->
                                                    val isSelected = selectedRawMaterial?.id == rawMat.id

                                                    Card(
                                                        modifier = Modifier.fillMaxWidth().clickable {
                                                            selectedRawMaterial = rawMat
                                                            showItemSelectDialog = false
                                                            hasApplied = false
                                                        },
                                                        colors = CardDefaults.cardColors(
                                                            containerColor = if (isSelected) GBRBlueMain.copy(alpha = 0.12f) else cardBg
                                                        ),
                                                        border = BorderStroke(1.dp, if (isSelected) GBRBlueMain else borderColor)
                                                    ) {
                                                        Row(
                                                            modifier = Modifier.padding(12.dp),
                                                            horizontalArrangement = Arrangement.SpaceBetween,
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                            Column(modifier = Modifier.weight(1f)) {
                                                                Text(rawMat.name, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                                if (rawMat.productionName.isNotBlank()) {
                                                                    Text("اسم الإنتاج: ${rawMat.productionName}", fontSize = 11.sp, color = textSecondary)
                                                                }
                                                            }
                                                            if (isSelected) {
                                                                Icon(Icons.Default.Check, contentDescription = null, tint = GBRBlueMain)
                                                            }
                                                        }
                                                    }
                                                }
                                            } else {
                                                // --- OPTION 1: ALL APPROVED FORMULATIONS ---
                                                Card(
                                                    modifier = Modifier.fillMaxWidth().clickable {
                                                        selectedMovementFormula = null
                                                        showItemSelectDialog = false
                                                        hasApplied = false
                                                    },
                                                    colors = CardDefaults.cardColors(
                                                        containerColor = if (selectedMovementFormula == null) GBRBlueMain.copy(alpha = 0.12f) else cardBg
                                                    ),
                                                    border = BorderStroke(1.dp, if (selectedMovementFormula == null) GBRBlueMain else borderColor)
                                                ) {
                                                    Row(
                                                        modifier = Modifier.padding(12.dp),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Column {
                                                            Text("الكل (جميع التركيبات المعتمدة)", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                            Text("عرض إجمالي حركة كافة التركيبات المعتمدة للإنتاج", fontSize = 10.sp, color = textSecondary)
                                                        }
                                                        if (selectedMovementFormula == null) {
                                                            Icon(Icons.Default.Check, contentDescription = null, tint = GBRBlueMain)
                                                        }
                                                    }
                                                }

                                                // --- APPROVED FORMULATIONS LIST ---
                                                val dialogFilteredFormulas = approvedFormulations.filter { formula ->
                                                    formula.name.trim().isNotBlank() && formula.code.trim().isNotBlank() &&
                                                    (formula.name.contains(itemSearchInDialog, ignoreCase = true) ||
                                                     formula.code.contains(itemSearchInDialog, ignoreCase = true))
                                                }

                                                dialogFilteredFormulas.forEach { formula ->
                                                    val runsCount = allRuns.count { run -> isRunMatchingFormula(run, formula) }
                                                    val isSelected = selectedMovementFormula?.id == formula.id || selectedMovementFormula?.code == formula.code

                                                    Card(
                                                        modifier = Modifier.fillMaxWidth().clickable {
                                                            selectedMovementFormula = formula
                                                            showItemSelectDialog = false
                                                            hasApplied = false
                                                        },
                                                        colors = CardDefaults.cardColors(
                                                            containerColor = if (isSelected) GBRBlueMain.copy(alpha = 0.12f) else cardBg
                                                        ),
                                                        border = BorderStroke(1.dp, if (isSelected) GBRBlueMain else borderColor)
                                                    ) {
                                                        Row(
                                                            modifier = Modifier.padding(12.dp),
                                                            horizontalArrangement = Arrangement.SpaceBetween,
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                            Column(modifier = Modifier.weight(1f)) {
                                                                Text(formula.name, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                                Text("كود: ${formula.code}", fontSize = 11.sp, color = textSecondary)
                                                            }
                                                            Box(
                                                                modifier = Modifier
                                                                    .clip(RoundedCornerShape(8.dp))
                                                                    .background(GBRBlueMain.copy(alpha = 0.1f))
                                                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                                                            ) {
                                                                Text("$runsCount أمر إنتاج", fontSize = 11.sp, color = GBRBlueMain, fontWeight = FontWeight.Bold)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                },
                                confirmButton = {
                                    TextButton(onClick = { showItemSelectDialog = false }) {
                                        Text("إغلاق", fontWeight = FontWeight.Bold)
                                    }
                                }
                            )
                        }
                    }

                    "cost" -> {
                        // 2. COST DEVIATION REPORT
                        val completedOrders = productionOrdersList.filter { it.status == "مكتمل" || it.status.contains("مكتمل") || it.status.contains("مؤرشف") || it.status == "📦 مؤرشف" }

                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("انحرافات أوزان الخلط بين المخطط والفعلي ⚖", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = textPrimary)

                            if (completedOrders.isEmpty()) {
                                Box(modifier = Modifier.fillMaxWidth().padding(40.dp), contentAlignment = Alignment.Center) {
                                    Text("لا توجد أوامر إنتاج مكتملة حتى الآن للمطابقة والمقارنة.", fontSize = 12.sp, color = textSecondary)
                                }
                            } else {
                                completedOrders.forEach { order ->
                                    val orderAdjustments = allAdjustments.filter { it.productionOrderId == order.id }
                                    val totalDeviationKg = orderAdjustments.sumOf { it.difference }

                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, borderColor)
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp)) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Text("أمر إنتاج: ${order.orderNumber}", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                    Text(order.formulationName, fontSize = 11.sp, color = textSecondary)
                                                }
                                                Box(
                                                    modifier = Modifier
                                                        .clip(RoundedCornerShape(8.dp))
                                                        .background(if (totalDeviationKg != 0.0) GBRPinkAccent.copy(alpha = 0.1f) else SuccessGreen.copy(alpha = 0.1f))
                                                        .padding(horizontal = 8.dp, vertical = 4.dp)
                                                ) {
                                                    Text(
                                                        text = if (totalDeviationKg == 0.0) "مطابق للتركيبة ✔" else "انحراف ${formatQuantity(totalDeviationKg)} كغم",
                                                        fontSize = 11.sp,
                                                        color = if (totalDeviationKg != 0.0) GBRPinkAccent else SuccessGreen,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                }
                                            }

                                            Divider(modifier = Modifier.padding(vertical = 10.dp), color = borderColor)

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text("الوزن المجدول المخطط:", fontSize = 11.sp, color = textSecondary)
                                                Text("${formatQuantity(order.requiredWeightKg)} كجم", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                            }

                                            Row(
                                                modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text("عدد المواد المعدلة بالكامل:", fontSize = 11.sp, color = textSecondary)
                                                Text("${orderAdjustments.size} مادة المعدل", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                            }

                                            if (orderAdjustments.isNotEmpty()) {
                                                Spacer(modifier = Modifier.height(10.dp))
                                                Text("تفاصيل التعديلات التي تمت وتكلفتها:", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                Column(modifier = Modifier.padding(top = 4.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                    orderAdjustments.forEach { adj ->
                                                        Row(
                                                            modifier = Modifier
                                                                .fillMaxWidth()
                                                                .background(if (isDark) Color(0xFF131D31) else Color(0xFFF8FAFC), RoundedCornerShape(8.dp))
                                                                .padding(8.dp),
                                                            horizontalArrangement = Arrangement.SpaceBetween
                                                        ) {
                                                            Text(adj.rawMaterialName, fontSize = 10.sp, color = textPrimary)
                                                            Text(
                                                                text = "${formatQuantity(adj.originalQuantity)} ⬅ ${formatQuantity(adj.newQuantity)} كغم (${if(adj.difference > 0) "+" else ""}${formatQuantity(adj.difference)})",
                                                                fontSize = 10.sp,
                                                                color = if (adj.difference > 0) GBRPinkAccent else SuccessGreen,
                                                                fontWeight = FontWeight.Bold
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    "adjustments" -> {
                        // 3. PRODUCTION ADJUSTMENTS LOG
                        var searchQuery by remember { mutableStateOf("") }
                        val filteredAdjustments = allAdjustments.filter {
                            it.rawMaterialName.contains(searchQuery, ignoreCase = true) || it.userName.contains(searchQuery, ignoreCase = true)
                        }

                        Column(modifier = Modifier.fillMaxSize()) {
                            OutlinedTextField(
                                value = searchQuery,
                                onValueChange = { searchQuery = it },
                                label = { Text("بحث عن المواد الخام أو بمسؤول التعديل") },
                                leadingIcon = { Icon(Icons.Default.Search, contentDescription = null) },
                                modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                                colors = OutlinedTextFieldDefaults.colors(
                                    focusedBorderColor = GBRBlueMain,
                                    unfocusedBorderColor = borderColor
                                )
                            )

                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .weight(1f)
                                    .verticalScroll(rememberScrollState()),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                if (filteredAdjustments.isEmpty()) {
                                    Box(modifier = Modifier.fillMaxWidth().padding(40.dp), contentAlignment = Alignment.Center) {
                                        Text("لا توجد أية تعديلات مضافة مسجلة حتى الآن.", fontSize = 12.sp, color = textSecondary)
                                    }
                                } else {
                                    filteredAdjustments.forEach { adj ->
                                        val formattedDate = java.text.DateFormat.getDateTimeInstance()
                                            .format(java.util.Date(adj.timestamp))

                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor)
                                        ) {
                                            Column(modifier = Modifier.padding(12.dp)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(adj.rawMaterialName, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(8.dp))
                                                            .background(GBRPinkAccent.copy(alpha = 0.12f))
                                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                                    ) {
                                                        Text(
                                                            text = "${if (adj.difference > 0) "+" else ""}${formatQuantity(adj.difference)} كجم",
                                                            fontSize = 11.sp,
                                                            color = GBRPinkAccent,
                                                            fontWeight = FontWeight.Bold
                                                        )
                                                    }
                                                }

                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text("مسؤول الخطوة: ${adj.userName}", fontSize = 11.sp, color = textSecondary)
                                                Text("الوزن: ${formatQuantity(adj.originalQuantity)} كجم ⬅  الوزن الفعلي: ${formatQuantity(adj.newQuantity)} كجم", fontSize = 11.sp, color = textSecondary)

                                                if (adj.reason.trim().isNotEmpty()) {
                                                    Box(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .padding(top = 8.dp)
                                                            .background(if (isDark) Color(0xFF1E293B) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                                                            .padding(8.dp)
                                                    ) {
                                                        Text("سبب التعديل: ${adj.reason}", fontSize = 10.sp, color = textPrimary)
                                                    }
                                                }

                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text("سجل أمر التشغيل: $formattedDate", fontSize = 9.sp, color = textSecondary)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    "leaderboard" -> {
                        // 4. LEADERBOARD OF MOST PRODUCED PRODUCTS
                        var sortByWeight by remember { mutableStateOf(false) }
                        var selectedLeaderboardItem by remember { mutableStateOf<LeaderboardProductItem?>(null) }

                        val leaderboardData = remember(productionOrdersList, formulationsList, sortByWeight) {
                            val validOrders = productionOrdersList.filter { it.status != "ملغي" }
                            
                            val grouped = validOrders.groupBy { order ->
                                val formula = formulationsList.find { it.id == order.formulationId }
                                val code = formula?.code?.trim()?.uppercase() ?: ""
                                val name = formula?.name?.trim() ?: order.formulationName.trim()
                                if (code.isNotBlank()) "CODE_$code" else "NAME_${name.lowercase()}"
                            }

                            grouped.map { (key, orders) ->
                                val sampleOrder = orders.first()
                                val matchingFormula = formulationsList.find { formula ->
                                    formula.id == sampleOrder.formulationId ||
                                    (formula.code.isNotBlank() && key == "CODE_${formula.code.trim().uppercase()}") ||
                                    (key == "NAME_${formula.name.trim().lowercase()}")
                                }

                                val name = matchingFormula?.name ?: sampleOrder.formulationName.ifBlank { "منتج غير مسمى" }
                                val code = matchingFormula?.code ?: ""
                                val fId = matchingFormula?.id ?: sampleOrder.formulationId

                                val completedOrders = orders.filter { it.status == "مكتمل" || it.status.contains("مكتمل") || it.status.contains("مؤرشف") || it.status == "📦 مؤرشف" }
                                val activeSet = if (completedOrders.isNotEmpty()) completedOrders else orders
                                val count = activeSet.size
                                val totalWeight = activeSet.sumOf { it.requiredWeightKg }

                                LeaderboardProductItem(
                                    formulationName = name,
                                    formulationCode = code,
                                    formulationId = fId,
                                    completedOrderCount = count,
                                    totalOrderCount = orders.size,
                                    totalWeightKg = totalWeight,
                                    orders = orders.sortedByDescending { it.createdAt }
                                )
                            }.sortedWith(
                                if (sortByWeight) compareByDescending { it.totalWeightKg }
                                else compareByDescending<LeaderboardProductItem> { it.completedOrderCount }.thenByDescending { it.totalOrderCount }
                            )
                        }

                        Column(modifier = Modifier.fillMaxSize()) {
                            // Sort controllers
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(if (isDark) Color(0xFF131D31) else Color(0xFFF1F5F9), RoundedCornerShape(12.dp))
                                    .padding(4.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Button(
                                    onClick = { sortByWeight = false },
                                    modifier = Modifier.weight(1f),
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (!sortByWeight) GBRBlueMain else Color.Transparent,
                                        contentColor = if (!sortByWeight) Color.White else textPrimary
                                    ),
                                    shape = RoundedCornerShape(8.dp),
                                    elevation = null
                                ) {
                                    Text("حسب أوامر الإنتاج 🔢", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                                Button(
                                    onClick = { sortByWeight = true },
                                    modifier = Modifier.weight(1f),
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (sortByWeight) GBRBlueMain else Color.Transparent,
                                        contentColor = if (sortByWeight) Color.White else textPrimary
                                    ),
                                    shape = RoundedCornerShape(8.dp),
                                    elevation = null
                                ) {
                                    Text("حسب الكميات المنتجة ⚖", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }

                            Spacer(modifier = Modifier.height(14.dp))

                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .weight(1f)
                                    .verticalScroll(rememberScrollState()),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                if (leaderboardData.isEmpty()) {
                                    Box(modifier = Modifier.fillMaxWidth().padding(40.dp), contentAlignment = Alignment.Center) {
                                        Text("لا يوجد سجل أوامر إنتاج لإدراج القائمة المتصدرة.", fontSize = 12.sp, color = textSecondary)
                                    }
                                } else {
                                    leaderboardData.forEachIndexed { idx, item ->
                                        val medal = when (idx) {
                                            0 -> "👑 المركز الأول"
                                            1 -> "🥈 المركز الثاني"
                                            2 -> "🥉 المركز الثالث"
                                            else -> "الترتيب #${idx + 1}"
                                        }
                                        val medalColor = when (idx) {
                                            0 -> WarningOrange
                                            1 -> Color.Gray
                                            2 -> GBRPinkAccent
                                            else -> textSecondary
                                        }

                                        Card(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable { selectedLeaderboardItem = item },
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor)
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(12.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text(medal, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = medalColor)
                                                    Spacer(modifier = Modifier.height(2.dp))
                                                    Text(item.formulationName, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                    if (item.formulationCode.isNotBlank()) {
                                                        Text("كود: ${item.formulationCode}", fontSize = 11.sp, color = textSecondary)
                                                    }
                                                    Text("انقر لعرض أوامر الإنتاج 🔍", fontSize = 10.sp, color = GBRBlueMain, fontWeight = FontWeight.Medium, modifier = Modifier.padding(top = 2.dp))
                                                }

                                                Column(horizontalAlignment = Alignment.End) {
                                                    Text("${item.completedOrderCount} أمر إنتاج", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                                                    Text("${formatQuantity(item.totalWeightKg)} كغم", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = SuccessGreen)
                                                    if (item.totalOrderCount > item.completedOrderCount) {
                                                        Text("إجمالي: ${item.totalOrderCount} أمر", fontSize = 9.sp, color = textSecondary)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Dialog to show production orders for selected formulation
                        if (selectedLeaderboardItem != null) {
                            val item = selectedLeaderboardItem!!
                            AlertDialog(
                                onDismissRequest = { selectedLeaderboardItem = null },
                                shape = RoundedCornerShape(20.dp),
                                containerColor = cardBg,
                                title = {
                                    Column(modifier = Modifier.fillMaxWidth()) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = item.formulationName,
                                                fontSize = 16.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = textPrimary,
                                                modifier = Modifier.weight(1f)
                                            )
                                            IconButton(onClick = { selectedLeaderboardItem = null }, modifier = Modifier.size(24.dp)) {
                                                Icon(imageVector = Icons.Default.Close, contentDescription = "إغلاق", tint = textSecondary)
                                            }
                                        }
                                        if (item.formulationCode.isNotBlank()) {
                                            Text(
                                                text = "كود التركيبة: ${item.formulationCode}",
                                                fontSize = 12.sp,
                                                color = textSecondary
                                            )
                                        }
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(top = 8.dp)
                                                .background(GBRBlueMain.copy(alpha = 0.1f), RoundedCornerShape(8.dp))
                                                .padding(8.dp)
                                        ) {
                                            Text(
                                                text = "عدد أوامر الإنتاج: ${item.orders.size} | إجمالي الوزن: ${formatQuantity(item.totalWeightKg)} كغم",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = GBRBlueMain,
                                                modifier = Modifier.fillMaxWidth(),
                                                textAlign = TextAlign.Center
                                            )
                                        }
                                    }
                                },
                                text = {
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .heightIn(max = 350.dp)
                                            .verticalScroll(rememberScrollState()),
                                        verticalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        item.orders.forEach { order ->
                                            val statusColor = when (order.status) {
                                                "مكتمل" -> SuccessGreen
                                                "قيد التنفيذ" -> GBRBlueMain
                                                "جاهز للتنفيذ" -> WarningOrange
                                                "مسودة" -> Color.Gray
                                                else -> GBRPinkAccent
                                            }
                                            val formattedDate = try {
                                                java.text.SimpleDateFormat("yyyy/MM/dd hh:mm a", java.util.Locale.getDefault()).format(java.util.Date(order.createdAt))
                                            } catch (e: Exception) { "" }

                                            Card(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable {
                                                        viewModel.selectedProductionOrder.value = order
                                                        selectedLeaderboardItem = null
                                                    },
                                                shape = RoundedCornerShape(12.dp),
                                                colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC)),
                                                border = BorderStroke(1.dp, borderColor)
                                            ) {
                                                Column(modifier = Modifier.padding(10.dp)) {
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Column {
                                                            Text(
                                                                text = "أمر إنتاج: ${order.orderNumber}",
                                                                fontSize = 13.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = textPrimary
                                                            )
                                                            if (order.batchNumber.isNotBlank()) {
                                                                Text(
                                                                    text = "الوجبة: ${order.batchNumber}",
                                                                    fontSize = 11.sp,
                                                                    color = textSecondary
                                                                )
                                                            }
                                                        }
                                                        Box(
                                                            modifier = Modifier
                                                                .clip(RoundedCornerShape(6.dp))
                                                                .background(statusColor.copy(alpha = 0.15f))
                                                                .padding(horizontal = 8.dp, vertical = 3.dp)
                                                        ) {
                                                            Text(
                                                                text = order.status,
                                                                fontSize = 11.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = statusColor
                                                            )
                                                        }
                                                    }

                                                    Spacer(modifier = Modifier.height(6.dp))
                                                    Row(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        horizontalArrangement = Arrangement.SpaceBetween
                                                    ) {
                                                        Text(
                                                            text = "الكمية: ${formatQuantity(order.requiredWeightKg)} كغم",
                                                            fontSize = 11.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = SuccessGreen
                                                        )
                                                        Text(
                                                            text = formattedDate,
                                                            fontSize = 10.sp,
                                                            color = textSecondary
                                                        )
                                                    }
                                                    if (order.operatorName.isNotBlank()) {
                                                        Text(
                                                            text = "المشرف: ${order.operatorName}",
                                                            fontSize = 10.sp,
                                                            color = textSecondary,
                                                            modifier = Modifier.padding(top = 2.dp)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                },
                                confirmButton = {
                                    Button(
                                        onClick = { selectedLeaderboardItem = null },
                                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Text("إغلاق", fontWeight = FontWeight.Bold, color = Color.White)
                                    }
                                }
                            )
                        }
                    }

                    "revisions" -> {
                        // 5. FORMULATION REVISIONS HISTORY
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("أرشيف تتبع مراجعات التركيبات 📋", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = textPrimary)

                            if (allRevisions.isEmpty()) {
                                Box(modifier = Modifier.fillMaxWidth().padding(40.dp), contentAlignment = Alignment.Center) {
                                    Text("لا توجد مراجعات أو تحديثات مسجلة على أي تركيبة حتى الآن.", fontSize = 12.sp, color = textSecondary)
                                }
                            } else {
                                allRevisions.forEach { rev ->
                                    val matchedFormula = formulationsList.find { it.id == rev.formulationId }
                                    val formulaName = matchedFormula?.name ?: "تركيبة محذوفة/أرشيفية"

                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, borderColor)
                                    ) {
                                        Column(modifier = Modifier.padding(12.dp)) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Text(formulaName, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                    Text("تاريخ التعديل: ${rev.dateChange}", fontSize = 11.sp, color = textSecondary)
                                                }
                                                Box(
                                                    modifier = Modifier
                                                        .clip(RoundedCornerShape(8.dp))
                                                        .background(GBRCyanAccent.copy(alpha = 0.12f))
                                                        .padding(horizontal = 8.dp, vertical = 4.dp)
                                                ) {
                                                    Text("نسخة ${rev.version}", fontSize = 10.sp, color = GBRCyanAccent, fontWeight = FontWeight.Bold)
                                                }
                                            }

                                            Divider(modifier = Modifier.padding(vertical = 10.dp), color = borderColor)

                                            Text("العنصر المعدل: ${rev.materialName}", fontSize = 11.sp, color = textPrimary, fontWeight = FontWeight.Bold)
                                            Text("التغيير في النسب: من ${rev.oldValue} إلى ${rev.newValue}", fontSize = 11.sp, color = textSecondary)

                                            if (rev.editReason.trim().isNotEmpty()) {
                                                Box(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(top = 8.dp)
                                                        .background(if (isDark) Color(0xFF1E293B) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                                                        .padding(8.dp)
                                                ) {
                                                    Text("سبب التحديث الفني: ${rev.editReason}", fontSize = 10.sp, color = textPrimary)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    "qc" -> {
                        // 6. PRODUCTION ORDERS WITH QC TEST RESULTS & LABORATORY INSPECTIONS
                        if (selectedQcSession != null) {
                            val currentSession = labSessions.find { it.id == selectedQcSession!!.id } ?: selectedQcSession!!
                            SessionDetailsView(
                                session = currentSession,
                                viewModel = viewModel,
                                onBack = { selectedQcSession = null },
                                onDelete = {
                                    viewModel.deleteLabSession(currentSession)
                                    selectedQcSession = null
                                },
                                isEmbedded = true
                            )
                        } else {
                            var qcSearchQuery by remember { mutableStateOf("") }
                            val coroutineScope = rememberCoroutineScope()

                            val ordersWithQC = remember(productionOrdersList, labSessions, allProductionOrderTestRecords) {
                                productionOrdersList.mapNotNull { order ->
                                    val matchedSessions = labSessions.filter { sess ->
                                        val props = (sess.sampleProperties ?: "").trim()
                                        val matchesProp = props.contains("ORDER_ID:${order.id}") ||
                                                props.contains("ORDER_NO:${order.orderNumber}") ||
                                                (order.id.isNotBlank() && props.contains(order.id))
                                        val matchesSampleOrProduct = sess.sampleOrProduct.isNotBlank() && (
                                                sess.sampleOrProduct.trim().equals(order.orderNumber.trim(), ignoreCase = true) ||
                                                (order.batchNumber.isNotBlank() && sess.sampleOrProduct.trim().equals(order.batchNumber.trim(), ignoreCase = true)) ||
                                                (order.formulationName.isNotBlank() && sess.sampleOrProduct.trim().equals(order.formulationName.trim(), ignoreCase = true) && (sess.notes.contains(order.batchNumber.trim()) || sess.testName.contains(order.batchNumber.trim())))
                                        )
                                        val matchesNotesOrName = (order.batchNumber.isNotBlank() && (sess.notes.contains(order.batchNumber.trim(), ignoreCase = true) || sess.testName.contains(order.batchNumber.trim(), ignoreCase = true))) ||
                                                (order.orderNumber.isNotBlank() && (sess.notes.contains(order.orderNumber.trim(), ignoreCase = true) || sess.testName.contains(order.orderNumber.trim(), ignoreCase = true)))

                                        matchesProp || matchesSampleOrProduct || matchesNotesOrName
                                    }
                                    val directRecs = allProductionOrderTestRecords.filter { it.productionOrderId == order.id }

                                    if (matchedSessions.isNotEmpty() || directRecs.isNotEmpty()) {
                                        val latestSessionTime = matchedSessions.maxOfOrNull { it.createdAt } ?: 0L
                                        val latestDirectTime = directRecs.maxOfOrNull { it.timestamp } ?: 0L
                                        val latestInspectionTime = maxOf(latestSessionTime, latestDirectTime, order.endTime, order.createdAt)

                                        OrderQCReportItem(
                                            order = order,
                                            sessions = matchedSessions,
                                            labTests = emptyList(),
                                            directRecords = directRecs,
                                            latestInspectionTime = latestInspectionTime
                                        )
                                    } else {
                                        null
                                    }
                                }.sortedByDescending { it.latestInspectionTime }
                            }

                            val filteredOrdersWithQC = remember(ordersWithQC, qcSearchQuery) {
                                if (qcSearchQuery.isBlank()) {
                                    ordersWithQC
                                } else {
                                    val q = qcSearchQuery.trim().lowercase()
                                    ordersWithQC.filter { item ->
                                        val ord = item.order
                                        ord.orderNumber.lowercase().contains(q) ||
                                        ord.batchNumber.lowercase().contains(q) ||
                                        ord.formulationName.lowercase().contains(q) ||
                                        ord.operatorName.lowercase().contains(q) ||
                                        item.sessions.any { s ->
                                            s.sessionNumber.lowercase().contains(q) ||
                                            s.technicianName.lowercase().contains(q) ||
                                            s.testName.lowercase().contains(q) ||
                                            s.notes.lowercase().contains(q)
                                        }
                                    }
                                }
                            }

                            Column(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .verticalScroll(rememberScrollState()),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                // Search Header
                                OutlinedTextField(
                                    value = qcSearchQuery,
                                    onValueChange = { qcSearchQuery = it },
                                    modifier = Modifier.fillMaxWidth(),
                                    placeholder = { Text("بحث برقم أمر الإنتاج، الوجبة، اسم المنتج...", fontSize = 11.sp, color = textSecondary) },
                                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = "بحث", tint = GBRBlueMain, modifier = Modifier.size(18.dp)) },
                                    trailingIcon = {
                                        if (qcSearchQuery.isNotEmpty()) {
                                            IconButton(onClick = { qcSearchQuery = "" }) {
                                                Icon(Icons.Default.Close, contentDescription = "مسح", tint = textSecondary, modifier = Modifier.size(16.dp))
                                            }
                                        }
                                    },
                                    singleLine = true,
                                    shape = RoundedCornerShape(10.dp),
                                    colors = OutlinedTextFieldDefaults.colors(
                                        focusedBorderColor = GBRBlueMain,
                                        unfocusedBorderColor = borderColor,
                                        focusedContainerColor = cardBg,
                                        unfocusedContainerColor = cardBg
                                    )
                                )

                                // Count Summary Header
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        "قائمة أوامر الإنتاج المفحوصة مخبرياً 🧪",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = textPrimary
                                    )
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(GBRBlueMain.copy(alpha = 0.12f))
                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                    ) {
                                        Text(
                                            "${filteredOrdersWithQC.size} أمر إنتاج",
                                            fontSize = 10.5.sp,
                                            color = GBRBlueMain,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }

                                if (filteredOrdersWithQC.isEmpty()) {
                                    Card(
                                        modifier = Modifier.fillMaxWidth().padding(vertical = 20.dp),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, borderColor),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Column(
                                            modifier = Modifier.fillMaxWidth().padding(32.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Text("🧪", fontSize = 32.sp)
                                            Text(
                                                "لا توجد أوامر إنتاج مسجل لها فحوصات مخبرية.",
                                                fontSize = 12.sp,
                                                color = textSecondary,
                                                textAlign = TextAlign.Center
                                            )
                                        }
                                    }
                                } else {
                                    filteredOrdersWithQC.forEach { item ->
                                        val order = item.order
                                        val sessions = item.sessions

                                        Card(
                                            onClick = {
                                                if (sessions.size == 1) {
                                                    selectedQcSession = sessions.first()
                                                } else if (sessions.size > 1) {
                                                    multipleSessionsForOrderDialog = Pair(order, sessions)
                                                } else {
                                                    // Create or link a session for this order
                                                    val todayStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date())
                                                    viewModel.addLabSession(
                                                        testName = "فحص جودة: ${order.formulationName}",
                                                        testDate = todayStr,
                                                        technicianName = order.operatorName.ifBlank { "مشرف المختبر" },
                                                        sampleOrProduct = "دفعة #${order.batchNumber} - ${order.formulationName}",
                                                        category = "فحص جودة الإنتاج",
                                                        testType = "🧪 فحص أحادي",
                                                        notes = "جلسة فحص جودة مرتبطة بأمر الإنتاج رقم ${order.orderNumber} لمنتج ${order.formulationName}.",
                                                        comparisonType = null,
                                                        partyA = null,
                                                        partyB = null,
                                                        sampleProperties = "ORDER_ID:${order.id}"
                                                    )
                                                    // Find the newly added or existing session
                                                    coroutineScope.launch {
                                                        kotlinx.coroutines.delay(200)
                                                        val newlyFound = labSessions.find { it.sampleProperties == "ORDER_ID:${order.id}" }
                                                        if (newlyFound != null) {
                                                            selectedQcSession = newlyFound
                                                        }
                                                    }
                                                }
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = cardBg),
                                            border = BorderStroke(1.dp, borderColor),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                                // Top row: Order Number & Status
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                        Text(
                                                            "أمر إنتاج #${order.orderNumber}",
                                                            fontSize = 13.5.sp,
                                                            fontWeight = FontWeight.Bold,
                                                            color = textPrimary
                                                        )
                                                        Box(
                                                            modifier = Modifier
                                                                .clip(RoundedCornerShape(6.dp))
                                                                .background(
                                                                    when (order.status) {
                                                                        "مكتمل" -> SuccessGreen.copy(alpha = 0.12f)
                                                                        "قيد التشغيل" -> Color(0xFFF59E0B).copy(alpha = 0.12f)
                                                                        "ملغي" -> Color.Red.copy(alpha = 0.12f)
                                                                        else -> GBRBlueMain.copy(alpha = 0.12f)
                                                                    }
                                                                )
                                                                .padding(horizontal = 6.dp, vertical = 2.dp)
                                                        ) {
                                                            Text(
                                                                order.status,
                                                                fontSize = 9.5.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = when (order.status) {
                                                                    "مكتمل" -> SuccessGreen
                                                                    "قيد التشغيل" -> Color(0xFFD97706)
                                                                    "ملغي" -> Color.Red
                                                                    else -> GBRBlueMain
                                                                }
                                                            )
                                                        }
                                                    }

                                                    // Sessions badge
                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(8.dp))
                                                            .background(GBRBlueMain.copy(alpha = 0.1f))
                                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                                    ) {
                                                        Text(
                                                            if (sessions.isNotEmpty()) "${sessions.size} جلسة فحص 🔬" else "فحص مسجل 📋",
                                                            fontSize = 10.sp,
                                                            color = GBRBlueMain,
                                                            fontWeight = FontWeight.Bold
                                                        )
                                                    }
                                                }

                                                // Middle Row: Product info and batch
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Column(modifier = Modifier.weight(1f)) {
                                                        Text(
                                                            "المنتج: ${order.formulationName}",
                                                            fontSize = 11.5.sp,
                                                            fontWeight = FontWeight.Medium,
                                                            color = textPrimary
                                                        )
                                                        Spacer(modifier = Modifier.height(2.dp))
                                                        Text(
                                                            "الدفعة: #${order.batchNumber} | الكمية: ${order.requiredWeightKg} كجم",
                                                            fontSize = 10.5.sp,
                                                            color = textSecondary
                                                        )
                                                    }
                                                }

                                                Divider(color = borderColor.copy(alpha = 0.5f))

                                                // Action prompt
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(
                                                        "اضغط لعرض تفاصيل جلسة الفحص والمواصفات",
                                                        fontSize = 10.sp,
                                                        color = GBRBlueMain,
                                                        fontWeight = FontWeight.Medium
                                                    )
                                                    Icon(
                                                        imageVector = Icons.Default.ArrowBack,
                                                        contentDescription = "عرض",
                                                        tint = GBRBlueMain,
                                                        modifier = Modifier.size(16.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            // Multiple sessions selector dialog
                            if (multipleSessionsForOrderDialog != null) {
                                val (dlgOrder, dlgSessions) = multipleSessionsForOrderDialog!!
                                AlertDialog(
                                    onDismissRequest = { multipleSessionsForOrderDialog = null },
                                    title = {
                                        Text(
                                            "اختر جلسة الفحص - أمر #${dlgOrder.orderNumber}",
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = textPrimary
                                        )
                                    },
                                    text = {
                                        Column(
                                            modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState()),
                                            verticalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            dlgSessions.forEach { session ->
                                                Card(
                                                    onClick = {
                                                        selectedQcSession = session
                                                        multipleSessionsForOrderDialog = null
                                                    },
                                                    modifier = Modifier.fillMaxWidth(),
                                                    colors = CardDefaults.cardColors(containerColor = cardBg),
                                                    border = BorderStroke(1.dp, borderColor)
                                                ) {
                                                    Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                                        Row(
                                                            modifier = Modifier.fillMaxWidth(),
                                                            horizontalArrangement = Arrangement.SpaceBetween,
                                                            verticalAlignment = Alignment.CenterVertically
                                                        ) {
                                                            Text(
                                                                session.testName.ifBlank { "جلسة فحص #${session.sessionNumber}" },
                                                                fontSize = 11.5.sp,
                                                                fontWeight = FontWeight.Bold,
                                                                color = textPrimary
                                                            )
                                                            Text(
                                                                session.testDate,
                                                                fontSize = 10.sp,
                                                                color = textSecondary
                                                            )
                                                        }
                                                        if (session.technicianName.isNotBlank()) {
                                                            Text("الفاحص: ${session.technicianName}", fontSize = 10.sp, color = textSecondary)
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    },
                                    confirmButton = {
                                        TextButton(onClick = { multipleSessionsForOrderDialog = null }) {
                                            Text("إلغاء", fontSize = 11.sp, color = textSecondary)
                                        }
                                    },
                                    containerColor = cardBg,
                                    shape = RoundedCornerShape(12.dp)
                                )
                            }
                        }
                    }

                    "notes" -> {
                        // 7. FORMULAS WITH PRODUCTION NOTES
                        val notedFormulas = latestFormulations.filter { it.notes.trim().isNotEmpty() }

                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("تنبيهات وتوجيهات عمال التشغيل 📝", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = textPrimary)

                            if (notedFormulas.isEmpty()) {
                                Box(modifier = Modifier.fillMaxWidth().padding(40.dp), contentAlignment = Alignment.Center) {
                                    Text("جميع التعليمات الفنية التوجيهية للتركيبات فارغة.", fontSize = 12.sp, color = textSecondary)
                                }
                            } else {
                                notedFormulas.forEach { formula ->
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, borderColor)
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp)) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Text(formula.name, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                    Text("الكود: ${formula.code}", fontSize = 11.sp, color = textSecondary)
                                                }
                                            }

                                            Spacer(modifier = Modifier.height(10.dp))

                                            Box(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(if (isDark) Color(0xFF3B2F1F) else Color(0xFFFEF3C7), RoundedCornerShape(8.dp))
                                                    .padding(10.dp)
                                            ) {
                                                Column {
                                                    Text("الملاحظة والتوجيه التشغيلي:", fontSize = 10.sp, color = WarningOrange, fontWeight = FontWeight.Bold)
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    Text(formula.notes, fontSize = 11.sp, color = textPrimary, lineHeight = 15.sp)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    "aging" -> {
                        // 8. AGING (UNPRODUCED PRODUCTS) REPORT
                        val agingFormulas = latestFormulations.filter { formula ->
                            (formula.status == "🟢 معتمدة للإنتاج" || formula.status.contains("معتمد")) &&
                            allRuns.none { run -> isRunMatchingFormula(run, formula) }
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("تركيبات لم تدخل خط الإنتاج والتصنيع 📦", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = textPrimary)

                            if (agingFormulas.isEmpty()) {
                                Box(modifier = Modifier.fillMaxWidth().padding(40.dp), contentAlignment = Alignment.Center) {
                                    Text("رائع! جميع التركيبات المسجلة تم تصنيعها وتشغيلها بانتظام ✔.", fontSize = 12.sp, color = SuccessGreen)
                                }
                            } else {
                                agingFormulas.forEach { formula ->
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = cardBg),
                                        border = BorderStroke(1.dp, borderColor)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(14.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text(formula.name, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = textPrimary)
                                                Text("الكود: ${formula.code}", fontSize = 11.sp, color = textSecondary)
                                                Text("تاريخ التسجيل: ${formula.createdAt}", fontSize = 10.sp, color = textSecondary)
                                            }
                                            Box(
                                                modifier = Modifier
                                                    .clip(RoundedCornerShape(8.dp))
                                                    .background(if (isDark) Color(0xFF334155) else Color(0xFFF1F5F9))
                                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                                            ) {
                                                Text("راكد ⏸", fontSize = 10.sp, color = textSecondary, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// ==========================================
// SEGMENT 7 PANEL: SETTINGS PANEL (قائمة الإعدادات)
// ==========================================
@Composable
fun SettingsPanel(viewModel: GbrViewModel) {
    val context = LocalContext.current
    val selectedSettingSectionState by viewModel.selectedSettingSection.collectAsState()
    var selectedSettingSection by remember(selectedSettingSectionState) {
        object : MutableState<String?> {
            override var value: String?
                get() = viewModel.selectedSettingSection.value
                set(v) { viewModel.selectedSettingSection.value = v }
            override fun component1() = value
            override fun component2(): (String?) -> Unit = { value = it }
        }
    }
    val lang by viewModel.appLanguage.collectAsState()
    val currentUser by viewModel.currentUser.collectAsState()
    val isSupervisor = currentUser?.role == "مشرف الإنتاج"
    val hasUnsavedChangesInSubView by viewModel.hasUnsavedConnectionSettingsInUi.collectAsState()
    var showUnsavedChangesWarningDialogInSubView by remember { mutableStateOf(false) }
    
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    
    // Manage back clicks to settings main list or home screen
    BackHandler(enabled = true) {
        if (selectedSettingSection == "قاعدة البيانات" && hasUnsavedChangesInSubView) {
            showUnsavedChangesWarningDialogInSubView = true
        } else if (selectedSettingSection != null) {
            selectedSettingSection = null
        } else {
            viewModel.showSegment(null)
        }
    }

    if (selectedSettingSection == "سلة المحذوفات") {
        com.example.ui.RecycleBinPanel(viewModel = viewModel)
        return
    }
    if (selectedSettingSection == "مراقبة المزامنة") {
        com.example.ui.SyncMonitoringPanel(viewModel = viewModel)
        return
    }

    if (showUnsavedChangesWarningDialogInSubView) {
        AlertDialog(
            onDismissRequest = { showUnsavedChangesWarningDialogInSubView = false },
            title = {
                Text(
                    text = t("⚠️ تنبيه: تغييرات غير محفوظة", "⚠️ Unsaved Changes Warning"),
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = Color(0xFFB45309)
                )
            },
            text = {
                Text(
                    text = t(
                        "لقد قمت بتعديل طريقة ونوع المزامنة دون حفظ الإعدادات. هل ترغب في تجاهل التغييرات والرجوع أم البقاء لحفظها؟",
                        "You modified the sync mode connection settings without saving. Do you want to discard your changes and leave, or stay and save them?"
                    ),
                    fontSize = 12.sp,
                    lineHeight = 16.sp,
                    color = Color.DarkGray
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        showUnsavedChangesWarningDialogInSubView = false
                        viewModel.hasUnsavedConnectionSettingsInUi.value = false
                        selectedSettingSection = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFE11D48))
                ) {
                    Text(text = t("تجاهل التغييرات والرجوع 🚪", "Discard & Leave 🚪"), fontSize = 11.sp)
                }
            },
            dismissButton = {
                TextButton(
                    onClick = { showUnsavedChangesWarningDialogInSubView = false }
                ) {
                    Text(text = t("البقاء للحفظ 💾", "Stay & Save"), fontSize = 11.sp, color = GBRBlueMain)
                }
            }
        )
    }

    // System Back Button Handling for Settings Subviews
    BackHandler(enabled = selectedSettingSection != null) {
        if (selectedSettingSection == "قاعدة البيانات" && hasUnsavedChangesInSubView) {
            showUnsavedChangesWarningDialogInSubView = true
        } else {
            selectedSettingSection = null
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .verticalScroll(rememberScrollState())
            .padding(20.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Top
    ) {
        // Back Header Logic
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Start
        ) {
            IconButton(
                onClick = {
                    if (selectedSettingSection == "قاعدة البيانات" && hasUnsavedChangesInSubView) {
                        showUnsavedChangesWarningDialogInSubView = true
                    } else if (selectedSettingSection != null) {
                        selectedSettingSection = null
                    } else {
                        viewModel.showSegment(null)
                    }
                },
                modifier = Modifier
                    .clip(RoundedCornerShape(12.dp))
                    .background(Color.LightGray.copy(alpha = 0.2f))
            ) {
                Icon(
                    imageVector = Icons.Default.ArrowForward,
                    contentDescription = "الرجوع",
                    tint = GBRBlueMain
                )
            }
            Spacer(modifier = Modifier.width(12.dp))
            Text(
                text = if (selectedSettingSection == null) s().settingsTitle else {
                    when (selectedSettingSection) {
                        "الأصوات والتنبيهات" -> if (lang == "ar") "إعدادات الأصوات والتنبيهات 🔔" else "Sounds & Notifications 🔔"
                        "خصائص التطبيق" -> s().settingsCatAppProperties
                        "إعدادات الطباعة والترويسة" -> if (lang == "ar") "إعدادات الطباعة والترويسة" else "Print & Header Settings"
                        "بوابة ربط Hostinger" -> if (lang == "ar") "بوابة ربط استضافة Hostinger 🌐" else "Hostinger Hosting Gateway 🌐"
                        "المظهر واللغة" -> s().settingsCatAppearanceLanguage
                        "قاعدة البيانات" -> s().settingsCatDatabase
                        "العبوات والتغليف" -> s().settingsCatPackaging
                        "المستخدمون" -> s().settingsCatUsers
                        "حول التطبيق" -> s().settingsCatAbout
                        else -> selectedSettingSection!!
                    }
                },
                fontSize = 18.sp,
                fontWeight = FontWeight.Bold,
                color = GBRDarkIndigo
            )
        }

        if (selectedSettingSection == null) {
            // Main Settings Menu List
            Column(
                verticalArrangement = Arrangement.spacedBy(12.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                // Section 0: سلة المحذوفات (Recycle Bin with badge)
                val recycleBinList by viewModel.recycleBinItems.collectAsState()
                val recycleBinCount = recycleBinList.size
                SettingCategoryCard(
                    title = if (lang == "ar") "سلة المحذوفات 🗑️" else "Recycle Bin 🗑️",
                    subtitle = if (lang == "ar") "استعادة المواد، التركيبات، الفحوصات ومشاريع التطوير المحذوفة مؤخراً" else "Restore deleted materials, formulations, tests, and projects",
                    icon = Icons.Default.Delete,
                    iconBgColor = Color(0xFFFEF2F2),
                    iconColor = Color(0xFFEF4444),
                    badgeCount = recycleBinCount,
                    onClick = { selectedSettingSection = "سلة المحذوفات" }
                )

                // Section 0.5: مراقبة المزامنة (Sync Monitoring)
                SettingCategoryCard(
                    title = if (lang == "ar") "مراقبة المزامنة 🔄" else "Sync Monitoring 🔄",
                    subtitle = if (lang == "ar") "تتبع فوري وحوكمة التزامن مع Firestore وفحص حالة السحابة" else "Real-time tracking and sync governance with Firestore",
                    icon = Icons.Default.Refresh,
                    iconBgColor = Color(0xFFECFDF5),
                    iconColor = SuccessGreen,
                    onClick = { selectedSettingSection = "مراقبة المزامنة" }
                )

                // Section 1: خصائص التطبيق (App Properties Central Station)
                SettingCategoryCard(
                    title = s().settingsCatAppProperties,
                    subtitle = s().settingsCatAppPropertiesSub,
                    icon = Icons.Default.Build,
                    iconBgColor = Color(0xFFF5F3FF),
                    iconColor = Color(0xFF7C3AED),
                    onClick = { selectedSettingSection = "خصائص التطبيق" }
                )

                // Section 2: المظهر واللغة
                SettingCategoryCard(
                    title = s().settingsCatAppearanceLanguage,
                    subtitle = s().settingsCatAppearanceLanguageSub,
                    icon = Icons.Default.Info,
                    iconBgColor = Color(0xFFECFDF5),
                    iconColor = SuccessGreen,
                    onClick = { selectedSettingSection = "المظهر واللغة" }
                )

                if (!isSupervisor) {
                    // Section 3: قاعدة البيانات وإدارة التقارير والدمج المدقق
                    SettingCategoryCard(
                        title = s().settingsCatDatabase,
                        subtitle = s().settingsCatDatabaseSub,
                        icon = Icons.Default.Refresh,
                        iconBgColor = Color(0xFFFEF3C7),
                        iconColor = WarningOrange,
                        onClick = { selectedSettingSection = "قاعدة البيانات" }
                    )
                }

                // Section 4: العبوات والتغليف
                SettingCategoryCard(
                    title = s().settingsCatPackaging,
                    subtitle = s().settingsCatPackagingSub,
                    icon = Icons.Default.Menu,
                    iconBgColor = Color(0xFFEFF6FF),
                    iconColor = GBRBlueMain,
                    onClick = { selectedSettingSection = "العبوات والتغليف" }
                )

                if (!isSupervisor) {
                    // Section 5: المستخدمون
                    SettingCategoryCard(
                        title = s().settingsCatUsers,
                        subtitle = s().settingsCatUsersSub,
                        icon = Icons.Default.Person,
                        iconBgColor = Color(0xFFE0F2FE),
                        iconColor = GBRBlueMain,
                        onClick = { selectedSettingSection = "المستخدمون" }
                    )
                }

                // Section 6: حول التطبيق
                SettingCategoryCard(
                    title = s().settingsCatAbout,
                    subtitle = s().settingsCatAboutSub,
                    icon = Icons.Default.Info,
                    iconBgColor = Color(0xFFFDF2F8),
                    iconColor = GBRPinkAccent,
                    onClick = { selectedSettingSection = "حول التطبيق" }
                )

                // Section 7: إعدادات الطباعة والترويسة
                SettingCategoryCard(
                    title = if (lang == "ar") "إعدادات الطباعة والترويسة 🖨️" else "Print & Header Settings 🖨️",
                    subtitle = if (lang == "ar") "تخصيص ترويسة التقارير والشعار ونصوص الطباعة المعتمدة" else "Customize report headers, logo, and approved footer texts",
                    icon = Icons.Default.Share,
                    iconBgColor = Color(0xFFEFF6FF),
                    iconColor = GBRBlueMain,
                    onClick = { selectedSettingSection = "إعدادات الطباعة والترويسة" }
                )

                // Section 8: بوابة ربط استضافة Hostinger
                SettingCategoryCard(
                    title = if (lang == "ar") "بوابة ربط استضافة Hostinger 🌐" else "Hostinger Hosting Gateway 🌐",
                    subtitle = if (lang == "ar") "تحميل سكربتات PHP لرفع الملفات (upload, delete, health) والتعليمات" else "Download PHP scripts for uploading/management and integration guides",
                    icon = Icons.Default.Build,
                    iconBgColor = Color(0xFFF0FDF4),
                    iconColor = Color(0xFF16A34A),
                    onClick = { selectedSettingSection = "بوابة ربط Hostinger" }
                )

                // Section 9: الأصوات والتنبيهات 🔔
                SettingCategoryCard(
                    title = if (lang == "ar") "الأصوات والتنبيهات 🔔" else "Sounds & Notifications 🔔",
                    subtitle = if (lang == "ar") "تخصيص نغمات فحص وانتهاء مدة مرحلة الإنتاج وتفعيل الاهتزاز" else "Customize alert tones, end-of-stage timeout beep, and haptic feedback preferences",
                    icon = Icons.Default.Notifications,
                    iconBgColor = Color(0xFFFFF1F2),
                    iconColor = Color(0xFFF43F5E),
                    onClick = { selectedSettingSection = "الأصوات والتنبيهات" }
                )

                // Section 10: إدارة الأجهزة والأمان 🛡️
                if (!isSupervisor) {
                    SettingCategoryCard(
                        title = if (lang == "ar") "إدارة الأجهزة والأمان 🛡️" else "Device Security & Management 🛡️",
                        subtitle = if (lang == "ar") "التحكم بالأجهزة المصرح لها، اعتماد الأجهزة الجديدة، استرداد المسؤول" else "Control authorized devices, approve new entries, and set recovery key",
                        icon = Icons.Default.Lock,
                        iconBgColor = Color(0xFFEFF6FF),
                        iconColor = GBRBlueMain,
                        onClick = { selectedSettingSection = "إدارة الأجهزة والأمان" }
                    )
                }

                // Section 11: تسجيل الخروج 🚪
                SettingCategoryCard(
                    title = if (lang == "ar") "تسجيل الخروج 🚪" else "Logout 🚪",
                    subtitle = if (lang == "ar") "الخروج من الحساب الحالي والعودة لشاشة الدخول" else "Sign out of the current account and return to login",
                    icon = Icons.Default.ExitToApp,
                    iconBgColor = Color(0xFFFEF2F2),
                    iconColor = Color(0xFFDC2626),
                    onClick = { viewModel.logout() }
                )
            }
        } else {
            // Render Selected Section Subviews
            when (selectedSettingSection) {
                "الأصوات والتنبيهات" -> SoundsNotificationsSettingsSubView(viewModel = viewModel)
                "خصائص التطبيق" -> AppPropertiesSubView(viewModel = viewModel)
                "إعدادات الطباعة والترويسة" -> PrintSettingsSubView(viewModel = viewModel)
                "بوابة ربط Hostinger" -> HostingerHostingSubView(viewModel = viewModel)
                "المظهر واللغة" -> AppearanceLanguageSettingsSubView(viewModel = viewModel)
                "قاعدة البيانات" -> DatabaseSettingsSubView(viewModel = viewModel)
                "العبوات والتغليف" -> PackagingSettingsSubView(viewModel = viewModel)
                "المستخدمون" -> UsersSettingsSubView(viewModel = viewModel)
                "حول التطبيق" -> AboutAppSettingsSubView(viewModel = viewModel)
                "إدارة الأجهزة والأمان" -> com.example.ui.DeviceSecurityManagementSubView(viewModel = viewModel)
            }
        }
    }
}

@Composable
fun SettingCategoryCard(
    title: String,
    subtitle: String,
    icon: ImageVector,
    iconBgColor: Color,
    iconColor: Color,
    badgeCount: Int = 0,
    onClick: () -> Unit
) {
    Card(
        onClick = onClick,
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.5.dp, IndustrialBorder),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier
                    .size(50.dp)
                    .clip(RoundedCornerShape(12.dp))
                    .background(iconBgColor),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = icon,
                    contentDescription = null,
                    modifier = Modifier.size(24.dp),
                    tint = iconColor
                )
            }

            Spacer(modifier = Modifier.width(14.dp))

            Column(
                modifier = Modifier.weight(1f)
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = title,
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                    if (badgeCount > 0) {
                        Box(
                            modifier = Modifier
                                .background(Color(0xFFEF4444), CircleShape)
                                .padding(horizontal = 8.dp, vertical = 2.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = badgeCount.toString(),
                                color = Color.White,
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
                Spacer(modifier = Modifier.height(3.dp))
                Text(
                    text = subtitle,
                    fontSize = 11.sp,
                    color = Color.Gray,
                    lineHeight = 15.sp
                )
            }

            Icon(
                imageVector = Icons.Default.KeyboardArrowLeft,
                contentDescription = null,
                tint = Color.LightGray,
                modifier = Modifier.size(20.dp)
            )
        }
    }
}

// Subview 1: العبوات والتغليف (Dynamic Controls)
@Composable
fun PackagingSettingsSubView(viewModel: GbrViewModel) {
    val packagingList by viewModel.customPackagings.collectAsState()
    
    // Create Mode Form states
    var newPkgName by remember { mutableStateOf("") }
    var newPkgNetWeight by remember { mutableStateOf("") }
    var newPkgEmptyWeightWithLid by remember { mutableStateOf("0.8") }
    var newPkgPrice by remember { mutableStateOf("") }
    var formError by remember { mutableStateOf<String?>(null) }

    // Edit Mode State
    var editingPackageId by remember { mutableStateOf<String?>(null) }
    var editPkgName by remember { mutableStateOf("") }
    var editPkgNetWeight by remember { mutableStateOf("") }
    var editPkgEmptyWeightWithLid by remember { mutableStateOf("") }
    var editPkgPrice by remember { mutableStateOf("") }
    var editFormError by remember { mutableStateOf<String?>(null) }

    Column(
        verticalArrangement = Arrangement.spacedBy(16.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        // Explanatory Banner
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(12.dp),
            colors = CardDefaults.cardColors(containerColor = GBRBlueMain.copy(alpha = 0.05f)),
            border = BorderStroke(1.dp, GBRBlueMain.copy(alpha = 0.15f))
        ) {
            Column(modifier = Modifier.padding(14.dp)) {
                Text(
                    text = "⚙️ إدارة أوعية وعبوات التغليف النشطة:",
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRBlueMain
                )
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    text = "يسمح هذا القسم بالتحكم وإنشاء وتعديل العبوات المستخدمة للتعبئة في خطوط الإنتاج. أدخل اسم العبوة، وزن الطلاء الصافي ووزن العبوة فارغة مع الغطاء، وسعر الأوعية لتحديث محاسبة التكلفة فورياً.",
                    fontSize = 11.5.sp,
                    color = Color(0xFF334155),
                    lineHeight = 17.sp
                )
            }
        }

        // Add Packaging Form Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "📥 تسجيل وعاء / عبوة تشغيل جديدة",
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                // 4 fields for adding (split weights cleanly into 2 direct numbers)
                OutlinedTextField(
                    value = newPkgName,
                    onValueChange = { 
                        newPkgName = it
                        formError = null 
                    },
                    label = { Text("اسم العبوة (مثال: سطل 18 لتر مميز)") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    shape = RoundedCornerShape(10.dp)
                )

                OutlinedTextField(
                    value = newPkgNetWeight,
                    onValueChange = { 
                        newPkgNetWeight = it
                        formError = null 
                    },
                    label = { Text("الوزن الصافي لتعبئة الطلاء (كجم) - مثال: 18") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                    shape = RoundedCornerShape(10.dp)
                )

                OutlinedTextField(
                    value = newPkgEmptyWeightWithLid,
                    onValueChange = { 
                        newPkgEmptyWeightWithLid = it
                        formError = null 
                    },
                    label = { Text("الوزن الصافي للعبوة فارغة مع الغطاء (كجم) - مثال: 0.8") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                    shape = RoundedCornerShape(10.dp)
                )

                OutlinedTextField(
                    value = newPkgPrice,
                    onValueChange = { 
                        newPkgPrice = it
                        formError = null 
                    },
                    label = { Text("سعر/تكلفة العبوة الواحدة (شيكل)") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                    shape = RoundedCornerShape(10.dp)
                )

                if (formError != null) {
                    Text(
                        text = formError!!,
                        color = Color.Red,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(vertical = 2.dp)
                    )
                }

                Button(
                    onClick = {
                        val name = newPkgName.trim()
                        val priceVal = newPkgPrice.toDoubleOrNull()
                        val netW = newPkgNetWeight.toDoubleOrNull()
                        val emptyW = newPkgEmptyWeightWithLid.toDoubleOrNull()
                        val withLidW = if (netW != null && emptyW != null) netW + emptyW else null
                        
                        if (name.isEmpty()) {
                            formError = "الرجاء إدخال اسم العبوة قبل الحفظ!"
                        } else if (netW == null || netW <= 0) {
                            formError = "الرجاء إدخال وزن صافي تعبئة صحيح!"
                        } else if (emptyW == null || emptyW < 0) {
                            formError = "الرجاء إدخال وزن عبوة فارغ صحيح!"
                        } else if (withLidW == null || withLidW <= 0) {
                            formError = "الرجاء كتابة وزن صحيح وبصيغة صالحة!"
                        } else if (priceVal == null || priceVal < 0) {
                            formError = "الرجاء إدخال سعر صحيح (قيمة رقمية إيجابية)!"
                        } else {
                            viewModel.addCustomPackaging(name, netW, withLidW, priceVal)
                            newPkgName = ""
                            newPkgNetWeight = ""
                            newPkgEmptyWeightWithLid = "0.8"
                            newPkgPrice = ""
                            formError = null
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Icon(imageVector = Icons.Default.Add, contentDescription = null, tint = Color.White, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("إضافة العبوة وتحديث النظام", fontWeight = FontWeight.Bold, color = Color.White, fontSize = 13.sp)
                }
            }
        }

        // Active Packagings List Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text(
                    text = "📦 العبوات المدخرة بالنظام (${packagingList.size} عبوة)",
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                if (packagingList.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 30.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "لا توجد عبوات تشغيل مسجلة بالنظام حالياً. أضف عبوة من الأعلى.",
                            color = Color.Gray,
                            fontSize = 12.sp
                        )
                    }
                } else {
                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        packagingList.forEach { pkg ->
                            val isEditing = editingPackageId == pkg.id
                            
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color(0xFFF8FAFC), RoundedCornerShape(12.dp))
                                    .border(
                                        width = if (isEditing) 2.dp else 1.dp, 
                                        color = if (isEditing) GBRBlueMain else Color(0xFFE2E8F0), 
                                        shape = RoundedCornerShape(12.dp)
                                    )
                                    .padding(12.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                if (isEditing) {
                                    // 4 fields editing inline
                                    Text(
                                        text = "✏️ تعديل بيانات العبوة ومواصفاتها:",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRBlueMain
                                    )
                                    
                                    OutlinedTextField(
                                        value = editPkgName,
                                        onValueChange = { editPkgName = it },
                                        label = { Text("اسم العبوة") },
                                        modifier = Modifier.fillMaxWidth(),
                                        singleLine = true,
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                    
                                    OutlinedTextField(
                                        value = editPkgNetWeight,
                                        onValueChange = { editPkgNetWeight = it },
                                        label = { Text("الوزن الصافي لتعبئة الطلاء (كجم)") },
                                        modifier = Modifier.fillMaxWidth(),
                                        singleLine = true,
                                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                                        shape = RoundedCornerShape(8.dp)
                                    )

                                    OutlinedTextField(
                                        value = editPkgEmptyWeightWithLid,
                                        onValueChange = { editPkgEmptyWeightWithLid = it },
                                        label = { Text("الوزن الصافي للعبوة فارغة مع الغطاء (كجم)") },
                                        modifier = Modifier.fillMaxWidth(),
                                        singleLine = true,
                                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                                        shape = RoundedCornerShape(8.dp)
                                    )

                                    OutlinedTextField(
                                        value = editPkgPrice,
                                        onValueChange = { editPkgPrice = it },
                                        label = { Text("سعر/تكلفة العبوة (شيكل)") },
                                        modifier = Modifier.fillMaxWidth(),
                                        singleLine = true,
                                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                                        shape = RoundedCornerShape(8.dp)
                                    )

                                    if (editFormError != null) {
                                        Text(
                                            text = editFormError!!,
                                            color = Color.Red,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Button(
                                            onClick = {
                                                val name = editPkgName.trim()
                                                val priceVal = editPkgPrice.toDoubleOrNull()
                                                val netW = editPkgNetWeight.toDoubleOrNull()
                                                val emptyW = editPkgEmptyWeightWithLid.toDoubleOrNull()
                                                val withLidW = if (netW != null && emptyW != null) netW + emptyW else null
                                                
                                                if (name.isEmpty()) {
                                                    editFormError = "الاسم فارغ!"
                                                } else if (netW == null || netW <= 0) {
                                                    editFormError = "الوزن الصافي للطلاء خاطئ!"
                                                } else if (emptyW == null || emptyW < 0) {
                                                    editFormError = "وزن العبوة فارغ خاطئ!"
                                                } else if (withLidW == null || withLidW <= 0) {
                                                    editFormError = "الوزن الكلي خاطئ!"
                                                } else if (priceVal == null || priceVal < 0) {
                                                    editFormError = "السعر خاطئ!"
                                                } else {
                                                    viewModel.updateCustomPackaging(pkg.id, name, netW, withLidW, priceVal)
                                                    editingPackageId = null
                                                    editFormError = null
                                                }
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Text("حفظ وتعديل", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                        }

                                        TextButton(
                                            onClick = { editingPackageId = null },
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Text("إلغاء", color = Color.Gray, fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                        }
                                    }
                                } else {
                                    // Display mode row
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(36.dp)
                                                    .clip(RoundedCornerShape(8.dp))
                                                    .background(GBRBlueMain.copy(alpha = 0.08f)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Menu,
                                                    contentDescription = null,
                                                    tint = GBRBlueMain,
                                                    modifier = Modifier.size(18.dp)
                                                )
                                            }

                                            Column {
                                                Text(
                                                    text = pkg.name,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 13.sp,
                                                    color = GBRDarkIndigo
                                                )
                                                Spacer(modifier = Modifier.height(2.dp))
                                                val emptyW = try { formatQuantity(pkg.weightWithLid - pkg.netWeight) } catch (e: Exception) { "0.8" }
                                                Text(
                                                    text = "صافي الطلاء: ${formatQuantity(pkg.netWeight)} كجم | غطاء فارغ: $emptyW كجم | التكلفة: ${pkg.price} شيكل",
                                                    fontSize = 11.sp,
                                                    color = Color.Gray
                                                )
                                            }
                                        }

                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            // Edit Button
                                            IconButton(
                                                onClick = {
                                                    editingPackageId = pkg.id
                                                    editPkgName = pkg.name
                                                    editPkgNetWeight = pkg.netWeight.toString()
                                                    editPkgEmptyWeightWithLid = try { formatQuantity(pkg.weightWithLid - pkg.netWeight) } catch (e: Exception) { "0.8" }
                                                    editPkgPrice = pkg.price.toString()
                                                    editFormError = null
                                                },
                                                modifier = Modifier
                                                    .clip(CircleShape)
                                                    .background(GBRBlueMain.copy(alpha = 0.08f))
                                                    .size(32.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Edit,
                                                    contentDescription = "تعديل العبوة",
                                                    tint = GBRBlueMain,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }

                                            // Delete Button
                                            IconButton(
                                                onClick = { viewModel.deleteCustomPackaging(pkg.id) },
                                                modifier = Modifier
                                                    .clip(CircleShape)
                                                    .background(Color.Red.copy(alpha = 0.08f))
                                                    .size(32.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = "حذف العبوة",
                                                    tint = Color.Red,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// Subview 3: المشغلون والمستعملون (Dynamic Control)
@Composable
fun UsersSettingsSubView(viewModel: GbrViewModel) {
    val usersList by viewModel.customUsers.collectAsState()

    // Form states
    var newUsername by remember { mutableStateOf("") }
    var newFullName by remember { mutableStateOf("") }
    var newUserPass by remember { mutableStateOf("") }
    
    val presetRoles = listOf("مدير النظام", "مشرف الإنتاج", "عامل صالة الإنتاج")
    val futurePresetRoles = listOf(
        "فني مختبر Lab Technician",
        "مراقب جودة Quality Assurance",
        "أمين مستودع Inventory Manager",
        "مدير مصنع Plant Manager"
    )
    
    var selectedRole by remember { mutableStateOf("عامل صالة الإنتاج") }
    var isCustomRoleChecked by remember { mutableStateOf(false) }
    var customRoleLabel by remember { mutableStateOf("") }
    
    var isNewActive by remember { mutableStateOf(true) }
    var formUserError by remember { mutableStateOf<String?>(null) }
    
    var editingUser by remember { mutableStateOf<GbrViewModel.CustomUser?>(null) }
    var userPendingDelete by remember { mutableStateOf<GbrViewModel.CustomUser?>(null) }

    Column(
        verticalArrangement = Arrangement.spacedBy(14.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        // Add User Form Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    text = "👥 إضافة تفويض مستخدم جديد للنظام",
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                OutlinedTextField(
                    value = newUsername,
                    onValueChange = { 
                        newUsername = it.replace(" ", "")
                        formUserError = null 
                    },
                    label = { Text("اسم المستخدم للولوج (أحرف إنجليزية/أرقام - مثال: ahmad99)") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    shape = RoundedCornerShape(10.dp)
                )

                OutlinedTextField(
                    value = newFullName,
                    onValueChange = { 
                        newFullName = it
                        formUserError = null 
                    },
                    label = { Text("الاسم الكامل للمستخدم (اختياري - أحمد العلي)") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    shape = RoundedCornerShape(10.dp)
                )

                OutlinedTextField(
                    value = newUserPass,
                    onValueChange = { 
                        newUserPass = it
                        formUserError = null 
                    },
                    label = { Text("كلمة المرور السرية") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    shape = RoundedCornerShape(10.dp)
                )

                Text(
                    text = "نوع الصلاحية ورتبة العمل بالمعمل:",
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.padding(top = 4.dp)
                )

                Column(
                    verticalArrangement = Arrangement.spacedBy(4.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    // Presets
                    (presetRoles + futurePresetRoles).forEach { roleName ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable {
                                    isCustomRoleChecked = false
                                    selectedRole = roleName
                                    formUserError = null
                                }
                                .padding(vertical = 4.dp)
                        ) {
                            RadioButton(
                                selected = !isCustomRoleChecked && selectedRole == roleName,
                                onClick = {
                                    isCustomRoleChecked = false
                                    selectedRole = roleName
                                    formUserError = null
                                },
                                colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(text = roleName, fontSize = 12.sp, color = Color.DarkGray)
                        }
                    }

                    // Custom role option
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                isCustomRoleChecked = true
                                formUserError = null
                            }
                            .padding(vertical = 4.dp)
                    ) {
                        RadioButton(
                            selected = isCustomRoleChecked,
                            onClick = {
                                isCustomRoleChecked = true
                                formUserError = null
                            },
                            colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(text = "دور وصلاحية مخصصة (إدخال يدوي)", fontSize = 12.sp, color = Color.DarkGray)
                    }

                    if (isCustomRoleChecked) {
                        OutlinedTextField(
                            value = customRoleLabel,
                            onValueChange = {
                                customRoleLabel = it
                                formUserError = null
                            },
                            label = { Text("اكتب المسمى المخصص لحفظه كدور للصلاحية") },
                            modifier = Modifier.fillMaxWidth(),
                            singleLine = true,
                            shape = RoundedCornerShape(10.dp)
                        )
                    }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.Start
                ) {
                    Checkbox(
                        checked = isNewActive,
                        onCheckedChange = { isNewActive = it },
                        colors = CheckboxDefaults.colors(checkedColor = GBRBlueMain)
                    )
                    Text(
                        text = "تمكين الحساب وحالة الترخيص فورًا (حساب نشط ومصرح بالولوج)",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                }

                if (formUserError != null) {
                    Text(
                        text = formUserError!!,
                        color = Color.Red,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                Button(
                    onClick = {
                        val usernameClean = newUsername.trim()
                        val finalRoleName = if (isCustomRoleChecked) customRoleLabel.trim() else selectedRole
                        val passwordClean = newUserPass.trim()
                        
                        if (usernameClean.isEmpty() || finalRoleName.isEmpty() || passwordClean.isEmpty()) {
                            formUserError = "يرجى تعبئة جميع حقول المستخدم الجديد الحيوية (اسم المستخدم، كلمة المرور، والدور)!"
                        } else if (usersList.any { it.username.trim().lowercase() == usernameClean.lowercase() }) {
                            formUserError = "اسم المستخدم هذا مسجل بالفعل لولوج حساب آخر!"
                        } else {
                            val isSup = finalRoleName == "مدير النظام" || finalRoleName == "مشرف الإنتاج" || finalRoleName.startsWith("مشرف") || finalRoleName.startsWith("مدير")
                            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.getDefault())
                            val dateStr = sdf.format(java.util.Date())

                            viewModel.addCustomUser(
                                username = usernameClean,
                                role = finalRoleName,
                                password = passwordClean,
                                isSupervisor = isSup,
                                fullName = newFullName.trim(),
                                isActive = isNewActive,
                                createdAt = dateStr
                            )

                            // Reset states
                            newUsername = ""
                            newFullName = ""
                            newUserPass = ""
                            customRoleLabel = ""
                            isCustomRoleChecked = false
                            isNewActive = true
                            formUserError = null
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Icon(imageVector = Icons.Default.Add, contentDescription = null, tint = Color.White, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("حفظ ومنح صلاحية تسجيل الدخول", fontWeight = FontWeight.Bold, color = Color.White, fontSize = 13.sp)
                }
            }
        }

        // Users List Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text(
                    text = "👥 قائمة المستخدمين والمسؤولين المصرح لهم بمصنع GBR",
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                Column(
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    usersList.forEachIndexed { index, user ->
                        if (index > 0) {
                            HorizontalDivider(color = Color(0xFFF1F5F9))
                        }
                        
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1.4f)) {
                                Text(
                                    text = user.fullName.ifBlank { user.name },
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 13.sp,
                                    color = GBRDarkIndigo
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Text(
                                        text = "@${user.username.ifBlank { user.name.lowercase().replace(" ", "") }}",
                                        fontSize = 11.sp,
                                        color = Color.Gray,
                                        fontWeight = FontWeight.Medium
                                    )
                                    Text("•", fontSize = 11.sp, color = Color.LightGray)
                                    Text(
                                        text = user.role,
                                        fontSize = 11.sp,
                                        color = Color.Gray,
                                        fontWeight = FontWeight.SemiBold
                                    )
                                }
                                if (user.createdAt.isNotBlank()) {
                                    Text(
                                        text = "أنشئ في: ${user.createdAt}",
                                        fontSize = 10.sp,
                                        color = Color.Gray,
                                        modifier = Modifier.padding(top = 2.dp)
                                    )
                                }
                            }

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                modifier = Modifier.weight(1.1f)
                            ) {
                                // Status indicator badge
                                Box(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(6.dp))
                                        .background(if (user.isActive) Color(0xFFD1FAE5) else Color(0xFFFEE2E2))
                                        .padding(horizontal = 8.dp, vertical = 3.dp)
                                ) {
                                    Text(
                                        text = if (user.isActive) "نشط" else "معطل",
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = if (user.isActive) SuccessGreen else ErrorRed
                                    )
                                }

                                // Edit Button
                                IconButton(
                                    onClick = { editingUser = user },
                                    modifier = Modifier
                                        .clip(CircleShape)
                                        .background(GBRBlueMain.copy(alpha = 0.08f))
                                        .size(32.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Edit,
                                        contentDescription = "تعديل المستخدم",
                                        tint = GBRBlueMain,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }

                                // Prevent deleting the initial core administrator to avoid getting locked out, but allow deleting others
                                if (user.id != "1") {
                                    IconButton(
                                        onClick = { userPendingDelete = user },
                                        modifier = Modifier
                                            .clip(CircleShape)
                                            .background(Color.Red.copy(alpha = 0.08f))
                                            .size(32.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Delete,
                                            contentDescription = "حذف المستخدم",
                                            tint = Color.Red,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(12.dp),
            colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
            border = BorderStroke(1.dp, Color(0xFFFCE8B3))
        ) {
            Row(
                modifier = Modifier.padding(12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.Default.Warning,
                    contentDescription = null,
                    tint = WarningOrange,
                    modifier = Modifier.size(24.dp)
                )
                Spacer(modifier = Modifier.width(10.dp))
                Text(
                    text = "للدخول بأي مستخدم مسجل أعلاه، استخدم الاسم الظاهر بالموجز مع كلمة المرور التي اخترتها.",
                    fontSize = 10.5.sp,
                    color = Color(0xFFB45309),
                    lineHeight = 15.sp
                )
            }
        }
    }

    // Modal Edit dialog for editing users
    // تأكيد قبل حذف مستخدم (S2): الحذف كان فورياً بلا سؤال
    userPendingDelete?.let { pendingUser ->
        AlertDialog(
            onDismissRequest = { userPendingDelete = null },
            title = {
                Text(
                    text = "⚠️ " + t("تأكيد حذف المستخدم", "Confirm Delete User"),
                    fontWeight = FontWeight.Bold,
                    fontSize = 15.sp,
                    color = ErrorRed
                )
            },
            text = {
                Text(
                    text = t(
                        "هل أنت متأكد من حذف المستخدم «${pendingUser.fullName.ifBlank { pendingUser.name }}»؟ لا يمكن التراجع عن هذا الإجراء.",
                        "Are you sure you want to delete user \"${pendingUser.fullName.ifBlank { pendingUser.name }}\"? This cannot be undone."
                    ),
                    fontSize = 12.sp,
                    lineHeight = 17.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.deleteCustomUser(pendingUser.id)
                        userPendingDelete = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = ErrorRed)
                ) {
                    Text(text = t("نعم، احذف", "Yes, Delete"), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { userPendingDelete = null }) {
                    Text(text = t("تراجع", "Cancel"), fontSize = 11.sp)
                }
            }
        )
    }

    if (editingUser != null) {
        var editUsername by remember(editingUser) { mutableStateOf(editingUser!!.username.ifBlank { editingUser!!.name.lowercase().replace(" ", "") }) }
        var editFullName by remember(editingUser) { mutableStateOf(editingUser!!.fullName.ifBlank { editingUser!!.name }) }
        var editRole by remember(editingUser) { mutableStateOf(editingUser!!.role) }
        var editPass by remember(editingUser) { mutableStateOf(editingUser!!.password) }
        var editIsActive by remember(editingUser) { mutableStateOf(editingUser!!.isActive) }
        var editCustomRoleEnabled by remember(editingUser) { mutableStateOf(!presetRoles.contains(editingUser!!.role) && !futurePresetRoles.contains(editingUser!!.role)) }
        var editCustomRoleText by remember(editingUser) { mutableStateOf(if (editCustomRoleEnabled) editingUser!!.role else "") }
        var editError by remember { mutableStateOf<String?>(null) }

        AlertDialog(
            onDismissRequest = { editingUser = null },
            title = {
                Text("تعديل بيانات الحساب والصلاحيات", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = GBRDarkIndigo)
            },
            text = {
                Column(
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState())
                ) {
                    OutlinedTextField(
                        value = editUsername,
                        onValueChange = { editUsername = it.replace(" ", ""); editError = null },
                        label = { Text("اسم المستخدم (أحرف/أرقام)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp),
                        enabled = editingUser!!.id != "1"
                    )

                    OutlinedTextField(
                        value = editFullName,
                        onValueChange = { editFullName = it },
                        label = { Text("الاسم الكامل للمستخدم") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp)
                    )

                    OutlinedTextField(
                        value = editPass,
                        onValueChange = { editPass = it; editError = null },
                        label = { Text("كلمة المرور الجديدة") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp)
                    )

                    Text("حدد الصلاحية والدور المخصص:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.Gray)
                    
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        (presetRoles + futurePresetRoles).forEach { pRole ->
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { 
                                        editRole = pRole
                                        editCustomRoleEnabled = false
                                        editError = null
                                    }
                                    .padding(vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                RadioButton(
                                    selected = !editCustomRoleEnabled && editRole == pRole,
                                    onClick = {
                                        editRole = pRole
                                        editCustomRoleEnabled = false
                                        editError = null
                                    },
                                    colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                                )
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(pRole, fontSize = 12.sp, color = GBRDarkIndigo)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { 
                                    editCustomRoleEnabled = true 
                                }
                                .padding(vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            RadioButton(
                                selected = editCustomRoleEnabled,
                                onClick = { editCustomRoleEnabled = true },
                                colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("دور صلاحيات مخصص (إدخل يدوي)", fontSize = 12.sp, color = GBRDarkIndigo)
                        }

                        if (editCustomRoleEnabled) {
                            OutlinedTextField(
                                value = editCustomRoleText,
                                onValueChange = { editCustomRoleText = it; editError = null },
                                label = { Text("اكتب المسمى المخصص للدور") },
                                modifier = Modifier.fillMaxWidth(),
                                singleLine = true,
                                shape = RoundedCornerShape(10.dp)
                            )
                        }
                    }

                    if (editingUser!!.id != "1") {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 8.dp)
                        ) {
                            Text("حالة الحساب:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                            Spacer(modifier = Modifier.width(10.dp))
                            Switch(
                                checked = editIsActive,
                                onCheckedChange = { editIsActive = it },
                                colors = SwitchDefaults.colors(checkedThumbColor = SuccessGreen, checkedTrackColor = Color(0xFFD1FAE5))
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(if (editIsActive) "نشط ومصرح بالعمل" else "معطل ومحظور الدخول", fontSize = 11.sp, color = if (editIsActive) SuccessGreen else ErrorRed)
                        }
                    } else {
                        Text("مدير النظام الأساسي نشط دائمًا للحيلولة دون الإغلاق الفجائي", fontSize = 10.sp, color = Color.Gray, modifier = Modifier.padding(top = 4.dp))
                    }

                    if (editError != null) {
                        Text(editError!!, color = Color.Red, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val finalRole = if (editCustomRoleEnabled) editCustomRoleText.trim() else editRole
                        if (editUsername.isBlank() || finalRole.isBlank() || editPass.isBlank()) {
                            editError = "يرجى ملء كافة البيانات الرئيسية الحيوية!"
                        } else {
                            val isSup = finalRole == "مدير النظام" || finalRole == "مشرف الإنتاج" || finalRole.startsWith("مشرف") || finalRole.startsWith("مدير")
                            viewModel.updateCustomUser(
                                userId = editingUser!!.id,
                                username = editUsername.trim(),
                                role = finalRole,
                                password = editPass,
                                isSupervisor = isSup,
                                fullName = editFullName.trim(),
                                isActive = if (editingUser!!.id == "1") true else editIsActive
                            )
                            editingUser = null
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text("حفظ التحديثات", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { editingUser = null }) {
                    Text("إلغاء", color = Color.Gray)
                }
            },
            containerColor = Color.White,
            shape = RoundedCornerShape(20.dp)
        )
    }
}

// Subview 4: معلومات النظام البرمجية وقاعدة البيانات
