}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RecipePanel(viewModel: GbrViewModel) {
    val selectedFormulation by viewModel.selectedFormulation.collectAsState()
    val recipePhases by viewModel.selectedFormulationRecipePhases.collectAsState()
    val recipeItems by viewModel.selectedFormulationRecipeItems.collectAsState()
    val originalPhases by viewModel.originalRecipePhases.collectAsState()
    val originalItems by viewModel.originalRecipeItems.collectAsState()
    val recipeStatusObj by viewModel.selectedFormulationRecipeStatus.collectAsState()
    val formulationItems by viewModel.selectedFormulationDetailItems.collectAsState()
    val formulationsList by viewModel.formulations.collectAsState()
    val context = LocalContext.current
    val saveSuccessMsg = t("تم حفظ تعديلات وصفة التشغيل بنجاح 💾", "Recipe changes saved successfully 💾")

    val isReadOnly = remember(selectedFormulation, formulationsList) {
        val currentCode = selectedFormulation?.code.orEmpty().trim().uppercase()
        if (currentCode.isBlank()) {
            false
        } else {
            val versions = formulationsList.filter { it.code.trim().uppercase() == currentCode }
            val latestId = versions.maxOfOrNull { it.id } ?: -1
            selectedFormulation?.id != latestId
        }
    }

    val hasUnsavedRecipeChanges = remember(recipePhases, originalPhases, recipeItems, originalItems) {
        recipePhases != originalPhases || recipeItems != originalItems
    }

    var showUnsavedChangesDialog by remember { mutableStateOf(false) }

    // Handle back action
    BackHandler {
        if (hasUnsavedRecipeChanges) {
            showUnsavedChangesDialog = true
        } else {
            viewModel.activeSegment.value = "formulations"
        }
    }

    if (selectedFormulation == null) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            Text(t("يرجى اختيار تركيبة أولاً", "Please select a formulation first"), fontSize = 16.sp, fontWeight = FontWeight.Bold, color = Color.Gray)
        }
        return
    }

    val formula = selectedFormulation!!

    val batchWeightDouble = remember(formulationItems) { formulationItems.sumOf { it.quantityMultiplier } }
    val scaleFactor = 1.0

    // Dialog state variables
    var showEditPhaseDialog by remember { mutableStateOf<RecipePhase?>(null) }
    var editPhaseNameInput by remember { mutableStateOf("") }
    var editPhaseRpmInput by remember { mutableStateOf("") }
    var editPhaseDurationInput by remember { mutableStateOf("") }
    var editPhaseInstructionsInput by remember { mutableStateOf("") }

    var showAddPhaseDialog by remember { mutableStateOf(false) }
    var addPhaseNameInput by remember { mutableStateOf("") }

    var showDeletePhaseConfirmation by remember { mutableStateOf<RecipePhase?>(null) }

    var showSplitItemDialog by remember { mutableStateOf<RecipeItem?>(null) }
    var splitAmountInput by remember { mutableStateOf("") }
    
    var showCreatePhaseFromItemDialog by remember { mutableStateOf<RecipeItem?>(null) }
    var splitSelectedTargetPhaseId by remember { mutableStateOf<String?>(null) }
    var showMergeConfirmationDialog by remember { mutableStateOf<Pair<RecipeItem, RecipeItem>?>(null) }
    val flatRecipeItemsList = remember(recipePhases, recipeItems) {
        recipePhases.sortedBy { it.sequence }.flatMap { p ->
            recipeItems.filter { it.phaseId == p.id }.sortedBy { it.sequence }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFFF8FAFC))
            .padding(16.dp)
    ) {
        // Phases scrolling list (everything moves inside so header components are not static/sticky during scrolling)
        LazyColumn(
            modifier = Modifier
                .fillMaxSize(),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            contentPadding = PaddingValues(bottom = 80.dp)
        ) {
            item {
                // 1. Back Button and Page Header Row
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        IconButton(
                            onClick = {
                                if (hasUnsavedRecipeChanges) {
                                    showUnsavedChangesDialog = true
                                } else {
                                    viewModel.activeSegment.value = "formulations"
                                }
                            },
                            modifier = Modifier
                                .clip(RoundedCornerShape(12.dp))
                                .background(Color.LightGray.copy(alpha = 0.2f))
                                .size(40.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.ArrowForward,
                                contentDescription = t("الرجوع", "Back"),
                                tint = GBRBlueMain
                            )
                        }

                        Text(
                            text = if (isReadOnly) t("📋 تقرير وصفة التشغيل (للاطلاع)", "📋 Operating Recipe Report (Read-only)") else t("📖 وصفة التشغيل", "📖 Operating Recipe"),
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Black,
                            color = GBRDarkIndigo
                        )
                    }

                    if (!isReadOnly) {
                        Button(
                            onClick = {
                                viewModel.saveRecipeChanges()
                                Toast.makeText(context, saveSuccessMsg, Toast.LENGTH_SHORT).show()
                            },
                            enabled = hasUnsavedRecipeChanges,
                            colors = ButtonDefaults.buttonColors(
                                containerColor = GBRBlueMain,
                                disabledContainerColor = Color(0xFFE2E8F0),
                                contentColor = Color.White,
                                disabledContentColor = Color(0xFF94A3B8)
                            ),
                            shape = RoundedCornerShape(10.dp),
                            contentPadding = PaddingValues(horizontal = 14.dp, vertical = 8.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Save,
                                contentDescription = null,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = t("حفظ التعديلات", "Save Changes"),
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            }

            if (isReadOnly) {
                item {
                    Surface(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 12.dp),
                        color = Color(0xFFF1F5F9),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Default.Info,
                                contentDescription = null,
                                tint = Color(0xFF475569),
                                modifier = Modifier.size(18.dp)
                            )
                            Text(
                                text = t("تقرير وصفة التشغيل (إصدار قديم - للقراءة فقط) 🔒", "Operating Recipe Report (Older Version - Read-only) 🔒"),
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF475569)
                            )
                        }
                    }
                }
            }

            item {
                // 2. Formulation Details & Status Banner Card
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 16.dp),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column(
                            verticalArrangement = Arrangement.spacedBy(4.dp),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(
                                text = formula.name,
                                fontWeight = FontWeight.Black,
                                fontSize = 16.sp,
                                color = GBRDarkIndigo,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {

                                Surface(
                                    color = GBRBlueMain.copy(alpha = 0.08f),
                                    shape = RoundedCornerShape(6.dp)
                                ) {
                                    Text(
                                        text = t("الإصدار: ${formula.version}", "Version: ${formula.version}"),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRBlueMain,
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                    )
                                }
                            }
                        }

                        // Status Toggler / Indicator Banner
                        val currentStatusStr = recipeStatusObj?.status ?: "READY"
                        Surface(
                            color = if (currentStatusStr == "READY") Color(0xFFDCFCE7) else Color(0xFFFEF3C7),
                            shape = RoundedCornerShape(12.dp),
                            border = BorderStroke(1.dp, if (currentStatusStr == "READY") Color(0xFF86EFAC) else Color(0xFFFDE68A)),
                            modifier = Modifier.then(
                                if (isReadOnly) Modifier else Modifier.clickable {
                                    viewModel.updateRecipeStatus(formula.id, isReady = currentStatusStr != "READY")
                                }
                            )
                        ) {
                            Row(
                                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(8.dp)
                                        .background(
                                            color = if (currentStatusStr == "READY") Color(0xFF16A34A) else Color(0xFFD97706),
                                            shape = CircleShape
                                        )
                                )
                                Text(
                                    text = if (currentStatusStr == "READY") t("جاهزة للإنتاج 🟢", "Ready for Production 🟢") else t("تحتاج مراجعة ⚠️", "Needs Review ⚠️"),
                                    fontWeight = FontWeight.ExtraBold,
                                    fontSize = 12.sp,
                                    color = if (currentStatusStr == "READY") Color(0xFF15803D) else Color(0xFFB45309)
                                )
                            }
                        }
                    }
                }
            }

            item {
                // Card showing Standard Batch details with total weight in the same single line
                Card(
                    modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFF1F5F9)),
                    shape = RoundedCornerShape(12.dp),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.Start,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = t("📋 مراحل وخطوات التشغيل للدفعة القياسية: ${formatQuantity(batchWeightDouble)} كجم", "📋 Operating Steps & Phases for Standard Batch: ${formatQuantity(batchWeightDouble)} kg"),
                                fontSize = 14.sp,
                                fontWeight = FontWeight.Bold,
                                color = GBRDarkIndigo
                            )
                        }
                    }
                }
            }

            item {
                Row(
                    modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = t("الخطوات والمراحل التفصيلية للتشغيل:", "Detailed Operating Steps & Phases:"),
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                }
            }

            itemsIndexed(recipePhases) { phaseIndex, phase ->
                val phaseItemsFiltered = recipeItems
                    .filter { it.phaseId == phase.id }
                    .sortedBy { it.sequence }

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.2.dp, Color(0xFFE2E8F0)),
                    elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                ) {
                    Column(modifier = Modifier.fillMaxWidth().padding(14.dp)) {
                        // Title row
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Surface(
                                    color = GBRDarkIndigo.copy(alpha = 0.1f),
                                    shape = CircleShape,
                                    modifier = Modifier.size(28.dp)
                                ) {
                                    Box(contentAlignment = Alignment.Center) {
                                        Text(
                                            text = "${phaseIndex + 1}",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Black,
                                            color = GBRDarkIndigo
                                        )
                                    }
                                }

                                Text(
                                    text = phase.name,
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.Black,
                                    color = GBRDarkIndigo
                                )
                            }

                            // Controls: Reorder phase, Edit settings, Delete phase
                            if (!isReadOnly) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    // Up Phase
                                    IconButton(
                                        onClick = { viewModel.moveRecipePhaseUpDown(phase, up = true) },
                                        enabled = phaseIndex > 0,
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.KeyboardArrowUp,
                                            contentDescription = t("رفع المرحلة", "Move Phase Up"),
                                            tint = if (phaseIndex > 0) GBRBlueMain else Color.LightGray,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }

                                    // Down Phase
                                    IconButton(
                                        onClick = { viewModel.moveRecipePhaseUpDown(phase, up = false) },
                                        enabled = phaseIndex < recipePhases.size - 1,
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.KeyboardArrowDown,
                                            contentDescription = t("خفض المرحلة", "Move Phase Down"),
                                            tint = if (phaseIndex < recipePhases.size - 1) GBRBlueMain else Color.LightGray,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }

                                    // Edit Settings
                                    IconButton(
                                        onClick = {
                                            editPhaseNameInput = phase.name
                                            editPhaseRpmInput = phase.mixerRpm.toString()
                                            editPhaseDurationInput = phase.durationMinutes.toString()
                                            editPhaseInstructionsInput = phase.instructions
                                            showEditPhaseDialog = phase
                                        },
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Settings,
                                            contentDescription = t("إعدادات المرحلة", "Phase Settings"),
                                            tint = Color(0xFF0F766E),
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }

                                    // Delete Phase Confirmation Check
                                    IconButton(
                                        onClick = { showDeletePhaseConfirmation = phase },
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Delete,
                                            contentDescription = t("حذف المرحلة", "Delete Phase"),
                                            tint = ErrorRed,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                            }
                        }

                        // Settings display badge row
                        Spacer(modifier = Modifier.height(8.dp))
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Surface(
                                color = if (phase.mixerRpm > 0) Color(0xFFEFF6FF) else Color(0xFFF1F5F9),
                                shape = RoundedCornerShape(6.dp)
                            ) {
                                Text(
                                    text = if (phase.mixerRpm > 0) t("الخلط: ${phase.mixerRpm} RPM", "Mixing: ${phase.mixerRpm} RPM") else t("الخلط: غير محدد", "Mixing: Unspecified"),
                                    fontSize = 11.sp,
                                    color = if (phase.mixerRpm > 0) Color(0xFF1E40AF) else Color.Gray,
                                    fontWeight = FontWeight.Bold,
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                )
                            }
                            Surface(
                                color = if (phase.durationMinutes > 0) Color(0xFFFFF7ED) else Color(0xFFF1F5F9),
                                shape = RoundedCornerShape(6.dp)
                            ) {
                                Text(
                                    text = if (phase.durationMinutes > 0) t("الزمن: ${phase.durationMinutes} دقيقة", "Time: ${phase.durationMinutes} min") else t("الزمن: غير محدد", "Time: Unspecified"),
                                    fontSize = 11.sp,
                                    color = if (phase.durationMinutes > 0) Color(0xFFC2410C) else Color.Gray,
                                    fontWeight = FontWeight.Bold,
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = if (phase.instructions.isNotBlank()) t("تعليمات المشغل: ${phase.instructions}", "Operator Instructions: ${phase.instructions}") else t("تعليمات المشغل: غير محدد", "Operator Instructions: Unspecified"),
                            fontSize = 12.sp,
                            color = if (phase.instructions.isNotBlank()) Color(0xFF475569) else Color.LightGray,
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                                .padding(8.dp),
                            fontWeight = FontWeight.Medium,
                            textAlign = TextAlign.Right
                        )

                        Spacer(modifier = Modifier.height(12.dp))
                        HorizontalDivider(color = Color(0xFFF1F5F9))
                        Spacer(modifier = Modifier.height(8.dp))

                        // Materials list
                        if (phaseItemsFiltered.isEmpty()) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 12.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = t("لا توجد مواد داخل هذه المرحلة حالياً", "No materials in this phase currently"),
                                    fontSize = 12.sp,
                                    color = Color.LightGray
                                )
                            }
                        } else {
                            phaseItemsFiltered.forEachIndexed { itemIndex, item ->
                                val formItem = formulationItems.find { it.rawMaterialId == item.rawMaterialId }
                                val quantityMultiplier = formItem?.quantityMultiplier ?: 0.0
                                val displayQty = item.ratio * quantityMultiplier * scaleFactor

                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .then(
                                            if (isReadOnly) Modifier else Modifier.clickable {
                                                if (formItem != null && displayQty > 1.0) {
                                                    splitAmountInput = ""
                                                    showSplitItemDialog = item
                                                }
                                            }
                                        )
                                        .padding(vertical = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.PlayArrow,
                                            contentDescription = null,
                                            tint = GBRBlueMain,
                                            modifier = Modifier.size(14.dp)
                                        )

                                        // Split-step dynamic arrow next to name
                                        if (!isReadOnly) {
                                            IconButton(
                                                onClick = { showCreatePhaseFromItemDialog = item },
                                                modifier = Modifier.size(28.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.KeyboardArrowDown,
                                                    contentDescription = t("إنشاء خطوة جديدة بدءاً من هنا", "Create new step starting here"),
                                                    tint = Color(0xFF0F766E),
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                        }

                                        Column {
                                            Text(
                                                text = formItem?.rawMaterialName ?: t("مادة مجهولة", "Unknown Material"),
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 13.sp,
                                                color = GBRDarkIndigo
                                            )
                                            if (item.ratio < 1.0) {
                                                Text(
                                                    text = t("نسبة التوزيع للدفعة: ${formatQuantity(item.ratio * 100.0)}%", "Batch Distribution Ratio: ${formatQuantity(item.ratio * 100.0)}%"),
                                                    fontSize = 10.sp,
                                                    color = Color.Gray,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }
                                    }

                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                                    ) {
                                        Text(
                                            text = t("${formatQuantity(displayQty)} كجم", "${formatQuantity(displayQty)} kg"),
                                            fontSize = 13.sp,
                                            color = GBRBlueMain,
                                            fontWeight = FontWeight.Black
                                        )

                                        // Item sequencing within phase buttons (Supporting cross-phase move)
                                        if (!isReadOnly) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(2.dp)
                                            ) {
                                                val isUpEnabled = itemIndex > 0 || phaseIndex > 0
                                                IconButton(
                                                    onClick = {
                                                        val itemPos = flatRecipeItemsList.indexOfFirst { it.id == item.id }
                                                        val upperItem = if (itemPos > 0) flatRecipeItemsList[itemPos - 1] else null
                                                        if (upperItem != null && upperItem.rawMaterialId == item.rawMaterialId) {
                                                            showMergeConfirmationDialog = Pair(item, upperItem)
                                                        } else {
                                                            viewModel.moveRecipeItemUpDown(item, up = true)
                                                        }
                                                    },
                                                    enabled = isUpEnabled,
                                                    modifier = Modifier.size(24.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.KeyboardArrowUp,
                                                        contentDescription = t("نقل لأعلى", "Move Up"),
                                                        tint = if (isUpEnabled) GBRBlueMain else Color.LightGray,
                                                        modifier = Modifier.size(16.dp)
                                                    )
                                                }
                                                
                                                val isDownEnabled = itemIndex < phaseItemsFiltered.size - 1 || phaseIndex < recipePhases.size - 1
                                                IconButton(
                                                    onClick = { viewModel.moveRecipeItemUpDown(item, up = false) },
                                                    enabled = isDownEnabled,
                                                    modifier = Modifier.size(24.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.KeyboardArrowDown,
                                                        contentDescription = t("نقل لأسفل", "Move Down"),
                                                        tint = if (isDownEnabled) GBRBlueMain else Color.LightGray,
                                                        modifier = Modifier.size(16.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }

                                if (itemIndex < phaseItemsFiltered.size - 1) {
                                    HorizontalDivider(color = Color(0xFFF8FAFC))
                                }
                            }
                        }
                    }
                }
            }

            if (!isReadOnly) {
                item {
                    Button(
                        onClick = {
                            viewModel.addRecipePhase(formula.id)
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 12.dp, bottom = 16.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                        shape = RoundedCornerShape(12.dp),
                        contentPadding = PaddingValues(vertical = 12.dp)
                    ) {
                        Icon(Icons.Default.Add, contentDescription = null, tint = Color.White, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(t("إضافة مرحلة جديدة ➕", "Add New Phase ➕"), fontSize = 14.sp, fontWeight = FontWeight.Bold, color = Color.White)
                    }
                }
            }
        }
    }

    // Dialog: Add Phase
    if (showAddPhaseDialog) {
        AlertDialog(
            onDismissRequest = { showAddPhaseDialog = false },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = t("إضافة مرحلة جديدة ➕", "Add New Phase ➕"),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    OutlinedTextField(
                        value = addPhaseNameInput,
                        onValueChange = { addPhaseNameInput = it },
                        label = { Text(t("اسم المرحلة", "Phase Name")) },
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (addPhaseNameInput.isNotBlank()) {
                            viewModel.addRecipePhase(formula.id, addPhaseNameInput.trim())
                            showAddPhaseDialog = false
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text(t("إضافة", "Add"), fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { showAddPhaseDialog = false }) {
                    Text(t("إلغاء", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    // Dialog: Edit Phase Settings
    if (showEditPhaseDialog != null) {
        val editingPhase = showEditPhaseDialog!!
        val isFirstPhase = recipePhases.firstOrNull()?.id == editingPhase.id

        AlertDialog(
            onDismissRequest = { showEditPhaseDialog = null },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = t("⚙️ إعدادات المرحلة: ${editingPhase.name}", "⚙️ Phase Settings: ${editingPhase.name}"),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    OutlinedTextField(
                        value = editPhaseNameInput,
                        onValueChange = { editPhaseNameInput = it },
                        label = { Text(t("اسم المرحلة", "Phase Name")) },
                        modifier = Modifier.fillMaxWidth()
                    )

                    OutlinedTextField(
                        value = editPhaseRpmInput,
                        onValueChange = { editPhaseRpmInput = it },
                        label = { Text(t("سرعة الخلاط RPM", "Mixer Speed RPM")) },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        modifier = Modifier.fillMaxWidth()
                    )

                    OutlinedTextField(
                        value = if (isFirstPhase) "0" else editPhaseDurationInput,
                        onValueChange = { if (!isFirstPhase) editPhaseDurationInput = it },
                        label = { Text(if (isFirstPhase) t("مؤقت الخلط (مغلق للمرحلة الأولى) ⏱️", "Mix Timer (Disabled for 1st Phase) ⏱️") else t("مدة الخلط أو الانتظار بالتفصيل (بالدقائق)", "Mixing/Waiting Duration (minutes)")) },
                        enabled = !isFirstPhase,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        modifier = Modifier.fillMaxWidth()
                    )
                    if (isFirstPhase) {
                        Text(
                            text = t("⚠️ يُمنع إضافة مؤقت زمني للمرحلة الأولى لتسهيل تدفق المكونات المبدئية بمرونة.", "⚠️ Timers are disabled for the first phase to allow flexible initial material flow."),
                            fontSize = 11.sp,
                            color = Color(0xFFEF4444),
                            fontWeight = FontWeight.Bold,
                            modifier = Modifier.padding(horizontal = 4.dp)
                        )
                    }

                    OutlinedTextField(
                        value = editPhaseInstructionsInput,
                        onValueChange = { editPhaseInstructionsInput = it },
                        label = { Text(t("تعليمات للمشغل", "Operator Instructions")) },
                        modifier = Modifier.fillMaxWidth(),
                        maxLines = 4
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val rpm = editPhaseRpmInput.toIntOrNull() ?: 0
                        val dur = if (isFirstPhase) 0 else (editPhaseDurationInput.toIntOrNull() ?: 0)
                        viewModel.updateRecipePhase(
                            editingPhase.copy(
                                name = editPhaseNameInput.trim(),
                                mixerRpm = rpm,
                                durationMinutes = dur,
                                instructions = editPhaseInstructionsInput.trim()
                            )
                        )
                        showEditPhaseDialog = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text(t("تطبيق وحفظ", "Apply & Save"), fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { showEditPhaseDialog = null }) {
                    Text(t("إلغاء", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    // Dialog: Split Item
    if (showSplitItemDialog != null) {
        val item = showSplitItemDialog!!
        val formItem = formulationItems.find { it.rawMaterialId == item.rawMaterialId }
        val fOriginalItem = formItem?.let {
            com.example.data.FormulationItem(
                id = it.id,
                formulationId = it.formulationId,
                rawMaterialId = it.rawMaterialId,
                quantityMultiplier = it.quantityMultiplier,
                needsGrinding = it.needsGrinding,
                grindingDurationMinutes = it.grindingDurationMinutes,
                sequence = it.sequence
            )
        }
        val totalQuantity = formItem?.quantityMultiplier ?: 0.0
        val displayQty = item.ratio * totalQuantity

        val otherPhases = recipePhases.filter { it.id != item.phaseId }
        if (splitSelectedTargetPhaseId == null && otherPhases.isNotEmpty()) {
            splitSelectedTargetPhaseId = otherPhases.first().id
        }

        AlertDialog(
            onDismissRequest = { 
                showSplitItemDialog = null
                splitSelectedTargetPhaseId = null
            },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = t("توزيع كمية مادة ⚖️", "Distribute Material Quantity ⚖️"),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Text(
                        text = t("المادة: ${formItem?.rawMaterialName ?: "مجهولة"}", "Material: ${formItem?.rawMaterialName ?: "Unknown"}"),
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp,
                        color = GBRDarkIndigo
                    )
                    Text(
                        text = t("الكمية الحالية في هذه المرحلة: ${formatQuantity(displayQty)} كجم", "Current quantity in this phase: ${formatQuantity(displayQty)} kg"),
                        fontSize = 13.sp,
                        color = Color.Gray
                    )

                    Spacer(modifier = Modifier.height(10.dp))

                    OutlinedTextField(
                        value = splitAmountInput,
                        onValueChange = { splitAmountInput = it },
                        label = { Text(t("ما كمية هذه المرحلة (كجم)؟", "Amount for this phase (kg)?")) },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        modifier = Modifier.fillMaxWidth()
                    )

                    val inputVal = parseUserDouble(splitAmountInput) ?: 0.0
                    val remaining = displayQty - inputVal

                    Spacer(modifier = Modifier.height(6.dp))
                    
                    Text(
                        text = t("اختر المرحلة المستهدفة لنقل المتبقي (${formatQuantity(remaining)} كجم):", "Select target phase to transfer remaining (${formatQuantity(remaining)} kg):"),
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )

                    if (otherPhases.isEmpty()) {
                        Text(
                            text = t("⚠️ لا توجد مراحل أخرى متاحة لنقل الكمية إليها. فضلاً أضف مرحلة جديدة أولاً.", "⚠️ No other phases available. Please add a new phase first."),
                            fontSize = 12.sp,
                            color = ErrorRed
                        )
                    } else {
                        Column(
                            verticalArrangement = Arrangement.spacedBy(6.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            otherPhases.forEach { phaseOption ->
                                val isSelected = splitSelectedTargetPhaseId == phaseOption.id
                                Surface(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { splitSelectedTargetPhaseId = phaseOption.id }
                                        .border(
                                            width = 1.dp,
                                            color = if (isSelected) GBRBlueMain else Color(0xFFE2E8F0),
                                            shape = RoundedCornerShape(10.dp)
                                        ),
                                    color = if (isSelected) GBRBlueMain.copy(alpha = 0.08f) else Color.White,
                                    shape = RoundedCornerShape(10.dp)
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Text(
                                            text = phaseOption.name,
                                            fontSize = 13.sp,
                                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                            color = if (isSelected) GBRBlueMain else GBRDarkIndigo
                                        )
                                        if (isSelected) {
                                            Icon(
                                                imageVector = Icons.Default.Check,
                                                contentDescription = null,
                                                tint = GBRBlueMain,
                                                modifier = Modifier.size(16.dp)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if (inputVal > 0.0 && inputVal < displayQty && splitSelectedTargetPhaseId != null) {
                        val selectedPhaseName = otherPhases.find { it.id == splitSelectedTargetPhaseId }?.name ?: ""
                        Text(
                            text = t("✔️ سيقوم النظام بإبقاء ${formatQuantity(inputVal)} كجم في هذه المرحلة ونقل الباقي (${formatQuantity(remaining)} كجم) تلقائياً إلى: $selectedPhaseName.", "✔️ System will keep ${formatQuantity(inputVal)} kg in this phase and move remaining (${formatQuantity(remaining)} kg) to: $selectedPhaseName."),
                            fontSize = 12.sp,
                            color = Color(0xFF16A34A),
                            fontWeight = FontWeight.Medium
                        )
                    } else if (inputVal >= displayQty && displayQty > 0.0) {
                        Text(
                            text = t("⚠️ الكمية الحالية ${formatQuantity(displayQty)} كجم. الكمية المدخلة التي ستبقى يجب أن تكون أقل من الكمية الحالية.", "⚠️ Current quantity ${formatQuantity(displayQty)} kg. Input amount must be less than current quantity."),
                            fontSize = 12.sp,
                            color = ErrorRed
                        )
                    }
                }
            },
            confirmButton = {
                val inputVal = parseUserDouble(splitAmountInput)
                val targetId = splitSelectedTargetPhaseId
                val isEnabled = inputVal != null && inputVal > 0.0 && inputVal < displayQty && targetId != null && fOriginalItem != null
                Button(
                    onClick = {
                        if (isEnabled) {
                            viewModel.splitRecipeItem(item, targetId!!, inputVal!!, fOriginalItem!!)
                            showSplitItemDialog = null
                            splitSelectedTargetPhaseId = null
                        }
                    },
                    enabled = isEnabled,
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text(t("توزيع الكمية", "Distribute Quantity"), fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { 
                    showSplitItemDialog = null
                    splitSelectedTargetPhaseId = null
                }) {
                    Text(t("إلغاء", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    // Dialog: Confirm Create Phase from Item
    if (showCreatePhaseFromItemDialog != null) {
        val pivotItem = showCreatePhaseFromItemDialog!!
        val formItem = formulationItems.find { it.rawMaterialId == pivotItem.rawMaterialId }
        AlertDialog(
            onDismissRequest = { showCreatePhaseFromItemDialog = null },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = t("إنشاء خطوة جديدة ⚡", "Create New Step ⚡"),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Text(
                    text = t("هل تريد إنشاء خطوة (مرحلة) جديدة تبدأ بـ: (${formItem?.rawMaterialName ?: "هذه المادة"})؟\n\nتأكيد هذا الإجراء سينشئ فوراً مرحلة جديدة ويضع هذه المادة وجميع المواد التي أسفلها في هذه الخطوة الجديدة.", "Do you want to create a new step (phase) starting with: (${formItem?.rawMaterialName ?: "this material"})?\n\nConfirming will create a new phase and place this material and all items below it into the new step."),
                    fontSize = 14.sp,
                    color = Color.DarkGray,
                    textAlign = TextAlign.Right
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.createNewPhaseFromItem(pivotItem)
                        showCreatePhaseFromItemDialog = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text(t("تأكيد وإنشاء خطوة", "Confirm & Create Step"), fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { showCreatePhaseFromItemDialog = null }) {
                    Text(t("إلغاء", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    // Dialog: Confirm Delete Recipe Phase with Material migration
    if (showDeletePhaseConfirmation != null) {
        val phaseToDelete = showDeletePhaseConfirmation!!
        val isLastRemaining = recipePhases.size <= 1
        val phaseItemsCount = recipeItems.filter { it.phaseId == phaseToDelete.id }.size
        
        AlertDialog(
            onDismissRequest = { showDeletePhaseConfirmation = null },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = t("تأكيد حذف المرحلة ⚠️", "Confirm Delete Phase ⚠️"),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = ErrorRed,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Text(
                    text = if (isLastRemaining) {
                        t("إنها المرحلة الوحيدة المتبقية في الوصفة. لا يمكن حذف هذه المرحلة للحفاظ على بنية الوصفة.", "This is the only remaining phase in the recipe. It cannot be deleted to preserve recipe structure.")
                    } else if (phaseItemsCount > 0) {
                        t("هل أنت متأكد من حذف هذه المرحلة؟\n\nتنبيه: تحتوي هذه المرحلة على ($phaseItemsCount) من المواد. سيتم نقل هذه المواد تلقائياً إلى المرحلة التي تسبقها للحفاظ على سلامة الوصفة.", "Are you sure you want to delete this phase?\n\nWarning: This phase contains ($phaseItemsCount) material(s). These materials will automatically be moved to the preceding phase.")
                    } else {
                        t("هل أنت متأكد من حذف هذه المرحلة الفارغة؟", "Are you sure you want to delete this empty phase?")
                    },
                    fontSize = 14.sp,
                    color = Color.DarkGray,
                    textAlign = TextAlign.Right
                )
            },
            confirmButton = {
                if (!isLastRemaining) {
                    Button(
                        onClick = {
                            viewModel.deleteRecipePhase(phaseToDelete)
                            showDeletePhaseConfirmation = null
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = ErrorRed)
                    ) {
                        Text(t("نعم، احذف وانقل المواد", "Yes, Delete & Move Materials"), fontWeight = FontWeight.Bold, color = Color.White)
                    }
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeletePhaseConfirmation = null }) {
                    Text(if (isLastRemaining) t("إغلاق", "Close") else t("إلغاء", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    // Dialog: Confirm Merge Recipe Items
    if (showMergeConfirmationDialog != null) {
        val pair = showMergeConfirmationDialog!!
        val clickedItem = pair.first
        val targetItem = pair.second
        val formItem = formulationItems.find { it.rawMaterialId == clickedItem.rawMaterialId }
        val materialName = formItem?.rawMaterialName ?: t("المادة", "Material")

        AlertDialog(
            onDismissRequest = { showMergeConfirmationDialog = null },
            shape = RoundedCornerShape(20.dp),
            containerColor = Color.White,
            title = {
                Text(
                    text = t("دمج المادة وإلغاء التوزيع 🔄", "Merge Material & Undo Distribution 🔄"),
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
            },
            text = {
                Text(
                    text = t("تم اكتشاف نفس المادة ($materialName) في المرحلة السابقة.\n\nهل ترغب في دمج الكميتين وإلغاء التوزيع؟", "Same material ($materialName) detected in previous phase.\n\nWould you like to merge both quantities and undo distribution?"),
                    fontSize = 14.sp,
                    color = Color.DarkGray,
                    textAlign = TextAlign.Right,
                    modifier = Modifier.fillMaxWidth()
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        viewModel.mergeRecipeItems(clickedItem, targetItem)
                        showMergeConfirmationDialog = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text(t("دمج المادة", "Merge Material"), fontWeight = FontWeight.Bold, color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showMergeConfirmationDialog = null }) {
                    Text(t("إلغاء", "Cancel"), color = Color.Gray, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    if (showUnsavedChangesDialog) {
        androidx.compose.ui.window.Dialog(
            onDismissRequest = { showUnsavedChangesDialog = false }
        ) {
            Card(
                shape = RoundedCornerShape(20.dp),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 12.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(50.dp)
                            .clip(CircleShape)
                            .background(Color(0xFFFEF3C7)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Warning,
                            contentDescription = null,
                            tint = Color(0xFFD97706),
                            modifier = Modifier.size(26.dp)
                        )
                    }

                    Text(
                        text = t("حفظ تغييرات وصفة التشغيل ⚠️", "Save Recipe Changes ⚠️"),
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo,
                        textAlign = TextAlign.Center
                    )

                    Text(
                        text = t(
                            "لقد قمت بإجراء تعديلات على وصفة التشغيل ولم تقم بحفظها بعد.\nهل ترغب في حفظ التغييرات قبل الخروج أم تجاهلها؟",
                            "You have unsaved changes in the operating recipe.\nWould you like to save changes before exiting or discard them?"
                        ),
                        fontSize = 13.sp,
                        color = Color(0xFF475569),
                        textAlign = TextAlign.Center,
                        lineHeight = 19.sp
                    )

                    Spacer(modifier = Modifier.height(4.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        OutlinedButton(
                            onClick = {
                                viewModel.discardRecipeChanges()
                                showUnsavedChangesDialog = false
                                viewModel.activeSegment.value = "formulations"
                            },
                            modifier = Modifier
                                .weight(1f)
                                .height(42.dp),
                            shape = RoundedCornerShape(10.dp),
                            border = BorderStroke(1.dp, Color(0xFFEF4444)),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFFDC2626)),
                            contentPadding = PaddingValues(horizontal = 4.dp, vertical = 0.dp)
                        ) {
                            Text(
                                text = t("تجاهل والتراجع ❌", "Discard & Exit ❌"),
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                maxLines = 1
                            )
                        }

                        Button(
                            onClick = {
                                viewModel.saveRecipeChanges()
                                showUnsavedChangesDialog = false
                                Toast.makeText(context, saveSuccessMsg, Toast.LENGTH_SHORT).show()
                                viewModel.activeSegment.value = "formulations"
                            },
                            modifier = Modifier
                                .weight(1f)
                                .height(42.dp),
                            shape = RoundedCornerShape(10.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                            contentPadding = PaddingValues(horizontal = 4.dp, vertical = 0.dp)
                        ) {
                            Text(
                                text = t("حفظ والتراجع 💾", "Save & Exit 💾"),
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White,
                                maxLines = 1
                            )
                        }
                    }
                }
            }
        }
    }
}

