@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AppPropertiesSubView(viewModel: GbrViewModel) {
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    // Branding State
    val brandCompany by viewModel.companyName.collectAsState()
    val brandApp by viewModel.appNamePref.collectAsState()
    val brandLogo by viewModel.companyLogoUri.collectAsState()
    val brandIcon by viewModel.appIconUri.collectAsState()
    val brandLoginImg by viewModel.loginImageUri.collectAsState()

    var inputCompany by remember { mutableStateOf(brandCompany) }
    var inputApp by remember { mutableStateOf(brandApp) }
    var inputLogo by remember { mutableStateOf(brandLogo ?: "") }
    var inputIcon by remember { mutableStateOf(brandIcon ?: "") }
    var inputLoginImg by remember { mutableStateOf(brandLoginImg ?: "") }

    var validationError by remember { mutableStateOf<String?>(null) }
    var showAppPropertiesConfirmation by remember { mutableStateOf(false) }

    fun validateImageInput(url: String, type: String): Boolean {
        if (url.isEmpty()) return true
        val lower = url.trim().lowercase()
        val isPng = lower.endsWith(".png")
        val isJpg = lower.endsWith(".jpg") || lower.endsWith(".jpeg")
        
        if (type == "logo" && !isPng && !isJpg) {
            validationError = if (lang == "ar") {
                "خطأ: شعار الشركة يجب أن يكون بصيغة PNG أو JPG!"
            } else {
                "Error: Company logo must be in PNG or JPG format!"
            }
            return false
        }
        if (type == "icon" && !isPng) {
            validationError = if (lang == "ar") {
                "خطأ: أيقونة التطبيق يجب أن تكون بصيغة PNG فقط!"
            } else {
                "Error: App icon must be PNG format only!"
            }
            return false
        }
        if (type == "login" && !isPng && !isJpg) {
            validationError = if (lang == "ar") {
                "خطأ: شاشة تسجيل الدخول يجب أن تكون بصيغة PNG أو JPG!"
            } else {
                "Error: Login splash image must be PNG or JPG format!"
            }
            return false
        }
        validationError = null
        return true
    }

    Column(
        verticalArrangement = Arrangement.spacedBy(16.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "🎨 " + t("هوية التطبيق وتعديل الشعار", "App Identity & Custom Logos"),
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                if (validationError != null) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFFFEF2F2), RoundedCornerShape(8.dp))
                            .border(1.dp, Color(0xFFFCA5A5), RoundedCornerShape(8.dp))
                            .padding(10.dp)
                    ) {
                        Text(
                            text = validationError!!,
                            color = Color(0xFFDC2626),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                OutlinedTextField(
                    value = inputCompany,
                    onValueChange = { inputCompany = it },
                    label = { Text(t("اسم الشركة", "Company Name")) },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(10.dp)
                )

                OutlinedTextField(
                    value = inputApp,
                    onValueChange = { inputApp = it },
                    label = { Text(t("اسم التطبيق", "App Name")) },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(10.dp)
                )

                Divider(modifier = Modifier.padding(vertical = 4.dp))

                Column(modifier = Modifier.fillMaxWidth()) {
                    OutlinedTextField(
                        value = inputLogo,
                        onValueChange = {
                            inputLogo = it
                            validateImageInput(it, "logo")
                        },
                        label = { Text(t("رابط شعار الشركة", "Company Logo URL")) },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "📋 " + t("المواصفات: PNG أو JPG | خلفية شفافة | المقاس المقترح 512×512", "Specs: PNG or JPG | transparent background | size 512x512"),
                        fontSize = 10.5.sp,
                        color = Color.Gray
                    )
                }

                Column(modifier = Modifier.fillMaxWidth()) {
                    OutlinedTextField(
                        value = inputIcon,
                        onValueChange = {
                            inputIcon = it
                            validateImageInput(it, "icon")
                        },
                        label = { Text(t("رابط أيقونة التطبيق", "App Icon URL")) },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "📋 " + t("المواصفات: PNG فقط | مربعة | المقاس المقترح 1024×1024", "Specs: PNG only | square | size 1024x1024"),
                        fontSize = 10.5.sp,
                        color = Color.Gray
                    )
                }

                Column(modifier = Modifier.fillMaxWidth()) {
                    OutlinedTextField(
                        value = inputLoginImg,
                        onValueChange = {
                            inputLoginImg = it
                            validateImageInput(it, "login")
                        },
                        label = { Text(t("صورة شاشة تسجيل الدخول", "Login Screen Image URL")) },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "📋 " + t("المواصفات: نسبة شاشة مناسبة | الحجم المقترح 1920×1080", "Specs: Wide screen aspect ratio | size 1920x1080"),
                        fontSize = 10.5.sp,
                        color = Color.Gray
                    )
                }

                Spacer(modifier = Modifier.height(6.dp))

                Button(
                    onClick = {
                        if (validateImageInput(inputLogo, "logo") &&
                            validateImageInput(inputIcon, "icon") &&
                            validateImageInput(inputLoginImg, "login")
                        ) {
                            showAppPropertiesConfirmation = true
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(10.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen)
                ) {
                    Text(
                        text = t("تحديث هوية وشعار التطبيق 💾", "Save Brand Customizations 💾"),
                        fontWeight = FontWeight.Bold,
                        color = Color.White
                    )
                }
            }
        }
    }

    if (showAppPropertiesConfirmation) {
        AlertDialog(
            onDismissRequest = { showAppPropertiesConfirmation = false },
            title = {
                Text(text = t("تأكيد تعديل الهوية", "Confirm Brand Changes"), fontSize = 16.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
            },
            text = {
                Text(
                    text = t(
                        "هل أنت متأكد من رغبتك في تطبيق التغييرات على هوية واسم وشعار التطبيق؟ ستنعكس التعديلات فورياً في جميع أنحاء النظام وشاشات التشغيل.",
                        "Are you sure you want to apply changes to app identity, title, and corporate logos? The modifications will instantly propagate across the environment."
                    ),
                    fontSize = 13.sp,
                    color = Color.DarkGray,
                    lineHeight = 18.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        showAppPropertiesConfirmation = false
                        viewModel.updateAppIdentity(
                            company = inputCompany,
                            app = inputApp,
                            logo = inputLogo.ifBlank { null },
                            icon = inputIcon.ifBlank { null },
                            loginImg = inputLoginImg.ifBlank { null }
                        )
                        android.widget.Toast.makeText(context, t("تم تحديث وحفظ هوية التطبيق بنجاح!", "App brand custom identity updated successfully!"), android.widget.Toast.LENGTH_SHORT).show()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen)
                ) {
                    Text(t("تأكيد العملية", "Confirm Action"), fontWeight = FontWeight.Bold, color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showAppPropertiesConfirmation = false }) {
                    Text(t("تراجع", "Cancel"), color = Color.Gray)
                }
            },
            shape = RoundedCornerShape(16.dp)
        )
    }
}

@Composable
fun AppearanceLanguageSettingsSubView(viewModel: GbrViewModel) {
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val themeStr by viewModel.appTheme.collectAsState()

    Column(
        verticalArrangement = Arrangement.spacedBy(16.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            border = BorderStroke(1.5.dp, IndustrialBorder)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "🌐 " + s().settingsCatAppearanceLanguage,
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )

                Text(
                    text = s().settingsCatAppearanceLanguageSub,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.Gray
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    val isAr = lang == "ar"
                    Button(
                        onClick = { viewModel.updateLanguage("ar") },
                        modifier = Modifier.weight(1f),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (isAr) GBRBlueMain else Color.LightGray.copy(alpha = 0.3f),
                            contentColor = if (isAr) Color.White else Color.DarkGray
                        ),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Text("العربية (Arabic)", fontWeight = FontWeight.Bold)
                    }

                    Button(
                        onClick = { viewModel.updateLanguage("en") },
                        modifier = Modifier.weight(1f),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (!isAr) GBRBlueMain else Color.LightGray.copy(alpha = 0.3f),
                            contentColor = if (!isAr) Color.White else Color.DarkGray
                        ),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Text("English (الإنجليزية)", fontWeight = FontWeight.Bold)
                    }
                }

                Spacer(modifier = Modifier.height(6.dp))

                Text(
                    text = s().appThemeLabel,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.Gray
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    val modes = listOf("light", "dark", "system")
                    val modeLabelsAr = listOf("فاتح", "داكن", "تلقائي")
                    val modeLabelsEn = listOf("Light", "Dark", "System")
                    
                    modes.forEachIndexed { idx, mode ->
                        val isSel = themeStr == mode
                        Button(
                            onClick = { viewModel.updateTheme(mode) },
                            modifier = Modifier.weight(1f),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (isSel) GBRPinkAccent else Color.LightGray.copy(alpha = 0.3f),
                                contentColor = if (isSel) Color.White else Color.DarkGray
                            ),
                            shape = RoundedCornerShape(8.dp),
                            contentPadding = PaddingValues(0.dp)
                        ) {
                            Text(
                                text = if (lang == "ar") modeLabelsAr[idx] else modeLabelsEn[idx],
                                fontSize = 11.5.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun PrintSettingsSubView(viewModel: GbrViewModel) {
