@Composable
fun HostingerHostingSubView(viewModel: GbrViewModel) {
    val lang by viewModel.appLanguage.collectAsState()
    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    var readmeText by remember { mutableStateOf("") }
    LaunchedEffect(Unit) {
        try {
            readmeText = context.assets.open("hostinger/README.md").bufferedReader().use { it.readText() }
        } catch (e: Exception) {
            readmeText = t("جاري تحميل التعليمات...", "Loading documentation...")
        }
    }

    var pendingDownloadFile by remember { mutableStateOf<String?>(null) }

    val createDocLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.CreateDocument("*/*")
    ) { uri: Uri? ->
        if (uri != null && pendingDownloadFile != null) {
            val fileName = pendingDownloadFile!!
            try {
                if (fileName == "Hostinger_Storage.zip") {
                    context.contentResolver.openOutputStream(uri)?.use { outputStream ->
                        java.util.zip.ZipOutputStream(outputStream).use { zipOut ->
                            val files = listOf("health.php", "upload.php", "delete.php", "README.md")
                            for (fName in files) {
                                val assetPath = "hostinger/$fName"
                                context.assets.open(assetPath).use { inputStream ->
                                    zipOut.putNextEntry(java.util.zip.ZipEntry(fName))
                                    inputStream.copyTo(zipOut)
                                    zipOut.closeEntry()
                                }
                            }
                            // Create empty folders inside the zip package
                            val folders = listOf("tds/", "images/", "lab/")
                            for (folder in folders) {
                                zipOut.putNextEntry(java.util.zip.ZipEntry(folder))
                                zipOut.closeEntry()
                            }
                        }
                    }
                    Toast.makeText(context, t("تم تحميل الحزمة الكاملة ZIP بنجاح! 📦", "Full ZIP package downloaded successfully! 📦"), Toast.LENGTH_SHORT).show()
                } else {
                    context.contentResolver.openOutputStream(uri)?.use { outputStream ->
                        context.assets.open("hostinger/$fileName").use { inputStream ->
                            inputStream.copyTo(outputStream)
                        }
                    }
                    Toast.makeText(context, t("تم تحميل ملف $fileName بنجاح! 📥", "$fileName downloaded successfully! 📥"), Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                e.printStackTrace()
                Toast.makeText(context, t("فشل تحميل الملف: ${e.message}", "Failed to download file: ${e.message}"), Toast.LENGTH_LONG).show()
            } finally {
                pendingDownloadFile = null
            }
        }
    }

    val hostingerGatewayUrl by viewModel.hostingerGatewayUrl.collectAsState()
    val hostingerEnabled by viewModel.hostingerEnabled.collectAsState()
    val hostingerStats by viewModel.hostingerStats.collectAsState(initial = null)

    LaunchedEffect(Unit) {
        viewModel.refreshHostingerStats()
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // Warning Banner
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = Color(0xFFF0FDF4)),
            border = BorderStroke(1.dp, Color(0xFFBBF7D0))
        ) {
            Row(
                modifier = Modifier.padding(12.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(36.dp)
                        .clip(CircleShape)
                        .background(Color(0xFFDCFCE7)),
                    contentAlignment = Alignment.Center
                ) {
                    Text("💡", fontSize = 16.sp)
                }
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = t("المرحلة المتقدمة لربط استضافة Hostinger 🌐", "Advanced Shift to Hostinger Hosting 🌐"),
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF15803D)
                    )
                    Text(
                        text = t(
                            "يمكنك الآن إدخال مسار بوابة الرفع على استضافتك لاختبار صحة المجلدات والملفات وتفعيل الربط المباشر. عند تفعيل الربط، سيعتمد التطبيق Hostinger كمزود التخزين السحابي الوحيد بدلاً من Firebase Storage لكافة مستندات الـ TDS، صور التركيبات، ومرفقات المختبر.",
                            "You can now enter your hosting upload gateway URL to test directory health, script access, and enable live linking. Once enabled, GBR app relies solely on Hostinger for all TDS documents, formulation images, and laboratory attachments."
                        ),
                        fontSize = 11.sp,
                        color = Color(0xFF166534)
                    )
                }
            }
        }

        // ------------------ HOSTINGER CONNECTION CONSOLE ------------------
        var urlInput by remember(hostingerGatewayUrl) { mutableStateOf(hostingerGatewayUrl) }
        var isCheckingConnection by remember { mutableStateOf(false) }
        var connectionCheckResult by remember { mutableStateOf<com.example.data.ConnectionResult?>(null) }
        
        val isLinked = hostingerEnabled
        
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // ADDED: Stats
                hostingerStats?.let { stats ->
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        border = BorderStroke(1.dp, GBRBlueMain.copy(alpha = 0.3f))
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("📊", fontSize = 20.sp)
                            Column {
                                Text(t("إجمالي الملفات المرتبطة:", "Total Linked Files:"), fontSize = 11.sp, color = Color.Gray)
                                Text("${stats.totalFiles}", fontSize = 16.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                            }
                        }
                    }
                }
                
                // Header of Console
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(32.dp)
                            .clip(CircleShape)
                            .background(if (isLinked) Color(0xFF16A34A) else Color(0xFF94A3B8)),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = if (isLinked) "🟢" else "⚪",
                            fontSize = 12.sp
                        )
                    }
                    Column {
                        Text(
                            text = t("لوحة تفعيل بوابة التخزين Hostinger", "Hostinger Storage Control Panel"),
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )
                        Text(
                            text = if (isLinked) {
                                t("الاستضافة مفعلة كمزود تخزين وحيد نشط حالياً 🌐 (Firebase Storage معطل)", "Hosting is active as the sole storage provider 🌐 (Firebase Discontinued)")
                            } else {
                                t("الاستضافة غير نشطة حالياً (تخزين Firebase نشط افتراضياً)", "Hosting is currently inactive (Firebase cloud is active default)")
                            },
                            fontSize = 11.sp,
                            color = if (isLinked) Color(0xFF16A34A) else Color.Gray,
                            fontWeight = if (isLinked) FontWeight.Bold else FontWeight.Normal
                        )
                    }
                }

                Divider(color = IndustrialBorder.copy(alpha = 0.5f))

                // Input Field
                Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    Text(
                        text = t("رابط مسار التخزين الخاص بالاستضافة (URL Gateway):", "Hosting Storage Path (Gateway URL):"),
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                    OutlinedTextField(
                        value = urlInput,
                        onValueChange = { urlInput = it },
                        placeholder = { Text("مثال: https://deco.ps/gbr_storage/", fontSize = 12.sp) },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        textStyle = TextStyle(fontSize = 13.sp, fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace),
                        shape = RoundedCornerShape(8.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = GBRBlueMain,
                            unfocusedBorderColor = IndustrialBorder
                        )
                    )
                    Text(
                        text = t(
                            "يرجى كتابة الرابط مع علامة التحسين المائل في النهاية. يجب رفع ملفات PHP داخل هذا المجلد تماماً.",
                            "Please specify the complete URL ending with a slash. PHP files must be placed directly in this folder."
                        ),
                        fontSize = 10.sp,
                        color = Color.Gray
                    )
                }

                // Check connection button
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Button(
                        onClick = {
                            isCheckingConnection = true
                            connectionCheckResult = null
                            scope.launch {
                                // Combined verify and adopt
                                val result = viewModel.verifyAndAdoptHostingerUrl(urlInput)
                                connectionCheckResult = result
                                if (result.success) {
                                    val finalUrl = com.example.data.HostingerStorageManager.normalizeUrl(urlInput)
                                    viewModel.updateHostingerSettings(finalUrl, true)
                                    Toast.makeText(context, t("تم التحقق واعتماد المسار الجديد! 🌐", "Connection verified and path adopted! 🌐"), Toast.LENGTH_SHORT).show()
                                }
                                isCheckingConnection = false
                            }
                        },
                        enabled = !isCheckingConnection && urlInput.isNotBlank(),
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth().height(42.dp)
                    ) {
                        if (isCheckingConnection) {
                            CircularProgressIndicator(modifier = Modifier.size(18.dp), color = Color.White, strokeWidth = 2.dp)
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(t("جاري التحقق والاعتماد...", "Verifying and adopting..."), fontSize = 11.sp, color = Color.White)
                        } else {
                            Text(t("✅ التحقق من الربط واعتماده", "✅ Verify Gateway & Adopt"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.White)
                        }
                    }
                }

                // Connection Check Result Alert
                connectionCheckResult?.let { res ->
                    val bgColor = if (res.success) Color(0xFFF0FDF4) else Color(0xFFFEF2F2)
                    val borderColor = if (res.success) Color(0xFFBBF7D0) else Color(0xFFFCA5A5)
                    val textColor = if (res.success) Color(0xFF166534) else Color(0xFF991B1B)
                    
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = bgColor),
                        border = BorderStroke(1.dp, borderColor)
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text(if (res.success) "✅" else "❌", fontSize = 16.sp)
                            Text(
                                text = res.message,
                                fontSize = 11.sp,
                                color = textColor,
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                }

                Divider(color = IndustrialBorder.copy(alpha = 0.5f))

                // Link Hostinger Storage Action Trigger
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (isLinked) Color(0xFFDCFCE7) else Color(0xFFF1F5F9))
                        .padding(12.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = t("ربط واعتماد بوابة Hostinger كمزود تخزين وحيد", "Adopt Hostinger as Sole Storage Provider"),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )
                        Text(
                            text = t(
                                "تحويل تخزين كافة مستندات الشرح، صور التركيبات، ومرفقات المختبر إلى Hostinger تماماً وإيقاف Firebase",
                                "Redirects all formulation images, TDS documents, and lab attachments to Hostinger and turns off Firebase"
                            ),
                            fontSize = 10.sp,
                            color = Color.Gray
                        )
                    }

                    Switch(
                        checked = isLinked,
                        onCheckedChange = { checked ->
                            if (checked) {
                                val isTestedOk = connectionCheckResult?.success == true
                                if (isTestedOk || (urlInput == hostingerGatewayUrl && hostingerGatewayUrl.isNotBlank())) {
                                    val finalUrl = com.example.data.HostingerStorageManager.normalizeUrl(urlInput)
                                    viewModel.updateHostingerSettings(finalUrl, true)
                                    Toast.makeText(context, t("تم تفعيل بوابة Hostinger بنجاح! تم الاستغناء الكلي عن Firebase Storage. 🌐", "Hostinger Gateway linked successfully! Discontinued Firebase Storage completely. 🌐"), Toast.LENGTH_LONG).show()
                                } else {
                                    Toast.makeText(context, t("يرجى فحص الاتصال بالخادم بنجاح أولاً قبل محاولة ربط واعتماد البوابة!", "Please verify host connection successfully first before linkage adoption!"), Toast.LENGTH_LONG).show()
                                }
                            } else {
                                viewModel.updateHostingerSettings(urlInput, false)
                                Toast.makeText(context, t("تم إيقاف الربط والرجوع التلقائي إلى الرفع على Firebase Storage", "Disconnected Hostinger and reverted back to default Firebase Storage"), Toast.LENGTH_SHORT).show()
                            }
                        },
                        colors = SwitchDefaults.colors(
                            checkedThumbColor = Color.White,
                            checkedTrackColor = Color(0xFF16A34A),
                            uncheckedThumbColor = Color.Gray,
                            uncheckedTrackColor = Color(0xFFE2E8F0)
                        )
                    )
                }
            }
        }

        // Complete ZIP package
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = Color(0xFFEFF6FF)),
            border = BorderStroke(1.5.dp, Color(0xFFBFDBFE))
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    text = t("📦 تحميل حزمة الاستضافة الكاملة (الكل في ملف ZIP واحد)", "📦 Download Complete Hosting Package (All in one ZIP)"),
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF1E40AF),
                    textAlign = TextAlign.Center
                )
                Text(
                    text = t(
                        "تحتوي هذه الحزمة المجهّزة على كافة ملفات PHP الثلاثة (upload, delete, health) ومستند الشرح والتعليمات لتسهيل عملية الرفع دفعة واحدة على Hostinger.",
                        "This prepackaged zip contains all three PHP files (upload, delete, health) and the documentation to easily upload to Hostinger in one step."
                    ),
                    fontSize = 11.sp,
                    color = Color(0xFF1E3A8A),
                    textAlign = TextAlign.Center
                )
                Button(
                    onClick = {
                        pendingDownloadFile = "Hostinger_Storage.zip"
                        createDocLauncher.launch("Hostinger_Storage.zip")
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2563EB)),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.fillMaxWidth().height(42.dp)
                ) {
                    Icon(imageVector = Icons.Default.Share, contentDescription = null, modifier = Modifier.size(16.dp), tint = Color.White)
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(t("تحميل حزمة الاستضافة (ZIP) ⬇️", "Download Hosting Zip ⬇️"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
            }
        }

        Divider(color = IndustrialBorder)

        // Individual File Downloads
        Text(
            text = t("📄 الملفات الفردية لبرمجيات الاستضافة:", "📄 Individual Hosting Scripts & Files:"),
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold,
            color = GBRDarkIndigo
        )

        val scripts = listOf(
            Triple("upload.php", t("ملف استقبال ورفع الملفات بأمان وتوجيهها للمجلدات المختصة", "Receives and safely processes file uploads into respective directories"), "php"),
            Triple("delete.php", t("ملف الحذف الفوري والآمن للمستندات، صور التركيبات، ومرفقات المختبر من على خادم الاستضافة", "Securely purges raw materials PDFs, formulation images, and lab attachments from storage"), "php"),
            Triple("health.php", t("ملف اختبار الصحة وفحص الجاهزية وإصدار PHP وصلاحيات المجلدات", "Queries directory status, engine compatibility, and server write permissions"), "php"),
            Triple("README.md", t("مستند الدليل التوجيهي وهيكل المجلدات المطلوب داخل public_html", "Setup guide and public_html folder architecture guidelines"), "markdown")
        )

        scripts.forEach { (fileName, description, ext) ->
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                border = BorderStroke(1.dp, IndustrialBorder)
            ) {
                Row(
                    modifier = Modifier.padding(12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (ext == "php") Color(0xFFEEF2F6) else Color(0xFFFFF7ED)),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = if (ext == "php") "🐘" else "📝",
                            fontSize = 16.sp
                        )
                    }

                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = fileName,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )
                        Text(
                            text = description,
                            fontSize = 10.sp,
                            color = Color.Gray
                        )
                    }

                    Button(
                        onClick = {
                            pendingDownloadFile = fileName
                            createDocLauncher.launch(fileName)
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp),
                        modifier = Modifier.height(30.dp),
                        shape = RoundedCornerShape(6.dp)
                    ) {
                        Text(t("تحميل 📥", "Get 📥"), fontSize = 10.sp, color = Color.White)
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(8.dp))

        // Live Guide Display Box
        Text(
            text = t("📖 دليل الربط ونظرية العمل المباشرة:", "📖 Live Documentation & Guide:"),
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold,
            color = GBRDarkIndigo
        )

        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = Color(0xFFFAF9F6)),
            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text(
                    text = readmeText,
                    fontSize = 11.sp,
                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace,
                    color = Color(0xFF334155),
                    lineHeight = 15.sp,
                    modifier = Modifier.fillMaxWidth()
                )
            }
        }
    }
}

@Composable
fun DatabaseSettingsSubView(viewModel: GbrViewModel) {
    val lang by viewModel.appLanguage.collectAsState()
    val lastSyncRawMaterials by viewModel.syncLastRawMaterials.collectAsState()
    val lastSyncFormulations by viewModel.syncLastFormulations.collectAsState()
    val lastSyncProductionOrders by viewModel.syncLastProductionOrders.collectAsState()
    val globalSyncStatus by viewModel.globalSyncStatus.collectAsState()
    val syncStatusMessage by viewModel.syncStatusMessage.collectAsState()
    val pendingSyncCount by viewModel.pendingSyncCount.collectAsState()
    val currentSyncReport by viewModel.currentSyncReport.collectAsState()
    val showSyncReportDialog by viewModel.showSyncReportDialog.collectAsState()
    val showSyncProgressDialog by viewModel.showSyncProgressDialog.collectAsState()
    val showHostingWarningAlert by viewModel.showHostingWarningAlert.collectAsState()
    val syncProgressPercent by viewModel.syncProgressPercent.collectAsState()
    val syncProgressMessage by viewModel.syncProgressMessage.collectAsState()

    fun t(ar: String, en: String): String = if (lang == "ar") ar else en
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    val syncPrefs = remember { context.getSharedPreferences("gbr_sync_prefs", android.content.Context.MODE_PRIVATE) }
    var fbProjectId by remember { mutableStateOf(syncPrefs.getString("fb_project_id", "") ?: "") }
    var fbApiKey by remember { mutableStateOf(syncPrefs.getString("fb_api_key", "") ?: "") }
    var fbAppId by remember { mutableStateOf(syncPrefs.getString("fb_app_id", "") ?: "") }

    // Cloud connection state and popup variables
    var showConnectionStatusDialog by remember { mutableStateOf(false) }
    var statusDialogProjectName by remember { mutableStateOf("") }
    var statusDialogFirestoreConnected by remember { mutableStateOf(false) }
    var statusDialogStorageConnected by remember { mutableStateOf(false) }
    var statusDialogErrorMessage by remember { mutableStateOf<String?>(null) }
    var isTestingImportConnection by remember { mutableStateOf(false) }
    
    // Choose between 0 = Smart Import (google-services.json), 1 = Manual Entry
    var syncSetupMethod by remember { mutableStateOf(0) }
    var maskApiKey by remember { mutableStateOf(true) }

    val vmActiveTab by viewModel.databaseSettingsActiveTab.collectAsState()
    var activeTab by remember { mutableStateOf(vmActiveTab) }
    LaunchedEffect(vmActiveTab) {
        activeTab = vmActiveTab
    }
    val tabsList = listOf(
        t("إعدادات الاتصال والمزامنة", "Sync & Connection"),
        t("Firebase والسحابة", "Firebase & Cloud"),
        t("بوابة ربط Hostinger", "Hostinger Gateway"),
        t("النسخ الاحتياطي والاستعادة", "Backup & Restore"),
        t("سجل النظام", "System Logs"),
        "سجل النشاط"
    )

    var exportPayload by remember { mutableStateOf<String?>(null) }
    var importInputText by remember { mutableStateOf("") }
    var importAnalysisResult by remember { mutableStateOf<GbrViewModel.ImportAnalysis?>(null) }
    var importStatusMessage by remember { mutableStateOf<String?>(null) }

    var isFullExportNew by remember { mutableStateOf(true) }
    var selectedExportSectionsNew by remember { mutableStateOf(com.example.data.BackupManager.sections.map { it.key }.toSet()) }

    // Selected import strategy
    var selectedStrategy by remember { mutableStateOf(1) } // 1 = Smart Merge, 2 = Overwrite, 3 = Preview only

    // Encryption & Decryption states
    var showEncryptionPasswordDialog by remember { mutableStateOf(false) }
    var encryptionPasswordInput by remember { mutableStateOf("") }
    var encryptionPasswordConfirmInput by remember { mutableStateOf("") }
    var encryptionPasswordError by remember { mutableStateOf<String?>(null) }
    var pendingExportFormat by remember { mutableStateOf<String?>(null) } // "json" or "zip"
    var encryptedExportPayloadBytes by remember { mutableStateOf<ByteArray?>(null) }

    var showDecryptionPasswordDialog by remember { mutableStateOf(false) }
    var decryptionPasswordInput by remember { mutableStateOf("") }
    var decryptionPasswordError by remember { mutableStateOf<String?>(null) }
    var pendingImportBytes by remember { mutableStateOf<ByteArray?>(null) }

    // Export progress popup dialog states
    var showExportProgressDialog by remember { mutableStateOf(false) }
    var exportProgressStep by remember { mutableStateOf(1) } // 1: التدقيق, 2: المراجعة, 3: الإعداد والتشفير, 4: النجاح (إتمامه)
    var exportProgressPercent by remember { mutableStateOf(0.25f) }
    var exportProgressStatusText by remember { mutableStateOf("") }
    var exportSummaryType by remember { mutableStateOf("") }
    var exportSummaryFormat by remember { mutableStateOf("") }
    var exportSummarySize by remember { mutableStateOf("") }
    var exportSummaryDate by remember { mutableStateOf("") }

    // Import progress popup dialog states
    var showImportProgressDialog by remember { mutableStateOf(false) }
    var importProgressStep by remember { mutableStateOf(1) } // 1: التدقيق والتحقق, 2: المعالجة والدمج, 3: التحديث, 4: النجاح (إتمامه)
    var importProgressPercent by remember { mutableStateOf(0.25f) }
    var importProgressStatusText by remember { mutableStateOf("") }
    var importSummaryStrategy by remember { mutableStateOf("") }
    var importSummarySections by remember { mutableStateOf("") }
    var importSummaryItemsCount by remember { mutableStateOf("") }
    var importSummaryDate by remember { mutableStateOf("") }

    val cloudStats by viewModel.cloudCleanupStats.collectAsState()
    val isFetchingCloudStats by viewModel.isFetchingCloudCleanupStats.collectAsState()

    LaunchedEffect(Unit) {
        viewModel.fetchCloudCleanupStats()
    }

    // Unsaved Changes connection settings parameters
    val currentSyncMode by viewModel.syncMode.collectAsState()
    var selectedSyncModeTemp by remember(currentSyncMode) { mutableStateOf(currentSyncMode) }
    val hasUnsavedChanges = selectedSyncModeTemp != currentSyncMode

    // Keep GbrViewModel state in sync so parent SettingsPanel detects it
    LaunchedEffect(hasUnsavedChanges) {
        viewModel.hasUnsavedConnectionSettingsInUi.value = hasUnsavedChanges
    }

    // Tab switching intercept check
    var showUnsavedWarningForTabSwitch by remember { mutableStateOf(false) }
    var pendingTabSwitchIndex by remember { mutableStateOf(0) }

    // Connection Report Modal state values
    var showConnectionReportDialog by remember { mutableStateOf(false) }
    var reportConnectionStatus by remember { mutableStateOf("") } // SUCCESS, WARNING, FAILURE
    var reportSuccess by remember { mutableStateOf(false) }
    var reportFirebaseProject by remember { mutableStateOf("") }
    var reportCollectionsCount by remember { mutableStateOf(0) }
    var reportPingLatency by remember { mutableStateOf(0L) }
    var reportLastSuccessTime by remember { mutableStateOf("") }
    var reportErrorDetails by remember { mutableStateOf<String?>(null) }

    // Export formats launchers
    val createGbrLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.CreateDocument("application/octet-stream")
    ) { uri ->
        if (uri != null) {
            scope.launch(Dispatchers.IO) {
                try {
                    context.contentResolver.openOutputStream(uri)?.use { outputStream ->
                        val bytes = encryptedExportPayloadBytes ?: byteArrayOf()
                        outputStream.write(bytes)
                        
                        val sizeStr = String.format(java.util.Locale.US, "%.2f KB", bytes.size.toDouble() / 1024.0)
                        val backupType = if (pendingExportFormat == "zip") "GBR (Compressed & Encrypted)" else "GBR (Encrypted)"
                        viewModel.recordBackupCreated(sizeStr, backupType)
                        viewModel.addSystemLog("backup", "تم إنشاء نسخة احتياطية مشفرة بنجاح بصيغة GBR (الحجم: $sizeStr)")
                        withContext(Dispatchers.Main) {
                            exportSummarySize = sizeStr
                            exportProgressStep = 4
                            exportProgressPercent = 1.0f
                            exportProgressStatusText = t("تمت عملية التصدير وحفظ الملف بنجاح!", "Export completed and file saved successfully!")
                            Toast.makeText(context, t("🎉 تم حفظ ملف النسخة الاحتياطية المشفرة بنجاح!", "🎉 Encrypted backup file saved successfully!"), Toast.LENGTH_LONG).show()
                        }
                    }
                } catch (e: Exception) {
                    viewModel.addSystemLog("error", "فشل في حفظ ملف النسخة الاحتياطية GBR: ${e.localizedMessage}")
                    withContext(Dispatchers.Main) {
                        showExportProgressDialog = false
                        Toast.makeText(context, "Error saving GBR backup: ${e.localizedMessage}", Toast.LENGTH_LONG).show()
                    }
                }
            }
        } else {
            showExportProgressDialog = false
        }
    }

    val createJsonLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.CreateDocument("application/json")
    ) { uri ->
        if (uri != null) {
            scope.launch(Dispatchers.IO) {
                try {
                    context.contentResolver.openOutputStream(uri)?.use { outputStream ->
                        val payload = exportPayload ?: ""
