    fun runCloudConnectionTestAndShowStatusDialog(projId: String, bucket: String) {
        statusDialogProjectName = projId
        showConnectionStatusDialog = true
        isTestingImportConnection = true
        statusDialogFirestoreConnected = false
        statusDialogStorageConnected = false
        statusDialogErrorMessage = null
        
        scope.launch(Dispatchers.IO) {
            val isOnline = SyncManager.isNetworkAvailable(context)
            if (!isOnline) {
                withContext(Dispatchers.Main) {
                    isTestingImportConnection = false
                    statusDialogErrorMessage = t(
                        "❌ لا توجد شبكة إنترنت نشطة للتحقق من الاتصال السحابي.",
                        "❌ No active internet connection found to perform verification."
                    )
                }
                return@launch
            }
            
            var firestoreOk = false
            var storageOk = false
            var errorDetails = ""
            
            // 0. Ensure we are authenticated with Firebase Auth to pass Security Rules
            try {
                val auth = com.google.firebase.auth.FirebaseAuth.getInstance()
                if (auth.currentUser == null) {
                    android.util.Log.i("FirebaseTest", "No active session found during verification. Performing synchronous sign-in...")
                    com.google.android.gms.tasks.Tasks.await(auth.signInAnonymously(), 10, java.util.concurrent.TimeUnit.SECONDS)
                    android.util.Log.i("FirebaseTest", "Synchronous Anonymous Auth check passed successfully!")
                }
            } catch (e: Exception) {
                android.util.Log.w("FirebaseTest", "Warning during Anonymous Auth check: ${e.message}")
                errorDetails += "\nAuthentication: ${e.localizedMessage}"
            }
            
            // 1. Test Firestore Database Connectivity
            try {
                val db = com.google.firebase.firestore.FirebaseFirestore.getInstance()
                com.google.android.gms.tasks.Tasks.await(db.collection("sync_metadata").limit(1).get(), 8, java.util.concurrent.TimeUnit.SECONDS)
                firestoreOk = true
            } catch (e: Exception) {
                android.util.Log.e("FirebaseTest", "Firestore error during verification", e)
                errorDetails += "\nFirestore: ${e.localizedMessage}"
            }
            
            // 2. Test Cloud Storage Access Link
            try {
                val storage = com.google.firebase.storage.FirebaseStorage.getInstance()
                val b = storage.reference.bucket
                if (b.isNotBlank()) {
                    storageOk = true
                }
            } catch (e: Exception) {
                android.util.Log.e("FirebaseTest", "Storage error during verification", e)
                errorDetails += "\nFirebase Storage: ${e.localizedMessage}"
            }
            
            withContext(Dispatchers.Main) {
                isTestingImportConnection = false
                statusDialogFirestoreConnected = firestoreOk
                statusDialogStorageConnected = storageOk
                if (!firestoreOk) {
                    statusDialogErrorMessage = t(
                        "فشل الاتصال ببعض الخدمات السحابية. يرجى مراجعة الصلاحيات والتحقق ورمز الحماية:\n" + errorDetails,
                        "Failed to reach sub-services. Please verify your config, keys or Firestore security rules:\n" + errorDetails
                    )
                } else {
                    viewModel.addSystemLog("sync", "تم التحقق الكامل من استيراد إعدادات السحابة بنجاح لمشروع: $projId")
                }
            }
        }
    }

    val googleServicesPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.OpenDocument()
    ) { uri ->
        if (uri != null) {
            scope.launch(Dispatchers.IO) {
                try {
                    context.contentResolver.openInputStream(uri)?.use { inputStream ->
                        val content = inputStream.readBytes().toString(Charsets.UTF_8)
                        withContext(Dispatchers.Main) {
                            try {
                                val json = org.json.JSONObject(content)
                                var parsedProjectId = ""
                                var parsedApiKey = ""
                                var parsedAppId = ""
                                var parsedStorageBucket = ""

                                if (json.has("gbr_cloud_config")) {
                                    parsedProjectId = json.optString("fb_project_id", "")
                                    parsedApiKey = json.optString("fb_api_key", "")
                                    parsedAppId = json.optString("fb_app_id", "")
                                    parsedStorageBucket = json.optString("fb_storage_bucket", "")
                                } else if (json.has("project_info")) {
                                    val projectInfo = json.optJSONObject("project_info")
                                    parsedProjectId = projectInfo?.optString("project_id") ?: ""
                                    parsedStorageBucket = projectInfo?.optString("storage_bucket") ?: ""
                                    
                                    val clientArray = json.optJSONArray("client")
                                    if (clientArray != null && clientArray.length() > 0) {
                                        val clientObj = clientArray.optJSONObject(0)
                                        val clientInfo = clientObj?.optJSONObject("client_info")
                                        parsedAppId = clientInfo?.optString("mobilesdk_app_id") ?: ""
                                        
                                        val apiKeyArray = clientObj?.optJSONArray("api_key")
                                        if (apiKeyArray != null && apiKeyArray.length() > 0) {
                                            val apiKeyObj = apiKeyArray.optJSONObject(0)
                                            parsedApiKey = apiKeyObj?.optString("current_key") ?: ""
                                        }
                                    }
                                }

                                if (parsedProjectId.isBlank() || parsedApiKey.isBlank() || parsedAppId.isBlank()) {
                                    Toast.makeText(context, t("❌ الملف المختار لا يحتوي على بيانات Firebase صالحة!", "❌ Selected file does not contain valid Firebase properties!"), Toast.LENGTH_LONG).show()
                                } else {
                                    if (parsedStorageBucket.isNotBlank()) {
                                        syncPrefs.edit().putString("fb_storage_bucket", parsedStorageBucket.trim()).apply()
                                    }

                                    // Fill the input boxes
                                    fbProjectId = parsedProjectId.trim()
                                    fbApiKey = parsedApiKey.trim()
                                    fbAppId = parsedAppId.trim()

                                    // Automatically switch to the Manual Setup tab and notify user to review and save
                                    syncSetupMethod = 1
                                    Toast.makeText(context, t("📋 تم استخراج بيانات السحابة بنجاح وإدراجها في خانات الإدخال. يرجى الضغط على زر حفظ وتطبيق الإعدادات.", "📋 Cloud credentials parsed and loaded into manual inputs. Please click 'Save Cloud Configurations' to apply."), Toast.LENGTH_LONG).show()

                                    viewModel.addSystemLog("sync", "تم استخراج إعدادات السحابة من الملف بنجاح وإدراجها في خانات الإدخال اليدوي: $parsedProjectId")
                                }
                            } catch (e: Exception) {
                                Toast.makeText(context, t("❌ فشل قراءة هيكل ملف JSON: ", "❌ Error parsing JSON format: ") + e.localizedMessage, Toast.LENGTH_LONG).show()
                            }
                        }
                    }
                } catch (e: Exception) {
                    withContext(Dispatchers.Main) {
                        Toast.makeText(context, "Error: " + e.localizedMessage, Toast.LENGTH_LONG).show()
                    }
                }
            }
        }
    }

