    fun runCloudConnectionTest() {
        isTestingConnection = true
        reportErrorDetails = null
        reportCollectionsCount = 0
        reportPingLatency = 0L
        reportFirebaseProject = fbProjectId.trim().ifEmpty { "غير محدد / Unspecified" }
        connectionTestResult = t("جاري فحص الاستجابة بمصافحة خوادم السحابة...", "Pinging cloud node API...")
        
        scope.launch(Dispatchers.IO) {
            val isOnline = SyncManager.isNetworkAvailable(context)
            if (!isOnline) {
                withContext(Dispatchers.Main) {
                    reportSuccess = false
                    reportConnectionStatus = "FAILURE"
                    reportErrorDetails = t("الهاتف غير متصل بأي شبكة إنترنت نشطة 📶", "No active internet connection found.")
                    showConnectionReportDialog = true
                    connectionTestResult = t("❌ فشل الاتصال: الهاتف غير متصل بالإنترنت", "❌ Connection Failed: Device Offline")
                    isTestingConnection = false
                }
                return@launch
            }
            
            val startTime = System.currentTimeMillis()
            var collectionsOk = 0
            
            try {
                // Test primary collection list to calculate discovered schemas count
                val db = com.google.firebase.firestore.FirebaseFirestore.getInstance()
                val collectionsToTest = listOf(
                    "raw_materials",
                    "formulations",
                    "production_orders",
                    "recipe_phases",
                    "recipe_items",
                    "system_logs"
                )
                
                // Track latency of the metadata handshake request
                com.google.android.gms.tasks.Tasks.await(db.collection("sync_metadata").limit(1).get(), 8, java.util.concurrent.TimeUnit.SECONDS)
                val latency = System.currentTimeMillis() - startTime
                
                // Test the read accessibility of each catalog collection
                for (col in collectionsToTest) {
                    try {
                        com.google.android.gms.tasks.Tasks.await(db.collection(col).limit(1).get(), 4, java.util.concurrent.TimeUnit.SECONDS)
                        collectionsOk++
                    } catch (e: Exception) {
                        android.util.Log.e("GBR_PING_COL", "Collection $col query failed: ${e.localizedMessage}")
                    }
                }
                
                withContext(Dispatchers.Main) {
                    reportSuccess = true
                    reportPingLatency = latency
                    reportCollectionsCount = collectionsOk
                    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault())
                    reportLastSuccessTime = sdf.format(java.util.Date())
                    reportConnectionStatus = if (latency > 2500) "WARNING" else "SUCCESS"
                    syncPrefs.edit().putString("last_successful_test_time", reportLastSuccessTime).apply()
                    
                    showConnectionReportDialog = true
                    connectionTestResult = t("✅ المزامنة جاهزة! الاتصال مستقر والاستجابة سريعة جداً.", "✅ Connection Stable! Latitude handshake verified.")
                    isTestingConnection = false
                    viewModel.addSystemLog("sync", "تم فحص الاتصال السحابي بنجاح: الاستجابة ${latency}ms")
                }
                
            } catch (e: Exception) {
                val latency = System.currentTimeMillis() - startTime
                withContext(Dispatchers.Main) {
                    reportSuccess = false
                    reportConnectionStatus = "FAILURE"
                    reportPingLatency = latency
                    reportErrorDetails = e.localizedMessage ?: "حدث خطأ غير معروف في خوادم Google Firestore."
                    
                    showConnectionReportDialog = true
                    connectionTestResult = t("❌ فشل الاتصال: تلمس سجل التفاصيل المرفقة", "❌ Handshake Failed: Inspect error logs")
                    isTestingConnection = false
                    viewModel.addSystemLog("error", "فشل فحص الاتصال السحابي: ${e.localizedMessage}")
                }
            }
        }
    }

