                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(text = label, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.DarkGray)
                                    Text(text = status, fontSize = 9.sp, color = Color.Gray)
                                }
                                if (currentSyncMode == "manual") {
                                    IconButton(
