                                )
                            }

                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (syncSetupMethod == 1) Color.White else Color.Transparent)
                                    .clickable { syncSetupMethod = 1 }
                                    .padding(vertical = 8.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = t("الإدخال اليدوي 🛠️", "Manual Setup 🛠️"),
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (syncSetupMethod == 1) GBRBlueMain else Color.Gray
