                                border = BorderStroke(1.dp, Color.LightGray.copy(alpha = 0.3f))
                            ) {
                                Column(
                                    modifier = Modifier.padding(14.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Settings,
                                        contentDescription = null,
                                        tint = GBRBlueMain,
                                        modifier = Modifier.size(36.dp)
                                    )

                                    Text(
                                        text = t("استيراد إعدادات Firebase تلقائيًا", "Import Firebase Config Automatically"),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color.DarkGray
                                    )

                                    Text(
                                        text = t(
                                            "اختر ملف google-services.json المستخرج من خدمة Firebase لنظامك وسيتم استخراج وتجربة الاتصال السحابي بالكامل.",
                                            "Select the google-services.json file extracted from your Firebase console, and we will extract and test sync connectivity."
                                        ),
                                        fontSize = 10.sp,
                                        color = Color.Gray,
                                        textAlign = TextAlign.Center,
                                        lineHeight = 14.sp
                                    )

                                    Button(
                                        onClick = { googleServicesPickerLauncher.launch(arrayOf("application/json")) },
                                        shape = RoundedCornerShape(8.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                        modifier = Modifier.fillMaxWidth().testTag("import_firebase_file_btn")
                                    ) {
                                        Text(
                                            text = t("استيراد ملف Firebase 📄", "Select Firebase File 📄"),
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        } else {
                            // Manual Input Settings Layout
                            Column(
                                verticalArrangement = Arrangement.spacedBy(8.dp),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                OutlinedTextField(
                                    value = fbProjectId,
                                    onValueChange = { fbProjectId = it },
                                    label = { Text(t("معرّف المشروع السحابي (Project ID)", "Project ID"), fontSize = 11.sp) },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(8.dp),
                                    singleLine = true
                                )

                                OutlinedTextField(
                                    value = fbApiKey,
                                    onValueChange = { fbApiKey = it },
                                    label = { Text(t("مفتاح واجهة السحابة (Firebase API Key)", "Firebase API Key"), fontSize = 11.sp) },
                                    modifier = Modifier.fillMaxWidth(),
