                                            .putString("fb_api_key", fbApiKey.trim())
                                            .putString("fb_app_id", fbAppId.trim())
                                            .apply()
                                        
                                        viewModel.addSystemLog("backup", "تمت تهيئة إعدادات المزامنة السحابية يدوياً")
                                        Toast.makeText(context, t("🎉 تم حفظ وتطبيق الإعدادات بنجاح!", "🎉 Configuration stored successfully!"), Toast.LENGTH_LONG).show()
                                        
                                        // Re-initialize Firebase, register device, test connection, and trigger sync sequentially
                                        scope.launch(Dispatchers.IO) {
                                            val initSuccess = SyncManager.initializeFirebase(context)
                                            if (initSuccess) {
                                                val isLocalPrimary = context.getSharedPreferences("gbr_device_security_prefs", android.content.Context.MODE_PRIVATE).getBoolean("is_primary", false)
                                                if (isLocalPrimary) {
                                                    com.example.data.DeviceSecurityManager.ensureDeviceRegisteredOnCloud(context)
                                                } else {
                                                    com.example.data.DeviceSecurityManager.sendRegistrationRequestToCloud(context)
                                                }
                                                com.example.data.DeviceSecurityManager.startRealtimeStatusListener(context)
                                                val status = com.example.data.DeviceSecurityManager.verifyDeviceStatus(context)
                                                if (status == com.example.data.DeviceSecurityManager.STATUS_APPROVED) {
                                                    if (viewModel.syncMode.value == "realtime") {
                                                        SyncManager.startRealtimeListeners(context, viewModel.repository)
                                                    }
                                                    withContext(Dispatchers.Main) {
                                                        viewModel.triggerManualSync("all", force = true)
                                                    }
                                                } else {
                                                    withContext(Dispatchers.Main) {
                                                        Toast.makeText(context, t("⏳ تم إرسال طلب الاعتماد إلى السحابة بنجاح! بانتظار موافقة هاتف المسؤول.", "⏳ Device registration sent to cloud! Awaiting admin approval."), Toast.LENGTH_LONG).show()
                                                    }
                                                }
                                            } else {
                                                withContext(Dispatchers.Main) {
                                                    Toast.makeText(context, t("❌ فشل الاتصال بالسحابة: يرجى التأكد من صحة المفاتيح والاتصال بالإنترنت.", "❌ Cloud connection failed! Please check credentials and connection."), Toast.LENGTH_LONG).show()
                                                }
                                            }
                                        }
