                                ) {
                                    Text(
                                        text = t("⚙️ التكوين السحابي النشط حالياً:", "Active Cloud Node Summary:"),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color.DarkGray
                                    )

                                    Row(horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                                        Text(text = "Project:", fontSize = 10.5.sp, color = Color.Gray)
                                        Text(text = fbProjectId, fontSize = 10.5.sp, fontWeight = FontWeight.Bold, color = Color.DarkGray)
                                    }

                                    Row(horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                                        Text(text = "API Key:", fontSize = 10.5.sp, color = Color.Gray)
                                        val masked = if (fbApiKey.length > 10) fbApiKey.substring(0, 7) + "..." + fbApiKey.substring(fbApiKey.length - 4) else "••••••••"
                                        Text(text = masked, fontSize = 10.5.sp, fontWeight = FontWeight.Bold, color = Color.Gray)
                                    }

                                    Row(horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                                        Text(text = "Storage Bucket:", fontSize = 10.5.sp, color = Color.Gray)
                                        val storedBucket = syncPrefs.getString("fb_storage_bucket", "") ?: (fbProjectId + ".firebasestorage.app")
                                        Text(text = storedBucket.ifBlank { "N/A" }, fontSize = 10.5.sp, color = Color.DarkGray)
                                    }
                                }
                            }

                            val currentDeviceStatus by com.example.data.DeviceSecurityManager.deviceStatus.collectAsState()
                            if (currentDeviceStatus == com.example.data.DeviceSecurityManager.STATUS_PENDING) {
                                Spacer(modifier = Modifier.height(10.dp))
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                                    border = BorderStroke(1.5.dp, Color(0xFFFDE68A))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(14.dp),
                                        verticalArrangement = Arrangement.spacedBy(10.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Warning,
                                                contentDescription = null,
                                                tint = WarningOrange,
                                                modifier = Modifier.size(24.dp)
                                            )
                                            Text(
                                                text = t("⏳ هذا الجهاز بانتظار الاعتماد السحابي", "Device Awaiting Cloud Approval"),
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color(0xFF92400E)
                                            )
                                        }
                                        
                                        Text(
                                            text = t(
                                                "تم تسجيل هذا الهاتف بنجاح كجهاز معلق (Pending). للاعتماد وبدء المزامنة فوراً، يمكنك إدخال الرمز الأمني الثابت المعتمد أو اعتماده من الهاتف الرئيسي.",
                                                "This phone was registered successfully as pending. To authorize and start sync immediately, enter the recovery code below or approve it from the primary phone."
                                            ),
                                            fontSize = 10.sp,
                                            color = Color.DarkGray,
                                            lineHeight = 14.sp
                                        )
                                        
                                        var settingsRecoveryInput by remember { mutableStateOf("") }
                                        var isSettingsRecovering by remember { mutableStateOf(false) }
                                        
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            OutlinedTextField(
                                                value = settingsRecoveryInput,
                                                onValueChange = { settingsRecoveryInput = it },
                                                placeholder = { Text("GBR-XXXX-XXXX-XXXX") },
                                                modifier = Modifier.weight(1f),
                                                singleLine = true,
                                                colors = OutlinedTextFieldDefaults.colors(
                                                    focusedBorderColor = GBRBlueMain,
                                                    unfocusedBorderColor = Color.LightGray
                                                )
                                            )
                                            Button(
                                                onClick = {
                                                    scope.launch {
                                                        isSettingsRecovering = true
                                                        val success = com.example.data.DeviceSecurityManager.recoverSystem(context, settingsRecoveryInput)
                                                        isSettingsRecovering = false
                                                        if (success) {
                                                            settingsRecoveryInput = ""
                                                            Toast.makeText(context, t("🎉 تم اعتماد هذا الجهاز بنجاح كمسؤول رئيسي!", "🎉 Device authorized successfully!"), Toast.LENGTH_LONG).show()
                                                            com.example.data.SyncManager.initializeFirebase(context)
                                                            if (viewModel.syncMode.value == "realtime") {
                                                                com.example.data.SyncManager.startRealtimeListeners(context, viewModel.repository)
                                                            }
                                                            viewModel.triggerManualSync("all", force = true)
                                                        } else {
                                                            Toast.makeText(context, t("❌ الرمز المدخل غير صحيح أو لا يوجد اتصال بالإنترنت!", "❌ Invalid code or no internet connection!"), Toast.LENGTH_LONG).show()
                                                        }
                                                    }
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                                enabled = settingsRecoveryInput.isNotEmpty() && !isSettingsRecovering,
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.height(48.dp)
                                            ) {
                                                if (isSettingsRecovering) {
                                                    CircularProgressIndicator(color = Color.White, modifier = Modifier.size(16.dp))
                                                } else {
                                                    Text(t("اعتماد 🔓", "Authorize 🔓"), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                        }
                                        
                                        var isRetryingConnection by remember { mutableStateOf(false) }
                                        
                                        Spacer(modifier = Modifier.height(6.dp))
