                                                    isRetryingConnection = true
                                                    val res = com.example.data.DeviceSecurityManager.verifyDeviceStatus(context)
                                                    isRetryingConnection = false
                                                    if (res == com.example.data.DeviceSecurityManager.STATUS_APPROVED) {
                                                        Toast.makeText(context, t("🎉 رائع! تم اعتماد وتنشيط جهازك بنجاح من المسؤول!", "🎉 Excellent! Your device has been successfully approved by the admin!"), Toast.LENGTH_LONG).show()
                                                        com.example.data.SyncManager.initializeFirebase(context)
                                                        if (viewModel.syncMode.value == "realtime") {
                                                            com.example.data.SyncManager.startRealtimeListeners(context, viewModel.repository)
                                                        }
                                                        viewModel.triggerManualSync("all", force = true)
                                                    } else {
                                                        Toast.makeText(context, t("⏳ تم تحديث الاتصال وإعادة تسجيل الجهاز بالسحابة بنجاح! يرجى الطلب من المسؤول اعتماده من هاتفه الرئيسي.", "⏳ Connection refreshed & device re-registered! Please ask the admin to approve this device from their primary phone."), Toast.LENGTH_LONG).show()
                                                    }
                                                }
                                            },
                                            colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFFD97706)),
                                            border = BorderStroke(1.2.dp, Color(0xFFF59E0B)),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.fillMaxWidth().height(40.dp),
                                            enabled = !isRetryingConnection
                                        ) {
                                            if (isRetryingConnection) {
                                                CircularProgressIndicator(color = Color(0xFFD97706), modifier = Modifier.size(16.dp))
                                            } else {
                                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                    Text("🔄", fontSize = 12.sp)
                                                    Text(t("تحديث ومحاولة الاتصال بالسحابة مجدداً", "Retry & Refresh Cloud Connection"), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Future Ready: Export & Import Connections Config (Seamless configuration of other phones/tablets in seconds)
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(1.dp)
                                .background(Color.LightGray.copy(alpha = 0.3f))
                        )

                        Text(
                            text = "📲 " + t("إعداد الأجهزة والتابلت الجديدة خلال ثوانٍ", "Migrate/Sync Config to other Devices"),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Button(
