                            ) {
                                Text(text = t("تصدير الإعدادات 📤", "Export Config 📤"), fontSize = 10.sp, fontWeight = FontWeight.Bold)
                            }

                            Button(
                                onClick = { googleServicesPickerLauncher.launch(arrayOf("application/json")) },
                                modifier = Modifier.weight(1f),
                                shape = RoundedCornerShape(8.dp),
                                colors = ButtonDefaults.buttonColors(containerColor = Color.DarkGray)
                            ) {
                                Text(text = t("استيراد الإعدادات 📥", "Import Config 📥"), fontSize = 10.sp, fontWeight = FontWeight.Bold)
                            }
                        }

                        Spacer(modifier = Modifier.height(12.dp))

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFAF5FF)),
                            border = BorderStroke(1.dp, Color(0xFFE9D5FF))
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Text(text = "🧹", fontSize = 16.sp)
                                        Text(
                                            text = t("مساعد تطهير وتنظيف قاعدة البيانات السحابية", "Cloud Database Purge & Cleanup Assistant"),
                                            fontSize = 12.5.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF6B21A8)
                                        )
                                    }

                                    IconButton(
                                        onClick = { viewModel.fetchCloudCleanupStats() },
                                        modifier = Modifier.size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Refresh,
                                            contentDescription = "تحديث الفحص",
                                            tint = Color(0xFF7E22CE),
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }

                                Text(
                                    text = t(
                                        "يقوم المساعد الذكي تلقائياً بفحص السحابة للتعرف على السجلات القديمة والملغاة من التطبيق، ويعرض عليك توصيات ذكية وإحصائيات الحجم الفعلي لتسريع المزامنة وحماية مواردك.",
                                        "This smart assistant dynamically checks Firestore to identify orphaned or deprecated collections. It provides actionable advisory tips and real-time document counts to protect your cloud storage."
                                    ),
                                    fontSize = 10.sp,
                                    color = Color(0xFF581C87),
                                    lineHeight = 14.sp
                                )

                                Divider(color = Color(0xFFF3E8FF))

                                val purgableCollections = listOf(
                                    Triple(
                                        "mail",
                                        t("البريد الإلكتروني والأكواد الأمنية (mail)", "Security Emails (mail)"),
                                        t("تحتوي على رسائل تأكيد أكواد الاسترداد. تم إيقاف المزامنة والكتابة إليها تماماً بناءً على طلبك.", "Contains past secure emails. We have disabled all writes to this collection.")
                                    ),
                                    Triple(
                                        "quality_tests",
                                        t("مجموعة الفحوصات الملغاة (quality_tests)", "Old Quality Tests (quality_tests)"),
                                        t("تحتوي على الفحوصات المرجعية القديمة للمعمل قبل إلغاء الميزة واستبدالها.", "Contains old laboratory QA test categories before the feature upgrade.")
                                    ),
                                    Triple(
                                        "system_logs",
                                        t("سجلات عمليات النظام (system_logs)", "System Operational Logs (system_logs)"),
                                        t("سجل النظام الفني والتحذيرات. يمكنك تصفيرها بالكامل من الهاتف والسحابة لإنعاش الأداء.", "Operational runtime logs. Purge to refresh database performance completely.")
                                    )
                                )

                                if (isFetchingCloudStats) {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 12.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            CircularProgressIndicator(
                                                modifier = Modifier.size(16.dp),
                                                color = Color(0xFF7E22CE),
                                                strokeWidth = 2.dp
                                            )
                                            Text(
                                                text = t("جاري سحب الإحصائيات الذكية من Firestore... 🔎", "Querying smart stats from Firestore... 🔎"),
                                                fontSize = 10.sp,
                                                color = Color(0xFF6B21A8)
                                            )
                                        }
                                    }
                                }

                                purgableCollections.forEach { (colName, colTitle, colDesc) ->
                                    val count = cloudStats[colName]
                                    
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(Color.White, RoundedCornerShape(8.dp))
                                            .border(1.dp, Color(0xFFF3E8FF), RoundedCornerShape(8.dp))
                                            .padding(10.dp),
                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(text = colTitle, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF581C87))
                                            
                                            // Dynamic Status Badge
                                            when {
                                                count == null -> {
                                                    Text(
                                                        text = t("جاري الفحص... 🔎", "Checking... 🔎"),
                                                        fontSize = 8.5.sp,
                                                        color = Color.Gray,
                                                        modifier = Modifier
                                                            .background(Color(0xFFF3F4F6), RoundedCornerShape(4.dp))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                                count == -1 -> {
                                                    Text(
                                                        text = t("فشل الفحص ⚠️", "Inaccessible ⚠️"),
                                                        fontSize = 8.5.sp,
                                                        color = Color(0xFF991B1B),
                                                        modifier = Modifier
                                                            .background(Color(0xFFFEF2F2), RoundedCornerShape(4.dp))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                                count == 0 -> {
                                                    Text(
                                                        text = t("مطهر بنجاح (0) 🟢", "Fully Purged (0) 🟢"),
                                                        fontSize = 8.5.sp,
                                                        color = Color(0xFF166534),
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier
                                                            .background(Color(0xFFF0FDF4), RoundedCornerShape(4.dp))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                                count > 0 -> {
                                                    Text(
                                                        text = t("نشط سحابياً ($count مستند) ⚠️", "Active in Cloud ($count docs) ⚠️"),
                                                        fontSize = 8.5.sp,
                                                        color = Color(0xFF92400E),
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier
                                                            .background(Color(0xFFFFFBEB), RoundedCornerShape(4.dp))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                            }
                                        }

                                        Text(text = colDesc, fontSize = 9.sp, color = Color.Gray, lineHeight = 12.sp)

                                        // Dynamic Advisory / Space Recommendations Box
                                        val advisoryTip = when {
                                            count == null -> null
                                            count == -1 -> t(
                                                "⚠️ توصية: تعذر الاتصال بـ Firestore لقراءة السجلات. تأكد من إعداد ملف google-services.json وصلاحيات الاتصال بالشبكة.",
                                                "⚠️ Advice: Could not read collection size. Verify your internet connection or google-services.json setup."
                                            )
                                            count == 0 -> t(
                                                "✨ حالة ممتازة: تم مسح هذا السجل بالكامل وتصفيته سحابياً بنجاح. لا داعي لاتخاذ أي إجراء.",
                                                "✨ Excellent: Collection is clean and holds 0 entries in the cloud. No action needed."
                                            )
                                            count > 0 -> {
                                                when (colName) {
                                                    "mail" -> {
                                                        val sizeKB = String.format(java.util.Locale.US, "%.2f", count * 0.4)
                                                        t(
                                                            "🧼 نصيحة ذكية: تستهلك هذه البيانات المتروكة سحابياً حوالي ${sizeKB}KB من حصة قراءات Firestore المجانية. تطهيرها الفوري آمن وموصى به لتوفير المساحة السحابية.",
                                                            "🧼 Smart Tip: This leftover data consumes about ${sizeKB}KB of Firestore capacity. Wiping it is 100% safe and highly recommended to optimize cloud limits."
                                                        )
                                                    }
                                                    "quality_tests" -> {
                                                        val sizeKB = String.format(java.util.Locale.US, "%.2f", count * 0.8)
                                                        t(
                                                            "🧼 نصيحة ذكية: الفحوصات الملغاة تستهلك حوالي ${sizeKB}KB وتتسبب في تداخل واستعلامات دمج معقدة في الخلفية. التطهير السحابي يمنع التشويش تماماً.",
                                                            "🧼 Smart Tip: Deprecated laboratory checks consume ${sizeKB}KB and may cause sync interference. Wiping them prevents backend clutter entirely."
                                                        )
                                                    }
                                                    "system_logs" -> {
                                                        val sizeKB = String.format(java.util.Locale.US, "%.2f", count * 0.6)
                                                        t(
                                                            "🧼 نصيحة ذكية: سجل العمليات يحتوي على $count عملية سحابية غير نشطة بمجموع ${sizeKB}KB. تصفير السجل سحابياً ومحلياً دورياً ينعش سرعة المزامنة والاتصال 🚀.",
                                                            "🧼 Smart Tip: Operations log contains $count entries consuming about ${sizeKB}KB. Clearing it refreshes sync speed & mobile database response times 🚀."
                                                        )
                                                    }
                                                    else -> null
                                                }
                                            }
                                            else -> null
                                        }

                                        if (advisoryTip != null) {
                                            Box(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(
                                                        if (count == 0) Color(0xFFF0FDF4) else if (count == -1) Color(0xFFF9FAFB) else Color(0xFFFEF3C7).copy(alpha = 0.4f),
                                                        RoundedCornerShape(6.dp)
                                                    )
                                                    .border(
                                                        1.dp,
                                                        if (count == 0) Color(0xFFDCFCE7) else if (count == -1) Color(0xFFE5E7EB) else Color(0xFFFDE68A).copy(alpha = 0.6f),
                                                        RoundedCornerShape(6.dp)
                                                    )
                                                    .padding(8.dp)
                                            ) {
                                                Text(
                                                    text = advisoryTip,
                                                    fontSize = 8.5.sp,
                                                    color = if (count == 0) Color(0xFF15803D) else if (count == -1) Color(0xFF4B5563) else Color(0xFF92400E),
                                                    lineHeight = 12.sp
                                                )
                                            }
                                        }

                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.End
                                        ) {
                                            Button(
                                                onClick = {
                                                    viewModel.purgeFirebaseCollectionAndUnify(colName)
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF7E22CE)),
                                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 2.dp),
                                                shape = RoundedCornerShape(6.dp),
                                                modifier = Modifier.height(28.dp),
                                                enabled = (count != null && count > 0)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = null,
                                                    tint = Color.White,
                                                    modifier = Modifier.size(12.dp)
                                                )
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text(
                                                    text = t("تطهير وحذف كلي 🧼", "Purge Collection 🧼"),
                                                    fontSize = 9.5.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color.White
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            2 -> {
                // TAB 2: HOSTINGER CONFIGURATION
                HostingerHostingSubView(viewModel = viewModel)
            }

            3 -> {
                // TAB 3: BACKUP & RESTORE
                val backupReminderDays by viewModel.backupReminderDays.collectAsState()
                val lastBackupTimeVal by viewModel.lastBackupTime.collectAsState()
                val lastBackupTimestampVal by viewModel.lastBackupTimestamp.collectAsState()
                val backupDueDaysCountVal by viewModel.backupDueDaysCount.collectAsState()

                // 🔔 CARD 0: SCHEDULED BACKUP REMINDER CONFIGURATION
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, IndustrialBorder)
                ) {
                    Column(
                        modifier = Modifier.padding(14.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(38.dp)
                                    .background(GBRBlueMain.copy(alpha = 0.1f), RoundedCornerShape(10.dp)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Notifications,
                                    contentDescription = null,
                                    tint = GBRBlueMain,
                                    modifier = Modifier.size(22.dp)
                                )
                            }
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = t("التنبيه والتذكير بالنسخ الاحتياطي الدوري 🔔", "Scheduled Backup Reminder 🔔"),
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = GBRDarkIndigo
                                )
                                Text(
                                    text = t(
                                        "تنبيه ذكي يظهر عند فتح التطبيق لطلب عمل نسخة احتياطية بعد انتهاء الفترة المحددة منذ آخر عملية حفظ لضمان سلامة وأمان المعلومات.",
                                        "Prompts on app launch to create a backup after the selected interval passes since your last backup to secure factory data."
                                    ),
                                    fontSize = 10.sp,
                                    color = Color.Gray,
                                    lineHeight = 14.sp
                                )
                            }
                        }

                        // Live Status & Countdown Panel
                        val isReminderActive = backupReminderDays > 0
                        val isBackupDue = isReminderActive && (lastBackupTimestampVal == 0L || backupDueDaysCountVal >= backupReminderDays)
                        val remainingDays = if (isReminderActive && lastBackupTimestampVal > 0L) {
                            maxOf(0, backupReminderDays - backupDueDaysCountVal)
                        } else 0
                        
                        val statusBgColor = when {
                            !isReminderActive -> Color(0xFFF1F5F9)
                            isBackupDue -> Color(0xFFFEF2F2)
                            else -> Color(0xFFF0FDF4)
                        }
                        val statusBorderColor = when {
                            !isReminderActive -> Color(0xFFCBD5E1)
                            isBackupDue -> Color(0xFFFECACA)
                            else -> Color(0xFFBBF7D0)
                        }

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            colors = CardDefaults.cardColors(containerColor = statusBgColor),
                            border = BorderStroke(1.dp, statusBorderColor)
                        ) {
                            Column(
                                modifier = Modifier.padding(10.dp),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Icon(
                                            imageVector = when {
                                                !isReminderActive -> Icons.Default.Info
                                                isBackupDue -> Icons.Default.Warning
                                                else -> Icons.Default.CheckCircle
                                            },
                                            contentDescription = null,
                                            tint = when {
                                                !isReminderActive -> Color.Gray
                                                isBackupDue -> Color(0xFFDC2626)
                                                else -> Color(0xFF16A34A)
                                            },
                                            modifier = Modifier.size(16.dp)
                                        )
                                        Text(
                                            text = when {
                                                !isReminderActive -> t("حالة التذكير: معطل", "Reminder Status: Disabled")
                                                isBackupDue -> t("حالة التذكير: ⚠️ مستحق الآن!", "Reminder Status: ⚠️ Due Now!")
                                                else -> t("حالة التذكير: 🟢 نشط ومحمي", "Reminder Status: 🟢 Protected")
                                            },
                                            fontSize = 11.5.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = when {
                                                !isReminderActive -> Color.DarkGray
                                                isBackupDue -> Color(0xFF991B1B)
                                                else -> Color(0xFF166534)
                                            }
                                        )
                                    }

                                    if (isReminderActive) {
                                        Text(
                                            text = if (isBackupDue) {
                                                t("تجاوز $backupDueDaysCountVal يوم", "$backupDueDaysCountVal days elapsed")
                                            } else {
                                                t("متبقي $remainingDays يوم", "$remainingDays days left")
                                            },
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = if (isBackupDue) Color(0xFFDC2626) else Color(0xFF16A34A)
                                        )
                                    }
                                }

                                HorizontalDivider(color = statusBorderColor, thickness = 0.8.dp)

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text(
                                        text = t("📅 آخر نسخة احتياطية:", "Last Backup:"),
                                        fontSize = 10.5.sp,
                                        color = Color.Gray
                                    )
                                    Text(
                                        text = lastBackupTimeVal,
                                        fontSize = 10.5.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                }

                                if (isReminderActive && lastBackupTimestampVal > 0L) {
                                    val nextDueMs = lastBackupTimestampVal + (backupReminderDays.toLong() * 86400000L)
                                    val nextDueStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(nextDueMs))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Text(
                                            text = t("🗓️ موعد التذكير القادم:", "Next Reminder Date:"),
                                            fontSize = 10.5.sp,
                                            color = Color.Gray
                                        )
                                        Text(
                                            text = nextDueStr,
                                            fontSize = 10.5.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isBackupDue) Color(0xFFDC2626) else GBRBlueMain
                                        )
                                    }
                                }
                            }
                        }

                        // Reminder Interval Choices
                        Text(
                            text = t("حدد دورة التذكير والتنبيه لإنشاء النسخ الاحتياطية:", "Choose backup reminder schedule interval:"),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )

                        val reminderOptions = listOf(
                            Pair(0, Pair(t("عدم التنبيه (إيقاف)", "Never (Disabled)"), t("إيقاف التذكيرات الدورية عند فتح التطبيق", "No launch reminders"))),
                            Pair(7, Pair(t("تنبيه كل أسبوع (7 أيام) 📅", "Every week (7 days) 📅"), t("تذكير أسبوعي بعد آخر عملية نسخ احتياطي", "Weekly reminder"))),
                            Pair(15, Pair(t("تنبيه كل 15 يوماً 🗓️", "Every 15 days 🗓️"), t("تذكير نصف شهري منتظم", "Bi-weekly reminder"))),
                            Pair(30, Pair(t("تنبيه كل شهر (30 يوماً) 📆", "Every month (30 days) 📆"), t("تذكير شهري لحفظ شامل لقاعدة البيانات", "Monthly reminder")))
                        )

                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            reminderOptions.forEach { (days, labels) ->
                                val isOptionSelected = backupReminderDays == days
                                val (optionTitle, optionDesc) = labels

                                Card(
                                    onClick = {
                                        viewModel.setBackupReminderInterval(days)
                                        val toastMsg = if (days == 0) {
                                            t("تم تعطيل التنبيه الدوري للنسخ الاحتياطي", "Backup reminder disabled")
                                        } else {
                                            t("تم ضبط التنبيه ليذكرك كل $days يوماً بعد آخر نسخة احتياطية ⏰", "Backup reminder set to every $days days ⏰")
                                        }
                                        Toast.makeText(context, toastMsg, Toast.LENGTH_SHORT).show()
                                    },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp),
                                    colors = CardDefaults.cardColors(
                                        containerColor = if (isOptionSelected) GBRBlueMain.copy(alpha = 0.08f) else Color(0xFFFAFAFA)
                                    ),
                                    border = BorderStroke(
                                        if (isOptionSelected) 1.5.dp else 1.dp,
                                        if (isOptionSelected) GBRBlueMain else Color.LightGray.copy(alpha = 0.4f)
                                    )
                                ) {
                                    Row(
                                        modifier = Modifier.padding(10.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        RadioButton(
                                            selected = isOptionSelected,
                                            onClick = {
                                                viewModel.setBackupReminderInterval(days)
                                                val toastMsg = if (days == 0) {
                                                    t("تم تعطيل التنبيه الدوري للنسخ الاحتياطي", "Backup reminder disabled")
                                                } else {
                                                    t("تم ضبط التنبيه ليذكرك كل $days يوماً بعد آخر نسخة احتياطية ⏰", "Backup reminder set to every $days days ⏰")
                                                }
                                                Toast.makeText(context, toastMsg, Toast.LENGTH_SHORT).show()
                                            },
                                            colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                                        )
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(
                                                text = optionTitle,
                                                fontSize = 11.5.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = if (isOptionSelected) GBRBlueMain else GBRDarkIndigo
                                            )
                                            Text(
                                                text = optionDesc,
                                                fontSize = 9.5.sp,
                                                color = Color.Gray,
                                                lineHeight = 13.sp
                                            )
                                        }
                                        if (isOptionSelected) {
                                            Icon(
                                                imageVector = Icons.Default.Check,
                                                contentDescription = null,
                                                tint = GBRBlueMain,
                                                modifier = Modifier.size(18.dp)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(4.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, IndustrialBorder)
                ) {
                    Column(
                        modifier = Modifier.padding(14.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text(
                            text = "📤 " + t("إنشاء وتصدير نسخة احتياطية محلية", "Compile Local Database Backup"),
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )

                                        // Option 1: Full Database Export
                        Card(
                            onClick = { isFullExportNew = true },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            colors = CardDefaults.cardColors(containerColor = if (isFullExportNew) GBRBlueMain.copy(alpha = 0.08f) else Color.White),
                            border = BorderStroke(if (isFullExportNew) 1.5.dp else 1.dp, if (isFullExportNew) GBRBlueMain else Color.LightGray.copy(alpha = 0.4f))
                        ) {
                            Row(
                                modifier = Modifier.padding(10.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                RadioButton(
                                    selected = isFullExportNew,
                                    onClick = { isFullExportNew = true },
                                    colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                                )
                                Column {
                                    Text(
                                        text = t("تصدير كامل لقاعدة البيانات 🗄️", "Full Database Export 🗄️"),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    Text(
                                        text = t("تصدير جميع أقسام التطبيق والبيانات والسجلات بالكامل دون استثناء لضمان الحفظ الشامل.", "Exports all app sections, configurations, databases, and logs for absolute protection."),
                                        fontSize = 10.sp,
                                        color = Color.Gray,
                                        lineHeight = 14.sp
                                    )
                                }
                            }
                        }

                        // Option 2: Custom Selective Export
                        Card(
                            onClick = { isFullExportNew = false },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            colors = CardDefaults.cardColors(containerColor = if (!isFullExportNew) GBRBlueMain.copy(alpha = 0.08f) else Color.White),
                            border = BorderStroke(if (!isFullExportNew) 1.5.dp else 1.dp, if (!isFullExportNew) GBRBlueMain else Color.LightGray.copy(alpha = 0.4f))
                        ) {
                            Row(
                                modifier = Modifier.padding(10.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                RadioButton(
                                    selected = !isFullExportNew,
                                    onClick = { isFullExportNew = false },
                                    colors = RadioButtonDefaults.colors(selectedColor = GBRBlueMain)
                                )
                                Column {
                                    Text(
                                        text = t("تصدير مخصص (تحديد أقسام معينة) ⚙️", "Custom Selective Export ⚙️"),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    Text(
                                        text = t("حدد أقساماً معينة ترغب في تصديرها فقط مثل التركيبات، المواد الخام، المختبر، أو التحكم بالمعدات.", "Choose specific modules of the application to compile into the backup archive."),
                                        fontSize = 10.sp,
                                        color = Color.Gray,
                                        lineHeight = 14.sp
                                    )
                                }
                            }
                        }

                        if (!isFullExportNew) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(10.dp),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                border = BorderStroke(1.dp, Color.LightGray.copy(alpha = 0.4f))
                            ) {
                                Column(
                                    modifier = Modifier.padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Text(
                                        text = t("قائمة أقسام التطبيق المتاحة للمخصص:", "Available Modules for Custom Backup:"),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    com.example.data.BackupManager.sections.forEach { section ->
                                        val isChecked = selectedExportSectionsNew.contains(section.key)
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable {
                                                    selectedExportSectionsNew = if (isChecked) {
                                                        selectedExportSectionsNew - section.key
                                                    } else {
                                                        selectedExportSectionsNew + section.key
                                                    }
                                                }
                                                .padding(vertical = 4.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Checkbox(
                                                checked = isChecked,
                                                onCheckedChange = { checked ->
                                                    selectedExportSectionsNew = if (checked) {
                                                        selectedExportSectionsNew + section.key
                                                    } else {
                                                        selectedExportSectionsNew - section.key
                                                    }
                                                },
                                                colors = CheckboxDefaults.colors(checkedColor = GBRBlueMain)
                                            )
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Column {
                                                Text(
                                                    text = if (lang == "ar") section.titleAr else section.titleEn,
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.SemiBold,
                                                    color = Color.DarkGray
                                                )
                                                Text(
                                                    text = t("الجداول المدرجة: ", "Included tables: ") + section.tables.joinToString(", "),
                                                    fontSize = 9.sp,
                                                    color = Color.Gray
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(4.dp))

                        // Format trigger buttons
                        // Single export button (encrypted + compressed) — the former JSON / ZIP pair produced the same encrypted .gbr file
                        Button(
                            onClick = { showExportAlertByFormat = "zip" },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                        ) {
                            Text(text = t("تصدير نسخة احتياطية (مشفّرة ومضغوطة) 🔒🗜️", "Export backup (encrypted & compressed) 🔒🗜️"), fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }

                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(1.dp)
                                .background(Color.LightGray.copy(alpha = 0.3f))
                        )

                        Text(
                            text = "📥 " + t("تحميل واستعادة نسخة احتياطية بالكامل", "Ingest and Restructure Machine from Backup"),
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = GBRDarkIndigo
                        )

                        Button(
                            onClick = { openDocumentLauncher.launch(arrayOf("application/json", "application/zip", "application/octet-stream")) },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = GBRDarkIndigo)
                        ) {
                            Text(text = t("اختر ملف نسخة احتياطية من الهاتف (JSON / ZIP) 📁", "Select Backup File (JSON / ZIP) 📁"), fontWeight = FontWeight.Bold, fontSize = 11.sp)
                        }

                        // Preview parsed elements
                        importAnalysisResult?.let { resParsed ->
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(10.dp),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                                border = BorderStroke(1.dp, Color.LightGray.copy(alpha = 0.4f))
                            ) {
                                Column(
                                    modifier = Modifier.padding(12.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Text(
                                        text = "📊 تفاصيل البنية والسجلات المكتشفة بالملف:",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )

                                    val countsList = listOf(
                                        "${resParsed.rawMaterialsCount} مواد خام مصنعية معالجة",
                                        "${resParsed.formulationsCount} تركيبات خلط جاهزة ومعتمدة",
                                        "${resParsed.revisionsCount} سجلات تاريخية لتحديث الخبراء ومراجعاتهم",
                                        "${resParsed.recipePhasesCount} خطوات تشغيل لوصفات الصب على الماكينات",
                                        "${resParsed.ordersCount} أوامر تشغيل مكتملة وجارية",
                                        "${resParsed.testsCount} فحوصات مطابقة الجودة الاستباقية"
                                    )

                                    countsList.forEach { countVal ->
                                        Text(text = "- $countVal", fontSize = 10.sp, color = Color.Gray)
                                    }

                                    Spacer(modifier = Modifier.height(4.dp))

                                    // Import Strategy Radio selections
                                    Text(
                                        text = t("اختر طريقة واستراتيجية معالجة ودمج البيانات: ", "Select Backup Processing Strategy:"),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )

                                    val stratOptions = listOf(
                                        Triple(1, t("دمج ذكي (Smart Merge & Fusion)", "Smart Fusion"), t("يحافظ على سجلاتك الحالية ويقوم بتحديث المتشابه فقط لمنع التكرار نهائياً.", "Intelligently merges with existing resources without redundancy.")),
                                        Triple(2, t("استبدال ومسح شامل (Full Database Overwrite ⚠️)", "Full Overwrite ⚠️"), t("يقوم بحذف مطلق وكامل لجميع الجداول الحالية بالكامل وتعبئتها من الصفر.", "Completely formats local SQLite tables before loading backup content.")),
                                        Triple(3, t("معاينة كود المصدر فقط (Simulation Mode)", "Integrity Preview Only"), t("يقوم بفحص سلامة الكود والروابط المرجعية للمفتاح الأساسي دون تعديل.", "Validates integrity diagnostic structure without writing."))
                                    )

                                    stratOptions.forEach { (stratId, name, sDesc) ->
                                        val isStratSelected = selectedStrategy == stratId
                                        Card(
                                            onClick = { selectedStrategy = stratId },
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(8.dp),
                                            colors = CardDefaults.cardColors(containerColor = if (isStratSelected) WarningOrange.copy(alpha = 0.08f) else Color.White),
                                            border = BorderStroke(if (isStratSelected) 1.5.dp else 1.dp, if (isStratSelected) WarningOrange else Color.LightGray.copy(alpha = 0.3f))
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(8.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                RadioButton(
                                                    selected = isStratSelected,
                                                    onClick = { selectedStrategy = stratId },
                                                    colors = RadioButtonDefaults.colors(selectedColor = WarningOrange)
                                                )
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text(text = name, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                                                    Text(text = sDesc, fontSize = 9.sp, color = Color.Gray, lineHeight = 12.sp)
                                                }
                                            }
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(4.dp))

                                    // Category selective check checkboxes for import
                                    val importCheckboxes: List<Triple<Boolean, String, (Boolean) -> Unit>> = listOf(
                                        Triple(impMaterials, t("المواد الخام المتاحة", "Raw Materials") + " (${resParsed.rawMaterialsCount})", { v: Boolean -> impMaterials = v }),
                                        Triple(impFormulations, t("التركيبات والمكونات", "Formulations") + " (${resParsed.formulationsCount})", { v: Boolean -> impFormulations = v }),
                                        Triple(impRevisions, t("تاريخ التعديل والتحسين", "Versions") + " (${resParsed.revisionsCount})", { v: Boolean -> impRevisions = v }),
                                        Triple(impRecipes, t("وصفات ومراحل التشغيل", "Recipes") + " (${resParsed.recipePhasesCount})", { v: Boolean -> impRecipes = v }),
                                        Triple(impOrders, t("أوامر التشغيل والباتشات", "Orders") + " (${resParsed.ordersCount})", { v: Boolean -> impOrders = v }),
                                        Triple(impTests, t("فحوصات الجودة والمعمل", "QA Tests") + " (${resParsed.testsCount})", { v: Boolean -> impTests = v }),
                                        Triple(impPackagings, t("خصائص عبوات التغليف", "Containers") + " (${resParsed.packagingsCount})", { v: Boolean -> impPackagings = v }),
                                        Triple(impCosts, t("تواريخ التغيير في التكاليف", "Costs") + " (${resParsed.priceHistoryCount})", { v: Boolean -> impCosts = v })
                                    )

                                    Text(text = t("حدد العناصر المحددة للاستيراد الفعلي:", "Select categories to import selectively:"), fontSize = 10.sp, fontWeight = FontWeight.Bold, color = Color.DarkGray)

                                    val importCheckboxesChunked = importCheckboxes.chunked(2)
                                    Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                                        importCheckboxesChunked.forEach { pairRowList ->
                                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                                pairRowList.forEach { (state, label, setter) ->
                                                    Row(
                                                        modifier = Modifier.weight(1f).clickable { setter(!state) },
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Checkbox(
                                                            checked = state,
                                                            onCheckedChange = { setter(it) },
                                                            colors = CheckboxDefaults.colors(checkedColor = WarningOrange)
                                                        )
                                                        Text(text = label, fontSize = 10.sp, color = Color.DarkGray, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                                    }
                                                }
                                                if (pairRowList.size == 1) {
                                                    Spacer(modifier = Modifier.weight(1f))
                                                }
                                            }
                                        }
                                    }

                                    Button(
                                        onClick = { showImportAlert = true },
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(8.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen)
                                    ) {
                                        Text(
                                            text = when(selectedStrategy) {
                                                2 -> t("تأكيد المَسح وكتابة الأرشيف ⚠️", "Format & Overwrite Local SQLite ⚠️")
                                                3 -> t("بدء محاكاة وفحص المحتويات المكتشفة 🔍", "Start Integrity dry run diagnostic 🔍")
                                                else -> t("تنفيذ دمج البيانات المحددة 📥", "Fuse and selectively ingest elements 📥")
                                            },
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 11.5.sp
                                        )
                                    }
                                }
                            }
                        }

                        // Import feedback results
                        importStatusMessage?.let { statusOutput ->
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color(0xFFFEF3C7).copy(alpha = 0.5f), RoundedCornerShape(8.dp))
                                    .border(1.dp, WarningOrange.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                                    .padding(10.dp)
                            ) {
                                Text(text = statusOutput, fontSize = 11.sp, color = Color.DarkGray, lineHeight = 15.sp)
                            }
                        }

                    }
                }
            }

            4 -> {
                // TAB 4: SYSTEM ACTIVITIES LOG
                val systemLogsList by viewModel.systemLogs.collectAsState()
                var selectedLogFilter by remember { mutableStateOf("all") } // all, sync, error, backup, auth

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, IndustrialBorder)
                ) {
                    Column(
                        modifier = Modifier.padding(14.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "📋 " + t("سجلات عمليات النظام والتحذيرات", "System Runtime Activity Logs"),
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = GBRDarkIndigo,
                                modifier = Modifier.weight(1f)
                            )

                            Row(verticalAlignment = Alignment.CenterVertically) {
                            // Copy logs (يُنسخ ما يظهر حسب الفلتر المحدد مع التاريخ والتصنيف والنص كاملاً)
                            TextButton(
                                onClick = {
                                    val logsToCopy = if (selectedLogFilter == "all") systemLogsList
                                    else systemLogsList.filter { it.category == selectedLogFilter }
                                    if (logsToCopy.isEmpty()) {
                                        android.widget.Toast.makeText(context, t("لا توجد سجلات للنسخ", "No logs to copy"), android.widget.Toast.LENGTH_SHORT).show()
                                    } else {
                                        val sdfCopy = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault())
                                        val copyText = logsToCopy.joinToString("\n\n") { lg ->
                                            val lbl = when (lg.category) {
                                                "sync" -> "[مزامنة]"
                                                "error" -> "[تنبيه]"
                                                "backup" -> "[أرشيف]"
                                                else -> "[أمان]"
                                            }
                                            val tm = try { sdfCopy.format(java.util.Date(lg.timestamp)) } catch (e: Exception) { "--" }
                                            "$tm $lbl\n${lg.message}"
                                        }
                                        val cm = context.getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
                                        cm.setPrimaryClip(android.content.ClipData.newPlainText("GBR system log", copyText))
                                        android.widget.Toast.makeText(context, t("تم نسخ ${logsToCopy.size} سجل", "Copied ${logsToCopy.size} log entries"), android.widget.Toast.LENGTH_SHORT).show()
                                    }
                                }
                            ) {
                                Text(text = t("نسخ السجل", "Copy Logs"), color = GBRBlueMain, fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1, softWrap = false)
                            }

                            // Clear logs
                            TextButton(
                                onClick = {
                                    context.getSharedPreferences("gbr_system_logs", android.content.Context.MODE_PRIVATE).edit().clear().apply()
                                    viewModel.systemLogs.value = listOf(GbrViewModel.SystemLog(category = "auth", message = "تم تصفية ومسح سجلات النظام بالكامل."))
                                }
                            ) {
                                Text(text = t("مسح السجل", "Clear List"), color = ErrorRed, fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1, softWrap = false)
                            }
                            }
                        }

                        // Filter chips Row
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .horizontalScroll(rememberScrollState()),
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            val filters = listOf(
                                "all" to t("الكل", "All"),
                                "sync" to t("المزامنة", "Sync"),
                                "error" to t("أخطاء وتنبيهات", "Errors"),
                                "backup" to t("أرشيف واستعادة", "Backups"),
                                "auth" to t("تسجيلات الولوج", "Auth")
                            )

                            filters.forEach { (fCode, label) ->
                                val isSelected = selectedLogFilter == fCode
                                Box(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(if (isSelected) GBRBlueMain else Color.LightGray.copy(alpha = 0.2f))
                                        .clickable { selectedLogFilter = fCode }
                                        .padding(horizontal = 10.dp, vertical = 6.dp)
                                ) {
                                    Text(
                                        text = label, 
                                        fontSize = 10.5.sp, 
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) Color.White else Color.DarkGray
                                    )
                                }
                            }
                        }

                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(250.dp)
                                .background(Color(0xFF0F172A), RoundedCornerShape(10.dp))
                                .border(1.dp, Color.Black)
                                .padding(10.dp)
                        ) {
                            val filteredLogs = remember(systemLogsList, selectedLogFilter) {
                                if (selectedLogFilter == "all") systemLogsList 
                                else systemLogsList.filter { it.category == selectedLogFilter }
                            }

                            if (filteredLogs.isEmpty()) {
                                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                                    Text(text = t("سجل الفلاتر فارغ حالياً.", "Logs list is empty."), color = Color.Gray, fontSize = 11.sp)
                                }
                            } else {
                                androidx.compose.foundation.text.selection.SelectionContainer {
                                LazyColumn(
                                    verticalArrangement = Arrangement.spacedBy(8.dp),
                                    modifier = Modifier.fillMaxSize()
                                ) {
                                    items(filteredLogs) { log ->
                                        val timeStr = remember(log.timestamp) {
                                            try {
                                                val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault())
                                                sdf.format(java.util.Date(log.timestamp))
                                            } catch (e: Exception) {
                                                "--"
                                            }
                                        }

                                        val (labelAr, colorVal) = when(log.category) {
                                            "sync" -> t("[مزامنة]", "[Sync]") to GBRBlueMain
                                            "error" -> t("[تنبيه]", "[Alert]") to ErrorRed
                                            "backup" -> t("[أرشيف]", "[Archive]") to WarningOrange
                                            else -> t("[أمان]", "[Security]") to SuccessGreen
                                        }

                                        Column {
                                            Row(
                                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(text = timeStr, fontSize = 8.sp, color = Color.Gray, fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace)
                                                Text(text = labelAr, fontSize = 9.sp, fontWeight = FontWeight.Bold, color = colorVal)
                                            }
                                            Text(
                                                text = log.message, 
                                                fontSize = 11.sp, 
                                                color = Color.LightGray, 
                                                lineHeight = 15.sp,
                                                modifier = Modifier.padding(start = 4.dp, top = 2.dp)
                                            )
                                            Divider(color = Color.DarkGray.copy(alpha = 0.3f), modifier = Modifier.padding(top = 6.dp))
                                        }
                                    }
                                }
                                }
                            }
                        }
                    }
                }
            }

            5 -> {
                com.example.ui.ActivityLogTab()
            }
        }
    }

    // (Variables removed: declared in GbrAppContainer)

    // Modal Confirmation Alerts
    showExportAlertByFormat?.let { formatCodeSelected ->
        AlertDialog(
            onDismissRequest = { showExportAlertByFormat = null },
            title = {
                Text(text = t("تأكيد تصدير النسخة الاحتياطية", "Confirm Export Archive"), fontSize = 15.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
            },
            text = {
                Text(
                    text = if (formatCodeSelected == "zip") t("ستُجمع البيانات المحددة وتُضغط وتُشفَّر بكلمة مرور في ملف واحد بصيغة GBR. هل تود المتابعة وحفظ الملف؟", "The selected data will be compressed and encrypted with a password into a single GBR file. Proceed?")
                           else t("سيقوم النظام بتجميع وتشفير البيانات المطلوبة في ملف نصي موحد بصيغة JSON. هل تود المتابعة وحفظ الملف؟", "Construct a text-based JSON file format? Proceed?"),
                    fontSize = 12.sp,
                    color = Color.DarkGray,
                    lineHeight = 16.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        val formatApplied = formatCodeSelected
                        showExportAlertByFormat = null
                        pendingExportFormat = formatApplied
                        encryptionPasswordInput = ""
                        encryptionPasswordConfirmInput = ""
                        encryptionPasswordError = null
                        showEncryptionPasswordDialog = true
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen)
                ) {
                    Text(t("تأكيد وحماية الملف 🔒", "Confirm & Encrypt File 🔒"), fontWeight = FontWeight.Bold, color = Color.White, fontSize = 11.5.sp)
                }
            },
            dismissButton = {
                TextButton(onClick = { showExportAlertByFormat = null }) {
                    Text(t("تراجع", "Cancel"), color = Color.Gray, fontSize = 11.sp)
                }
            },
            shape = RoundedCornerShape(16.dp)
        )
    }

    if (showEncryptionPasswordDialog) {
        AlertDialog(
            onDismissRequest = { showEncryptionPasswordDialog = false },
            title = {
                Text(
                    text = t("🔒 تشفير النسخة الاحتياطية بكلمة مرور", "🔒 Password-Protect Backup File"),
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo
                )
            },
            text = {
                Column(
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = t(
                            "الرجاء إدخال كلمة مرور قوية لتشفير ملف النسخة الاحتياطية. لن تتمكن من استعادة البيانات مستقبلاً بدون كلمة المرور هذه. لا يتم تخزين كلمة المرور في أي مكان لدى النظام لحمايتك.",
