                        if (impRevisions) sectionsList.add(t("التعديلات", "Revisions"))
                        if (impRecipes) sectionsList.add(t("وصفات التشغيل", "Recipes"))
                        if (impOrders) sectionsList.add(t("أوامر الإنتاج", "Orders"))
                        if (impTests) sectionsList.add(t("فحوصات الجودة", "Tests"))
                        if (impPackagings) sectionsList.add(t("العبوات", "Packagings"))
                        if (impCosts) sectionsList.add(t("سجل الأسعار", "Costs"))

                        importSummarySections = if (sectionsList.isEmpty()) t("جميع الأقسام", "All Sections") else sectionsList.joinToString(" ، ")

                        val totalCount = (importAnalysisResult?.rawMaterialsCount ?: 0) +
                                         (importAnalysisResult?.formulationsCount ?: 0) +
                                         (importAnalysisResult?.ordersCount ?: 0) +
                                         (importAnalysisResult?.recipePhasesCount ?: 0) +
                                         (importAnalysisResult?.testsCount ?: 0)
                        importSummaryItemsCount = if (totalCount > 0) "$totalCount " + t("عنصر/سجل مكتشف", "items found") else t("سجلات البيانات كاملة", "Complete data records")

                        scope.launch {
                            try {
                                // Step 1: التدقيق والتحقق
                                kotlinx.coroutines.delay(650)

                                // Step 2: معالجة البيانات والدمج
                                importProgressStep = 2
                                importProgressPercent = 0.60f
                                importProgressStatusText = t("جاري معالجة ودمج سجلات المواد والتركيبات المحددة...", "Processing and merging materials & formulations...")
                                kotlinx.coroutines.delay(700)

                                // Step 3: تحديث قاعدة البيانات
                                importProgressStep = 3
                                importProgressPercent = 0.85f
                                importProgressStatusText = t("جاري تحديث قاعدة البيانات المحلية وإعادة بناء الفهارس...", "Updating local database tables & rebuilding indices...")

                                val success = viewModel.executeSelectiveImport(
                                    jsonString = importInputText,
                                    importRawMaterials = impMaterials,
                                    importFormulations = impFormulations,
                                    importRevisions = impRevisions,
                                    importRecipes = impRecipes,
                                    importOrders = impOrders,
                                    importTests = impTests,
                                    importPackagings = impPackagings,
                                    importCosts = impCosts,
                                    importStrategy = selectedStrategy
                                )
                                kotlinx.coroutines.delay(400)

                                if (success) {
                                    importProgressStep = 4
                                    importProgressPercent = 1.0f
                                    importProgressStatusText = t("تمت عملية استعادة النسخة الاحتياطية بنجاح!", "Backup restoration completed successfully!")
                                    importStatusMessage = when(selectedStrategy) {
                                        2 -> t("🎉 تم مسح وإعادة كتابة قاعدة البيانات محلياً بنجاح تام وفق تراكيب الملف المختار!", "🎉 Database formatted completely and loaded from backup template successfully!")
                                        3 -> t("🔍 اكتملت المحاكاة وسجل سلامة التراكيب سليم بنسبة ١٠٠٪. لا تعديل بالبيانات المحلية.", "🔍 Simulation dry run diagnostic checked completely! Zero variables locally modified.")
                                        else -> t("🎉 تم دمج وتحديث البيانات المستوردة مع الهيكل المصنعي بنجاح تام دون أي تكرار!", "🎉 Smart fusion completed successfully and local DB updated!")
                                    }
                                    viewModel.addSystemLog("backup", "تمت استعادة نسخة احتياطية بنجاح باستخدام استراتيجية: $stratName")
                                    importInputText = ""
                                    importAnalysisResult = null
                                } else {
                                    showImportProgressDialog = false
                                    importStatusMessage = t("❌ فشل استيراد البيانات: تأكد من سلامة هيكل الملف المختار وحاول مرة أخرى.", "❌ Processing Exception: format or code mismatch parse.")
                                    viewModel.addSystemLog("error", "فشلت عملية استعادة النسخة الاحتياطية")
                                }
                            } catch (e: Exception) {
                                showImportProgressDialog = false
                                importStatusMessage = t("❌ فشل استيراد البيانات: ${e.localizedMessage}", "❌ Import error: ${e.localizedMessage}")
                                viewModel.addSystemLog("error", "فشلت عملية استعادة النسخة الاحتياطية: ${e.localizedMessage}")
                            }
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = SuccessGreen)
                ) {
