                                Triple(expFormulations, t("التركيبات والمكونات", "Formulations & Ingredients"), { v: Boolean -> expFormulations = v }),
                                Triple(expRevisions, t("تاريخ التعديلات والإصدارات", "Revisions & Versions History"), { v: Boolean -> expRevisions = v }),
                                Triple(expRecipes, t("وصفات وخطوات تشغيل المصنع", "Recipe Phases & Settings"), { v: Boolean -> expRecipes = v }),
                                Triple(expOrders, t("أوامر الإنتاج وسجلات الوجبات", "Production Orders & Batches"), { v: Boolean -> expOrders = v }),
                                Triple(expTests, t("فحوصات الجودة والمعمل", "Quality & Lab Tests"), { v: Boolean -> expTests = v }),
                                Triple(expPackagings, t("إعدادات عبوات وأواني التغليف", "Packaging Styles & Weights"), { v: Boolean -> expPackagings = v }),
