@Composable
fun StepIndicatorItem(
    step: Int,
    currentStep: Int,
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    label: String,
    modifier: Modifier = Modifier
) {
    val isActive = step == currentStep
    val isCompleted = step < currentStep
    val colorAccent = if (isActive || isCompleted) GBRBlueMain else Color.Gray
    val containerColor = if (isActive) GBRBlueMain else if (isCompleted) GBRBlueMain.copy(alpha = 0.15f) else Color.LightGray.copy(alpha = 0.4f)
    val contentColor = if (isActive) Color.White else colorAccent

    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        Box(
            modifier = Modifier
                .size(28.dp)
                .clip(androidx.compose.foundation.shape.CircleShape)
                .background(containerColor),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = contentColor,
                modifier = Modifier.size(14.dp)
            )
        }
        Text(
            text = label,
            fontSize = 11.sp,
            fontWeight = if (isActive) FontWeight.ExtraBold else FontWeight.Bold,
            color = colorAccent,
            maxLines = 1
        )
    }
}

@Composable
fun ProductionFloorOperatorDashboard(viewModel: GbrViewModel) {
    val selectedOrder by viewModel.selectedProductionOrder.collectAsState()
    val ordersList by viewModel.productionOrders.collectAsState(initial = emptyList())
    
    // 1. Ready, waiting to start: status == "جاهز للتنفيذ"
    val readyOrders = remember(ordersList) {
        ordersList.filter { it.status == "جاهز للتنفيذ" }
    }
    
    // 2. Active, executing: status == "قيد التنفيذ"
    val liveRunningOrders = remember(ordersList) {
        ordersList.filter { it.status == "قيد التنفيذ" }
    }
    
    var activeTabIdx by remember { mutableIntStateOf(0) }
    var orderToConfirmStart by remember { mutableStateOf<com.example.data.ProductionOrder?>(null) }
    
    BackHandler(enabled = selectedOrder != null) {
        viewModel.closeSelectedProductionOrder()
    }

    if (selectedOrder != null) {
        // Direct execution for operators - automatically runs in "Shop Floor" mode
        com.example.ui.OrderExecutionOrRecordView(
            order = selectedOrder!!,
            viewModel = viewModel,
            onClose = { viewModel.closeSelectedProductionOrder() }
        )
    } else {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFF8FAFC))
                .padding(20.dp)
        ) {
            // Header card
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = GBRBlueMain),
                border = BorderStroke(1.dp, Color(0xFF003D7E))
            ) {
                Column(
                    modifier = Modifier.padding(18.dp)
                ) {
                    Text(
                        text = "صالة الإنتاج والخلط الكيميائي 🧪",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.White
                    )
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        text = "مرحباً بك في واجهة المشغل لخلط وتركيب الدفعات. يرجى اختيار الأوامر الجاهزة للبدء، أو استئناف العمل على الأوامر الجارية قيد المعالجة.",
                        fontSize = 11.sp,
                        color = Color(0xFFDBEAFE),
                        lineHeight = 16.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Elegant Custom Tab Row for Operator view
            val coroutineScope = rememberCoroutineScope()
            val operatorPagerState = rememberPagerState(
                initialPage = activeTabIdx.coerceIn(0, 1),
                pageCount = { 2 }
            )

            LaunchedEffect(activeTabIdx) {
                if (operatorPagerState.currentPage != activeTabIdx) {
                    operatorPagerState.animateScrollToPage(activeTabIdx)
                }
            }

            LaunchedEffect(operatorPagerState.currentPage) {
                if (activeTabIdx != operatorPagerState.currentPage) {
                    activeTabIdx = operatorPagerState.currentPage
                }
            }

            TabRow(
                selectedTabIndex = operatorPagerState.currentPage,
                containerColor = Color.White,
                contentColor = GBRBlueMain,
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(12.dp))
                    .border(1.dp, IndustrialBorder, RoundedCornerShape(12.dp))
            ) {
                Tab(
                    selected = operatorPagerState.currentPage == 0,
                    onClick = {
                        activeTabIdx = 0
                        coroutineScope.launch { operatorPagerState.animateScrollToPage(0) }
                    }
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center,
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp, horizontal = 4.dp)
                    ) {
                        Box {
                            Icon(
                                imageVector = Icons.Default.CheckCircle,
                                contentDescription = null,
                                tint = if (operatorPagerState.currentPage == 0) GBRBlueMain else Color.Gray,
                                modifier = Modifier.size(24.dp)
                            )
                            if (readyOrders.isNotEmpty()) {
                                Box(
                                    modifier = Modifier
                                        .align(Alignment.TopEnd)
                                        .offset(x = 10.dp, y = (-8).dp)
                                        .background(Color(0xFFEF4444), CircleShape)
                                        .sizeIn(minWidth = 18.dp, minHeight = 18.dp)
                                        .padding(horizontal = 4.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = "${readyOrders.size}",
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color.White,
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = "جاهز بانتظار البدء",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (operatorPagerState.currentPage == 0) GBRBlueMain else Color.Gray,
                            maxLines = 2,
                            lineHeight = 17.sp,
                            textAlign = TextAlign.Center
                        )
                    }
                }
                Tab(
                    selected = operatorPagerState.currentPage == 1,
                    onClick = {
                        activeTabIdx = 1
                        coroutineScope.launch { operatorPagerState.animateScrollToPage(1) }
                    }
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center,
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp, horizontal = 4.dp)
                    ) {
                        Box {
                            Icon(
                                imageVector = Icons.Default.PlayArrow,
                                contentDescription = null,
                                tint = if (operatorPagerState.currentPage == 1) GBRBlueMain else Color.Gray,
                                modifier = Modifier.size(24.dp)
                            )
                            if (liveRunningOrders.isNotEmpty()) {
                                Box(
                                    modifier = Modifier
                                        .align(Alignment.TopEnd)
                                        .offset(x = 10.dp, y = (-8).dp)
                                        .background(Color(0xFFEF4444), CircleShape)
                                        .sizeIn(minWidth = 18.dp, minHeight = 18.dp)
                                        .padding(horizontal = 4.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = "${liveRunningOrders.size}",
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color.White,
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = "قيد المعالجة النشطة",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (operatorPagerState.currentPage == 1) GBRBlueMain else Color.Gray,
                            maxLines = 2,
                            lineHeight = 17.sp,
                            textAlign = TextAlign.Center
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            HorizontalPager(
                state = operatorPagerState,
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f)
            ) { page ->
                if (page == 0) {
                // Section 1: Ready, waiting to start
                if (readyOrders.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize(),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Icon(
                                imageVector = Icons.Default.Info,
                                contentDescription = null,
                                tint = Color.Gray,
                                modifier = Modifier.size(48.dp)
                            )
                            Spacer(modifier = Modifier.height(10.dp))
                            Text(
                                text = "لا توجد أوامر إنتاج جاهزة للبدء حالياً.",
                                fontSize = 13.sp,
                                color = Color.Gray,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "تظهر هنا الأوامر التي تمت جدولتها من الإدارة بانتظار تشغيلها.",
                                fontSize = 11.sp,
                                color = Color.Gray
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        items(readyOrders) { ord ->
                            Card(
                                onClick = {
                                    orderToConfirmStart = ord
                                },
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                border = BorderStroke(1.5.dp, IndustrialBorder),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("operator_ready_order_${ord.orderNumber}")
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(
                                                text = ord.formulationName,
                                                fontSize = 15.sp,
                                                fontWeight = FontWeight.Black,
                                                color = GBRDarkIndigo
                                            )
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text(
                                                    text = ord.orderNumber,
                                                    fontSize = 12.sp,
                                                    color = GBRBlueMain,
                                                    fontWeight = FontWeight.Bold
                                                )
                                                Text("|", fontSize = 12.sp, color = Color.LightGray)
                                                Text(
                                                    text = "الدفعة: ${ord.batchNumber}",
                                                    fontSize = 11.sp,
                                                    color = Color.Gray
                                                )
                                            }
                                        }
                                        
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(GBRBlueMain.copy(alpha = 0.1f))
                                                .padding(horizontal = 10.dp, vertical = 5.dp)
                                        ) {
                                            Text(
                                                text = "جاهز للبدء",
                                                fontSize = 11.sp,
                                                color = GBRBlueMain,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(12.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(
                                                text = "إجمالي الوزن المطلوب للوجبة الكيميائية:",
                                                fontSize = 10.sp,
                                                color = Color.Gray
                                            )
                                            Text(
                                                text = "${formatQuantity(ord.requiredWeightKg)} كغم",
                                                fontSize = 16.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = GBRDarkIndigo
                                            )
                                        }
                                        
                                        Button(
                                            onClick = {
                                                orderToConfirmStart = ord
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain),
                                            shape = RoundedCornerShape(10.dp),
                                            modifier = Modifier.height(38.dp)
                                        ) {
                                            Text(
                                                text = "بدء التنفيذ",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color.White
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // Section 2: Active running orders (In Progress)
                if (liveRunningOrders.isEmpty()) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize(),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Icon(
                                imageVector = Icons.Default.Info,
                                contentDescription = null,
                                tint = Color.Gray,
                                modifier = Modifier.size(48.dp)
                            )
                            Spacer(modifier = Modifier.height(10.dp))
                            Text(
                                text = "لا توجد أوامر إنتاج قيد التنفيذ حالياً.",
                                fontSize = 13.sp,
                                color = Color.Gray,
                                fontWeight = FontWeight.Bold
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "ابدأ تنفيذ أحد الأوامر الجاهزة من التبويب المجاور للمتابعة.",
                                fontSize = 11.sp,
                                color = Color.Gray
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        items(liveRunningOrders) { ord ->
                            Card(
                                onClick = {
                                    viewModel.selectedProductionOrder.value = ord
                                },
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                border = BorderStroke(1.5.dp, IndustrialBorder),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("operator_active_order_${ord.orderNumber}")
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(
                                                text = ord.formulationName,
                                                fontSize = 15.sp,
                                                fontWeight = FontWeight.Black,
                                                color = GBRDarkIndigo
                                            )
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                Text(
                                                    text = ord.orderNumber,
                                                    fontSize = 12.sp,
                                                    color = GBRBlueMain,
                                                    fontWeight = FontWeight.Bold
                                                )
                                                Text("|", fontSize = 12.sp, color = Color.LightGray)
                                                Text(
                                                    text = "الدفعة: ${ord.batchNumber}",
                                                    fontSize = 11.sp,
                                                    color = Color.Gray
                                                )
                                            }
                                        }
                                        
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(Color(0xFFFFF7ED))
                                                .padding(horizontal = 10.dp, vertical = 5.dp)
                                        ) {
                                            Text(
                                                text = "إنجاز: ${ord.progressPercent}%",
                                                fontSize = 12.sp,
                                                color = WarningOrange,
                                                fontWeight = FontWeight.Black
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(12.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(
                                                text = "إجمالي الوزن المطلوب للوجبة الكيميائية:",
                                                fontSize = 10.sp,
                                                color = Color.Gray
                                            )
                                            Text(
                                                text = "${formatQuantity(ord.requiredWeightKg)} كغم",
                                                fontSize = 16.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = GBRDarkIndigo
                                            )
                                        }
                                        
                                        Button(
                                            onClick = {
                                                viewModel.selectedProductionOrder.value = ord
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = WarningOrange),
                                            shape = RoundedCornerShape(10.dp),
                                            modifier = Modifier.height(38.dp)
                                        ) {
                                            Text(
                                                text = if (ord.progressPercent > 0) "استئناف الخلط" else "بدء العمل الآني",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color.White
                                            )
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(12.dp))

                                    LinearProgressIndicator(
                                        progress = ord.progressPercent / 100f,
                                        color = WarningOrange,
                                        trackColor = Color(0xFFFEF3C7),
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(8.dp)
                                            .clip(RoundedCornerShape(4.dp))
                                    )
                                }
                            }
                        }
                    }
                }
            }
            }
        }
    }

    // Elegant alert dialog confirmation for starting an order
    if (orderToConfirmStart != null) {
        val o = orderToConfirmStart!!
        AlertDialog(
            onDismissRequest = { orderToConfirmStart = null },
            title = {
                Text(
                    text = "تأكيد بدء التنفيذ",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    color = GBRDarkIndigo,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = androidx.compose.ui.text.style.TextAlign.Start
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        text = "هل تريد بدء تنفيذ أمر الإنتاج؟",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.Black
                    )
                    Divider(color = Color.LightGray.copy(alpha = 0.5f))
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("رقم الأمر الخاص:", fontSize = 12.sp, color = Color.Gray)
                        Text(o.orderNumber, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = GBRBlueMain)
                    }
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("اسم المنتج الكيميائي:", fontSize = 12.sp, color = Color.Gray)
                        Text(o.formulationName, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val ord = o
                        viewModel.startProductionExecution(ord.id)
                        // Transition immediately into live view
                        viewModel.selectedProductionOrder.value = ord.copy(status = "قيد التنفيذ")
                        orderToConfirmStart = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRBlueMain)
                ) {
                    Text("بدء التنفيذ", fontWeight = FontWeight.Bold, color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { orderToConfirmStart = null }) {
                    Text("إلغاء", fontWeight = FontWeight.Bold, color = Color.Gray)
                }
            },
            shape = RoundedCornerShape(14.dp),
            containerColor = Color.White
        )
    }
}

// --- 30. Laboratory Dashboard (لوحة تحكم فحص وجودة المختبر) ---
@Composable
fun LaboratoryDashboard(viewModel: GbrViewModel) {
    val ordersList by viewModel.productionOrders.collectAsState(initial = emptyList())
    var activeLabOrder by remember { mutableStateOf<com.example.data.ProductionOrder?>(null) }
    var activeLabOrderShowReport by remember { mutableStateOf(false) }

    BackHandler(enabled = activeLabOrder != null) {
        activeLabOrder = null
        activeLabOrderShowReport = false
    }

    val allTestRecords by viewModel.allProductionOrderTestRecords.collectAsState()
    val labSessions by viewModel.labSessions.collectAsState(initial = emptyList())
    val allLabTests by viewModel.allLabTests.collectAsState(initial = emptyList())

    if (activeLabOrder != null) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFF8FAFC))
                .padding(16.dp)
        ) {
            // Header with back button
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = "فحوصات المختبر ومطابقة الجودة",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = GBRDarkIndigo
                    )
                    Text(
                        text = "الأمر: ${activeLabOrder!!.orderNumber} | المنتج: ${activeLabOrder!!.formulationName}",
                        fontSize = 12.sp,
                        color = Color.Gray
                    )
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    val currentQcSession = remember(labSessions, activeLabOrder) {
                        labSessions.find { it.sampleProperties == "ORDER_ID:${activeLabOrder?.id}" }
                    }
                    if (currentQcSession != null && !activeLabOrderShowReport) {
                        IconButton(onClick = { activeLabOrderShowReport = true }) {
                            Icon(
                                imageVector = Icons.Default.Print,
                                contentDescription = "طباعة تقرير المختبر",
                                tint = GBRBlueMain,
                                modifier = Modifier.size(24.dp)
                            )
                        }
                    }
                    IconButton(onClick = { 
                        activeLabOrder = null 
                        activeLabOrderShowReport = false
                    }) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "إغلاق",
                            tint = ErrorRed
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Scrollable quality control panel
            Box(modifier = Modifier.weight(1f)) {
                com.example.ui.HistoricalQualityControlPanel(
                    order = activeLabOrder!!, 
                    viewModel = viewModel, 
                    onBack = { 
                        if (activeLabOrderShowReport) {
                            activeLabOrderShowReport = false
                        } else {
                            activeLabOrder = null 
                        }
                    },
                    showReportViewExternal = activeLabOrderShowReport,
                    onShowReportViewExternalChange = { activeLabOrderShowReport = it }
                )
            }
        }
    } else {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0xFFF8FAFC))
                .padding(20.dp)
        ) {
            // Header card
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = GBRBlueMain),
                border = BorderStroke(1.dp, Color(0xFF003D7E))
            ) {
                Column(
                    modifier = Modifier.padding(18.dp)
                ) {
                    Text(
                        text = "مختبر ضبط الجودة والمعايرة 🧪🔬",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.White
                    )
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        text = "مرحباً بك في واجهة فني المختبر. يرجى اختيار أي أمر إنتاج (نشط أو مكتمل) لإدخال وتوثيق نتائج الفحوصات الكيميائية والفيزيائية للدفعة.",
                        fontSize = 11.sp,
                        color = Color(0xFFDBEAFE),
                        lineHeight = 16.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(20.dp))

            Text(
                text = "قائمة أوامر الإنتاج المتاحة للفحص:",
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = GBRDarkIndigo,
                modifier = Modifier.padding(bottom = 10.dp)
            )

            if (ordersList.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = "لا توجد أوامر إنتاج مسجلة حالياً.",
                        fontSize = 13.sp,
                        color = Color.Gray
                    )
                }
            } else {
                LazyColumn(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(ordersList) { ord ->
                        val testsCount = remember(allTestRecords, labSessions, allLabTests, ord.id) {
                            val classicCount = allTestRecords.count { 
                                it.productionOrderId == ord.id && try {
                                    org.json.JSONObject(it.resultsJson).length() > 0
                                } catch (e: Exception) {
                                    false
                                }
                            }
                            val associatedSessions = labSessions.filter { it.sampleProperties.startsWith("ORDER_ID:${ord.id}") }
                            val sessionTestsCount = if (associatedSessions.isNotEmpty()) {
                                val sessionIds = associatedSessions.map { it.id }.toSet()
                                allLabTests.count { it.sessionId in sessionIds }
                            } else {
                                0
                            }
                            classicCount + sessionTestsCount
                        }
                        Card(
                            onClick = { activeLabOrder = ord },
                            shape = RoundedCornerShape(14.dp),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            border = BorderStroke(1.5.dp, Color(0xFFE2E8F0)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = ord.formulationName,
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRDarkIndigo
                                    )
                                    // Status Badge
                                    Box(
                                        modifier = Modifier
                                            .background(
                                                when (ord.status) {
                                                    "قيد التنفيذ" -> Color(0xFFFFF7ED)
                                                    "مكتمل" -> Color(0xFFF0FDF4)
                                                    else -> Color(0xFFF1F5F9)
                                                },
                                                shape = RoundedCornerShape(8.dp)
                                            )
                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                    ) {
                                        Text(
                                            text = ord.status,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = when (ord.status) {
                                                "قيد التنفيذ" -> Color(0xFFC2410C)
                                                "مكتمل" -> Color(0xFF15803D)
                                                else -> Color.DarkGray
                                            }
                                        )
                                    }
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = "الأمر: ${ord.orderNumber} | الدفعة: ${ord.batchNumber}",
                                        fontSize = 11.sp,
                                        color = Color.Gray
                                    )
                                    Text(
                                        text = "الوزن: ${formatQuantity(ord.requiredWeightKg)} كغم",
                                        fontSize = 11.sp,
                                        color = Color.DarkGray
                                    )
                                }
                                Spacer(modifier = Modifier.height(8.dp))
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    if (ord.status == "مكتمل" && testsCount > 0) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                            modifier = Modifier
                                                .background(Color(0xFFEFF6FF), RoundedCornerShape(4.dp))
                                                .padding(horizontal = 6.dp, vertical = 2.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Info,
                                                contentDescription = null,
                                                tint = GBRBlueMain,
                                                modifier = Modifier.size(10.dp)
                                            )
                                            Text(
                                                text = "الفحوصات: $testsCount",
                                                color = GBRBlueMain,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    } else {
                                        Spacer(modifier = Modifier.width(1.dp))
                                    }
                                    Text(
                                        text = "فتح شاشة الفحوصات والتحاليل 🧪 🔍",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = GBRBlueMain
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun A4WysiwygPreview(
    formula: com.example.data.Formulation,
    items: List<com.example.data.FormulationItemWithDetails>,
    qualityTests: List<com.example.data.FormulationQualityTest>,
    recipePhases: List<com.example.data.RecipePhase>,
    useRealNames: Boolean,
    usePercentage: Boolean
) {
    val totalWeight = items.sumOf { it.quantityMultiplier }
    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale("ar"))
    val todayDateStr = sdf.format(java.util.Date())
    
    Box(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(4.dp),
        contentAlignment = Alignment.Center
    ) {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .wrapContentHeight(),
            shape = RoundedCornerShape(8.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(14.dp)
                    .border(1.dp, Color(0xFF94A3B8))
                    .padding(3.dp)
                    .border(0.5.dp, Color(0xFFCBD5E1))
                    .padding(10.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                // 1. Header Row
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .background(Color(0xFF2563EB), RoundedCornerShape(4.dp))
                                .padding(horizontal = 8.dp, vertical = 4.dp)
                        ) {
                            Text("GBR", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                        Column {
                            Text("دهانات GBR Paints", fontSize = 8.5.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E3A8A))
                            Text("مجموعة مصانع الدهانات الممتازة والخاصة", fontSize = 6.5.sp, color = Color(0xFF64748B))
                        }
                    }
                    
                    Text(
                        text = "وثيقة التركيبة الفنية المعتمدة  📋",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF1E3A8A)
                    )
                }
                
                Divider(color = Color(0xFFE2E8F0), thickness = 0.5.dp)
                
                // 1.5 Product Spotlight Title Banner (full-width like PDF)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFFF1F5F9), RoundedCornerShape(6.dp))
                        .padding(vertical = 5.dp, horizontal = 8.dp),
                    horizontalArrangement = Arrangement.End,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "اسم المنتج: ${formula.name} 🎨",
                        fontSize = 10.5.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF1E3A8A),
                        textAlign = TextAlign.Right
                    )
                }
                
                // 2. Metadata Cards (3 columns to prevent congestion and digit wrapping on mobile screens)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    val cardWidthModifier = Modifier.weight(1f)
                    val isUnapproved = formula.status.contains("غير") || formula.status.contains("مسودة")
                    
                    MetadataMiniCard(title = "تاريخ الطباعة", value = "$todayDateStr 📅", isGreen = false, modifier = cardWidthModifier)
                    MetadataMiniCard(title = "الإصدار المعتمد", value = "إصدار ${formula.version}", isGreen = false, modifier = cardWidthModifier)
                    MetadataMiniCard(
                        title = "حالة التركيبة",
                        value = if (isUnapproved) "تحت المراجعة ⚠️" else "معتمدة للإنتاج ✅",
                        isGreen = !isUnapproved,
                        modifier = cardWidthModifier
                    )
                }
                
                // 3. Stats Capsule Bar (3 columns)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFFEBF5FF), RoundedCornerShape(12.dp))
                        .border(0.5.dp, Color(0xFFBFDBFE), RoundedCornerShape(12.dp))
                        .padding(vertical = 4.dp, horizontal = 8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val segmentModifier = Modifier.weight(1f)
                    
                    MetricCapsuleSegment(label = "⚙️ مراحل التشغيل", value = "${recipePhases.size} مراحل", modifier = segmentModifier)
                    MetricCapsuleSegment(label = "🧪 عدد المواد الخام", value = "${items.size} مادة", modifier = segmentModifier)
                    MetricCapsuleSegment(
                        label = "⚖️ إجمالي الوزن الكلي",
                        value = "${formatQuantity(totalWeight)} كغم",
                        modifier = segmentModifier
                    )
                }
                
                // 4. Ingredients Table Section
                Text(
                    text = "المكونات ونسب المواد الخام 🧪",
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF1E3A8A),
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Right
                )
                
                // Table
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(0.5.dp, Color(0xFFCBD5E1))
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFF1D4ED8))
                            .padding(vertical = 5.dp)
                    ) {
                        Text("اسم المادة الخام والمكون الكيميائي", modifier = Modifier.weight(0.44f), color = Color.White, fontSize = 7.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                        Text("الكمية المعتمدة", modifier = Modifier.weight(0.16f), color = Color.White, fontSize = 7.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                        Text("الوحدة", modifier = Modifier.weight(0.08f), color = Color.White, fontSize = 7.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                        Text("طريقة الإضافة والتوجيه والتجهيز", modifier = Modifier.weight(0.26f), color = Color.White, fontSize = 7.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                        Text("م", modifier = Modifier.weight(0.06f), color = Color.White, fontSize = 7.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                    }
                    
                    items.forEachIndexed { index, item ->
                        val isEven = index % 2 == 1
                        val rawName = if (useRealNames) item.rawMaterialName else item.rawMaterialProductionName.ifBlank { item.rawMaterialName }
                        
                        val quantStr: String
                        val unitStr: String
                        if (usePercentage) {
                            val pct = if (totalWeight > 0.0) (item.quantityMultiplier / totalWeight) * 100.0 else 0.0
                            quantStr = formatQuantity(pct)
                            unitStr = "٪"
                        } else {
                            quantStr = formatQuantity(item.quantityMultiplier)
                            unitStr = "كغم"
                        }
                        
                        val instructionStr = if (item.needsGrinding) "طحن وميكنة (${item.grindingDurationMinutes} د)" else "خلط وإضافة مباشرة"
                        
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(if (isEven) Color(0xFFF8FAFC) else Color.White)
                                .border(0.5.dp, Color(0xFFE2E8F0))
                                .padding(vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(rawName, modifier = Modifier.weight(0.44f).padding(end = 4.dp), fontSize = 7.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Right, color = Color(0xFF0F172A))
                            Text(quantStr, modifier = Modifier.weight(0.16f), fontSize = 7.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center, color = Color(0xFF0F172A))
                            Text(unitStr, modifier = Modifier.weight(0.08f), fontSize = 7.sp, textAlign = TextAlign.Center, color = Color(0xFF475569))
                            Text(instructionStr, modifier = Modifier.weight(0.26f), fontSize = 7.sp, textAlign = TextAlign.Center, color = Color(0xFF475569))
                            Text((index + 1).toString(), modifier = Modifier.weight(0.06f), fontSize = 7.sp, textAlign = TextAlign.Center)
                        }
                    }
                    
                    val valueSumStr = if (usePercentage) "100" else "${formatQuantity(totalWeight)} كغم"
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFFEFF6FF))
                            .border(0.5.dp, Color(0xFFBFDBFE))
                            .padding(vertical = 4.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text(valueSumStr, modifier = Modifier.padding(start = 8.dp), fontSize = 8.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1D4ED8))
                        Text("إجمالي الوزن الكلي للوجبة ⚖️", modifier = Modifier.padding(end = 8.dp), fontSize = 8.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1D4ED8))
                    }
                }
                
                // 5. Two Columns Section (Side by side)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    val halfWidthModifier = Modifier.weight(1f)
                    
                    Column(
                        modifier = halfWidthModifier,
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text("وصفة التشغيل ومراحل الخلط ⚙️", fontSize = 9.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E3A8A), modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Right)
                        
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFF1E3A8A))
                                .padding(vertical = 2.dp)
                        ) {
                            Text("المرحلة", modifier = Modifier.weight(0.18f), color = Color.White, fontSize = 6.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                            Text("السرعة (RPM)", modifier = Modifier.weight(0.32f), color = Color.White, fontSize = 6.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                            Text("مدة التشغيل والملاحظات", modifier = Modifier.weight(0.50f), color = Color.White, fontSize = 6.5.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                        }
                        
                        recipePhases.take(4).forEachIndexed { idx, ph ->
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(if (idx % 2 == 1) Color(0xFFF8FAFC) else Color.White)
                                    .border(0.5.dp, Color(0xFFE2E8F0))
                                    .padding(vertical = 2.dp)
                            ) {
                                Text((idx + 1).toString(), modifier = Modifier.weight(0.18f), fontSize = 6.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
                                Text(ph.mixerRpm.toString(), modifier = Modifier.weight(0.32f), fontSize = 6.sp, textAlign = TextAlign.Center)
                                Text("${ph.durationMinutes} دقيقة", modifier = Modifier.weight(0.50f), fontSize = 6.sp, textAlign = TextAlign.Center)
                            }
                        }
                        
                        Spacer(modifier = Modifier.height(2.dp))
                        
                        Text("إرشادات عامة للمشغل 💬", fontSize = 7.5.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E3A8A), modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Right)
                        val generalInstructionsList = recipePhases.mapNotNull { if (it.instructions.isBlank()) null else it.instructions }
                        val finalInstructionsText = if (generalInstructionsList.isNotEmpty()) {
                            generalInstructionsList.joinToString("\n") { "• $it" }
                        } else {
                            "• دعم خلط متجانس بدون تعليمات كيميائية إضافية.\n• التأكد من تجانس الخلطة قبل الانتقال للمرحلة التالية."
                        }
                        Text(
                            text = finalInstructionsText,
                            fontSize = 6.sp,
                            color = Color(0xFF475569),
                            lineHeight = 9.sp,
                            modifier = Modifier.fillMaxWidth(),
                            textAlign = TextAlign.Right
                        )
                    }
                    
                    Column(
                        modifier = halfWidthModifier,
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text("ملاحظات فنية 📝", fontSize = 9.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E3A8A), modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Right)
                        
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(0.5.dp, Color(0xFFE2E8F0), RoundedCornerShape(4.dp)),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            shape = RoundedCornerShape(4.dp)
                        ) {
                            Column(
                                modifier = Modifier.padding(6.dp),
                                verticalArrangement = Arrangement.spacedBy(3.dp)
                            ) {
                                val notesContentText = formula.notes.ifBlank {
                                    "• التركيبة معدة للإنتاج وفق المواصفات المعتمدة.\n• يجب الالتزام بنسبة المواد الخام وعدم التغيير.\n• الحفظ في مكان جاف وبارد بعيداً عن أشعة الشمس.\n• يفضل الرج قبل الاستخدام."
                                }
                                Text(
                                    text = notesContentText,
                                    fontSize = 6.sp,
                                    color = Color(0xFF475569),
                                    lineHeight = 9.sp,
                                    modifier = Modifier.fillMaxWidth(),
                                    textAlign = TextAlign.Right
                                )
                                
                                Spacer(modifier = Modifier.height(4.dp))
                                
