@Composable
fun SoundsNotificationsSettingsSubView(viewModel: GbrViewModel) {
    val lang by viewModel.appLanguage.collectAsState()
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    val prefs = remember { context.getSharedPreferences("gbr_prefs", android.content.Context.MODE_PRIVATE) }
    var soundEnabled by remember { mutableStateOf(prefs.getBoolean("gbr_sound_enabled", true)) }
    var vibrationEnabled by remember { mutableStateOf(prefs.getBoolean("gbr_vibration_enabled", true)) }
    var customSoundUriStr by remember { mutableStateOf(prefs.getString("gbr_custom_sound_uri", "") ?: "") }
    var customSoundName by remember { mutableStateOf(prefs.getString("gbr_sound_tone_name", "") ?: "") }

    var testPlayer by remember { mutableStateOf<android.media.MediaPlayer?>(null) }
    var isTestPlaying by remember { mutableStateOf(false) }

    fun t(ar: String, en: String): String = if (lang == "ar") ar else en

    fun stopTestSound() {
        try {
            testPlayer?.let {
                if (it.isPlaying) {
                    it.stop()
                }
                it.release()
            }
        } catch (e: Exception) {
            e.printStackTrace()
        } finally {
            testPlayer = null
            isTestPlaying = false
        }
    }

    fun playTestSound() {
        stopTestSound()
        try {
            val soundUri = if (customSoundUriStr.isNotBlank()) {
                android.net.Uri.parse(customSoundUriStr)
            } else {
                android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_ALARM)
                    ?: android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_RINGTONE)
                    ?: android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_NOTIFICATION)
            }

            val player = android.media.MediaPlayer().apply {
                setDataSource(context, soundUri)
                setAudioAttributes(
                    android.media.AudioAttributes.Builder()
                        .setUsage(android.media.AudioAttributes.USAGE_ALARM)
                        .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION)
                        .build()
                )
                setOnCompletionListener {
                    isTestPlaying = false
                }
                prepare()
                start()
            }
            testPlayer = player
            isTestPlaying = true
        } catch (e: Exception) {
            e.printStackTrace()
            Toast.makeText(context, t("❌ فشل تشغيل الصوت الاختباري!", "❌ Failed to play test audio!"), Toast.LENGTH_SHORT).show()
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            stopTestSound()
        }
    }

    val audioPickerLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri ->
        if (uri != null) {
            scope.launch(Dispatchers.IO) {
                try {
                    context.contentResolver.openInputStream(uri)?.use { inputStream ->
                        val targetFile = java.io.File(context.filesDir, "gbr_alert.mp3")
                        targetFile.outputStream().use { outputStream ->
                            inputStream.copyTo(outputStream)
                        }

                        val resolvedUri = android.net.Uri.fromFile(targetFile).toString()
                        
                        var fileName = t("نغمة مخصصة مرفوعة", "Uploaded Custom Tone")
                        try {
                            context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                                val nameIndex = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                                if (nameIndex != -1 && cursor.moveToFirst()) {
                                    fileName = cursor.getString(nameIndex)
                                }
                            }
                        } catch (e: Exception) {}

                        prefs.edit()
                            .putString("gbr_custom_sound_uri", resolvedUri)
                            .putString("gbr_sound_tone_name", fileName)
                            .apply()

                        withContext(Dispatchers.Main) {
                            customSoundUriStr = resolvedUri
                            customSoundName = fileName
                            Toast.makeText(context, t("🎉 تم رفع وحفظ نغمة التنبيه المخصصة بنجاح!", "🎉 Custom print tone uploaded and saved!"), Toast.LENGTH_SHORT).show()
                        }
                    }
                } catch (e: Exception) {
                    withContext(Dispatchers.Main) {
                        Toast.makeText(context, "Error: ${e.localizedMessage}", Toast.LENGTH_LONG).show()
                    }
                }
            }
        }
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, IndustrialBorder)
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            Text(
                text = "🔔 " + t("الأصوات والتنبيهات الموقوتة للمراحل", "Production Stage Timers & Alerts"),
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                color = GBRDarkIndigo
            )

            Text(
                text = t(
                    "يمكنك تخصيص تنبيهات انتهاء الوقت للمراحل الإنتاجية التي تحتوي على مدة زمنية محددة. يسهل هذا رصد العمليات في صالة الإنتاج والخلط الساخن.",
                    "Configure notification tones and vibration parameters for manufacturing stages with strict processing durations."
                ),
                fontSize = 10.5.sp,
                color = Color.Gray,
                lineHeight = 14.sp
            )

            Divider(color = IndustrialBorder)

            // Switch: Sounds Enabled
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable {
                        val newValue = !soundEnabled
                        soundEnabled = newValue
                        prefs.edit().putBoolean("gbr_sound_enabled", newValue).apply()
                    }
                    .padding(vertical = 4.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(text = t("تفعيل نغمة التنبيه الصوتي", "Enable Alarm Sounds"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                    Text(text = t("تشغيل صوت المنبه عندما تنتهي مدة المرحلة خط المعالجة", "Loop notification sounds when a stage duration runs out"), fontSize = 9.5.sp, color = Color.Gray)
                }
                Switch(
                    checked = soundEnabled,
                    onCheckedChange = {
                        soundEnabled = it
                        prefs.edit().putBoolean("gbr_sound_enabled", it).apply()
                    },
                    colors = SwitchDefaults.colors(checkedThumbColor = GBRBlueMain)
                )
            }

            // Switch: Vibration Enabled
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable {
                        val newValue = !vibrationEnabled
                        vibrationEnabled = newValue
                        prefs.edit().putBoolean("gbr_vibration_enabled", newValue).apply()
                    }
                    .padding(vertical = 4.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(text = t("تفعيل نمط الاهتزاز (Vibration)", "Enable Device Vibration"), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
                    Text(text = t("تهتز شاشة العامل باستمرار للفت الانتباه حتى عند الضجيج المرتفع", "Vibrate device persistently for rich haptic feedback amidst machinery noise"), fontSize = 9.5.sp, color = Color.Gray)
                }
                Switch(
                    checked = vibrationEnabled,
                    onCheckedChange = {
                        vibrationEnabled = it
                        prefs.edit().putBoolean("gbr_vibration_enabled", it).apply()
                    },
                    colors = SwitchDefaults.colors(checkedThumbColor = GBRBlueMain)
                )
            }

            Divider(color = IndustrialBorder)

            Text(
                text = "🎵 " + t("نغمة التنبيه الحالية:", "Active Signal Alert Tone:"),
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                color = GBRDarkIndigo
            )

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFFF8FAFC), RoundedCornerShape(10.dp))
                    .border(1.dp, IndustrialBorder, RoundedCornerShape(10.dp))
                    .padding(12.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = if (customSoundUriStr.isBlank()) t("نغمة النظام الافتراضية 🔔", "System Alarm Default 🔔") else customSoundName,
                        fontSize = 11.5.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (customSoundUriStr.isBlank()) Color.Gray else GBRBlueMain
                    )
                    if (customSoundUriStr.isNotBlank()) {
                        Text(
                            text = t("نغمة مخصصة مرفوعة محلية بالتطبيق", "Local custom asset stored inside application sandbox"),
                            fontSize = 8.5.sp,
                            color = Color.LightGray
                        )
                    }
                }

                if (customSoundUriStr.isNotBlank()) {
                    IconButton(
                        onClick = {
                            prefs.edit().remove("gbr_custom_sound_uri").remove("gbr_sound_tone_name").apply()
                            customSoundUriStr = ""
                            customSoundName = ""
                            Toast.makeText(context, t("تمت الاستعادة لنغمة رنين المصنع الافتراضية", "Reverted to factory default alarm"), Toast.LENGTH_SHORT).show()
                        }
                    ) {
                        Icon(imageVector = Icons.Default.Delete, contentDescription = "مسح", tint = ErrorRed, modifier = Modifier.size(18.dp))
                    }
                }
            }

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Button(
                    onClick = { audioPickerLauncher.launch("audio/*") },
                    colors = ButtonDefaults.buttonColors(containerColor = GBRDarkIndigo),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.weight(1f)
                ) {
                    Icon(imageVector = Icons.Default.Build, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(text = t("رفع نغمة رنين 📤", "Upload Custom 📤"), fontSize = 10.5.sp, fontWeight = FontWeight.Bold)
                }

                Button(
                    onClick = {
                        if (isTestPlaying) {
                            stopTestSound()
                        } else {
                            playTestSound()
                            if (vibrationEnabled) {
                                try {
                                    val vibrator = context.getSystemService(android.content.Context.VIBRATOR_SERVICE) as? android.os.Vibrator
                                    vibrator?.vibrate(500)
                                } catch (e: Exception) {}
                            }
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = if (isTestPlaying) ErrorRed else SuccessGreen),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.weight(1f)
                ) {
                    Icon(
                        imageVector = if (isTestPlaying) Icons.Default.Close else Icons.Default.Check,
                        contentDescription = null,
                        modifier = Modifier.size(16.dp)
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = if (isTestPlaying) t("إيقاف تجريبي ⏹️", "Stop Test ⏹️") else t("تشغيل تجريبي ⏯️", "Test Current ⏯️"),
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }
    }
}

@Composable
private fun ExportStepItem(
    stepNumber: Int,
    title: String,
    subtitle: String,
    currentStep: Int
) {
    val isCompleted = currentStep > stepNumber
    val isCurrent = currentStep == stepNumber

    Row(
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Box(
            modifier = Modifier
                .size(28.dp)
                .background(
                    when {
                        isCompleted -> Color(0xFFDCFCE7)
                        isCurrent -> GBRBlueMain.copy(alpha = 0.15f)
                        else -> Color(0xFFF1F5F9)
                    },
                    CircleShape
                ),
            contentAlignment = Alignment.Center
        ) {
            when {
                isCompleted -> {
                    Icon(
                        imageVector = Icons.Default.Check,
                        contentDescription = null,
                        tint = Color(0xFF16A34A),
                        modifier = Modifier.size(16.dp)
                    )
                }
                isCurrent -> {
                    CircularProgressIndicator(
                        modifier = Modifier.size(14.dp),
                        color = GBRBlueMain,
                        strokeWidth = 2.dp
                    )
                }
                else -> {
                    Text(
                        text = "$stepNumber",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.Gray
                    )
                }
            }
        }

        Column {
            Text(
                text = title,
                fontSize = 12.sp,
                fontWeight = if (isCurrent || isCompleted) FontWeight.Bold else FontWeight.Medium,
                color = when {
                    isCompleted -> Color(0xFF16A34A)
                    isCurrent -> GBRBlueMain
                    else -> Color.Gray
                }
            )
            Text(
                text = subtitle,
                fontSize = 10.sp,
                color = Color.Gray
            )
        }
    }
}

@Composable
private fun ExportSummaryRow(label: String, value: String) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(text = label, fontSize = 10.5.sp, color = Color.Gray)
        Text(text = value, fontSize = 10.5.sp, fontWeight = FontWeight.Bold, color = GBRDarkIndigo)
    }
}

